const QUIZ_BANK = [{"id":"CR001","cat":"crm","logic":false,"ru":{"q":"Какой этап воронки продаж брокера идёт сразу после квалификации лида?","a":["Подписание договора","Презентация объекта и переговоры","Ввод арендатора в эксплуатацию"],"c":1,"why":"После квалификации лида брокер переходит к презентации объекта и переговорам об условиях."},"uz":{"q":"Broker savdo voronkasida lidni malakaga solishtirishdan keyin qaysi bosqich keladi?","a":["Shartnoma imzolash","Obyektni taqdim etish va muzokaralar","Ijarachini obyektga kiritish"],"c":1,"why":"Lid malakalashtirilgach, broker obyektni taqdim etish va shartlar bo'yicha muzokaraga o'tadi."},"en":{"q":"Which sales funnel stage comes right after lead qualification for a leasing broker?","a":["Contract signing","Property presentation and negotiation","Tenant fit-out handover"],"c":1,"why":"Once a lead is qualified, the broker moves to presenting the space and negotiating terms."}},{"id":"CR002","cat":"crm","logic":false,"ru":{"q":"Что должен в первую очередь включать шортлист потенциальных арендаторов для нового ТРЦ?","a":["Случайный список любых компаний из интернета","Бренды, чей профиль соответствует концепции и MD ТРЦ","Только действующих арендаторов конкурента"],"c":1,"why":"Шортлист строится на соответствии бренда концепции, зонированию и торговой матрице объекта."},"uz":{"q":"Yangi savdo markazi uchun potensial ijarachilar shortlisti birinchi navbatda nimaga asoslanishi kerak?","a":["Internetdan tasodifiy tanlangan kompaniyalar ro'yxatiga","TSM konsepsiyasi va MD'ga mos brendlarga","Faqat raqobatchining hozirgi ijarachilariga"],"c":1,"why":"Shortlist brendning konsepsiya, zonalash va savdo matritsasiga mosligiga asoslanadi."},"en":{"q":"What should primarily drive a shortlist of prospective tenants for a new shopping mall?","a":["A random list of companies found online","Brands whose profile fits the mall's concept and merchandising mix","Only tenants currently leasing at a competitor mall"],"c":1,"why":"The shortlist should be based on brand fit with the mall's concept, zoning, and tenant mix."}},{"id":"CR003","cat":"crm","logic":false,"ru":{"q":"Зачем брокеру вести в CRM отдельное поле «дата следующего касания» по каждому лиду?","a":["Это требование бухгалтерии для отчётности","Чтобы не терять лид и обеспечить регулярность контакта","Поле не несёт практической пользы"],"c":1,"why":"Дата следующего касания дисциплинирует follow-up и не даёт лиду \"остыть\" без внимания."},"uz":{"q":"Nima uchun broker CRM'da har bir lid uchun \"keyingi aloqa sanasi\" maydonini yuritishi kerak?","a":["Bu buxgalteriya hisobotlari uchun talab","Lidni yo'qotmaslik va muntazam aloqani ta'minlash uchun","Bu maydon amaliy foyda keltirmaydi"],"c":1,"why":"Keyingi aloqa sanasi follow-up intizomini ta'minlaydi va lidni e'tiborsiz qoldirmaydi."},"en":{"q":"Why should a broker maintain a \"next touch date\" field in the CRM for every lead?","a":["It is only required for accounting reports","It prevents leads from going cold and ensures consistent follow-up","The field has no practical value"],"c":1,"why":"A next-touch date enforces follow-up discipline and keeps leads from going cold."}},{"id":"CR004","cat":"crm","logic":false,"ru":{"q":"Какая причина отказа арендатора чаще всего требует пересмотра коммерческого предложения, а не самого объекта?","a":["Высокая ставка аренды и условия по эскалации","Отсутствие парковки у ТРЦ","Низкий пешеходный трафик"],"c":0,"why":"Ставка и условия эскалации — коммерческие параметры, которые можно скорректировать в переговорах."},"uz":{"q":"Ijarachining qaysi rad etish sababi ko'pincha obyektni emas, balki tijorat taklifini qayta ko'rib chiqishni talab qiladi?","a":["Yuqori ijara stavkasi va eskalatsiya shartlari","TSM'da avtoturargoh yo'qligi","Past piyoda oqim"],"c":0,"why":"Stavka va eskalatsiya shartlari — muzokaralar orqali tuzatilishi mumkin bo'lgan tijorat parametrlari."},"en":{"q":"Which refusal reason most often calls for revising the commercial offer rather than the property itself?","a":["High rental rate and escalation terms","No parking available at the mall","Low foot traffic"],"c":0,"why":"Rate and escalation terms are commercial parameters that can be adjusted through negotiation."}},{"id":"CR005","cat":"crm","logic":false,"ru":{"q":"Арендатор отказался, сославшись на несоответствие площади его формату магазина. Что должен сделать брокер в CRM?","a":["Удалить карточку лида без комментариев","Зафиксировать точную причину отказа для дальнейшего анализа и подбора","Пометить лид как \"горячий\""],"c":1,"why":"Фиксация точной причины отказа помогает подобрать другой пул и избежать повторных ошибок в будущем."},"uz":{"q":"Ijarachi maydon o'z do'kon formatiga mos kelmasligini aytib rad etdi. Broker CRM'da nima qilishi kerak?","a":["Lid kartochkasini izohsiz o'chirish","Rad etishning aniq sababini keyingi tahlil uchun qayd etish","Lidni \"issiq\" deb belgilash"],"c":1,"why":"Rad etish sababini aniq qayd etish boshqa obyekt tanlashga va kelajakdagi xatolarni oldini olishga yordam beradi."},"en":{"q":"A tenant declined citing that the unit size doesn't fit their store format. What should the broker do in the CRM?","a":["Delete the lead record without comments","Log the exact refusal reason for future analysis and matching","Mark the lead as \"hot\""],"c":1,"why":"Recording the precise refusal reason supports better future matching and avoids repeating mistakes."}},{"id":"CR006","cat":"crm","logic":false,"ru":{"q":"Каким должен быть первый холодный контакт с брендом, ещё не представленным в Ташкенте?","a":["Сразу выслать проект договора аренды","Краткое персональное предложение с фактами по трафику и локации","Массовая рассылка одного письма по всем контактам бренда"],"c":1,"why":"Первый контакт должен быть кратким, персонализированным и содержать конкретные аргументы по объекту."},"uz":{"q":"Toshkentda hali vakillik qilmagan brend bilan birinchi sovuq aloqa qanday bo'lishi kerak?","a":["Darhol ijara shartnomasi loyihasini yuborish","Trafik va joylashuv faktlari bilan qisqa shaxsiy taklif","Brendning barcha kontaktlariga bir xil xatni ommaviy yuborish"],"c":1,"why":"Birinchi aloqa qisqa, shaxsiylashtirilgan va obyekt bo'yicha aniq dalillarni o'z ichiga olishi kerak."},"en":{"q":"What should the first cold outreach to a brand not yet present in Tashkent look like?","a":["Immediately send a draft lease agreement","A short, personalized pitch with key traffic and location facts","One generic mass email sent to all of the brand's contacts"],"c":1,"why":"First contact should be brief, personalized, and backed by concrete property data."}},{"id":"CR007","cat":"crm","logic":false,"ru":{"q":"Что является обязательной частью подготовки к презентации ТРЦ потенциальному арендатору?","a":["Импровизация без предварительных данных по трафику","Актуальные данные о трафике, соседстве брендов и демографии","Обсуждение только цены за квадратный метр"],"c":1,"why":"Качественная презентация опирается на конкретные данные о трафике, соседях-брендах и целевой аудитории."},"uz":{"q":"Potensial ijarachiga TSM taqdimotiga tayyorgarlikning majburiy qismi nima?","a":["Trafik bo'yicha oldindan ma'lumotsiz improvizatsiya qilish","Trafik, qo'shni brendlar va demografiya bo'yicha dolzarb ma'lumotlar","Faqat kvadrat metr narxini muhokama qilish"],"c":1,"why":"Sifatli taqdimot trafik, qo'shni brendlar va maqsadli auditoriya bo'yicha aniq ma'lumotlarga tayanadi."},"en":{"q":"What is an essential part of preparing to present a mall to a prospective tenant?","a":["Improvising without prior traffic data","Up-to-date data on foot traffic, tenant mix, and demographics","Discussing only the price per square meter"],"c":1,"why":"A strong presentation relies on concrete traffic, tenant-neighbor, and demographic data."}},{"id":"CR008","cat":"crm","logic":false,"ru":{"q":"Арендатор говорит: \"Нам нужно подумать\" после презентации. Какая реакция брокера наиболее профессиональна?","a":["Молча ждать, когда клиент сам перезвонит","Уточнить конкретные сомнения и назначить дату следующего контакта","Сразу снизить ставку аренды"],"c":1,"why":"Профессиональный брокер выявляет реальное возражение и фиксирует конкретный срок для follow-up."},"uz":{"q":"Taqdimotdan so'ng ijarachi \"O'ylab ko'rishimiz kerak\" deydi. Brokerning eng professional reaksiyasi qanday?","a":["Mijoz o'zi qo'ng'iroq qilishini jimgina kutish","Aniq shubhalarni aniqlab, keyingi aloqa sanasini belgilash","Darhol ijara stavkasini pasaytirish"],"c":1,"why":"Professional broker haqiqiy e'tirozni aniqlaydi va follow-up uchun aniq muddat belgilaydi."},"en":{"q":"A tenant says \"We need to think about it\" after the presentation. What is the most professional broker response?","a":["Wait silently for the client to call back","Probe for the specific concern and set a concrete follow-up date","Immediately lower the rental rate"],"c":1,"why":"A professional broker uncovers the real objection and locks in a specific follow-up date."}},{"id":"CR009","cat":"crm","logic":false,"ru":{"q":"Какой ответ на возражение \"у вас слишком высокая ставка аренды\" демонстрирует грамотную работу с возражениями?","a":["Немедленно согласиться на любую скидку","Показать расчёт ожидаемого товарооборота и сравнение с аналогами","Сказать, что ставка не обсуждается"],"c":1,"why":"Аргументированный ответ через цифры оборота и бенчмарки эффективнее, чем немедленная уступка или отказ обсуждать."},"uz":{"q":"\"Sizning ijara stavkangiz juda yuqori\" e'tiroziga qanday javob e'tirozlar bilan malakali ishlashni ko'rsatadi?","a":["Darhol har qanday chegirmaga rozi bo'lish","Kutilgan aylanma hisobi va o'xshash obyektlar bilan solishtirish","Stavka muhokama qilinmasligini aytish"],"c":1,"why":"Aylanma raqamlari va benchmarklar orqali asoslangan javob darhol chegirma berish yoki rad etishdan samaraliroq."},"en":{"q":"Which response to the objection \"your rental rate is too high\" reflects skilled objection handling?","a":["Immediately agree to any discount requested","Present projected turnover figures and comparable benchmarks","State that the rate is non-negotiable"],"c":1,"why":"A data-backed response using turnover projections and benchmarks is more effective than instant concessions or refusal to discuss."}},{"id":"CR010","cat":"crm","logic":false,"ru":{"q":"Какой из показателей KPI брокера отражает эффективность перехода от встреч к реальным предложениям?","a":["Количество отправленных писем","Конверсия встреч в LOI (letter of intent)","Число просмотренных вакантных площадей конкурентов"],"c":1,"why":"Конверсия встреч в LOI показывает, насколько результативно брокер переводит интерес в конкретное предложение."},"uz":{"q":"Brokerning qaysi KPI ko'rsatkichi uchrashuvlardan real takliflarga o'tish samaradorligini aks ettiradi?","a":["Yuborilgan xatlar soni","Uchrashuvlarning LOI (niyat xati)ga konversiyasi","Raqobatchilarning bo'sh maydonlarini ko'rish soni"],"c":1,"why":"Uchrashuvlarning LOI'ga konversiyasi brokerning qiziqishni aniq taklifga aylantirish samaradorligini ko'rsatadi."},"en":{"q":"Which broker KPI reflects how effectively meetings are converted into real offers?","a":["Number of emails sent","Meeting-to-LOI conversion rate","Number of competitor vacant units viewed"],"c":1,"why":"Meeting-to-LOI conversion shows how well the broker turns interest into a concrete offer."}},{"id":"CR011","cat":"crm","logic":false,"ru":{"q":"Что из перечисленного является примером \"touch\" (касания) в отчётности по активности брокера?","a":["Звонок или письмо потенциальному арендатору с уточнением статуса","Внутреннее совещание отдела без участия клиента","Обновление логотипа компании в презентации"],"c":0,"why":"Touch — это любой зафиксированный контакт с клиентом: звонок, письмо, встреча."},"uz":{"q":"Quyidagilardan qaysi biri broker faoliyati hisobotida \"touch\" (aloqa)ga misol bo'ladi?","a":["Potensial ijarachiga holatini aniqlash uchun qo'ng'iroq yoki xat","Mijozsiz o'tkaziladigan ichki bo'lim yig'ilishi","Taqdimotdagi kompaniya logotipini yangilash"],"c":0,"why":"Touch — mijoz bilan qayd etilgan har qanday aloqa: qo'ng'iroq, xat, uchrashuv."},"en":{"q":"Which of the following counts as a \"touch\" in broker activity reporting?","a":["A call or email to a prospect checking on status","An internal team meeting without the client","Updating the company logo in a presentation deck"],"c":0,"why":"A touch is any logged contact with a client, such as a call, email, or meeting."}},{"id":"CR012","cat":"crm","logic":false,"ru":{"q":"Почему важно различать в отчёте KPI показы объекта (viewings) и подписанные LOI?","a":["Разницы нет, это синонимы одного этапа воронки","Это разные этапы воронки, и их смешение искажает анализ конверсии","LOI всегда предшествует показу объекта"],"c":1,"why":"Показ и LOI — разные стадии сделки; раздельный учёт нужен для точного анализа конверсии по этапам."},"uz":{"q":"KPI hisobotida obyekt ko'rsatuvlari (viewings) va imzolangan LOI'larni ajratish nega muhim?","a":["Farqi yo'q, ular bir bosqichning sinonimlari","Bular voronkaning turli bosqichlari, aralashtirish tahlilni buzadi","LOI har doim obyekt ko'rsatuvidan oldin bo'ladi"],"c":1,"why":"Ko'rsatuv va LOI — bitimning turli bosqichlari; aniq tahlil uchun ularni alohida hisoblash kerak."},"en":{"q":"Why is it important to distinguish property viewings from signed LOIs in KPI reporting?","a":["There is no difference; they are the same funnel stage","They are distinct funnel stages, and merging them distorts conversion analysis","An LOI always happens before a viewing"],"c":1,"why":"Viewings and LOIs are separate deal stages, so tracking them separately enables accurate stage-by-stage conversion analysis."}},{"id":"CR013","cat":"crm","logic":false,"ru":{"q":"Какая модель комиссии наиболее распространена для брокера при заключении новой сделки аренды в ТРЦ?","a":["Фиксированная зарплата без привязки к сделкам","Процент от годовой арендной ставки подписанного договора","Оплата только за количество проведённых звонков"],"c":1,"why":"Стандартная практика в брокеридже — комиссия как процент от годовой ставки аренды по заключённому договору."},"uz":{"q":"TSM'da yangi ijara bitimi tuzilganda broker uchun eng keng tarqalgan komissiya modeli qaysi?","a":["Bitimlarga bog'liq bo'lmagan qat'iy oylik maosh","Imzolangan shartnomaning yillik ijara stavkasidan foiz","Faqat amalga oshirilgan qo'ng'iroqlar soni uchun to'lov"],"c":1,"why":"Brokerlikda standart amaliyot — tuzilgan shartnomaning yillik ijara stavkasidan foiz sifatidagi komissiya."},"en":{"q":"Which commission model is most common for a broker closing a new lease deal at a mall?","a":["A fixed salary unrelated to deals closed","A percentage of the signed lease's annual rental value","Payment based solely on the number of calls made"],"c":1,"why":"Standard brokerage practice pays commission as a percentage of the signed lease's annual rent."}},{"id":"CR014","cat":"crm","logic":false,"ru":{"q":"В каком случае комиссия брокера обычно выплачивается только частично на первом этапе?","a":["Когда комиссия делится на транши по этапам сделки","Комиссия всегда выплачивается целиком заранее до подписания","Комиссия не зависит от этапов сделки"],"c":0,"why":"Многие компании делят выплату комиссии на транши, привязанные к ключевым этапам сделки."},"uz":{"q":"Qanday holatda broker komissiyasi odatda birinchi bosqichda faqat qisman to'lanadi?","a":["Komissiya bitim bosqichlari bo'yicha transhlarga bo'lib to'langanda","Komissiya har doim shartnomadan oldin to'liq to'lanadi","Komissiya bitim bosqichlariga bog'liq emas"],"c":0,"why":"Ko'p kompaniyalar komissiyani bitimning asosiy bosqichlariga bog'liq transhlarga bo'lib to'laydi."},"en":{"q":"In which scenario is a broker's commission typically paid only partially at first?","a":["When commission is split into tranches by deal milestone","When commission is always paid in full before signing","When commission has no link to deal milestones"],"c":0,"why":"Many firms split commission payouts into tranches tied to key deal milestones."}},{"id":"CR015","cat":"crm","logic":false,"ru":{"q":"Что из перечисленного считается критической датой (critical date), требующей обязательного контроля брокером?","a":["День рождения контактного лица арендатора","Срок действия LOI или дедлайн подписания договора","Дата публикации новости о конкуренте"],"c":1,"why":"Критические даты — это сроки, влияющие на судьбу сделки: истечение LOI, дедлайны подписания и оплаты."},"uz":{"q":"Quyidagilardan qaysi biri broker tomonidan majburiy nazorat qilinishi kerak bo'lgan kritik sana hisoblanadi?","a":["Ijarachi kontakt shaxsining tug'ilgan kuni","LOI amal qilish muddati yoki shartnoma imzolash deadline'i","Raqobatchi haqidagi yangilik e'lon qilingan sana"],"c":1,"why":"Kritik sanalar — bitim taqdiriga ta'sir qiluvchi muddatlar: LOI tugashi, imzolash va to'lov deadline'lari."},"en":{"q":"Which of the following counts as a critical date that a broker must actively track?","a":["The tenant's contact person's birthday","The LOI expiry date or the contract signing deadline","The date a competitor's press release was published"],"c":1,"why":"Critical dates are deadlines that affect the deal's outcome, such as LOI expiry and signing deadlines."}},{"id":"CR016","cat":"crm","logic":false,"ru":{"q":"Почему пропуск критической даты по LOI особенно опасен для брокера?","a":["Это никак не влияет на дальнейшие переговоры","Арендатор может передумать или отдать предпочтение другому объекту","LOI не имеет юридического или практического значения"],"c":1,"why":"Просроченный LOI даёт арендатору возможность выбрать конкурирующий объект или отказаться от сделки."},"uz":{"q":"LOI bo'yicha kritik sanani o'tkazib yuborish nega broker uchun ayniqsa xavfli?","a":["Bu keyingi muzokaralarga hech qanday ta'sir qilmaydi","Ijarachi fikridan qaytishi yoki boshqa obyektni afzal ko'rishi mumkin","LOI hech qanday huquqiy yoki amaliy ahamiyatga ega emas"],"c":1,"why":"Muddati o'tgan LOI ijarachiga raqobatchi obyektni tanlash yoki bitimdan voz kechish imkonini beradi."},"en":{"q":"Why is missing a critical LOI deadline especially risky for a broker?","a":["It has no effect on further negotiations","The tenant may change their mind or choose a competing property","An LOI has no legal or practical significance"],"c":1,"why":"A lapsed LOI opens the door for the tenant to walk away or sign with a competing property."}},{"id":"CR017","cat":"crm","logic":false,"ru":{"q":"Какое действие является лучшей практикой поддержания \"чистоты\" данных в CRM?","a":["Хранить дублирующиеся карточки одного и того же арендатора","Регулярно обновлять статусы сделок и удалять неактуальные дубли","Вносить данные о клиенте только после подписания договора"],"c":1,"why":"Регулярное обновление статусов и устранение дублей — основа качественной работы с данными в CRM."},"uz":{"q":"CRM'da ma'lumotlar \"tozaligi\"ni saqlashning eng yaxshi amaliyoti qaysi?","a":["Bir xil ijarachining takroriy kartochkalarini saqlash","Statuslarni muntazam yangilash va dublikatlarni o'chirish","Mijoz ma'lumotlarini faqat shartnoma imzolangandan keyin kiritish"],"c":1,"why":"Statuslarni muntazam yangilash va dublikatlarni bartaraf etish sifatli CRM yuritishning asosidir."},"en":{"q":"What is best practice for keeping CRM data clean?","a":["Keep duplicate records for the same tenant","Regularly update deal statuses and remove outdated duplicate entries","Enter client data only after the contract is signed"],"c":1,"why":"Regularly updating statuses and eliminating duplicates is the foundation of good CRM data hygiene."}},{"id":"CR018","cat":"crm","logic":false,"ru":{"q":"Какая практика follow-up считается наиболее дисциплинированной после первой встречи с арендатором?","a":["Ждать, пока арендатор сам напишет о решении","Отправить резюме встречи и договориться о следующем шаге с конкретной датой","Позвонить через месяц без повода"],"c":1,"why":"Профессиональный follow-up фиксирует договорённости письменно и назначает конкретный следующий шаг."},"uz":{"q":"Ijarachi bilan birinchi uchrashuvdan keyin qaysi follow-up amaliyoti eng intizomli hisoblanadi?","a":["Ijarachi o'zi qaror haqida yozishini kutish","Uchrashuv xulosasini yuborish va aniq sana bilan keyingi qadamni kelishish","Sababsiz bir oydan keyin qo'ng'iroq qilish"],"c":1,"why":"Professional follow-up kelishuvlarni yozma ravishda mustahkamlaydi va aniq keyingi qadamni belgilaydi."},"en":{"q":"Which follow-up practice is considered most disciplined after a first meeting with a tenant?","a":["Wait for the tenant to reach out with a decision","Send a meeting recap and agree on a concrete next step with a date","Call back a month later with no specific reason"],"c":1,"why":"Professional follow-up documents agreements in writing and sets a concrete, dated next step."}},{"id":"CR019","cat":"crm","logic":false,"ru":{"q":"Какая частота follow-up обычно рекомендуется для \"тёплого\" лида, который взял паузу на раздумья?","a":["Один раз в полгода","Каждый час, пока не ответят","Через согласованный короткий интервал (например, раз в неделю) с ценным поводом"],"c":2,"why":"Для тёплого лида важен баланс: регулярный, но не навязчивый контакт с конкретным поводом."},"uz":{"q":"O'ylab ko'rish uchun pauza olgan \"issiq\" lid uchun odatda qanday follow-up chastotasi tavsiya etiladi?","a":["Yarim yilda bir marta","Javob berguncha har soatda","Kelishilgan qisqa oraliqda (masalan, haftada bir marta) qimmatli sabab bilan"],"c":2,"why":"Issiq lid uchun muvozanat muhim: muntazam, lekin zerikarli bo'lmagan, aniq sababli aloqa."},"en":{"q":"What follow-up frequency is typically recommended for a warm lead that asked for time to think?","a":["Once every six months","Every hour until they respond","At an agreed short interval (e.g. weekly) with a valuable reason to reconnect"],"c":2,"why":"For a warm lead, the right balance is regular but non-intrusive contact backed by a genuine reason."}},{"id":"CR020","cat":"crm","logic":false,"ru":{"q":"Что из перечисленного — верный пример работы с возражением \"мы уже присутствуем в другом ТРЦ города\"?","a":["Согласиться, что расширение не имеет смысла","Показать, как новый объект дополнит покрытие бренда, не создавая каннибализации","Прекратить дальнейшее общение с этим брендом"],"c":1,"why":"Грамотный брокер объясняет дополняющий эффект новой локации, а не спорит с фактом присутствия."},"uz":{"q":"\"Biz shaharning boshqa TSM'sida allaqachon bor\" e'tirozi bilan ishlashning to'g'ri namunasi qaysi?","a":["Kengayish ma'nosizligiga rozi bo'lish","Yangi obyekt brend qamrovini kannibalizatsiyasiz qanday to'ldirishini ko'rsatish","Ushbu brend bilan aloqani to'xtatish"],"c":1,"why":"Malakali broker mavjudlik faktiga qarshi bahslashmasdan, yangi joylashuvning to'ldiruvchi effektini tushuntiradi."},"en":{"q":"Which is a correct way to handle the objection \"we're already present at another mall in the city\"?","a":["Agree that expansion doesn't make sense","Show how the new location complements coverage, not cannibalizes it","Stop further communication with that brand"],"c":1,"why":"A skilled broker explains the complementary effect of the new location rather than disputing the existing presence."}},{"id":"CR021","cat":"crm","logic":false,"ru":{"q":"Какой показатель лучше всего отражает эффективность холодного охвата брендов брокером за месяц?","a":["Количество отправленных коммерческих предложений безотносительно ответов","Доля откликнувшихся брендов от общего числа контактов","Число посещённых конференций"],"c":1,"why":"Доля откликов (response rate) показывает реальную эффективность охвата, а не просто объём активности."},"uz":{"q":"Broker tomonidan oyiga brendlarga sovuq murojaat samaradorligini eng yaxshi qaysi ko'rsatkich aks ettiradi?","a":["Javoblardan qat'i nazar yuborilgan tijorat takliflari soni","Umumiy kontaktlar ichida javob bergan brendlar ulushi","Qatnashilgan konferensiyalar soni"],"c":1,"why":"Javob berish ulushi (response rate) shunchaki faollik hajmini emas, balki murojaatning haqiqiy samaradorligini ko'rsatadi."},"en":{"q":"Which metric best reflects the effectiveness of a broker's cold outreach to brands over a month?","a":["Number of proposals sent regardless of replies","Response rate — share of contacted brands that replied","Number of conferences attended"],"c":1,"why":"Response rate reflects actual outreach effectiveness rather than raw activity volume."}},{"id":"CR022","cat":"crm","logic":false,"ru":{"q":"Арендатор отказал из-за \"неподходящего соседства брендов\" рядом с предложенной локацией. Как это лучше использовать брокеру?","a":["Игнорировать эту информацию при работе с будущими лидами","Учитывать при формировании шортлиста для этой локации других брендов","Считать это единичным случаем, не влияющим на стратегию"],"c":1,"why":"Информация о несовместимости соседства должна использоваться для точного подбора будущих арендаторов на эту локацию."},"uz":{"q":"Ijarachi taklif qilingan joylashuv yaqinidagi \"noto'g'ri brend qo'shnichiligi\" tufayli rad etdi. Broker buni qanday ishlatishi kerak?","a":["Kelajakdagi lidlar bilan ishlashda bu ma'lumotni e'tiborsiz qoldirish","Ushbu joylashuv uchun shortlist tuzishda hisobga olish","Buni strategiyaga ta'sir qilmaydigan yakka hol deb hisoblash"],"c":1,"why":"Qo'shnichilik mos kelmasligi haqidagi ma'lumot kelajakda ushbu joylashuvga ijarachi tanlashda hisobga olinishi kerak."},"en":{"q":"A tenant declined citing \"poor brand adjacency\" near the proposed unit. How should the broker best use this information?","a":["Ignore it when working with future leads","Factor it into the shortlist of other brands for that specific location","Treat it as an isolated case with no strategic impact"],"c":1,"why":"Adjacency mismatch feedback should inform future tenant matching for that specific location."}},{"id":"CR023","cat":"crm","logic":false,"ru":{"q":"Что из перечисленного является примером количественного KPI брокера, а не качественного?","a":["Умение убедительно вести переговоры","Число подписанных договоров аренды за квартал","Уровень доверия арендатора к брокеру"],"c":1,"why":"Число подписанных договоров — измеримый количественный показатель, в отличие от субъективных качественных оценок."},"uz":{"q":"Quyidagilardan qaysi biri brokerning sifat emas, balki miqdoriy KPI ko'rsatkichiga misol bo'ladi?","a":["Ishonarli muzokara olib borish qobiliyati","Chorakda imzolangan ijara shartnomalari soni","Ijarachining brokerga bo'lgan ishonch darajasi"],"c":1,"why":"Imzolangan shartnomalar soni — subyektiv sifat baholaridan farqli o'laroq, o'lchanadigan miqdoriy ko'rsatkich."},"en":{"q":"Which of the following is an example of a quantitative broker KPI rather than a qualitative one?","a":["Ability to negotiate persuasively","Number of signed lease contracts per quarter","The tenant's level of trust in the broker"],"c":1,"why":"The number of signed contracts is a measurable quantitative metric, unlike subjective qualitative judgments."}},{"id":"CR024","cat":"crm","logic":false,"ru":{"q":"Почему важно фиксировать в CRM не только факт отказа арендатора, но и стадию воронки, на которой он произошёл?","a":["Это не имеет значения для анализа","Это позволяет анализировать, на каком этапе брокеры теряют больше всего сделок","Стадия отказа нужна только для юридического архива"],"c":1,"why":"Анализ стадии отказа помогает выявить узкие места воронки продаж и точечно улучшить процесс."},"uz":{"q":"CRM'da nafaqat ijarachining rad etish faktini, balki bu qaysi voronka bosqichida sodir bo'lganini qayd etish nega muhim?","a":["Bu tahlil uchun ahamiyatsiz","Qaysi bosqichda ko'p bitim yo'qotilishini aniqlash imkonini beradi","Rad etish bosqichi faqat yuridik arxiv uchun kerak"],"c":1,"why":"Rad etish bosqichini tahlil qilish savdo voronkasidagi tor joylarni aniqlash va jarayonni yaxshilashga yordam beradi."},"en":{"q":"Why is it important to log not just that a tenant declined, but at which funnel stage the refusal occurred?","a":["It has no bearing on analysis","It helps identify at which stage brokers lose the most deals","The refusal stage is only needed for legal archiving"],"c":1,"why":"Analyzing the refusal stage helps pinpoint bottlenecks in the sales funnel and target process improvements."}},{"id":"CR025","cat":"crm","logic":false,"ru":{"q":"Какой подход к комиссии мотивирует брокера в первую очередь заключать более крупные и качественные сделки, а не просто больше сделок?","a":["Фиксированная сумма за каждую сделку независимо от площади и ставки","Процент от арендной платы, растущий вместе с объёмом и сроком договора","Комиссия только за количество звонков в CRM"],"c":1,"why":"Процентная комиссия от объёма сделки напрямую увязывает вознаграждение брокера с ценностью для компании."},"uz":{"q":"Qaysi komissiya yondashuvi brokerni shunchaki ko'proq emas, balki yiriroq va sifatliroq bitimlar tuzishga undaydi?","a":["Maydon va stavkadan qat'i nazar har bir bitim uchun qat'iy summa","Shartnoma hajmi va muddati bilan birga o'sadigan ijara to'lovidan foiz","Faqat CRM'dagi qo'ng'iroqlar soni uchun komissiya"],"c":1,"why":"Bitim hajmiga bog'liq foizli komissiya broker mukofotini kompaniya uchun qiymat bilan to'g'ridan-to'g'ri bog'laydi."},"en":{"q":"Which commission approach best motivates a broker to prioritize larger, higher-quality deals over sheer deal count?","a":["A flat fee per deal regardless of size or rate","A percentage of rent that scales with deal size and contract term","Commission based only on the number of CRM calls logged"],"c":1,"why":"A percentage-based commission tied to deal value directly aligns broker incentives with value delivered to the company."}},{"id":"CR026","cat":"crm","logic":false,"ru":{"q":"На каком этапе воронки продаж брокеру следует зафиксировать вероятность сделки и ожидаемую дату закрытия?","a":["После получения подписанного договора","Сразу после квалификации лида и определения интереса","Только на этапе эскалации руководству"],"c":1,"why":"Прогноз вероятности и даты закрытия закладывается сразу после квалификации, чтобы воронка отражала реальную динамику."},"uz":{"q":"Sotuv voronkasining qaysi bosqichida broker bitim ehtimolini va yopilish sanasini qayd etishi kerak?","a":["Shartnoma imzolangandan keyin","Lidni kvalifikatsiya qilib, qiziqishni aniqlagandan keyin","Faqat rahbariyatga eskalatsiya bosqichida"],"c":1,"why":"Ehtimol va yopilish sanasi kvalifikatsiyadan keyin darhol belgilanadi, shunda voronka real holatni aks ettiradi."},"en":{"q":"At which stage of the sales funnel should a broker record the deal probability and expected close date?","a":["Only after the signed contract is received","Right after lead qualification confirms genuine interest","Only when the deal is escalated to management"],"c":1,"why":"Probability and close date should be set immediately after qualification so the funnel reflects real progress."}},{"id":"CR027","cat":"crm","logic":false,"ru":{"q":"Что важнее всего учитывать при подборе арендатора под конкретное свободное помещение (unit)?","a":["Только площадь помещения в квадратных метрах","Категорию арендатора, зонирование этажа и соседей по галерее","Только готовность арендатора подписать договор быстро"],"c":1,"why":"Правильный микс достигается через соответствие категории, зонирования и соседства, а не только по площади."},"uz":{"q":"Bo'sh joyga (unit) ijarachi tanlashda eng muhimi nima?","a":["Faqat xonaning kvadrat metrdagi maydoni","Ijarachi toifasi, qavat zonalanishi va qo'shni do'konlar","Faqat ijarachining tez shartnoma imzolashga tayyorligi"],"c":1,"why":"To'g'ri tenant-miks toifa, zonalanish va qo'shnichilikka mosligi orqali ta'minlanadi, faqat maydon bilan emas."},"en":{"q":"What is most important when matching a prospective tenant to a specific available unit?","a":["Only the unit's square meterage","Tenant category fit, floor zoning, and neighboring stores","Only how quickly the tenant is willing to sign"],"c":1,"why":"Good tenant mix depends on category fit, zoning, and adjacency, not floor area alone."}},{"id":"CR028","cat":"crm","logic":false,"ru":{"q":"Арендатор из категории 'детские товары' рассматривает единственное свободное помещение рядом с фудкортом. Как должен поступить брокер?","a":["Сразу предложить это помещение как единственный вариант","Оценить совместимость категории с окружением и предупредить о рисках","Отказать арендатору, не объясняя причину"],"c":1,"why":"Брокер обязан оценить совместимость категории с локацией и честно предупредить клиента о возможных рисках соседства."},"uz":{"q":"'Bolalar tovarlari' toifasidagi ijarachi fudkort yonidagi yagona bo'sh joyni ko'rib chiqmoqda. Broker qanday yo'l tutishi kerak?","a":["Darhol shu joyni yagona variant sifatida taklif qilish","Toifa va muhit mosligini baholab, xavflar haqida ogohlantirish","Sababini tushuntirmasdan ijarachiga rad javobi berish"],"c":1,"why":"Broker toifa va joylashuv mosligini baholab, mumkin bo'lgan qo'shnichilik xavflari haqida mijozni halol ogohlantirishi kerak."},"en":{"q":"A children's goods tenant is considering the only vacant unit next to the food court. What should the broker do?","a":["Immediately offer it as the only option available","Assess category-location fit and flag potential risks honestly","Reject the tenant without explanation"],"c":1,"why":"The broker must evaluate fit between category and surroundings and transparently flag adjacency risks to the client."}},{"id":"CR029","cat":"crm","logic":false,"ru":{"q":"Для чего в работе брокера нужна система напоминаний о критических датах (например, окончание опции резервирования)?","a":["Чтобы не пропустить срок и не потерять сделку или помещение","Чтобы отчитываться перед бухгалтерией","Это нужно только для маркетингового отдела"],"c":0,"why":"Напоминания о критических датах предотвращают потерю сделки из-за просроченных сроков резервирования или согласований."},"uz":{"q":"Broker ishida muhim sanalar (masalan, band qilish muddati tugashi) haqida eslatmalar nima uchun kerak?","a":["Muddatni o'tkazib yubormaslik va bitim yoki joyni yo'qotmaslik uchun","Buxgalteriyaga hisobot berish uchun","Bu faqat marketing bo'limi uchun kerak"],"c":0,"why":"Muhim sanalar bo'yicha eslatmalar band qilish muddati o'tib ketishi sababli bitim yoki joyni yo'qotishning oldini oladi."},"en":{"q":"Why does a broker need a reminder system for critical dates, such as an option/reservation expiry?","a":["To avoid missing the deadline and losing the deal or the unit","To report to the accounting department","It is only relevant for the marketing team"],"c":0,"why":"Critical date reminders prevent losing a deal or unit due to a missed reservation or approval deadline."}},{"id":"CR030","cat":"crm","logic":false,"ru":{"q":"Арендатор трижды переносил дату подписания договора без уважительной причины. Что должен сделать брокер?","a":["Продолжать бесконечно ждать без фиксации","Зафиксировать паттерн, уточнить реальный статус решения и пересмотреть приоритет сделки","Немедленно снять помещение с рынка для этого арендатора"],"c":1,"why":"Повторные переносы — сигнал риска, который нужно задокументировать и прояснить, а не игнорировать."},"uz":{"q":"Ijarachi shartnoma imzolash sanasini uch marta asossiz sabab bilan ko'chirdi. Broker nima qilishi kerak?","a":["Cheksiz kutishda davom etish va buni qayd etmaslik","Naqshni qayd etib, qaror holatini aniqlashtirish va bitim ustuvorligini qayta ko'rib chiqish","Ushbu ijarachi uchun joyni darhol bozordan olib tashlash"],"c":1,"why":"Takroriy kechikishlar xavf belgisi bo'lib, uni hujjatlashtirib, aniqlik kiritish lozim, e'tiborsiz qoldirmaslik kerak."},"en":{"q":"A tenant has postponed the signing date three times without valid reason. What should the broker do?","a":["Keep waiting indefinitely without documenting it","Log the pattern, verify the real decision status, and reprioritize the deal","Immediately pull the unit off the market for that tenant"],"c":1,"why":"Repeated delays are a risk signal that should be documented and clarified rather than ignored."}},{"id":"CR031","cat":"crm","logic":false,"ru":{"q":"Зачем брокеру анализировать причины отказов арендаторов за прошлый квартал?","a":["Чтобы найти виновного сотрудника и наказать его","Чтобы выявить системные проблемы (цена, локация, условия) и скорректировать стратегию","Это требование только для годового отчета собственнику"],"c":1,"why":"Анализ отказов помогает выявить повторяющиеся причины и системно улучшить подход к сделкам."},"uz":{"q":"Broker o'tgan chorakdagi ijarachilar rad javoblari sabablarini nima uchun tahlil qilishi kerak?","a":["Aybdor xodimni topib, uni jazolash uchun","Tizimli muammolarni (narx, joylashuv, shartlar) aniqlab, strategiyani tuzatish uchun","Bu faqat mulkdorga yillik hisobot uchun talab qilinadi"],"c":1,"why":"Rad javoblarini tahlil qilish takrorlanuvchi sabablarni aniqlab, yondashuvni tizimli yaxshilashga yordam beradi."},"en":{"q":"Why should a broker analyze the reasons behind tenant refusals from the past quarter?","a":["To identify and blame a specific staff member","To detect systemic issues (price, location, terms) and adjust strategy","It is only required for the annual owner report"],"c":1,"why":"Refusal analysis surfaces recurring root causes and enables systematic improvement of the sales approach."}},{"id":"CR032","cat":"crm","logic":false,"ru":{"q":"Бренд отказался от сделки, указав причину 'высокая ставка аренды'. Какое дальнейшее действие брокера наиболее полезно?","a":["Закрыть карточку сделки без комментариев","Уточнить, какая ставка была бы приемлема, и передать данные в анализ рынка","Немедленно снизить ставку для всех будущих арендаторов"],"c":1,"why":"Уточнение приемлемой ставки даёт полезные рыночные данные для будущих переговоров и ценовой политики."},"uz":{"q":"Brend bitimdan 'ijara stavkasi yuqori' sababli voz kechdi. Brokerning keyingi eng foydali qadami qanday?","a":["Bitim kartochkasini izohsiz yopish","Qanday stavka maqbul bo'lishini aniqlashtirib, bozor tahliliga uzatish","Barcha kelajakdagi ijarachilar uchun stavkani darhol tushirish"],"c":1,"why":"Maqbul stavkani aniqlashtirish kelajakdagi muzokaralar va narx siyosati uchun foydali bozor ma'lumotini beradi."},"en":{"q":"A brand declined a deal citing 'rental rate too high.' What is the most useful next step for the broker?","a":["Close the deal record with no further notes","Clarify what rate would be acceptable and feed it into market analysis","Immediately lower the rate for all future tenants"],"c":1,"why":"Clarifying the acceptable rate provides valuable market data for future negotiations and pricing strategy."}},{"id":"CR033","cat":"crm","logic":false,"ru":{"q":"Какая тактика переговоров с представителем бренда считается профессиональной при обсуждении ставки аренды?","a":["Сразу соглашаться на любые условия, лишь бы не потерять клиента","Аргументировать ставку данными о трафике, конкурентах и потенциале продаж","Давить на арендатора угрозой сдать помещение конкуренту"],"c":1,"why":"Профессиональные переговоры опираются на объективные данные о трафике и рыночном потенциале, а не на давление или уступчивость."},"uz":{"q":"Ijara stavkasi muhokamasida brend vakili bilan qaysi muzokara taktikasi professional hisoblanadi?","a":["Mijozni yo'qotmaslik uchun barcha shartlarga darhol rozi bo'lish","Stavkani trafik, raqobatchilar va savdo salohiyati ma'lumotlari bilan asoslash","Joyni raqobatchiga berish bilan tahdid qilib bosim o'tkazish"],"c":1,"why":"Professional muzokara trafik va bozor salohiyati bo'yicha ob'ektiv ma'lumotlarga tayanadi, bosim yoki bo'shashishga emas."},"en":{"q":"Which negotiation tactic with a brand representative is considered professional when discussing the rental rate?","a":["Agree to any terms immediately to avoid losing the client","Support the rate with data on foot traffic, competitors, and sales potential","Pressure the tenant by threatening to lease the unit to a competitor"],"c":1,"why":"Professional negotiation relies on objective traffic and market-potential data rather than pressure or blind concessions."}},{"id":"CR034","cat":"crm","logic":false,"ru":{"q":"Представитель бренда просит скидку 30% от прайса на аренду, ссылаясь на 'общую практику'. Как правильно ответить брокеру?","a":["Согласиться, чтобы не затягивать переговоры","Запросить обоснование и предложить встречные условия (например, KPI по товарообороту)","Прекратить переговоры без объяснений"],"c":1,"why":"Грамотный брокер требует обоснования запроса и предлагает альтернативные условия вместо немедленной уступки."},"uz":{"q":"Brend vakili 'umumiy amaliyot' deb 30% chegirma so'ramoqda. Broker qanday javob berishi to'g'ri?","a":["Muzokarani cho'zmaslik uchun rozi bo'lish","Asos so'rab, o'zaro shartlar (masalan, aylanma bo'yicha KPI) taklif qilish","Hech qanday tushuntirishsiz muzokarani to'xtatish"],"c":1,"why":"Malakali broker so'rov uchun asos talab qiladi va darhol yon berish o'rniga muqobil shartlar taklif qiladi."},"en":{"q":"A brand representative requests a 30% discount off list rent citing 'common practice.' What is the correct broker response?","a":["Accept it to avoid prolonging negotiations","Ask for justification and propose counter-terms, e.g. turnover-based KPIs","End the negotiation without explanation"],"c":1,"why":"A skilled broker requests justification and offers counter-terms instead of conceding immediately."}},{"id":"CR035","cat":"crm","logic":false,"ru":{"q":"Что обязательно должно быть включено в коммерческое предложение (КП) для потенциального арендатора?","a":["Только контактный номер телефона брокера","Условия аренды, площадь, ставка, срок действия предложения и характеристики ТРЦ","Личное мнение брокера о конкурентах арендатора"],"c":1,"why":"КП должно содержать конкретные коммерческие условия и характеристики объекта, а не субъективные комментарии."},"uz":{"q":"Potentsial ijarachi uchun tijorat taklifi (KP) tarkibida nima albatta bo'lishi kerak?","a":["Faqat brokerning aloqa telefon raqami","Ijara shartlari, maydon, stavka, taklif amal qilish muddati va TRC xususiyatlari","Brokerning ijarachi raqobatchilari haqidagi shaxsiy fikri"],"c":1,"why":"KP aniq tijorat shartlari va ob'ekt xususiyatlarini o'z ichiga olishi kerak, sub'ektiv fikrlarni emas."},"en":{"q":"What must a commercial proposal (KP) for a prospective tenant always include?","a":["Only the broker's personal phone number","Lease terms, area, rate, offer validity period, and mall characteristics","The broker's personal opinion about the tenant's competitors"],"c":1,"why":"A KP must contain concrete commercial terms and property characteristics, not subjective commentary."}},{"id":"CR036","cat":"crm","logic":false,"ru":{"q":"Через сколько дней после отправки КП брокеру следует запланировать первый контрольный follow-up, если арендатор не ответил?","a":["Через 2-3 рабочих дня","Через 2-3 месяца","Follow-up не нужен, если клиент сам не написал"],"c":0,"why":"Стандартная практика — короткий цикл follow-up в 2-3 рабочих дня, чтобы удержать интерес и темп сделки."},"uz":{"q":"KP yuborilgandan necha kun o'tgach, ijarachi javob bermasa, broker birinchi nazorat follow-up rejalashtirishi kerak?","a":["2-3 ish kunidan keyin","2-3 oydan keyin","Mijoz o'zi yozmasa, follow-up shart emas"],"c":0,"why":"Standart amaliyot — qiziqish va bitim tezligini saqlash uchun 2-3 ish kunlik qisqa follow-up sikli."},"en":{"q":"How soon after sending a KP should a broker schedule the first follow-up if the tenant hasn't responded?","a":["Within 2-3 business days","After 2-3 months","No follow-up is needed unless the client reaches out first"],"c":0,"why":"Standard practice is a short 2-3 business day follow-up cycle to maintain interest and deal momentum."}},{"id":"CR037","cat":"crm","logic":false,"ru":{"q":"Арендатор возражает: 'Ваш ТРЦ далеко от нашей целевой аудитории'. Какой ответ демонстрирует грамотную работу с возражением?","a":["Согласиться и предложить снизить ставку в качестве компенсации","Привести данные по трафику, составу посетителей и транспортной доступности","Сказать, что это не проблема брокера"],"c":1,"why":"Работа с возражением строится на фактических данных о трафике и профиле аудитории, а не на уступках или отрицании."},"uz":{"q":"Ijarachi 'Sizning TRC bizning maqsadli auditoriyamizdan uzoqda' deb e'tiroz bildirmoqda. Qaysi javob to'g'ri e'tiroz bilan ishlashni ko'rsatadi?","a":["Rozi bo'lib, kompensatsiya sifatida stavkani tushirishni taklif qilish","Trafik, tashrif buyuruvchilar tarkibi va transport qulayligi ma'lumotlarini keltirish","Bu brokerning muammosi emasligini aytish"],"c":1,"why":"E'tiroz bilan ishlash trafik va auditoriya profili bo'yicha faktik ma'lumotlarga asoslanadi, yon berish yoki rad etishga emas."},"en":{"q":"A tenant objects: 'Your mall is too far from our target audience.' Which response shows sound objection handling?","a":["Agree and offer a rate reduction as compensation","Present data on foot traffic, visitor demographics, and transport access","Say this is not the broker's problem to solve"],"c":1,"why":"Good objection handling uses factual traffic and audience data rather than concessions or dismissal."}},{"id":"CR038","cat":"crm","logic":false,"ru":{"q":"Что такое LCR (реестр учёта лидов/сделок) в работе брокера отдела лизинга?","a":["Отчёт только для отдела маркетинга о рекламных кампаниях","Актуальный единый реестр всех сделок и коммуникаций по каждому арендатору","Список уволенных сотрудников компании"],"c":1,"why":"LCR — это единый реестр, где фиксируется актуальный статус каждой сделки и вся история взаимодействия с арендатором."},"uz":{"q":"Lizing bo'limi brokeri ishida LCR (lidlar/bitimlar reestri) nima?","a":["Faqat marketing bo'limi uchun reklama kampaniyalari hisoboti","Har bir ijarachi bo'yicha barcha bitimlar va muloqotlarning yagona dolzarb reestri","Kompaniyadan bo'shatilgan xodimlar ro'yxati"],"c":1,"why":"LCR — har bir bitimning dolzarb holati va ijarachi bilan barcha muloqot tarixi qayd etiladigan yagona reestr."},"en":{"q":"What is the LCR (lead/deal registry) in a leasing broker's daily work?","a":["A report used only by the marketing department for ad campaigns","A single up-to-date registry of all deals and communications per tenant","A list of employees who have left the company"],"c":1,"why":"The LCR is a unified registry that tracks the current status of every deal and the full communication history."}},{"id":"CR039","cat":"crm","logic":false,"ru":{"q":"Почему важно вносить изменения статуса сделки в реестр (LCR) сразу, а не в конце недели?","a":["Чтобы реестр отражал реальную картину для коллег и руководства в любой момент","Это требование только для новых сотрудников на испытательном сроке","Так удобнее считать зарплату бухгалтерии"],"c":0,"why":"Своевременное обновление реестра обеспечивает актуальность данных для всей команды и корректную аналитику в реальном времени."},"uz":{"q":"Bitim holatini reestrga (LCR) hafta oxirida emas, darhol kiritish nima uchun muhim?","a":["Reestr istalgan vaqtda hamkasblar va rahbariyat uchun real holatni aks ettirishi uchun","Bu faqat sinov muddatidagi yangi xodimlar uchun talab","Buxgalteriyaga maosh hisoblash qulay bo'lishi uchun"],"c":0,"why":"Reestrni o'z vaqtida yangilash butun jamoa uchun ma'lumotlar dolzarbligini va real vaqtdagi to'g'ri tahlilni ta'minlaydi."},"en":{"q":"Why is it important to update a deal's status in the registry (LCR) immediately rather than at week's end?","a":["So the registry reflects the real picture for colleagues and management at any time","It is only required for new employees during probation","It makes payroll calculation easier for accounting"],"c":0,"why":"Timely registry updates keep data current for the whole team and support accurate real-time reporting."}},{"id":"CR040","cat":"crm","logic":false,"ru":{"q":"Какой из показателей чаще всего используется как ключевой KPI брокера по лизингу?","a":["Количество отправленных писем без учёта результата","Конверсия из лида в подписанный договор и объём законтрактованной площади","Количество часов, проведённых в офисе"],"c":1,"why":"Ключевые KPI брокера привязаны к результату — конверсии сделок и объёму законтрактованных площадей."},"uz":{"q":"Lizing brokeri uchun asosiy KPI sifatida ko'pincha qaysi ko'rsatkich ishlatiladi?","a":["Natijasidan qat'i nazar yuborilgan xatlar soni","Liddan imzolangan shartnomagacha konversiya va shartnoma tuzilgan maydon hajmi","Ofisda o'tkazilgan soatlar soni"],"c":1,"why":"Brokerning asosiy KPI'lari natijaga — bitimlar konversiyasi va shartnoma tuzilgan maydon hajmiga bog'liq."},"en":{"q":"Which metric is most commonly used as a key KPI for a leasing broker?","a":["Number of emails sent regardless of outcome","Lead-to-signed-contract conversion rate and volume of leased area","Number of hours spent in the office"],"c":1,"why":"Core broker KPIs are tied to outcomes — deal conversion rate and volume of contracted leasable area."}},{"id":"CR041","cat":"crm","logic":false,"ru":{"q":"Брокер выполнил план по количеству встреч, но не закрыл ни одной сделки за месяц. Как это должно оцениваться с точки зрения KPI?","a":["Как полное выполнение плана, поскольку встречи — главный показатель","Как проблема, поскольку итоговый KPI измеряется закрытыми сделками, а не активностью","KPI не имеет значения, если брокер занят"],"c":1,"why":"Активность (встречи) — промежуточный показатель, а не замена финальному результату — заключённым договорам."},"uz":{"q":"Broker uchrashuvlar rejasini bajardi, lekin oy davomida bironta bitim yopmadi. Bu KPI nuqtai nazaridan qanday baholanishi kerak?","a":["Reja to'liq bajarilgan, chunki uchrashuvlar asosiy ko'rsatkich","Muammo, chunki yakuniy KPI faoliyat emas, yopilgan bitimlar bilan o'lchanadi","Broker band bo'lsa, KPI ahamiyatsiz"],"c":1,"why":"Faoliyat (uchrashuvlar) oraliq ko'rsatkich bo'lib, yakuniy natija — tuzilgan shartnomalar o'rnini bosa olmaydi."},"en":{"q":"A broker hit the target number of meetings but closed zero deals for the month. How should this be viewed from a KPI perspective?","a":["As full plan achievement, since meetings are the main metric","As a concern, since the real KPI is measured by closed deals, not activity","KPIs don't matter as long as the broker stays busy"],"c":1,"why":"Activity metrics like meetings are leading indicators, not a substitute for the final outcome of signed deals."}},{"id":"CR042","cat":"crm","logic":false,"ru":{"q":"По какому принципу обычно рассчитывается комиссия брокера за закрытую сделку по аренде?","a":["Фиксированная сумма независимо от условий и объёма сделки","Процент от суммы годовой арендной платы или от суммы контракта","Комиссия не зависит от факта подписания договора"],"c":1,"why":"Комиссия брокера, как правило, привязана к проценту от годовой арендной ставки или общей суммы контракта."},"uz":{"q":"Ijara bo'yicha yopilgan bitim uchun broker komissiyasi odatda qanday tamoyilda hisoblanadi?","a":["Shartlar va bitim hajmidan qat'i nazar belgilangan summa","Yillik ijara to'lovi yoki shartnoma summasidan foiz","Komissiya shartnoma imzolanishiga bog'liq emas"],"c":1,"why":"Broker komissiyasi odatda yillik ijara stavkasi yoki shartnomaning umumiy summasidan foiz sifatida hisoblanadi."},"en":{"q":"What principle typically determines a broker's commission on a closed lease deal?","a":["A fixed amount regardless of deal size or terms","A percentage of the annual rent or total contract value","Commission does not depend on whether the contract is signed"],"c":1,"why":"Broker commission is typically calculated as a percentage of annual rent or total contract value."}},{"id":"CR043","cat":"crm","logic":false,"ru":{"q":"Сделка была закрыта совместно двумя брокерами: один нашёл лида, другой довёл до подписания. Как должна быть распределена комиссия?","a":["Вся комиссия достаётся только тому, кто подписал договор","По заранее установленному правилу разделения между участниками сделки","Комиссия не выплачивается при совместной работе"],"c":1,"why":"При совместной работе комиссия делится по установленным внутренним правилам компании, а не произвольно."},"uz":{"q":"Bitim ikki broker tomonidan birgalikda yopildi: biri lidni topdi, ikkinchisi imzolashga olib keldi. Komissiya qanday taqsimlanishi kerak?","a":["Butun komissiya faqat shartnomani imzolagan brokerga tegadi","Bitim ishtirokchilari o'rtasida oldindan belgilangan qoida bo'yicha taqsimlanadi","Birgalikdagi ishda komissiya to'lanmaydi"],"c":1,"why":"Birgalikdagi ishda komissiya kompaniyaning oldindan belgilangan ichki qoidalari bo'yicha taqsimlanadi, o'zboshimchalik bilan emas."},"en":{"q":"A deal was closed jointly by two brokers: one sourced the lead, the other brought it to signature. How should commission be split?","a":["The entire commission goes only to the broker who signed the deal","According to a pre-established split rule agreed for shared deals","No commission is paid when brokers work jointly"],"c":1,"why":"Joint deals are split according to the company's pre-established internal commission rules, not arbitrarily."}},{"id":"CR044","cat":"crm","logic":false,"ru":{"q":"В какой момент сделку обычно необходимо эскалировать руководству для согласования?","a":["Только если арендатор лично об этом попросил","Когда условия выходят за рамки стандартных полномочий брокера (например, крупная скидка)","Эскалация не требуется, если брокер уверен в своей правоте"],"c":1,"why":"Эскалация нужна, когда условия сделки выходят за пределы полномочий брокера и требуют утверждения на более высоком уровне."},"uz":{"q":"Bitimni odatda qachon tasdiqlash uchun rahbariyatga eskalatsiya qilish kerak?","a":["Faqat ijarachi shaxsan shuni so'raganda","Shartlar brokerning standart vakolatidan tashqariga chiqqanda (masalan, katta chegirma)","Broker o'z haqligiga ishonch hosil qilsa, eskalatsiya shart emas"],"c":1,"why":"Bitim shartlari brokerning vakolat doirasidan tashqariga chiqsa, yuqori darajada tasdiqlash uchun eskalatsiya zarur."},"en":{"q":"At what point should a deal typically be escalated to management for approval?","a":["Only if the tenant personally requests it","When terms exceed the broker's standard authority, e.g. a large discount","Escalation is unnecessary if the broker is confident in the terms"],"c":1,"why":"Escalation is required when deal terms exceed the broker's standard authority and need higher-level sign-off."}},{"id":"CR045","cat":"crm","logic":false,"ru":{"q":"Какую информацию обязательно нужно приложить, отправляя сделку на согласование руководству?","a":["Только устное сообщение о желании арендатора","Полную сводку условий, отклонений от стандарта и обоснование выгоды для ТРЦ","Личные контакты арендатора без деталей условий"],"c":1,"why":"Для принятия решения руководству нужна полная картина условий, отклонений и обоснование целесообразности сделки."},"uz":{"q":"Bitimni rahbariyatga tasdiqlash uchun yuborishda albatta qanday ma'lumot ilova qilinishi kerak?","a":["Faqat ijarachining istagi haqida og'zaki xabar","Shartlarning to'liq xulosasi, standartdan chetlanishlar va TSM uchun foyda asoslamasi","Shartlar tafsilotisiz ijarachining shaxsiy kontaktlari"],"c":1,"why":"Qaror qabul qilish uchun rahbariyatga shartlar, chetlanishlar va bitim maqsadga muvofiqligining to'liq asoslamasi kerak."},"en":{"q":"What information must always accompany a deal sent to management for approval?","a":["Just a verbal note that the tenant is interested","A full summary of terms, deviations from standard, and the rationale benefiting the mall","The tenant's personal contacts without any term details"],"c":1,"why":"Management needs a complete picture of terms, deviations, and rationale to make an informed approval decision."}},{"id":"CR046","cat":"crm","logic":false,"ru":{"q":"Что означает принцип 'own_only' (доступ только к своим сделкам) в системе учёта брокеров?","a":["Брокер видит и редактирует только сделки, закреплённые за ним самим","Брокер может редактировать сделки любого коллеги в отделе","Все брокеры видят только сделки директора"],"c":0,"why":"Принцип own_only ограничивает доступ брокера рамками его собственных закреплённых сделок для защиты данных и ответственности."},"uz":{"q":"Brokerlar hisob tizimidagi 'own_only' (faqat o'z bitimlariga kirish) tamoyili nimani anglatadi?","a":["Broker faqat o'ziga biriktirilgan bitimlarni ko'radi va tahrirlaydi","Broker bo'limdagi istalgan hamkasbning bitimini tahrirlashi mumkin","Barcha brokerlar faqat direktor bitimlarini ko'radi"],"c":0,"why":"own_only tamoyili ma'lumotlar xavfsizligi va javobgarlik uchun broker kirishini faqat o'ziga biriktirilgan bitimlar bilan cheklaydi."},"en":{"q":"What does the 'own_only' access principle mean in a broker's deal-tracking system?","a":["The broker can view and edit only deals assigned to themselves","The broker can edit any colleague's deals within the department","All brokers can only view the director's deals"],"c":0,"why":"The own_only principle restricts broker access to their own assigned deals to protect data and enforce accountability."}},{"id":"CR047","cat":"crm","logic":false,"ru":{"q":"Брокер с правами own_only пытается найти в системе сделку коллеги, чтобы 'помочь' без согласования с руководителем. Как это оценивается?","a":["Это нормально, если намерения хорошие","Это нарушение принципа доступа и должно решаться через руководителя, а не напрямую","Система в любом случае не позволит увидеть чужие данные, поэтому не важно"],"c":1,"why":"Даже с благими намерениями обход ограничения доступа нарушает правила и должен согласовываться через руководителя."},"uz":{"q":"own_only huquqiga ega broker rahbar bilan kelishmasdan hamkasbining bitimini tizimda 'yordam berish' uchun qidirmoqda. Bu qanday baholanadi?","a":["Niyat yaxshi bo'lsa, bu normal holat","Bu kirish tamoyilining buzilishi va to'g'ridan-to'g'ri emas, rahbar orqali hal qilinishi kerak","Tizim baribir begona ma'lumotlarni ko'rsatmaydi, shuning uchun ahamiyati yo'q"],"c":1,"why":"Yaxshi niyatga qaramay, kirish cheklovini chetlab o'tish qoidabuzarlik hisoblanadi va rahbar orqali kelishilishi kerak."},"en":{"q":"A broker with own_only access tries to look up a colleague's deal to 'help' without manager approval. How should this be viewed?","a":["This is fine as long as the intentions are good","This violates the access principle and should be routed through the manager instead","It doesn't matter since the system wouldn't show others' data anyway"],"c":1,"why":"Even with good intentions, bypassing access restrictions violates policy and should be handled through the manager."}},{"id":"CR048","cat":"crm","logic":false,"ru":{"q":"Почему принцип own_only считается полезным для оценки KPI и комиссий брокеров?","a":["Он усложняет работу без всякой пользы","Он обеспечивает прозрачное и однозначное закрепление результата за конкретным брокером","Он нужен только для IT-отдела"],"c":1,"why":"own_only исключает путаницу в авторстве сделок, что критично для корректного расчёта KPI и комиссии."},"uz":{"q":"own_only tamoyili nima uchun brokerlar KPI va komissiyasini baholash uchun foydali hisoblanadi?","a":["U hech qanday foydasiz ishni murakkablashtiradi","U natijani aniq brokerga shaffof va bir ma'noda biriktirishni ta'minlaydi","U faqat IT bo'limi uchun kerak"],"c":1,"why":"own_only bitim muallifligidagi chalkashlikni bartaraf etadi, bu esa KPI va komissiyani to'g'ri hisoblash uchun muhim."},"en":{"q":"Why is the own_only principle considered useful for evaluating broker KPIs and commissions?","a":["It adds complexity with no real benefit","It ensures transparent, unambiguous attribution of results to a specific broker","It exists solely for the IT department's convenience"],"c":1,"why":"own_only eliminates ambiguity over deal ownership, which is essential for accurate KPI and commission calculation."}},{"id":"CR049","cat":"crm","logic":false,"ru":{"q":"Арендатор запрашивает арендные каникулы на 2 месяца сверх стандартной политики ТРЦ. Каким должен быть первый шаг брокера?","a":["Самостоятельно одобрить каникулы, чтобы ускорить сделку","Зафиксировать запрос и вынести его на согласование руководству с обоснованием","Отказать без передачи информации руководству"],"c":1,"why":"Запрос сверх стандартных условий требует эскалации с обоснованием, а не единоличного решения брокера."},"uz":{"q":"Ijarachi TSMning standart siyosatidan tashqari 2 oylik ijara ta'tilini so'ramoqda. Brokerning birinchi qadami qanday bo'lishi kerak?","a":["Bitimni tezlashtirish uchun ta'tilni mustaqil tasdiqlash","So'rovni qayd etib, asoslash bilan rahbariyatga tasdiqlash uchun taqdim etish","Rahbariyatga ma'lumot bermasdan rad javobi berish"],"c":1,"why":"Standart shartlardan tashqari so'rov brokerning yakka o'zi emas, asoslash bilan eskalatsiyani talab qiladi."},"en":{"q":"A tenant requests a 2-month rent-free period beyond the mall's standard policy. What should the broker do first?","a":["Approve the rent-free period independently to speed up the deal","Log the request and escalate it to management with supporting rationale","Reject it without informing management at all"],"c":1,"why":"Requests beyond standard policy require escalation with justification rather than a unilateral broker decision."}},{"id":"CR050","cat":"crm","logic":false,"ru":{"q":"Какой из перечисленных факторов наиболее корректно влияет на итоговый размер комиссии брокера при равном объёме сделки?","a":["Личная симпатия руководителя к брокеру","Соблюдение внутренней методологии расчёта (ставка комиссии, срок договора, условия оплаты)","Количество лет работы арендатора на рынке"],"c":1,"why":"Размер комиссии определяется утверждённой методологией расчёта, а не субъективными или посторонними факторами."},"uz":{"q":"Bitim hajmi bir xil bo'lganda, quyidagilardan qaysi biri broker komissiyasining yakuniy miqdoriga to'g'ri ta'sir qiladi?","a":["Rahbarning brokerga shaxsiy nisbati","Ichki hisoblash metodologiyasiga rioya qilish (komissiya stavkasi, shartnoma muddati, to'lov shartlari)","Ijarachining bozorda ishlagan yillar soni"],"c":1,"why":"Komissiya miqdori tasdiqlangan hisoblash metodologiyasi bilan belgilanadi, sub'ektiv yoki bog'liq bo'lmagan omillar bilan emas."},"en":{"q":"For deals of equal size, which factor should correctly determine the final broker commission amount?","a":["The manager's personal rapport with the broker","Adherence to the approved calculation methodology (commission rate, term, payment terms)","How many years the tenant brand has operated in the market"],"c":1,"why":"Commission amount should be governed by the approved calculation methodology, not subjective or unrelated factors."}},{"id":"FN001","cat":"finance","logic":false,"ru":{"q":"Что означает показатель NOI (чистый операционный доход) в управлении ТРЦ?","a":["Доход от аренды за вычетом операционных расходов","Валовая выручка всех арендаторов","Сумма всех капитальных вложений"],"c":0,"why":"NOI — это доход от операционной деятельности объекта после вычета операционных расходов, но до уплаты налогов и обслуживания долга."},"uz":{"q":"ТРЦ boshqaruvida NOI (sof operatsion daromad) ko'rsatkichi nimani anglatadi?","a":["Ijaradan tushgan daromaddan operatsion xarajatlar ayirilgani","Barcha ijarachilarning yalpi tushumi","Barcha kapital investitsiyalar summasi"],"c":0,"why":"NOI — bu obyektning operatsion xarajatlar ayirilgandan keyingi, lekin soliq va qarz xizmati to'languncha bo'lgan daromadi."},"en":{"q":"What does NOI (Net Operating Income) represent in shopping mall management?","a":["Rental income minus operating expenses","Total gross revenue of all tenants","The sum of all capital investments"],"c":0,"why":"NOI is the income remaining after operating expenses are deducted, before taxes and debt service."}},{"id":"FN002","cat":"finance","logic":false,"ru":{"q":"Как рассчитывается cap rate (ставка капитализации) объекта недвижимости?","a":["Цена объекта минус NOI","NOI, разделённый на стоимость объекта","Арендная плата, умноженная на площадь"],"c":1,"why":"Ставка капитализации показывает доходность объекта и равна отношению NOI к его рыночной стоимости."},"uz":{"q":"Ko'chmas mulk obyektining cap rate (kapitallashtirish stavkasi) qanday hisoblanadi?","a":["Obyekt narxidan NOI ayirilgani","NOI obyekt qiymatiga bo'lingani","Ijara to'lovi maydonga ko'paytirilgani"],"c":1,"why":"Kapitallashtirish stavkasi obyekt daromadliligini ko'rsatadi va NOI ning bozor qiymatiga nisbati sifatida topiladi."},"en":{"q":"How is the cap rate (capitalization rate) of a property calculated?","a":["Property price minus NOI","NOI divided by the property value","Rent multiplied by leasable area"],"c":1,"why":"The cap rate measures a property's yield and equals NOI divided by its market value."}},{"id":"FN003","cat":"finance","logic":false,"ru":{"q":"Что показывает Occupancy Cost Ratio (OCR) для арендатора в ТРЦ?","a":["Долю арендных и сопутствующих затрат в его товарообороте","Процент свободных площадей в галерее","Соотношение зала к подсобным помещениям"],"c":0,"why":"OCR отражает, какую долю от выручки арендатора составляют его расходы на аренду и связанные платежи."},"uz":{"q":"ТРЦ dagi ijarachi uchun Occupancy Cost Ratio (OCR) nimani ko'rsatadi?","a":["Ijara va unga bog'liq xarajatlarning aylanmadagi ulushini","Galereyadagi bo'sh maydonlar foizini","Savdo zali va yordamchi xonalar nisbatini"],"c":0,"why":"OCR ijarachining aylanmasidan qancha qismi ijara va bog'liq to'lovlarga sarflanishini ko'rsatadi."},"en":{"q":"What does the Occupancy Cost Ratio (OCR) measure for a mall tenant?","a":["The share of rent and related costs in tenant sales","The percentage of vacant units in the gallery","The ratio of sales floor to back-office space"],"c":0,"why":"OCR shows what portion of a tenant's turnover is spent on rent and associated occupancy costs."}},{"id":"FN004","cat":"finance","logic":false,"ru":{"q":"Какой показатель обычно считается комфортным уровнем OCR для арендатора формата фэшн-ритейл?","a":["1-3%","8-15%","45-50%"],"c":1,"why":"Для большинства фэшн-ритейлеров приемлемым считается OCR в диапазоне примерно 8-15%."},"uz":{"q":"Fashion-ritel formatidagi ijarachi uchun qulay OCR darajasi odatda qanday hisoblanadi?","a":["1-3%","8-15%","45-50%"],"c":1,"why":"Ko'pchilik fashion-ritel ijarachilar uchun taxminan 8-15% oralig'idagi OCR maqbul hisoblanadi."},"en":{"q":"What OCR range is generally considered comfortable for a fashion retail tenant?","a":["1-3%","8-15%","45-50%"],"c":1,"why":"For most fashion retailers, an OCR of roughly 8-15% is considered a healthy benchmark."}},{"id":"FN005","cat":"finance","logic":false,"ru":{"q":"Если арендатор занимает 50 м² и платит 30$/м² в месяц, какова его базовая месячная арендная плата?","a":["150$","1500$","15000$"],"c":1,"why":"50 м² умножить на 30$/м² равно 1500$ в месяц."},"uz":{"q":"Agar ijarachi 50 m² maydonni egallab, oyiga 30$/m² to'lasa, uning bazaviy oylik ijara to'lovi qancha bo'ladi?","a":["150$","1500$","15000$"],"c":1,"why":"50 m² ni 30$/m² ga ko'paytirsak, oyiga 1500$ chiqadi."},"en":{"q":"If a tenant occupies 50 sqm at a rate of $30/sqm per month, what is the base monthly rent?","a":["$150","$1,500","$15,000"],"c":1,"why":"50 sqm multiplied by $30/sqm equals $1,500 per month."}},{"id":"FN006","cat":"finance","logic":false,"ru":{"q":"Что такое service charge (эксплуатационный платёж) в договоре аренды ТРЦ?","a":["Компенсация затрат на общее содержание и эксплуатацию здания","Единоразовый штраф за просрочку оплаты","Процент от товарооборота арендатора"],"c":0,"why":"Service charge покрывает расходы на содержание, уборку, охрану и эксплуатацию общих зон здания."},"uz":{"q":"ТРЦ ijara shartnomasidagi service charge (ekspluatatsion to'lov) nima?","a":["Binoning umumiy saqlash va ekspluatatsiya xarajatlarini qoplash","To'lov kechiktirilgani uchun bir martalik jarima","Ijarachi aylanmasidan foiz"],"c":0,"why":"Service charge binoning umumiy zonalarini tozalash, saqlash va ekspluatatsiya qilish xarajatlarini qoplaydi."},"en":{"q":"What is a service charge in a shopping mall lease agreement?","a":["Reimbursement for common area maintenance and building operations","A one-time penalty for late payment","A percentage of tenant turnover"],"c":0,"why":"The service charge covers cleaning, security, maintenance, and operation of common areas."}},{"id":"FN007","cat":"finance","logic":false,"ru":{"q":"Что представляет собой turnover rent (процент от товарооборота)?","a":["Фиксированную сумму аренды, не зависящую от продаж","Часть арендной платы, рассчитанную как процент от выручки арендатора","Плату за коммунальные услуги"],"c":1,"why":"Turnover rent — это дополнительная или альтернативная форма арендной платы, привязанная к проценту от продаж арендатора."},"uz":{"q":"Turnover rent (aylanmadan foiz) nimani anglatadi?","a":["Savdodan bog'liq bo'lmagan qat'iy ijara summasi","Ijarachi tushumidan foiz sifatida hisoblangan ijara qismi","Kommunal xizmatlar uchun to'lov"],"c":1,"why":"Turnover rent — ijarachi savdo tushumining foiziga bog'langan qo'shimcha yoki muqobil ijara turi."},"en":{"q":"What is turnover rent (percentage-of-sales rent)?","a":["A fixed rent amount unrelated to sales","A portion of rent calculated as a percentage of tenant sales","A charge for utility consumption"],"c":1,"why":"Turnover rent is rent linked to a percentage of the tenant's sales revenue, often supplementing base rent."}},{"id":"FN008","cat":"finance","logic":false,"ru":{"q":"В схеме аренды с natural breakpoint, при каком условии начинает применяться turnover rent?","a":["Когда товарооборот арендатора превышает уровень, при котором процент от продаж равен базовой аренде","С первого дня действия договора аренды","Только после окончания срока договора"],"c":0,"why":"Natural breakpoint — это уровень товарооборота, при котором сумма процента от продаж сравнивается с базовой арендой; свыше него начисляется turnover rent."},"uz":{"q":"Natural breakpoint sxemasida turnover rent qachon qo'llanila boshlaydi?","a":["Ijarachi aylanmasi foiz summasi bazaviy ijaraga teng bo'lgan darajadan oshganda","Shartnoma imzolangan birinchi kunidanoq","Faqat shartnoma muddati tugagandan keyin"],"c":0,"why":"Natural breakpoint — foiz summasi bazaviy ijaraga teng bo'ladigan aylanma darajasi, undan yuqorisida turnover rent hisoblanadi."},"en":{"q":"In a natural breakpoint lease structure, when does turnover rent start to apply?","a":["When tenant sales exceed the level where the percentage rent equals base rent","From the very first day of the lease","Only after the lease term expires"],"c":0,"why":"The natural breakpoint is the sales level at which percentage rent equals base rent; turnover rent applies above that threshold."}},{"id":"FN009","cat":"finance","logic":false,"ru":{"q":"Что такое yield (доходность) применительно к инвестициям в торговую недвижимость?","a":["Отношение годового дохода от объекта к вложенному капиталу","Общая площадь торговых помещений","Количество арендаторов в объекте"],"c":0,"why":"Yield выражает годовую доходность инвестиций как отношение дохода к сумме вложенных средств."},"uz":{"q":"Savdo ko'chmas mulkiga investitsiyalar uchun yield (daromadlilik) nimani bildiradi?","a":["Obyektdan yillik daromadning kiritilgan kapitalga nisbati","Savdo maydonlarining umumiy hajmi","Obyektdagi ijarachilar soni"],"c":0,"why":"Yield investitsiyaning yillik daromadliligini kiritilgan kapitalga nisbat sifatida ifodalaydi."},"en":{"q":"What does yield mean in the context of retail real estate investment?","a":["The ratio of annual income from the asset to invested capital","The total leasable retail area","The number of tenants in the property"],"c":0,"why":"Yield expresses annual investment return as the ratio of income to capital invested."}},{"id":"FN010","cat":"finance","logic":false,"ru":{"q":"Что означает срок окупаемости (payback period) проекта реконструкции ТРЦ?","a":["Время, за которое дополнительный доход покроет затраты на реконструкцию","Период гарантии на строительные работы","Срок действия договоров аренды после ремонта"],"c":0,"why":"Payback period показывает, за сколько времени сгенерированный дополнительный доход возместит вложенные в реконструкцию инвестиции."},"uz":{"q":"ТРЦ rekonstruksiyasi loyihasida payback period (o'zini oqlash muddati) nimani anglatadi?","a":["Qo'shimcha daromad rekonstruksiya xarajatlarini qoplaydigan vaqt","Qurilish ishlariga berilgan kafolat muddati","Ta'mirdan keyingi ijara shartnomalari amal qilish muddati"],"c":0,"why":"Payback period rekonstruksiyaga kiritilgan investitsiyalarni qo'shimcha daromad qancha vaqtda qoplashini ko'rsatadi."},"en":{"q":"What does the payback period of a mall renovation project mean?","a":["The time needed for additional income to cover renovation costs","The warranty period for construction works","The duration of lease agreements after renovation"],"c":0,"why":"The payback period is the time required for the extra income generated to recover the investment made in renovation."}},{"id":"FN011","cat":"finance","logic":false,"ru":{"q":"Как рассчитывается уровень вакантности (vacancy rate) в ТРЦ?","a":["Площадь свободных помещений, делённая на общую арендопригодную площадь","Количество посетителей в день, делённое на число арендаторов","Сумма арендной платы, делённая на площадь"],"c":0,"why":"Vacancy rate — это доля незанятых арендопригодных площадей от общей GLA объекта."},"uz":{"q":"ТРЦ dagi vacancy rate (bo'shliq darajasi) qanday hisoblanadi?","a":["Bo'sh maydonlarning umumiy ijaraga yaroqli maydonga nisbati","Kunlik tashrif buyuruvchilar sonining ijarachilar soniga nisbati","Ijara to'lovi summasining maydonga nisbati"],"c":0,"why":"Vacancy rate — obyektning umumiy GLA sidan band bo'lmagan maydonlar ulushini bildiradi."},"en":{"q":"How is the vacancy rate in a shopping mall calculated?","a":["Vacant leasable area divided by total gross leasable area","Daily footfall divided by the number of tenants","Total rent collected divided by area"],"c":0,"why":"Vacancy rate is the share of unoccupied leasable area relative to the total GLA of the property."}},{"id":"FN012","cat":"finance","logic":false,"ru":{"q":"Как рост вакантности площадей напрямую влияет на финансовые показатели ТРЦ?","a":["Увеличивает NOI за счёт экономии на service charge","Снижает арендный доход и, следовательно, NOI объекта","Не влияет на доход, только на посещаемость"],"c":1,"why":"Незанятые площади не приносят арендного дохода, что напрямую сокращает выручку и NOI объекта."},"uz":{"q":"Bo'sh maydonlar ko'payishi ТРЦ moliyaviy ko'rsatkichlariga qanday to'g'ridan-to'g'ri ta'sir qiladi?","a":["Service charge dan tejalgani hisobiga NOI ni oshiradi","Ijara daromadini va shu bilan NOI ni kamaytiradi","Daromadga ta'sir qilmaydi, faqat tashrifga ta'sir qiladi"],"c":1,"why":"Band bo'lmagan maydonlar ijara daromadi keltirmaydi, bu esa obyekt tushumi va NOI sini to'g'ridan-to'g'ri kamaytiradi."},"en":{"q":"How does rising vacancy directly affect a mall's financial performance?","a":["It increases NOI through service charge savings","It reduces rental income and therefore the property's NOI","It has no effect on income, only on foot traffic"],"c":1,"why":"Vacant space generates no rental income, which directly reduces revenue and NOI."}},{"id":"FN013","cat":"finance","logic":false,"ru":{"q":"Что подразумевается под анализом отклонений факта от бюджета (budget vs actual variance)?","a":["Сравнение плановых и фактических финансовых показателей за период","Расчёт стоимости объекта на основе будущих доходов","Оценку кредитоспособности арендатора"],"c":0,"why":"Budget vs actual variance — это сопоставление запланированных и реально достигнутых показателей для выявления отклонений."},"uz":{"q":"Budget vs actual variance (byudjet va haqiqiy ko'rsatkichlar farqi) tahlili nimani anglatadi?","a":["Davr uchun reja va haqiqiy moliyaviy ko'rsatkichlarni solishtirish","Kelajakdagi daromadlar asosida obyekt qiymatini hisoblash","Ijarachining kredit qobiliyatini baholash"],"c":0,"why":"Budget vs actual variance — rejalashtirilgan va haqiqatda erishilgan ko'rsatkichlarni solishtirib, farqlarni aniqlash."},"en":{"q":"What does budget vs actual variance analysis involve?","a":["Comparing planned and actual financial results for a period","Calculating asset value based on future income","Assessing a tenant's creditworthiness"],"c":0,"why":"Budget vs actual variance compares planned figures against actual results to identify deviations."}},{"id":"FN014","cat":"finance","logic":false,"ru":{"q":"Фактический доход ТРЦ за месяц составил 90 000$ при плане 100 000$. Каково отклонение (variance) в процентах?","a":["+10%","-10%","-90%"],"c":1,"why":"Отклонение считается как (факт - план) / план = (90000-100000)/100000 = -10%."},"uz":{"q":"ТРЦ ning oylik haqiqiy daromadi 90 000$ ni tashkil etdi, reja esa 100 000$ edi. Foizdagi farq (variance) qancha?","a":["+10%","-10%","-90%"],"c":1,"why":"Farq (haqiqiy - reja) / reja = (90000-100000)/100000 = -10% sifatida hisoblanadi."},"en":{"q":"A mall's actual monthly income was $90,000 against a budget of $100,000. What is the variance?","a":["+10%","-10%","-90%"],"c":1,"why":"Variance = (actual - budget) / budget = (90,000-100,000)/100,000 = -10%."}},{"id":"FN015","cat":"finance","logic":false,"ru":{"q":"Как оценивается ROI (рентабельность инвестиций) реконструкции торговой галереи?","a":["Как отношение прироста дохода после ремонта к затратам на реконструкцию","Как площадь отремонтированных помещений в квадратных метрах","Как количество новых арендаторов, привлечённых за год"],"c":0,"why":"ROI реконструкции показывает, насколько дополнительный доход или прирост стоимости объекта соотносится с вложенными в неё инвестициями."},"uz":{"q":"Savdo galereyasini rekonstruksiya qilishning ROI (investitsiya rentabelligi) qanday baholanadi?","a":["Ta'mirdan keyingi daromad o'sishining rekonstruksiya xarajatlariga nisbati sifatida","Ta'mirlangan xonalarning kvadrat metrdagi maydoni sifatida","Yil davomida jalb qilingan yangi ijarachilar soni sifatida"],"c":0,"why":"Rekonstruksiya ROI si qo'shimcha daromad yoki obyekt qiymati o'sishining kiritilgan investitsiyalarga nisbatini ko'rsatadi."},"en":{"q":"How is the ROI of a mall renovation project typically evaluated?","a":["As the ratio of post-renovation income increase to renovation cost","As the renovated area measured in square meters","As the number of new tenants signed within a year"],"c":0,"why":"Renovation ROI measures how the additional income or value uplift compares to the capital invested in the renovation."}},{"id":"FN016","cat":"finance","logic":false,"ru":{"q":"Что показывает fill rate (уровень заполняемости) торгового центра?","a":["Долю фактически сданных в аренду площадей от общей GLA","Средний чек посетителя торгового центра","Число арендаторов, расторгнувших договор за год"],"c":0,"why":"Fill rate (occupancy rate) — это процент арендопригодной площади, фактически занятой арендаторами."},"uz":{"q":"Savdo markazining fill rate (band bo'lish darajasi) nimani ko'rsatadi?","a":["Umumiy GLA dan haqiqatda ijaraga berilgan maydonlar ulushini","Savdo markazi tashrifchisining o'rtacha chekini","Yil davomida shartnomani bekor qilgan ijarachilar sonini"],"c":0,"why":"Fill rate (occupancy rate) — ijaraga yaroqli maydonning haqiqatda band qilingan qismi foizini bildiradi."},"en":{"q":"What does the fill rate (occupancy rate) of a shopping mall indicate?","a":["The share of GLA actually leased to tenants","The average purchase value per visitor","The number of tenants who terminated leases in a year"],"c":0,"why":"The fill rate (occupancy rate) is the percentage of leasable area actually occupied by tenants."}},{"id":"FN017","cat":"finance","logic":false,"ru":{"q":"Если из 20 000 м² GLA сдано в аренду 18 000 м², чему равен fill rate?","a":["10%","90%","111%"],"c":1,"why":"18000/20000 = 0.9, то есть 90% площадей заняты арендаторами."},"uz":{"q":"Agar 20 000 m² GLA dan 18 000 m² ijaraga berilgan bo'lsa, fill rate qancha bo'ladi?","a":["10%","90%","111%"],"c":1,"why":"18000/20000 = 0.9, ya'ni maydonlarning 90% i ijarachilar tomonidan band qilingan."},"en":{"q":"If 18,000 sqm out of 20,000 sqm of GLA is leased, what is the fill rate?","a":["10%","90%","111%"],"c":1,"why":"18,000/20,000 = 0.9, meaning 90% of the space is occupied by tenants."}},{"id":"FN018","cat":"finance","logic":false,"ru":{"q":"Что понимается под arrears (задолженность по арендной плате)?","a":["Просроченные и неоплаченные арендатором платежи","Скидка, предоставленная арендатору при подписании договора","Плановое повышение арендной ставки"],"c":0,"why":"Arrears — это сумма просроченной задолженности арендатора по арендным и иным платежам."},"uz":{"q":"Arrears (ijara to'lovi bo'yicha qarzdorlik) deganda nima tushuniladi?","a":["Ijarachi tomonidan muddati o'tgan va to'lanmagan to'lovlar","Shartnoma imzolanganda ijarachiga berilgan chegirma","Ijara stavkasining rejalashtirilgan oshishi"],"c":0,"why":"Arrears — ijarachining ijara va boshqa to'lovlar bo'yicha muddati o'tgan qarzdorligi summasidir."},"en":{"q":"What are arrears in the context of rent payments?","a":["Overdue and unpaid amounts owed by a tenant","A discount granted to a tenant at lease signing","A scheduled increase in the rental rate"],"c":0,"why":"Arrears refer to the overdue, unpaid balance a tenant owes on rent or related charges."}},{"id":"FN019","cat":"finance","logic":false,"ru":{"q":"Почему высокий уровень arrears опасен для управляющей компании ТРЦ?","a":["Он ухудшает денежный поток и может снизить фактический NOI","Он автоматически увеличивает стоимость объекта","Он не влияет на финансовое состояние, только на отчётность"],"c":0,"why":"Рост просроченной задолженности ухудшает поступление денежных средств и фактически снижает реализуемый доход объекта."},"uz":{"q":"Nega yuqori arrears darajasi ТРЦ boshqaruv kompaniyasi uchun xavfli hisoblanadi?","a":["Pul oqimini yomonlashtiradi va haqiqiy NOI ni kamaytirishi mumkin","Bu avtomatik ravishda obyekt qiymatini oshiradi","Moliyaviy holatga ta'sir qilmaydi, faqat hisobotga ta'sir qiladi"],"c":0,"why":"Qarzdorlikning o'sishi pul tushumini yomonlashtiradi va obyektning amaldagi daromadini pasaytiradi."},"en":{"q":"Why is a high level of arrears risky for a mall's management company?","a":["It worsens cash flow and can reduce realized NOI","It automatically increases the property's value","It has no financial impact, only affects reporting"],"c":0,"why":"Rising overdue debt weakens cash collection and effectively reduces the income actually realized by the property."}},{"id":"FN020","cat":"finance","logic":false,"ru":{"q":"В чём разница между gross rent (валовой арендой) и net rent (чистой арендой)?","a":["Gross rent включает эксплуатационные расходы, net rent — нет","Net rent всегда выше gross rent","Разницы нет, это синонимы одного понятия"],"c":0,"why":"Gross rent обычно включает базовую ставку плюс операционные расходы (service charge), тогда как net rent — это чистая базовая ставка без них."},"uz":{"q":"Gross rent (yalpi ijara) va net rent (sof ijara) o'rtasidagi farq nimada?","a":["Gross rent ekspluatatsion xarajatlarni o'z ichiga oladi, net rent esa yo'q","Net rent doim gross rent dan yuqori bo'ladi","Farqi yo'q, ular bir tushunchaning sinonimlari"],"c":0,"why":"Gross rent odatda bazaviy stavka va operatsion xarajatlarni (service charge) o'z ichiga oladi, net rent esa faqat sof bazaviy stavkadir."},"en":{"q":"What is the difference between gross rent and net rent?","a":["Gross rent includes operating expenses, net rent does not","Net rent is always higher than gross rent","There is no difference; they are synonyms"],"c":0,"why":"Gross rent typically includes the base rate plus operating costs (service charge), while net rent is the base rate alone."}},{"id":"FN021","cat":"finance","logic":false,"ru":{"q":"Что показывает operating expense ratio (коэффициент операционных расходов)?","a":["Долю операционных расходов в общем доходе от объекта","Количество квадратных метров на одного сотрудника","Процент арендаторов, продливших договор"],"c":0,"why":"Operating expense ratio отражает, какую часть валового дохода объекта съедают операционные расходы."},"uz":{"q":"Operating expense ratio (operatsion xarajatlar koeffitsienti) nimani ko'rsatadi?","a":["Obyektning umumiy daromadidagi operatsion xarajatlar ulushini","Bir xodimga to'g'ri keladigan kvadrat metrlar sonini","Shartnomani uzaytirgan ijarachilar foizini"],"c":0,"why":"Operating expense ratio obyektning yalpi daromadidan qancha qismi operatsion xarajatlarga sarflanishini ko'rsatadi."},"en":{"q":"What does the operating expense ratio measure?","a":["The share of operating expenses relative to total property income","The number of square meters per employee","The percentage of tenants who renewed their lease"],"c":0,"why":"The operating expense ratio shows what portion of a property's gross income is consumed by operating costs."}},{"id":"FN022","cat":"finance","logic":false,"ru":{"q":"Валовой доход ТРЦ — 200 000$, операционные расходы — 60 000$. Чему равен operating expense ratio?","a":["30%","60%","140%"],"c":0,"why":"60000/200000 = 0.3, то есть 30% валового дохода уходит на операционные расходы."},"uz":{"q":"ТРЦ ning yalpi daromadi 200 000$, operatsion xarajatlari 60 000$. Operating expense ratio qancha bo'ladi?","a":["30%","60%","140%"],"c":0,"why":"60000/200000 = 0.3, ya'ni yalpi daromadning 30% i operatsion xarajatlarga sarflanadi."},"en":{"q":"A mall's gross income is $200,000 and operating expenses are $60,000. What is the operating expense ratio?","a":["30%","60%","140%"],"c":0,"why":"60,000/200,000 = 0.3, meaning 30% of gross income goes toward operating expenses."}},{"id":"FN023","cat":"finance","logic":false,"ru":{"q":"Почему средний показатель арендной платы за м² важен при бенчмаркинге ТРЦ?","a":["Он позволяет сравнивать доходность объекта с конкурентами независимо от размера","Он определяет количество парковочных мест","Он заменяет собой расчёт NOI"],"c":0,"why":"Средняя ставка за м² — универсальный показатель, позволяющий сопоставлять доходность объектов разного масштаба."},"uz":{"q":"Nega o'rtacha ijara narxi (m² uchun) ТРЦ larni benchmarking qilishda muhim hisoblanadi?","a":["U obyekt daromadliligini hajmidan qat'i nazar raqobatchilar bilan solishtirish imkonini beradi","U avtoturargoh joylari sonini belgilaydi","U NOI hisobini o'rnini bosadi"],"c":0,"why":"M² uchun o'rtacha stavka - turli hajmdagi obyektlar daromadliligini solishtirish imkonini beruvchi universal ko'rsatkich."},"en":{"q":"Why is average rent per sqm important for benchmarking shopping malls?","a":["It allows comparing property performance with competitors regardless of size","It determines the number of parking spaces required","It replaces the need to calculate NOI"],"c":0,"why":"Average rent per sqm is a universal metric that enables comparison of income performance across properties of different sizes."}},{"id":"FN024","cat":"finance","logic":false,"ru":{"q":"Арендатор с товарооборотом 50 000$ в месяц платит 6 000$ совокупных арендных расходов. Каков его OCR?","a":["8.3%","12%","83%"],"c":1,"why":"6000/50000 = 0.12, то есть OCR составляет 12%."},"uz":{"q":"Oyiga 50 000$ aylanmaga ega ijarachi jami 6 000$ ijara xarajatlarini to'laydi. Uning OCR qancha?","a":["8.3%","12%","83%"],"c":1,"why":"6000/50000 = 0.12, ya'ni OCR 12% ni tashkil etadi."},"en":{"q":"A tenant with $50,000 monthly turnover pays $6,000 in total occupancy costs. What is their OCR?","a":["8.3%","12%","83%"],"c":1,"why":"6,000/50,000 = 0.12, meaning the OCR is 12%."}},{"id":"FN025","cat":"finance","logic":false,"ru":{"q":"Как обычно классифицируется расчёт service charge между арендаторами ТРЦ?","a":["Пропорционально арендуемой площади каждого арендатора","Поровну между всеми арендаторами независимо от площади","На усмотрение каждого арендатора самостоятельно"],"c":0,"why":"Service charge обычно распределяется пропорционально доле занимаемой арендатором площади в общей GLA."},"uz":{"q":"ТРЦ ijarachilar o'rtasida service charge odatda qanday taqsimlanadi?","a":["Har bir ijarachining egallagan maydoniga mutanosib ravishda","Maydonidan qat'i nazar barcha ijarachilar o'rtasida teng ravishda","Har bir ijarachi o'zi mustaqil belgilaydi"],"c":0,"why":"Service charge odatda ijarachining umumiy GLA dagi egallagan maydon ulushiga mutanosib taqsimlanadi."},"en":{"q":"How is the service charge typically allocated among mall tenants?","a":["Proportionally to each tenant's leased area","Equally among all tenants regardless of area","At each tenant's own discretion"],"c":0,"why":"The service charge is usually allocated in proportion to each tenant's share of the total GLA."}},{"id":"FN026","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного является ключевой причиной ежемесячного отслеживания budget vs actual в ТРЦ?","a":["Своевременное выявление отклонений и корректировка управленческих решений","Формальное требование налоговой отчётности","Определение размера штрафа для арендаторов"],"c":0,"why":"Регулярный контроль отклонений факта от бюджета позволяет вовремя выявлять проблемы и принимать корректирующие меры."},"uz":{"q":"ТРЦ da har oylik budget vs actual monitoringining asosiy sababi nima?","a":["Farqlarni o'z vaqtida aniqlab, boshqaruv qarorlarini tuzatish","Soliq hisobotining rasmiy talabi","Ijarachilar uchun jarima miqdorini belgilash"],"c":0,"why":"Reja va haqiqiy ko'rsatkichlar farqini muntazam kuzatish muammolarni o'z vaqtida aniqlash va tuzatish choralarini ko'rish imkonini beradi."},"en":{"q":"What is a key reason for tracking budget vs actual monthly in mall operations?","a":["To detect deviations early and adjust management decisions","It is a formal tax reporting requirement","To determine the penalty amount for tenants"],"c":0,"why":"Regular monitoring of budget variance allows management to spot issues early and take corrective action."}},{"id":"FN027","cat":"finance","logic":false,"ru":{"q":"Какой из показателей напрямую используется для оценки рыночной стоимости доходной недвижимости методом капитализации?","a":["Cap rate и NOI","Fill rate и площадь парковки","Количество арендаторов и их бренды"],"c":0,"why":"Метод капитализации дохода определяет стоимость объекта как NOI, делённый на cap rate."},"uz":{"q":"Daromadli ko'chmas mulkning bozor qiymatini kapitallashtirish usulida baholashda qaysi ko'rsatkichlar to'g'ridan-to'g'ri ishlatiladi?","a":["Cap rate va NOI","Fill rate va avtoturargoh maydoni","Ijarachilar soni va ularning brendlari"],"c":0,"why":"Daromadni kapitallashtirish usuli obyekt qiymatini NOI ni cap rate ga bo'lish orqali aniqlaydi."},"en":{"q":"Which metrics are directly used to estimate an income property's market value via the income capitalization method?","a":["Cap rate and NOI","Fill rate and parking area","Number of tenants and their brands"],"c":0,"why":"The income capitalization approach values a property as NOI divided by the cap rate."}},{"id":"FN028","cat":"finance","logic":false,"ru":{"q":"Реконструкция галереи стоит 200 000$ и приносит дополнительно 40 000$ дохода в год. Каков простой срок окупаемости?","a":["2 года","5 лет","8 лет"],"c":1,"why":"200000/40000 = 5 лет — именно за такой срок дополнительный доход покроет затраты."},"uz":{"q":"Galereyani rekonstruksiya qilish 200 000$ turadi va yiliga qo'shimcha 40 000$ daromad beradi. Oddiy o'zini oqlash muddati qancha?","a":["2 yil","5 yil","8 yil"],"c":1,"why":"200000/40000 = 5 yil — aynan shu muddatda qo'shimcha daromad xarajatlarni qoplaydi."},"en":{"q":"A gallery renovation costs $200,000 and generates an additional $40,000 in income per year. What is the simple payback period?","a":["2 years","5 years","8 years"],"c":1,"why":"200,000/40,000 = 5 years, the time needed for the extra income to recoup the investment."}},{"id":"FN029","cat":"finance","logic":false,"ru":{"q":"Почему аналитики ТРЦ отслеживают динамику arrears по каждому арендатору, а не только общую сумму?","a":["Это позволяет выявить проблемных арендаторов и риски досрочного расторжения","Общая сумма не имеет значения для управления","Это требуется только для маркетинговой отчётности"],"c":0,"why":"Отслеживание задолженности по каждому арендатору помогает своевременно выявить финансовые трудности конкретного арендатора."},"uz":{"q":"Nega ТРЦ tahlilchilari har bir ijarachi bo'yicha arrears dinamikasini, nafaqat umumiy summani kuzatadi?","a":["Bu muammoli ijarachilarni va muddatidan oldin bekor qilish xavfini aniqlashga yordam beradi","Umumiy summa boshqaruv uchun ahamiyatsiz","Bu faqat marketing hisobotlari uchun talab qilinadi"],"c":0,"why":"Har bir ijarachi bo'yicha qarzdorlikni kuzatish muayyan ijarachining moliyaviy qiyinchiliklarini o'z vaqtida aniqlashga yordam beradi."},"en":{"q":"Why do mall analysts track arrears trends per tenant rather than only the total amount?","a":["It helps identify problem tenants and risks of early lease termination","The total figure is irrelevant to management","It is only required for marketing reports"],"c":0,"why":"Tracking arrears by individual tenant helps identify financial trouble with a specific tenant early."}},{"id":"FN030","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного корректно описывает разницу между fill rate и OCR?","a":["Fill rate измеряет заполняемость площадей, OCR — нагрузку аренды на бизнес арендатора","Fill rate и OCR — это два названия одного и того же показателя","Fill rate рассчитывается для арендатора, а OCR — для всего здания"],"c":0,"why":"Fill rate — показатель заполняемости объекта арендаторами, а OCR — показатель финансовой нагрузки аренды на выручку конкретного арендатора."},"uz":{"q":"Fill rate va OCR o'rtasidagi farqni qaysi variant to'g'ri tavsiflaydi?","a":["Fill rate maydonlar bandligini, OCR esa ijaraning ijarachi biznesiga yukini o'lchaydi","Fill rate va OCR bir xil ko'rsatkichning ikki nomi","Fill rate ijarachi uchun, OCR esa butun bino uchun hisoblanadi"],"c":0,"why":"Fill rate obyektning ijarachilar bilan bandlik darajasini, OCR esa ijaraning muayyan ijarachi tushumiga solgan moliyaviy yukini ko'rsatadi."},"en":{"q":"Which statement correctly describes the difference between fill rate and OCR?","a":["Fill rate measures space occupancy, OCR measures rent burden on tenant sales","Fill rate and OCR are two names for the same metric","Fill rate is calculated per tenant, OCR for the whole building"],"c":0,"why":"Fill rate reflects how much of the property is occupied by tenants, while OCR reflects the financial burden of rent on a specific tenant's revenue."}},{"id":"FN031","cat":"finance","logic":false,"ru":{"q":"Что показывает коэффициент 'соотношение продаж к аренде' (sale-to-rent ratio) в торговой недвижимости?","a":["Долю товарооборота арендатора, уходящую на аренду","Отношение площади к продажам","Долю вакантных площадей к проданным"],"c":0,"why":"Sale-to-rent ratio отражает, какую часть выручки арендатор тратит на аренду."},"uz":{"q":"Savdo markazlarida 'savdo-ijara nisbati' (sale-to-rent ratio) nimani ko'rsatadi?","a":["Ijarachi aylanmasining ijaraga sarflangan ulushini","Maydonning savdoga nisbatini","Bo'sh maydonlarning sotilgan maydonlarga nisbatini"],"c":0,"why":"Sale-to-rent ratio ijarachi daromadining qancha qismi ijaraga ketishini ko'rsatadi."},"en":{"q":"What does the sale-to-rent ratio measure for a retail tenant?","a":["The share of tenant turnover spent on rent","The ratio of GLA to total sales","The ratio of vacant to leased space"],"c":0,"why":"It measures what portion of a tenant's sales revenue goes toward rent payments."}},{"id":"FN032","cat":"finance","logic":false,"ru":{"q":"Как называется уровень заполняемости ТРЦ, при котором доходы от аренды равны операционным расходам и обязательствам?","a":["Точка безубыточной заполняемости (break-even occupancy)","Пиковая заполняемость","Номинальная заполняемость"],"c":0,"why":"Break-even occupancy — минимальный уровень аренды, покрывающий все расходы."},"uz":{"q":"SM daromadlari operatsion xarajatlar va majburiyatlarga teng bo'ladigan bandlik darajasi qanday ataladi?","a":["Break-even (zararsizlik) bandlik darajasi","Eng yuqori bandlik darajasi","Nominal bandlik darajasi"],"c":0,"why":"Break-even occupancy — barcha xarajatlarni qoplaydigan minimal bandlik darajasi."},"en":{"q":"What term describes the occupancy level at which rental income exactly covers operating expenses and obligations?","a":["Break-even occupancy","Peak occupancy","Nominal occupancy"],"c":0,"why":"Break-even occupancy is the minimum occupancy needed to cover all costs."}},{"id":"FN033","cat":"finance","logic":false,"ru":{"q":"Что такое эффективная арендная ставка (effective rent)?","a":["Ставка с учётом скидок и периодов free-rent","Ставка, указанная в договоре без корректировок","Ставка, применяемая только к якорным арендаторам"],"c":0,"why":"Effective rent усредняет реальный доход с учётом всех стимулов и льготных периодов."},"uz":{"q":"Effektiv ijara stavkasi (effective rent) nima?","a":["Chegirmalar va free-rent davrlarini hisobga olgan stavka","Shartnomada ko'rsatilgan tuzatishsiz stavka","Faqat langar ijarachilarga qo'llaniladigan stavka"],"c":0,"why":"Effective rent barcha imtiyozlar va bepul davrlarni hisobga olgan haqiqiy o'rtacha daromadni ko'rsatadi."},"en":{"q":"What is 'effective rent' in a lease agreement?","a":["Rent adjusted for incentives and free-rent periods","The headline rent stated in the contract","A rent rate applied only to anchor tenants"],"c":0,"why":"Effective rent reflects the true average income after accounting for concessions and free-rent periods."}},{"id":"FN034","cat":"finance","logic":false,"ru":{"q":"Что измеряет показатель like-for-like rent growth (сопоставимый рост арендной платы)?","a":["Рост ставок в одних и тех же объектах без учёта новых площадей","Общий рост портфеля с учётом новых объектов","Рост площади торговых точек"],"c":0,"why":"Like-for-like исключает эффект новых или выбывших объектов, сравнивая сопоставимую базу."},"uz":{"q":"Like-for-like rent growth (taqqoslanadigan ijara o'sishi) nimani o'lchaydi?","a":["Yangi obyektlarsiz, bir xil obyektlardagi stavka o'sishini","Yangi obyektlarni hisobga olgan portfelning umumiy o'sishini","Savdo nuqtalari maydonining o'sishini"],"c":0,"why":"Like-for-like yangi yoki chiqib ketgan obyektlar ta'sirini istisno qilib, bir xil bazani taqqoslaydi."},"en":{"q":"What does like-for-like rent growth measure?","a":["Rent growth in the same assets, excluding new additions","Total portfolio growth including new properties","Growth in retail floor area"],"c":0,"why":"Like-for-like growth compares a consistent asset base, excluding acquisitions or new openings."}},{"id":"FN035","cat":"finance","logic":false,"ru":{"q":"В чём разница между валовой (gross) и чистой (net) арендной ставкой?","a":["Gross включает эксплуатационные расходы, net — нет","Net включает НДС, gross — нет","Gross применяется только к якорям"],"c":0,"why":"Gross rent обычно включает service charge и коммунальные платежи, net rent — это чистая ставка без них."},"uz":{"q":"Yalpi (gross) va sof (net) ijara stavkasi o'rtasidagi farq nimada?","a":["Gross ekspluatatsiya xarajatlarini o'z ichiga oladi, net esa yo'q","Net QQSni o'z ichiga oladi, gross esa yo'q","Gross faqat langarlar uchun qo'llaniladi"],"c":0,"why":"Gross rent odatda service charge va kommunal to'lovlarni o'z ichiga oladi, net rent esa ulardan xoli sof stavka."},"en":{"q":"What is the key difference between gross rent and net rent?","a":["Gross rent includes operating costs, net rent excludes them","Net rent includes VAT, gross rent does not","Gross rent applies only to anchor tenants"],"c":0,"why":"Gross rent typically bundles service charges and utilities, while net rent excludes them."}},{"id":"FN036","cat":"finance","logic":false,"ru":{"q":"Что показывает operating expense ratio (OER) в управлении ТРЦ?","a":["Долю операционных расходов от валового дохода объекта","Долю вакантных площадей от общей площади","Долю арендаторов, не оплативших аренду"],"c":0,"why":"OER = операционные расходы / валовой операционный доход, показывает эффективность управления затратами."},"uz":{"q":"SM boshqaruvida operating expense ratio (OER) nimani ko'rsatadi?","a":["Obyekt yalpi daromadidan operatsion xarajatlar ulushini","Umumiy maydondan bo'sh maydonlar ulushini","Ijarani to'lamagan ijarachilar ulushini"],"c":0,"why":"OER = operatsion xarajatlar / yalpi operatsion daromad, xarajatlarni boshqarish samaradorligini ko'rsatadi."},"en":{"q":"What does the operating expense ratio (OER) measure in mall management?","a":["The share of operating costs relative to gross operating income","The share of vacant space relative to total GLA","The share of tenants in arrears"],"c":0,"why":"OER = operating expenses / gross operating income, showing cost management efficiency."}},{"id":"FN037","cat":"finance","logic":false,"ru":{"q":"Что такое turnover rent (оборотная аренда)?","a":["Дополнительная арендная плата, привязанная к товарообороту арендатора","Фиксированная ставка, пересматриваемая раз в год","Штраф за просрочку платежа"],"c":0,"why":"Turnover rent — это переменная часть аренды, зависящая от процента от выручки арендатора."},"uz":{"q":"Turnover rent (aylanmaga bog'liq ijara) nima?","a":["Ijarachi aylanmasiga bog'liq qo'shimcha ijara to'lovi","Yiliga bir marta qayta ko'riladigan qat'iy stavka","To'lov kechikishi uchun jarima"],"c":0,"why":"Turnover rent ijarachi aylanmasining foizidan iborat o'zgaruvchan ijara qismidir."},"en":{"q":"What is turnover rent in a retail lease?","a":["Additional rent tied to a percentage of tenant sales turnover","A fixed rate reviewed annually","A penalty fee for late payment"],"c":0,"why":"Turnover rent is a variable component based on a percentage of the tenant's sales revenue."}},{"id":"FN038","cat":"finance","logic":false,"ru":{"q":"Арендатор с высоким occupancy cost ratio (OCR) при неизменном обороте — о чём это сигнализирует?","a":["Аренда становится финансово обременительной для арендатора","Арендатор получает высокую прибыль","Ставка аренды слишком низкая"],"c":0,"why":"Высокий OCR означает, что аренда 'съедает' большую долю выручки, повышая риск ухода арендатора."},"uz":{"q":"Aylanmasi o'zgarmagan holda OCR yuqori bo'lgan ijarachi haqida bu nimani anglatadi?","a":["Ijara ijarachi uchun moliyaviy og'irlashib bormoqda","Ijarachi yuqori foyda olmoqda","Ijara stavkasi juda past"],"c":0,"why":"Yuqori OCR ijaraning daromaddan katta ulush olayotganini va ijarachi ketish xavfini bildiradi."},"en":{"q":"What does a rising OCR with flat turnover signal about a tenant?","a":["Rent is becoming a financial burden for the tenant","The tenant is highly profitable","The rent rate is too low"],"c":0,"why":"A high OCR means rent consumes a large share of revenue, increasing churn risk."}},{"id":"FN039","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного НЕ входит в расчёт service charge (эксплуатационных платежей)?","a":["Налог на прибыль управляющей компании","Уборка и охрана общих зон","Расходы на маркетинг ТРЦ"],"c":0,"why":"Service charge покрывает эксплуатационные расходы объекта, но не корпоративный налог на прибыль УК."},"uz":{"q":"Quyidagilardan qaysi biri service charge (ekspluatatsiya to'lovi) tarkibiga kirmaydi?","a":["Boshqaruv kompaniyasining foyda solig'i","Umumiy hududlarni tozalash va qo'riqlash","SMning marketing xarajatlari"],"c":0,"why":"Service charge obyektning ekspluatatsion xarajatlarini qoplaydi, lekin BKning korporativ foyda solig'ini emas."},"en":{"q":"Which of the following is NOT part of the service charge calculation?","a":["The management company's corporate income tax","Cleaning and security of common areas","Mall marketing expenses"],"c":0,"why":"Service charge covers property operating costs, not the management company's own income tax."}},{"id":"FN040","cat":"finance","logic":false,"ru":{"q":"Как правильно интерпретировать отклонение факта от бюджета (budget vs actual) по статье 'доходы от аренды'?","a":["Сравнение плановых и фактических показателей для выявления причин расхождений","Автоматическую корректировку арендных ставок","Пересчёт NOI без учёта вакансий"],"c":0,"why":"Анализ budget vs actual нужен для выявления и объяснения отклонений плана от факта."},"uz":{"q":"'Ijaradan daromad' moddasi bo'yicha budjet va haqiqiy ko'rsatkich (budget vs actual) farqini qanday to'g'ri talqin qilish kerak?","a":["Farqlar sababini aniqlash uchun reja va haqiqiy ko'rsatkichlarni solishtirish","Ijara stavkalarini avtomatik tuzatish","Bo'sh joylarni hisobga olmasdan NOI ni qayta hisoblash"],"c":0,"why":"Budget vs actual tahlili reja va haqiqat orasidagi farqlarni aniqlash va tushuntirish uchun kerak."},"en":{"q":"What is the correct purpose of a budget vs actual analysis for the 'rental income' line item?","a":["Comparing planned and actual figures to identify causes of variance","Automatically adjusting rent rates","Recalculating NOI while ignoring vacancy"],"c":0,"why":"Budget vs actual analysis is used to identify and explain variances between plan and reality."}},{"id":"FN041","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного является примером арендных стимулов (incentives), снижающих effective rent?","a":["Период free-rent в начале договора","Повышение ставки индексацией","Штраф за досрочное расторжение"],"c":0,"why":"Free-rent период — классический стимул, снижающий среднюю эффективную ставку за срок договора."},"uz":{"q":"Quyidagilardan qaysi biri effective rentni pasaytiradigan ijara rag'batlantirish (incentive) namunasi?","a":["Shartnoma boshida beriladigan free-rent davri","Indeksatsiya orqali stavkani oshirish","Muddatidan oldin bekor qilish uchun jarima"],"c":0,"why":"Free-rent davri shartnoma muddati bo'yicha o'rtacha effektiv stavkani pasaytiruvchi klassik rag'batdir."},"en":{"q":"Which of the following is an example of a lease incentive that lowers effective rent?","a":["A free-rent period at the start of the lease","An indexation-based rent increase","An early termination penalty"],"c":0,"why":"A free-rent period is a classic incentive that reduces the average effective rate over the lease term."}},{"id":"FN042","cat":"finance","logic":false,"ru":{"q":"Договор аренды на 60 месяцев с 3 месяцами free-rent и ставкой 100 у.е./м² — как это влияет на effective rent?","a":["Effective rent будет ниже заявленной ставки 100 у.е./м²","Effective rent будет выше заявленной ставки","Effective rent останется равной 100 у.е./м²"],"c":0,"why":"Распределение дохода на весь срок с учётом бесплатных месяцев снижает среднюю эффективную ставку."},"uz":{"q":"60 oylik shartnoma, 3 oy free-rent va 100 birlik/m² stavka — bu effective rentga qanday ta'sir qiladi?","a":["Effective rent e'lon qilingan 100 birlikdan past bo'ladi","Effective rent e'lon qilingan stavkadan yuqori bo'ladi","Effective rent 100 birlikka teng qoladi"],"c":0,"why":"Bepul oylarni hisobga olib daromadni butun muddatga taqsimlash o'rtacha effektiv stavkani pasaytiradi."},"en":{"q":"A 60-month lease at 100 units/m² includes 3 months free-rent. How does this affect effective rent?","a":["Effective rent will be lower than the headline 100 units/m²","Effective rent will be higher than the headline rate","Effective rent remains exactly 100 units/m²"],"c":0,"why":"Spreading income over the full term including free months lowers the average effective rate."}},{"id":"FN043","cat":"finance","logic":false,"ru":{"q":"Что означает термин 'арендная задолженность' (arrears) в отчётности ТРЦ?","a":["Суммы, не выплаченные арендаторами в срок по договору","Плановые расходы на будущий ремонт","Разница между gross и net rent"],"c":0,"why":"Arrears — это просроченная задолженность арендаторов по арендным платежам."},"uz":{"q":"SM hisobotida 'ijara qarzdorligi' (arrears) atamasi nimani anglatadi?","a":["Ijarachilar tomonidan muddatida to'lanmagan summalar","Kelgusi ta'mirlash uchun rejalashtirilgan xarajatlar","Gross va net rent orasidagi farq"],"c":0,"why":"Arrears — ijarachilarning muddati o'tgan ijara to'lovlari bo'yicha qarzdorligi."},"en":{"q":"What does the term 'arrears' mean in mall financial reporting?","a":["Amounts owed by tenants that are overdue per the lease","Planned expenses for future renovation","The difference between gross and net rent"],"c":0,"why":"Arrears refers to overdue tenant payments that are past their contractual due date."}},{"id":"FN044","cat":"finance","logic":false,"ru":{"q":"Какой показатель наиболее полезен для оценки эффективности маркетингового ремонта общих зон ТРЦ?","a":["ROI ремонта, сравнивающий рост дохода с затратами","Средняя ставка аренды в соседнем ТРЦ","Курс валюты на момент ремонта"],"c":0,"why":"ROI ремонта показывает, окупаются ли вложенные средства приростом дохода."},"uz":{"q":"SM umumiy hududlarini ta'mirlash samaradorligini baholash uchun qaysi ko'rsatkich eng foydali?","a":["Ta'mirlash xarajatlarini daromad o'sishi bilan solishtiruvchi ROI","Qo'shni SMdagi o'rtacha ijara stavkasi","Ta'mirlash vaqtidagi valyuta kursi"],"c":0,"why":"Ta'mirlash ROI investitsiya daromad o'sishi orqali qoplanayotganini ko'rsatadi."},"en":{"q":"Which metric best evaluates the effectiveness of a common-area renovation in a mall?","a":["Renovation ROI, comparing income uplift to cost","The average rent rate in a neighboring mall","The exchange rate at the time of renovation"],"c":0,"why":"Renovation ROI shows whether the invested capital is recovered through income growth."}},{"id":"FN045","cat":"finance","logic":false,"ru":{"q":"Что показывает fill rate (уровень заполняемости) ТРЦ в отличие от occupancy rate по площади?","a":["Долю сданных юнитов от общего числа помещений","Долю посетителей от общего трафика","Долю арендаторов, повысивших оборот"],"c":0,"why":"Fill rate часто измеряется по количеству сданных юнитов, а не по квадратным метрам."},"uz":{"q":"Fill rate (bandlik darajasi) maydon bo'yicha occupancy ratedan farqli o'laroq nimani ko'rsatadi?","a":["Umumiy joylar sonidan ijaraga berilgan modullar ulushini","Umumiy trafikdan tashrif buyuruvchilar ulushini","Aylanmasini oshirgan ijarachilar ulushini"],"c":0,"why":"Fill rate ko'pincha kvadrat metr emas, ijaraga berilgan modullar soni bo'yicha o'lchanadi."},"en":{"q":"How does 'fill rate' differ from area-based occupancy rate in a mall?","a":["It measures the share of leased units out of total units","It measures the share of visitors out of total footfall","It measures the share of tenants with rising turnover"],"c":0,"why":"Fill rate is often measured by number of leased units rather than by square meters."}},{"id":"FN046","cat":"finance","logic":false,"ru":{"q":"Почему рост вакантности напрямую снижает NOI даже при неизменных операционных расходах?","a":["Падает валовой арендный доход при сохранении части постоянных затрат","Растут налоги на пустующие площади","Снижается capex на ремонт"],"c":0,"why":"Вакантные площади не приносят арендный доход, а часть расходов (охрана, коммуналка мест общего пользования) остаётся."},"uz":{"q":"Nima uchun operatsion xarajatlar o'zgarmasa ham, bo'sh joylar ko'payishi NOI ni to'g'ridan-to'g'ri pasaytiradi?","a":["Ba'zi doimiy xarajatlar saqlanib qolgan holda yalpi ijara daromadi kamayadi","Bo'sh maydonlar uchun soliqlar oshadi","Ta'mirlash uchun capex kamayadi"],"c":0,"why":"Bo'sh maydonlar ijara daromadi keltirmaydi, ammo umumiy hudud xarajatlarining bir qismi saqlanib qoladi."},"en":{"q":"Why does rising vacancy directly reduce NOI even if operating expenses stay the same?","a":["Gross rental income falls while some fixed costs remain","Taxes on vacant space increase","Renovation capex decreases"],"c":0,"why":"Vacant units generate no rental income, yet certain common-area costs continue regardless."}},{"id":"FN047","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного корректно характеризует net rent для собственника ТРЦ?","a":["Доход от аренды за вычетом операционных расходов, относимых на арендодателя","Доход от аренды до вычета амортизации","Доход только от turnover rent"],"c":0,"why":"Net rent — это чистый доход арендодателя после расходов, которые не перевыставляются арендаторам."},"uz":{"q":"SM egasi uchun net rentni to'g'ri tavsiflovchi javobni tanlang.","a":["Ijaraga oluvchilarga o'tkazilmaydigan xarajatlar chegirilgan ijara daromadi","Amortizatsiya chegirilmagan ijara daromadi","Faqat turnover rentdan olingan daromad"],"c":0,"why":"Net rent — ijarachilarga qayta taqsimlanmaydigan xarajatlar ayirilgandan keyingi sof daromad."},"en":{"q":"Which statement correctly describes net rent from the landlord's perspective?","a":["Rental income minus operating costs borne by the landlord","Rental income before depreciation deductions","Income derived only from turnover rent"],"c":0,"why":"Net rent is the landlord's income remaining after costs that are not recharged to tenants."}},{"id":"FN048","cat":"finance","logic":false,"ru":{"q":"Как рассчитывается break-even occupancy для конкретного бюджета ТРЦ?","a":["Уровень аренды, при котором доход покрывает операционные и финансовые расходы","Средняя загрузка парковки","Максимальная возможная заполняемость по проекту"],"c":0,"why":"Break-even occupancy определяется через отношение необходимых расходов к потенциальному доходу при полной загрузке."},"uz":{"q":"Muayyan SM budjeti uchun break-even occupancy qanday hisoblanadi?","a":["Daromad operatsion va moliyaviy xarajatlarni qoplaydigan bandlik darajasi","O'rtacha avtoturargoh bandligi","Loyihadagi maksimal mumkin bo'lgan bandlik"],"c":0,"why":"Break-even occupancy to'liq bandlikdagi potentsial daromadga zarur xarajatlar nisbati orqali aniqlanadi."},"en":{"q":"How is break-even occupancy calculated for a given mall budget?","a":["The occupancy level at which income covers operating and financing costs","The average parking lot utilization","The maximum possible occupancy per the project design"],"c":0,"why":"Break-even occupancy is derived from required costs relative to potential income at full occupancy."}},{"id":"FN049","cat":"finance","logic":false,"ru":{"q":"Какой из показателей напрямую влияет на срок окупаемости (payback period) инвестиций в ТРЦ?","a":["Годовой чистый денежный поток от объекта","Количество этажей здания","Цвет фасада здания"],"c":0,"why":"Payback period рассчитывается делением первоначальных инвестиций на годовой чистый денежный поток."},"uz":{"q":"SM investitsiyalarining o'zini oqlash muddatiga (payback period) qaysi ko'rsatkich to'g'ridan-to'g'ri ta'sir qiladi?","a":["Obyektning yillik sof pul oqimi","Binoning qavatlar soni","Bino fasadining rangi"],"c":0,"why":"Payback period boshlang'ich investitsiyani yillik sof pul oqimiga bo'lish orqali hisoblanadi."},"en":{"q":"Which factor directly affects the payback period of a mall investment?","a":["The property's annual net cash flow","The number of floors in the building","The color of the building facade"],"c":0,"why":"Payback period is calculated by dividing the initial investment by annual net cash flow."}},{"id":"FN050","cat":"finance","logic":false,"ru":{"q":"Почему при сравнении объектов важнее ориентироваться на net yield, а не на gross yield?","a":["Net yield учитывает операционные расходы, отражая реальную доходность","Gross yield всегда выше и точнее","Net yield не зависит от арендных ставок"],"c":0,"why":"Net yield вычитает операционные расходы из дохода, давая более точную картину доходности."},"uz":{"q":"Obyektlarni solishtirishda nima uchun gross yield emas, net yieldga tayanish muhimroq?","a":["Net yield operatsion xarajatlarni hisobga olib, haqiqiy daromadlilikni ko'rsatadi","Gross yield doim yuqori va aniqroq bo'ladi","Net yield ijara stavkalariga bog'liq emas"],"c":0,"why":"Net yield daromaddan operatsion xarajatlarni ayiradi va aniqroq daromadlilik ko'rsatkichini beradi."},"en":{"q":"Why is net yield generally a better comparison metric than gross yield?","a":["Net yield accounts for operating expenses, reflecting true returns","Gross yield is always higher and more accurate","Net yield is independent of rent levels"],"c":0,"why":"Net yield deducts operating expenses from income, giving a more accurate picture of returns."}},{"id":"FN051","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного считается наиболее прямым индикатором финансового здоровья арендатора внутри ТРЦ?","a":["Occupancy cost ratio на протяжении нескольких периодов","Этаж, на котором расположен магазин","Название бренда арендатора"],"c":0,"why":"Динамика OCR во времени показывает, справляется ли арендатор с арендной нагрузкой."},"uz":{"q":"Quyidagilardan qaysi biri SM ichidagi ijarachining moliyaviy holatini eng to'g'ridan-to'g'ri ko'rsatadi?","a":["Bir necha davr davomidagi occupancy cost ratio dinamikasi","Do'kon joylashgan qavat","Ijarachi brendining nomi"],"c":0,"why":"OCR dinamikasi ijarachi ijara yukiga bardosh berayotganini yoki yo'qligini ko'rsatadi."},"en":{"q":"Which of these is the most direct indicator of a tenant's financial health within a mall?","a":["The trend in occupancy cost ratio over several periods","The floor where the store is located","The tenant's brand name"],"c":0,"why":"OCR trends over time reveal whether a tenant can sustainably support its rent burden."}},{"id":"FN052","cat":"finance","logic":false,"ru":{"q":"Как service charge отражается в отчёте о доходах управляющей компании при полном перевыставлении расходов арендаторам?","a":["Как проходящий (компенсируемый) доход, не влияющий на прибыль УК","Как чистая прибыль управляющей компании","Как капитальные затраты объекта"],"c":0,"why":"При полном recharge service charge является транзитной статьёй и не формирует прибыль УК."},"uz":{"q":"Xarajatlar to'liq ijarachilarga qayta taqsimlanganda, service charge boshqaruv kompaniyasi daromadlar hisobotida qanday aks etadi?","a":["BK foydasiga ta'sir qilmaydigan o'tkazma (kompensatsiya) daromadi sifatida","BKning sof foydasi sifatida","Obyektning kapital xarajati sifatida"],"c":0,"why":"To'liq qayta taqsimlanganda service charge tranzit modda hisoblanadi va BK foydasini shakllantirmaydi."},"en":{"q":"How does the service charge appear in a management company's income statement when fully recharged to tenants?","a":["As a pass-through item with no impact on management profit","As net profit for the management company","As capital expenditure on the property"],"c":0,"why":"When fully recharged, the service charge is a pass-through item and does not generate management profit."}},{"id":"FN053","cat":"finance","logic":false,"ru":{"q":"ТРЦ с площадью 20 000 м² сдал в аренду 17 000 м². Как называется показатель 15% незанятых площадей?","a":["Vacancy rate (уровень вакантности)","Occupancy cost ratio","Sale-to-rent ratio"],"c":0,"why":"Vacancy rate — это доля свободных площадей от общей арендопригодной площади."},"uz":{"q":"20 000 m² maydonli SM 17 000 m² ni ijaraga bergan. Bo'sh qolgan 15% qanday ko'rsatkich deb ataladi?","a":["Vacancy rate (bo'shlik darajasi)","Occupancy cost ratio","Sale-to-rent ratio"],"c":0,"why":"Vacancy rate — umumiy ijaraga yaroqli maydondan bo'sh qolgan qism ulushi."},"en":{"q":"A 20,000 m² mall has leased 17,000 m². What is the metric describing the remaining 15% unleased space called?","a":["Vacancy rate","Occupancy cost ratio","Sale-to-rent ratio"],"c":0,"why":"Vacancy rate is the proportion of unleased space relative to total leasable area."}},{"id":"FN054","cat":"finance","logic":false,"ru":{"q":"Почему при переговорах с арендатором важно учитывать сравнение sale-to-rent ratio с бенчмарком по категории?","a":["Отклонение от нормы категории сигнализирует о завышенной или заниженной ставке","Это единственный показатель, влияющий на срок договора","Это заменяет расчёт service charge"],"c":0,"why":"Сравнение с отраслевым бенчмарком помогает понять, справедлива ли текущая ставка для данной категории ритейла."},"uz":{"q":"Ijarachi bilan muzokaralarda sale-to-rent ratio'ni kategoriya benchmarki bilan solishtirish nima uchun muhim?","a":["Kategoriya me'yoridan chetlanish stavkaning oshirilgan yoki pasaytirilganini ko'rsatadi","Bu shartnoma muddatiga ta'sir qiluvchi yagona ko'rsatkich","Bu service charge hisobini almashtiradi"],"c":0,"why":"Tarmoq benchmarki bilan solishtirish joriy stavka ushbu chakana savdo toifasi uchun adolatli ekanini tushunishga yordam beradi."},"en":{"q":"Why is comparing a tenant's sale-to-rent ratio against a category benchmark important during lease negotiations?","a":["A deviation from the category norm signals an over- or under-priced rent","It is the only factor affecting lease term","It replaces the need to calculate service charge"],"c":0,"why":"Benchmarking against industry norms helps determine whether the current rent is fair for that retail category."}},{"id":"FN055","cat":"finance","logic":false,"ru":{"q":"Какой эффект окажет продление free-rent периода с 1 до 3 месяцев на effective rent при том же номинальном тарифе?","a":["Effective rent снизится","Effective rent увеличится","Effective rent не изменится"],"c":0,"why":"Больше бесплатных месяцев означает меньше оплаченных периодов относительно всего срока, снижая среднюю ставку."},"uz":{"q":"Nominal tarif o'zgarmagan holda free-rent davrini 1 oydan 3 oyga uzaytirish effective rentga qanday ta'sir qiladi?","a":["Effective rent pasayadi","Effective rent oshadi","Effective rent o'zgarmaydi"],"c":0,"why":"Ko'proq bepul oylar butun muddatga nisbatan to'langan davrlar ulushini kamaytirib, o'rtacha stavkani pasaytiradi."},"en":{"q":"How does extending the free-rent period from 1 to 3 months affect effective rent, all else equal?","a":["Effective rent decreases","Effective rent increases","Effective rent stays the same"],"c":0,"why":"More free months reduce the paid portion of the lease term, lowering the average effective rate."}},{"id":"FN056","cat":"finance","logic":false,"ru":{"q":"Что означает отрицательный like-for-like rent growth в годовом отчёте ТРЦ?","a":["Ставки аренды в сопоставимых объектах снизились год к году","Общая площадь портфеля уменьшилась","Компания продала часть активов"],"c":0,"why":"Отрицательный like-for-like рост означает снижение арендных ставок на сопоставимой базе объектов."},"uz":{"q":"SMning yillik hisobotida manfiy like-for-like rent growth nimani anglatadi?","a":["Taqqoslanadigan obyektlarda ijara stavkalari yildan-yilga pasaygan","Portfelning umumiy maydoni kamaygan","Kompaniya aktivlarining bir qismini sotgan"],"c":0,"why":"Manfiy like-for-like o'sish taqqoslanadigan baza bo'yicha ijara stavkalarining pasayganini bildiradi."},"en":{"q":"What does negative like-for-like rent growth in an annual report indicate?","a":["Rents in comparable assets declined year over year","The total portfolio area decreased","The company sold part of its assets"],"c":0,"why":"Negative like-for-like growth means rents fell on a consistent, comparable asset base."}},{"id":"FN057","cat":"finance","logic":false,"ru":{"q":"Какой показатель наиболее подходит для сравнения доходности разных ТРЦ независимо от структуры их капитала?","a":["Cap rate (ставка капитализации)","Абсолютная сумма арендного дохода","Количество арендаторов"],"c":0,"why":"Cap rate = NOI / стоимость объекта, что позволяет сравнивать доходность независимо от заёмного финансирования."},"uz":{"q":"Turli SMlarning daromadliligini kapital tuzilishidan qat'i nazar solishtirish uchun qaysi ko'rsatkich eng mos?","a":["Cap rate (kapitalizatsiya stavkasi)","Ijara daromadining mutlaq summasi","Ijarachilar soni"],"c":0,"why":"Cap rate = NOI / obyekt qiymati, bu qarz moliyalashtirishidan qat'i nazar daromadlilikni solishtirish imkonini beradi."},"en":{"q":"Which metric best allows comparing profitability across malls regardless of their capital structure?","a":["Cap rate","The absolute rental income amount","The number of tenants"],"c":0,"why":"Cap rate (NOI / property value) enables comparison of returns independent of debt financing."}},{"id":"FN058","cat":"finance","logic":false,"ru":{"q":"Почему в отчётах об эффективности ТРЦ турновер-отчёты арендаторов важны для расчёта OCR?","a":["Без данных о товарообороте невозможно определить долю аренды в выручке","Турновер-отчёты заменяют бюджетирование расходов","Они определяют размер service charge"],"c":0,"why":"OCR рассчитывается как отношение аренды к обороту, поэтому точные данные о товарообороте необходимы."},"uz":{"q":"SM samaradorligi hisobotlarida ijarachilarning aylanma hisobotlari nima uchun OCR hisoblash uchun muhim?","a":["Aylanma ma'lumotlarisiz ijaraning daromaddagi ulushini aniqlab bo'lmaydi","Aylanma hisobotlari xarajatlar budjetlashtirishni almashtiradi","Ular service charge miqdorini belgilaydi"],"c":0,"why":"OCR ijaraning aylanmaga nisbati sifatida hisoblanadi, shuning uchun aniq aylanma ma'lumotlari zarur."},"en":{"q":"Why are tenant turnover reports essential for calculating OCR in mall performance reviews?","a":["Without turnover data, rent's share of revenue cannot be determined","Turnover reports replace expense budgeting","They determine the size of the service charge"],"c":0,"why":"OCR is calculated as rent divided by turnover, so accurate turnover data is required."}},{"id":"FN059","cat":"finance","logic":false,"ru":{"q":"Что из перечисленного корректно отражает влияние роста арендных ставок на cap rate при неизменной стоимости объекта?","a":["Cap rate вырастет за счёт увеличения NOI","Cap rate снизится независимо от NOI","Cap rate не связан с арендными ставками"],"c":0,"why":"Рост ставок повышает NOI, а при постоянной стоимости объекта это увеличивает cap rate."},"uz":{"q":"Obyekt qiymati o'zgarmagan holda ijara stavkalarining o'sishi cap rate'ga qanday ta'sir qilishini to'g'ri ifodalaydi?","a":["NOI oshishi hisobiga cap rate oshadi","Cap rate NOIga bog'liq bo'lmagan holda pasayadi","Cap rate ijara stavkalariga bog'liq emas"],"c":0,"why":"Stavkalar oshishi NOIni oshiradi, obyekt qiymati o'zgarmasa bu cap rate oshishiga olib keladi."},"en":{"q":"How does rising rent, with property value held constant, affect the cap rate?","a":["Cap rate increases as NOI rises","Cap rate decreases regardless of NOI","Cap rate is unrelated to rent levels"],"c":0,"why":"Higher rents increase NOI, and with a constant property value this raises the cap rate."}},{"id":"FN060","cat":"finance","logic":false,"ru":{"q":"Зачем в финансовой модели ТРЦ отдельно учитывают gross rent и net rent при расчёте доходности для инвестора?","a":["Инвестора интересует net rent, так как он отражает реальный доход после расходов","Gross rent всегда равен NOI","Net rent используется только для расчёта service charge"],"c":0,"why":"Инвестора интересует именно net rent (доход после операционных расходов), а не валовая ставка."},"uz":{"q":"SM moliyaviy modelida investor uchun daromadlilikni hisoblashda gross rent va net rent nega alohida hisobga olinadi?","a":["Investor uchun net rent muhim, chunki u xarajatlardan keyingi haqiqiy daromadni ko'rsatadi","Gross rent har doim NOIga teng","Net rent faqat service charge hisoblash uchun ishlatiladi"],"c":0,"why":"Investor uchun aynan net rent (operatsion xarajatlardan keyingi daromad) muhim, yalpi stavka emas."},"en":{"q":"Why do mall financial models track gross rent and net rent separately when calculating investor returns?","a":["Investors focus on net rent since it reflects real income after costs","Gross rent always equals NOI","Net rent is used only to calculate the service charge"],"c":0,"why":"Investors care about net rent — income after operating costs — rather than the gross headline rate."}},{"id":"LC001","cat":"logic","logic":true,"ru":{"q":"GLA торгового центра увеличилась на 10%, а продажи арендаторов остались на прежнем уровне. Что произойдёт с показателем occupancy cost ratio (доля аренды в обороте)?","a":["Снизится, так как площадь больше","Не изменится, ratio зависит только от ставки","Вырастет пропорционально росту площади, если аренда тоже выросла"],"c":2,"why":"Occupancy cost ratio = аренда/продажи; если аренда растёт вместе с площадью, а продажи не растут, доля аренды в обороте увеличивается."},"uz":{"q":"Savdo markazining GLA maydoni 10% ga oshdi, lekin ijarachilarning savdosi o'zgarmadi. Occupancy cost ratio (ijaraning aylanmadagi ulushi) ko'rsatkichiga nima bo'ladi?","a":["Maydon kattalashgani uchun pasayadi","O'zgarmaydi, chunki ratio faqat stavkaga bog'liq","Agar ijara ham oshgan bo'lsa, maydonga proporsional o'sadi"],"c":2,"why":"Occupancy cost ratio = ijara/savdo; agar maydon bilan birga ijara summasi oshsa, savdo o'zgarmagani uchun bu ulush ortadi."},"en":{"q":"A mall's GLA increases by 10%, but tenant sales stay flat. What happens to the occupancy cost ratio (rent as a share of sales)?","a":["It decreases because the space is larger","It stays the same since the ratio depends only on rate","It rises proportionally if total rent grew with the area"],"c":2,"why":"Occupancy cost ratio = rent/sales; if rent grows with area while sales stay flat, the ratio rises."}},{"id":"LC002","cat":"logic","logic":true,"ru":{"q":"Трафик торгового центра вырос на 10%, конверсия осталась прежней, средний чек не изменился. Что произойдёт с общими продажами?","a":["Продажи вырастут примерно на 10%","Продажи останутся на том же уровне","Продажи снизятся из-за перегрузки магазинов"],"c":0,"why":"Продажи = трафик × конверсия × средний чек; при неизменных двух из трёх переменных рост трафика даёт пропорциональный рост продаж."},"uz":{"q":"Savdo markaziga tashrif 10% ga oshdi, konversiya va o'rtacha chek o'zgarmadi. Umumiy savdoga nima bo'ladi?","a":["Savdo taxminan 10% ga oshadi","Savdo o'sha darajada qoladi","Do'konlarning ortiqcha yuklanishi tufayli savdo pasayadi"],"c":0,"why":"Savdo = tashrif × konversiya × o'rtacha chek; ikkita o'zgaruvchi o'zgarmasa, tashrifning o'sishi savdoni proporsional oshiradi."},"en":{"q":"Mall footfall grows 10%, while conversion rate and average basket size stay unchanged. What happens to total sales?","a":["Sales rise by roughly 10%","Sales remain flat","Sales drop due to store overcrowding"],"c":0,"why":"Sales = footfall x conversion x average basket; with two variables constant, a 10% footfall gain translates into roughly 10% more sales."}},{"id":"LC003","cat":"logic","logic":true,"ru":{"q":"Ставка аренды — $20/м², площадь помещения — 100 м². Какова месячная аренда? Если площадь увеличится на 20%, как изменится аренда (ставка та же)?","a":["$2000, вырастет до $2400","$2000, останется $2000","$1800, вырастет до $2000"],"c":0,"why":"20×100=2000; при увеличении площади до 120 м² аренда = 20×120=2400, то есть растёт пропорционально площади."},"uz":{"q":"Ijara stavkasi — 20$/m², xona maydoni — 100 m². Oylik ijara qancha bo'ladi? Agar maydon 20% ga oshsa (stavka o'zgarmasa), ijara qanday o'zgaradi?","a":["2000$, 2400$ gacha oshadi","2000$, 2000$da qoladi","1800$, 2000$ gacha oshadi"],"c":0,"why":"20×100=2000; maydon 120 m² bo'lganda ijara 20×120=2400 bo'ladi, ya'ni maydonga proporsional o'sadi."},"en":{"q":"The rate is $20/m² and the unit is 100 m². What is the monthly rent, and how does it change if the area grows 20% at the same rate?","a":["$2,000, rising to $2,400","$2,000, staying at $2,000","$1,800, rising to $2,000"],"c":0,"why":"20 x 100 = 2,000; at 120 m² the rent becomes 20 x 120 = 2,400, scaling proportionally with area."}},{"id":"LC004","cat":"logic","logic":true,"ru":{"q":"Вакансия в торговом центре выросла с 5% до 15%, ставки аренды не изменились. Что произойдёт с потенциальным рентным доходом (Potential Rental Income), фактически получаемым центром?","a":["Фактически собираемый доход снизится, так как больше площадей простаивает","Доход вырастет, так как свободные площади можно сдать дороже","Доход не изменится, PRI считается по всей GLA независимо от вакансии"],"c":0,"why":"PRI — это теоретический доход при 100% занятости; реально собираемый доход падает пропорционально росту доли пустующих площадей."},"uz":{"q":"Savdo markazida bo'sh maydonlar ulushi 5% dan 15% gacha oshdi, ijara stavkalari o'zgarmadi. Markaz haqiqatda oladigan ijara daromadiga nima bo'ladi?","a":["Bo'sh maydonlar ko'paygani uchun haqiqiy daromad kamayadi","Bo'sh maydonlarni qimmatroq sotish mumkin bo'lgani uchun daromad oshadi","O'zgarmaydi, chunki potensial daromad butun GLA bo'yicha hisoblanadi"],"c":0,"why":"Potensial daromad 100% bandlikda hisoblangan nazariy ko'rsatkich; bo'sh maydon ulushi oshsa, haqiqatda yig'iladigan daromad shunga mos kamayadi."},"en":{"q":"Vacancy in a mall rises from 5% to 15% while rental rates stay unchanged. What happens to the rental income actually collected versus potential rental income?","a":["Actual collected income falls as more space sits empty","Income rises because vacant units can be leased at a premium","Income is unaffected since PRI is calculated on total GLA"],"c":0,"why":"Potential rental income assumes full occupancy; actual collected income drops in proportion to the growing vacant share."}},{"id":"LC005","cat":"logic","logic":true,"ru":{"q":"Крупный якорный оператор (гипермаркет) закрывается и съезжает. Каков наиболее вероятный эффект на трафик соседних магазинов галереи?","a":["Трафик у соседних магазинов, скорее всего, снизится","Трафик вырастет, так как покупатели переключатся на них","Трафик не изменится, так как якорь и галерея независимы"],"c":0,"why":"Якорные операторы генерируют основной поток посетителей (co-tenancy эффект), поэтому их уход снижает трафик к расположенным рядом магазинам."},"uz":{"q":"Yirik langar operator (gipermarket) yopilib, ko'chib ketdi. Galereyadagi qo'shni do'konlarga tashrifga eng ehtimoliy ta'sir qanday bo'ladi?","a":["Qo'shni do'konlarga tashrif, ehtimol, kamayadi","Xaridorlar ularga o'tgani uchun tashrif oshadi","Langar va galereya bog'liq bo'lmagani uchun o'zgarmaydi"],"c":0,"why":"Langar operatorlar asosiy tashrifchi oqimini yaratadi (co-tenancy effekti), shuning uchun uning ketishi atrofdagi do'konlarga tashrifni kamaytiradi."},"en":{"q":"A major anchor tenant (hypermarket) closes and vacates. What is the most likely effect on foot traffic to nearby in-line stores?","a":["Foot traffic to nearby stores will likely decline","Foot traffic will rise as shoppers shift to them","Foot traffic is unaffected since anchors and in-line stores are independent"],"c":0,"why":"Anchor tenants drive the bulk of visitor flow (the co-tenancy effect), so their departure reduces traffic to surrounding stores."}},{"id":"LC006","cat":"logic","logic":true,"ru":{"q":"Выбор для помещения: (А) фикс $3000/мес; (Б) база $2000/мес плюс 8% с оборота при продажах $50000/мес. Что выгоднее арендодателю?","a":["Вариант А — $3000 больше","Вариант Б — $2000+8%×50000=$6000","Оба варианта дадут одинаковый доход"],"c":1,"why":"8% от $50000 = $4000, плюс база $2000 = $6000, что превышает фиксированную ставку $3000."},"uz":{"q":"Xona uchun tanlov: (A) fiks 3000$/oy; (B) baza 2000$/oy plyus 50000$/oy savdodan 8%. Uy egasiga qaysi variant foydali?","a":["A varianti — 3000$ ko'proq","B varianti — 2000$+8%×50000=6000$","Ikkala variant ham bir xil daromad beradi"],"c":1,"why":"50000$ dan 8% = 4000$, plyus 2000$ baza = 6000$, bu qat'iy 3000$ dan ko'proq."},"en":{"q":"Choice for a unit: (A) fixed $3,000/month; (B) $2,000 base plus 8% of turnover at $50,000/month sales. Which is better for the landlord?","a":["Option A — $3,000 is higher","Option B — $2,000 + 8% x 50,000 = $6,000","Both options yield the same revenue"],"c":1,"why":"8% of $50,000 is $4,000, plus the $2,000 base equals $6,000, well above the fixed $3,000 rent."}},{"id":"LC007","cat":"logic","logic":true,"ru":{"q":"Среднее время пребывания посетителей (dwell time) в ТРЦ выросло, а конверсия в покупку не изменилась. Как это, вероятнее всего, скажется на выручке F&B и развлечений?","a":["Вырастет, так как больше времени тратится на еду и досуг","Снизится, так как посетители устают и уходят раньше","Не изменится, dwell time не связан с расходами"],"c":0,"why":"Больше времени в ТРЦ обычно означает больше посещений фудкорта и развлекательных зон, даже если конверсия в fashion-покупках не растёт."},"uz":{"q":"TRC dagi tashrifchilarning o'rtacha bo'lish vaqti (dwell time) oshdi, lekin xarid konversiyasi o'zgarmadi. Bu F&B va ko'ngilochar zonalar daromadiga qanday ta'sir qilishi ehtimoli ko'proq?","a":["Oshadi, chunki ovqat va dam olishga ko'proq vaqt sarflanadi","Kamayadi, chunki tashrifchilar charchab, tezroq ketishadi","O'zgarmaydi, dwell time xarajatlarga bog'liq emas"],"c":0,"why":"TRC da ko'proq vaqt o'tkazish odatda fudkort va ko'ngilochar zonalarga ko'proq tashrif degani, hatto fashion xaridlar konversiyasi o'smasa ham."},"en":{"q":"Average visitor dwell time in a mall increases while purchase conversion stays unchanged. What is the likely effect on F&B and entertainment revenue?","a":["It rises, as more time is spent on food and leisure","It falls, as visitors get tired and leave sooner","It stays flat, since dwell time is unrelated to spend"],"c":0,"why":"More time spent in the mall typically means more food court and entertainment visits, even if fashion conversion doesn't change."}},{"id":"LC008","cat":"logic","logic":true,"ru":{"q":"NOI (чистый операционный доход) торгового центра снижается при неизменной валовой выручке. Какая из причин это объясняет?","a":["Операционные расходы выросли","GLA увеличилась","Средний чек посетителей вырос"],"c":0,"why":"NOI = валовый доход минус операционные расходы; если доход не менялся, а NOI упал, значит выросли расходы."},"uz":{"q":"Yalpi daromad o'zgarmagan holda savdo markazining NOI (sof operatsion daromadi) kamayib bormoqda. Bu qaysi sabab bilan izohlanadi?","a":["Operatsion xarajatlar oshgan","GLA kattalashgan","Tashrifchilarning o'rtacha cheki oshgan"],"c":0,"why":"NOI = yalpi daromad minus operatsion xarajatlar; daromad o'zgarmasa-yu NOI tushsa, demak xarajatlar oshgan."},"en":{"q":"A mall's NOI (net operating income) declines while gross revenue stays flat. Which factor explains this?","a":["Operating expenses increased","GLA expanded","Average visitor basket size increased"],"c":0,"why":"NOI equals gross income minus operating expenses; if income is unchanged but NOI dropped, expenses must have risen."}},{"id":"LC009","cat":"logic","logic":true,"ru":{"q":"Доля вакантных площадей в ТРЦ снизилась с 12% до 4% за год без изменения GLA. Что из этого следует про уровень занятости (occupancy rate)?","a":["Occupancy rate вырос с 88% до 96%","Occupancy rate снизился, так как вакансия и занятость растут вместе","Occupancy rate не связан с вакансией"],"c":0,"why":"Occupancy rate = 100% минус вакансия; снижение вакансии на 8 п.п. означает такой же рост занятости."},"uz":{"q":"TRC da bo'sh maydonlar ulushi yil davomida GLA o'zgarmagan holda 12% dan 4% gacha kamaydi. Bandlik darajasi (occupancy rate) haqida bu nimani bildiradi?","a":["Occupancy rate 88% dan 96% gacha oshdi","Occupancy rate kamaydi, chunki bo'shliq va bandlik birga o'sadi","Occupancy rate bo'shlikka bog'liq emas"],"c":0,"why":"Occupancy rate = 100% minus bo'shlik; bo'shlikning 8 foiz punktga kamayishi bandlikning xuddi shuncha oshishini bildiradi."},"en":{"q":"A mall's vacancy rate drops from 12% to 4% over a year with GLA unchanged. What does this imply about the occupancy rate?","a":["Occupancy rate rose from 88% to 96%","Occupancy rate fell, since vacancy and occupancy move together","Occupancy rate is unrelated to vacancy"],"c":0,"why":"Occupancy rate equals 100% minus vacancy; an 8-point drop in vacancy means an equal rise in occupancy."}},{"id":"LC010","cat":"logic","logic":true,"ru":{"q":"Арендатор платит turnover rent (процент от оборота) без фиксированного минимума. В низкий сезон его продажи падают вдвое. Что произойдёт с арендной платой этого месяца?","a":["Аренда снизится примерно вдвое","Аренда останется прежней, так как ставка фиксирована в договоре","Аренда вырастет, чтобы компенсировать падение продаж"],"c":0,"why":"При чистом turnover rent аренда — это процент от продаж, поэтому падение продаж напрямую снижает сумму аренды."},"uz":{"q":"Ijarachi turnover rent (aylanmadan foiz) to'laydi, minimal fiks stavka yo'q. Past sezonda uning savdosi ikki barobar kamaydi. Shu oyning ijara to'lovi qanday bo'ladi?","a":["Ijara taxminan ikki barobar kamayadi","Ijara o'zgarmaydi, chunki stavka shartnomada fiksirlangan","Savdo pasayishini qoplash uchun ijara oshadi"],"c":0,"why":"Sof turnover rent tizimida ijara savdodan foiz sifatida hisoblanadi, shuning uchun savdoning kamayishi ijara summasini ham to'g'ridan-to'g'ri kamaytiradi."},"en":{"q":"A tenant pays pure turnover rent (a percentage of sales) with no fixed minimum. In the low season, sales drop by half. What happens to that month's rent?","a":["Rent falls by roughly half","Rent stays the same since the rate is fixed in the contract","Rent rises to compensate for the sales drop"],"c":0,"why":"Under pure turnover rent, rent is a percentage of sales, so a sales drop directly cuts the rent amount."}},{"id":"LC011","cat":"logic","logic":true,"ru":{"q":"В бюджете ТРЦ заложен рост арендного дохода на 15%, но по факту рост составил лишь 5%. Аудит показал, что ставки были повышены как планировалось. Какая причина наиболее вероятна?","a":["Фактическая занятость (occupancy) оказалась ниже плановой","Операционные расходы выросли сильнее плана","Средний чек посетителей вырос сильнее плана"],"c":0,"why":"Если ставки выросли согласно плану, но общий доход отстаёт, значит недобор произошёл за счёт более низкой занятости площадей, чем закладывалось в бюджете."},"uz":{"q":"TRC byudjetida ijara daromadining 15% o'sishi rejalashtirilgan edi, lekin haqiqatda faqat 5% o'sdi. Audit shuni ko'rsatdiki, stavkalar reja bo'yicha oshirilgan. Eng ehtimoliy sabab qaysi?","a":["Haqiqiy bandlik (occupancy) rejadagidan past bo'lgan","Operatsion xarajatlar rejadan ko'proq oshgan","Tashrifchilarning o'rtacha cheki rejadan ko'proq oshgan"],"c":0,"why":"Agar stavkalar reja bo'yicha oshgan bo'lsa-yu umumiy daromad orqada qolsa, demak kamomad byudjetdagidan past bandlik hisobiga yuzaga kelgan."},"en":{"q":"A mall budgeted 15% growth in rental income but actual growth came in at only 5%. An audit confirmed rates were raised as planned. What is the most likely cause?","a":["Actual occupancy came in below the budgeted level","Operating expenses grew faster than planned","Average visitor spend grew faster than planned"],"c":0,"why":"If rates rose as planned but total income lagged, the shortfall most likely came from occupancy being lower than budgeted."}},{"id":"LC012","cat":"logic","logic":true,"ru":{"q":"GBA здания составляет 12000 м², а GLA (сдаваемая площадь) — 9000 м². Какая доля площади приходится на общие/технические зоны (коридоры, инженерия и т.д.)?","a":["25%","75%","133%"],"c":0,"why":"(12000-9000)/12000=0.25, то есть четверть общей площади здания не сдаётся в аренду напрямую."},"uz":{"q":"Binoning GBA maydoni 12000 m², GLA (ijaraga beriladigan maydon) esa 9000 m². Umumiy/texnik zonalarga (yo'laklar, muhandislik va h.k.) qancha ulush to'g'ri keladi?","a":["25%","75%","133%"],"c":0,"why":"(12000-9000)/12000=0.25, ya'ni binoning umumiy maydonining to'rtdan bir qismi bevosita ijaraga berilmaydi."},"en":{"q":"A building's GBA is 12,000 m², while GLA (leasable area) is 9,000 m². What share of the total area is common/technical space (corridors, MEP, etc.)?","a":["25%","75%","133%"],"c":0,"why":"(12,000-9,000)/12,000 = 0.25, meaning a quarter of the building's total area is not directly leasable."}},{"id":"LC013","cat":"logic","logic":true,"ru":{"q":"Арендодатель заменяет слабого арендатора одежды на популярную кофейню в той же зоне. Как это, скорее всего, повлияет на трафик к соседним бутикам?","a":["Трафик, вероятно, вырастет за счёт дополнительного повода зайти в зону","Трафик снизится, так как кофейня не продаёт одежду","Трафик не изменится, тип арендатора не влияет на соседей"],"c":0,"why":"Popular F&B операторы часто выступают локальными генераторами трафика (mini-anchor эффект), увеличивая проходимость мимо соседних магазинов."},"uz":{"q":"Uy egasi zaif kiyim-kechak ijarachisini xuddi shu zonadagi mashhur kofexonaga almashtirdi. Bu qo'shni butiklarga tashrifga qanday ta'sir qilishi ehtimoli ko'proq?","a":["Zonaga kirish uchun qo'shimcha sabab paydo bo'lgani uchun tashrif ortadi","Kofexona kiyim sotmagani uchun tashrif kamayadi","Ijarachi turi qo'shnilarga ta'sir qilmagani uchun o'zgarmaydi"],"c":0,"why":"Mashhur F&B operatorlari ko'pincha lokal tashrif generatori (mini-langar effekti) vazifasini bajarib, qo'shni do'konlar oldidan o'tish oqimini oshiradi."},"en":{"q":"A landlord replaces an underperforming apparel tenant with a popular coffee shop in the same zone. What is the likely effect on traffic to neighboring boutiques?","a":["Traffic likely increases due to an added reason to visit the zone","Traffic decreases since the coffee shop doesn't sell apparel","Traffic is unaffected, as tenant type doesn't impact neighbors"],"c":0,"why":"Popular F&B operators often act as local traffic generators (a mini-anchor effect), boosting passing traffic for nearby stores."}},{"id":"LC014","cat":"logic","logic":true,"ru":{"q":"Средняя ставка аренды по ТРЦ выросла на 10%, но общий арендный доход вырос лишь на 2%. Какая причина наиболее логично это объясняет?","a":["Занятость площадей за тот же период снизилась","Трафик посетителей вырос","Средний чек покупателей увеличился"],"c":0,"why":"Общий доход = ставка × сданная площадь; если ставка выросла сильнее дохода, значит сданная (занятая) площадь сократилась."},"uz":{"q":"TRC bo'yicha o'rtacha ijara stavkasi 10% ga oshdi, lekin umumiy ijara daromadi faqat 2% ga oshdi. Bu holatni eng mantiqiy izohlaydigan sabab qaysi?","a":["Xuddi shu davrda maydonlar bandligi kamaygan","Tashrifchilar oqimi oshgan","Xaridorlarning o'rtacha cheki oshgan"],"c":0,"why":"Umumiy daromad = stavka × ijaraga berilgan maydon; agar stavka daromaddan ko'proq oshgan bo'lsa, demak band qilingan maydon qisqargan."},"en":{"q":"A mall's average rental rate rose 10%, but total rental income grew only 2%. Which cause most logically explains this?","a":["Occupied space over the same period declined","Visitor footfall increased","Average customer spend increased"],"c":0,"why":"Total income = rate x leased area; if the rate grew faster than income, the leased (occupied) area must have shrunk."}},{"id":"LC015","cat":"logic","logic":true,"ru":{"q":"Оборот арендатора вырос на 30% за год, а его аренда — чисто фиксированная (без turnover). Что произойдёт с occupancy cost ratio этого арендатора?","a":["Ratio снизится, так как продажи растут быстрее фиксированной аренды","Ratio вырастет пропорционально продажам","Ratio не изменится, так как аренда фиксированная"],"c":0,"why":"При фиксированной аренде числитель (аренда) не меняется, а знаменатель (продажи) растёт, поэтому доля аренды в обороте снижается."},"uz":{"q":"Ijarachining aylanmasi yil davomida 30% ga oshdi, uning ijarasi esa sof fiksirlangan (turnover elementisiz). Bu ijarachining occupancy cost ratio ko'rsatkichiga nima bo'ladi?","a":["Savdo fiksirlangan ijaradan tezroq o'sgani uchun ratio pasayadi","Ratio savdoga proporsional oshadi","Ijara fiksirlangani uchun ratio o'zgarmaydi"],"c":0,"why":"Fiksirlangan ijarada suratdagi qiymat (ijara) o'zgarmaydi, maxrajdagi (savdo) esa oshadi, shuning uchun aylanmadagi ijara ulushi kamayadi."},"en":{"q":"A tenant's turnover grows 30% in a year, while its rent is purely fixed (no turnover component). What happens to that tenant's occupancy cost ratio?","a":["The ratio decreases, since sales outgrow the fixed rent","The ratio rises in proportion to sales","The ratio stays the same because rent is fixed"],"c":0,"why":"With fixed rent, the numerator (rent) stays constant while the denominator (sales) grows, so the rent-to-sales ratio falls."}},{"id":"LC016","cat":"logic","logic":true,"ru":{"q":"Два арендатора занимают по 50 м². У первого ставка $25/м², у второго — $18/м² плюс фикс $350/мес на маркетинг. У кого выше итоговый месячный платёж?","a":["Одинаково: у обоих $1250","Первый платит больше","Второй платит больше"],"c":0,"why":"25×50=1250; 18×50=900+350=1250 — суммы совпадают, несмотря на разную структуру платежа."},"uz":{"q":"Ikki ijarachi 50 m² dan egallaydi. Birinchisining stavkasi 25$/m², ikkinchisiniki — 18$/m² plyus marketing uchun fiks 350$/oy. Kimning yakuniy oylik to'lovi yuqori?","a":["Bir xil: ikkalasida ham 1250$","Birinchisi ko'proq to'laydi","Ikkinchisi ko'proq to'laydi"],"c":0,"why":"25×50=1250; 18×50=900+350=1250 — to'lov strukturasi turlicha bo'lsa-da summalar bir xil chiqadi."},"en":{"q":"Two tenants each occupy 50 m². Tenant 1 pays $25/m²; Tenant 2 pays $18/m² plus a fixed $350/month marketing charge. Whose total monthly payment is higher?","a":["Equal: both pay $1,250","Tenant 1 pays more","Tenant 2 pays more"],"c":0,"why":"25 x 50 = 1,250; 18 x 50 = 900 + 350 = 1,250 — the totals match despite the different payment structure."}},{"id":"LC017","cat":"logic","logic":true,"ru":{"q":"Конверсия в ТРЦ упала с 30% до 20%, при этом трафик вырос на 50%. Как в итоге изменится число покупок (транзакций)?","a":["Число покупок вырастет примерно на 0%","Число покупок вырастет примерно на 50%","Число покупок снизится вдвое"],"c":0,"why":"Транзакции = трафик × конверсия; 1.5×(20/30)=1.0, то есть рост трафика на 50% и падение конверсии на треть взаимно компенсируются."},"uz":{"q":"TRC da konversiya 30% dan 20% gacha tushdi, shu bilan birga tashrif 50% ga oshdi. Xaridlar (tranzaksiyalar) soni oxir-oqibat qanday o'zgaradi?","a":["Xaridlar soni taxminan 0% o'zgaradi","Xaridlar soni taxminan 50% ga oshadi","Xaridlar soni ikki barobar kamayadi"],"c":0,"why":"Tranzaksiyalar = tashrif × konversiya; 1.5×(20/30)=1.0, ya'ni tashrifning 50% o'sishi va konversiyaning uchdan biriga tushishi bir-birini qoplaydi."},"en":{"q":"Mall conversion rate drops from 30% to 20%, while footfall rises 50%. What ultimately happens to the number of transactions?","a":["Transactions change by roughly 0%","Transactions rise by roughly 50%","Transactions fall by half"],"c":0,"why":"Transactions = footfall x conversion; 1.5 x (20/30) = 1.0, so the 50% footfall gain and one-third drop in conversion roughly cancel out."}},{"id":"LC018","cat":"logic","logic":true,"ru":{"q":"В зоне фудкорта арендатор жалуется на низкий трафик. Менеджмент выяснил, что ближайший якорный кинотеатр закрыт третий месяц на ремонт. Как это связано?","a":["Кинотеатр как якорь обычно приводит трафик, идущий далее к фудкорту","Кинотеатр и фудкорт не связаны по потокам","Ремонт кинотеатра должен был увеличить трафик фудкорта"],"c":0,"why":"Кинотеатры — классический якорь для фудкорта: посетители до/после сеанса заходят поесть, поэтому закрытие снижает сопутствующий трафик."},"uz":{"q":"Fudkort zonasidagi ijarachi past tashrifdan shikoyat qilmoqda. Menejment yaqin atrofdagi langar kinoteatr uchinchi oydan beri ta'mirlash uchun yopiq ekanini aniqladi. Bu qanday bog'liq?","a":["Kinoteatr langar sifatida odatda fudkortga qo'shimcha tashrif olib keladi","Kinoteatr va fudkort oqimlar bo'yicha bog'liq emas","Kinoteatrning ta'mirlanishi fudkort tashrifini oshirishi kerak edi"],"c":0,"why":"Kinoteatrlar fudkort uchun klassik langar hisoblanadi: seansdan oldin/keyin tashrifchilar ovqatlanishga kirishadi, shuning uchun yopilish bilan bog'liq tashrif ham kamayadi."},"en":{"q":"A food court tenant complains of low traffic. Management finds the nearby anchor cinema has been closed for renovation for three months. How are these related?","a":["The cinema, as an anchor, normally drives traffic to the food court","The cinema and food court are unrelated in traffic terms","The cinema's closure should have boosted food court traffic"],"c":0,"why":"Cinemas are a classic food court anchor: visitors eat before or after a show, so its closure removes that spillover traffic."}},{"id":"LC019","cat":"logic","logic":true,"ru":{"q":"Арендатор занимает 80 м² при ставке $22/м², а его среднемесячные продажи — $8000. Какой occupancy cost ratio у этого арендатора?","a":["22%","8.8%","36.4%"],"c":0,"why":"Аренда=22×80=1760; ratio=1760/8000=0.22=22%."},"uz":{"q":"Ijarachi 22$/m² stavkada 80 m² maydonni egallaydi, uning oylik o'rtacha savdosi 8000$. Bu ijarachining occupancy cost ratio ko'rsatkichi qancha?","a":["22%","8.8%","36.4%"],"c":0,"why":"Ijara=22×80=1760; ratio=1760/8000=0.22=22%."},"en":{"q":"A tenant occupies 80 m² at a $22/m² rate, with average monthly sales of $8,000. What is that tenant's occupancy cost ratio?","a":["22%","8.8%","36.4%"],"c":0,"why":"Rent = 22 x 80 = 1,760; ratio = 1,760/8,000 = 0.22 = 22%."}},{"id":"LC020","cat":"logic","logic":true,"ru":{"q":"Менеджмент решает сдать пустующее помещение в fashion-зоне под пункт выдачи заказов (низкий трафикогенерирующий формат) вместо магазина одежды. Как это повлияет на трафик галереи в целом?","a":["Трафик галереи, скорее всего, снизится или не вырастет","Трафик заметно вырастет благодаря новому формату","Эффект одинаков независимо от формата арендатора"],"c":0,"why":"Пункты выдачи посещают целенаправленно и кратко, они не создают дополнительного покупательского потока для соседей, в отличие от полноценного магазина."},"uz":{"q":"Menejment fashion zonasidagi bo'sh xonani kiyim do'koni o'rniga past tashrif hosil qiluvchi buyurtma yetkazib berish punktiga berdi. Bu galereya tashrifiga qanday ta'sir qiladi?","a":["Galereya tashrifi, ehtimol, kamayadi yoki o'smaydi","Yangi format tufayli tashrif sezilarli oshadi","Ijarachi formatidan qat'i nazar ta'sir bir xil bo'ladi"],"c":0,"why":"Yetkazib berish punktlariga maqsadli va qisqa muddatga tashrif buyuriladi, ular to'liq qiymatli do'kondan farqli o'laroq qo'shnilar uchun qo'shimcha xaridor oqimini yaratmaydi."},"en":{"q":"Management leases a vacant fashion-zone unit to a parcel pickup point (a low-traffic-generating format) instead of an apparel store. How will this affect overall gallery traffic?","a":["Gallery traffic will likely decline or fail to grow","Traffic will rise noticeably thanks to the new format","The effect is the same regardless of tenant format"],"c":0,"why":"Pickup points are visited briefly and with a specific purpose; unlike a full retail store, they don't generate extra browsing traffic for neighbors."}},{"id":"LC021","cat":"logic","logic":true,"ru":{"q":"Общий доход от аренды в бюджете не выполнен, при этом ставки и занятость точно соответствовали плану. На что в первую очередь стоит проверить причину?","a":["На скидки, каникулы по аренде и списания (concessions/free rent)","На рост GLA здания","На рост среднего чека покупателей"],"c":0,"why":"Если ставка и занятость по плану, а факт дохода ниже, разницу чаще всего объясняют предоставленные скидки, льготные периоды или недосбор платежей."},"uz":{"q":"Byudjetdagi umumiy ijara daromadi bajarilmadi, shu bilan birga stavkalar va bandlik aniq rejaga mos kelgan. Sababni birinchi navbatda nimadan tekshirish kerak?","a":["Chegirmalar, ijara ta'tillari va yozib tashlashlar (concessions/free rent)","Binoning GLA o'sishidan","Xaridorlarning o'rtacha chekining oshishidan"],"c":0,"why":"Agar stavka va bandlik rejaga mos bo'lsa-yu, haqiqiy daromad past bo'lsa, farq ko'pincha berilgan chegirmalar, imtiyozli davrlar yoki to'lovlarning yig'ib olinmaganligi bilan izohlanadi."},"en":{"q":"Total budgeted rental income was missed, even though rates and occupancy matched the plan exactly. What should be checked first as the likely cause?","a":["Concessions, free-rent periods, and write-offs","Growth in building GLA","Growth in average customer spend"],"c":0,"why":"If rate and occupancy match the plan but actual income is lower, the gap is most often explained by concessions, rent-free periods, or uncollected charges."}},{"id":"LC022","cat":"logic","logic":true,"ru":{"q":"Арендатор предлагает заменить фиксированную аренду $2500/мес на turnover rent 10% при текущих продажах $15000/мес. Что выгоднее арендодателю при неизменных продажах?","a":["Остаться на фиксированной аренде $2500, это больше 10%×15000=$1500","Перейти на turnover, это принесёт больше $2500","Оба варианта дают одинаковый доход арендодателю"],"c":0,"why":"10% от $15000=$1500, что меньше текущих $2500 фиксированной аренды, поэтому при этих продажах переход невыгоден арендодателю."},"uz":{"q":"Ijarachi 2500$/oy fiks ijarani, oyiga 15000$ hozirgi savdoda 10% turnover rentga almashtirishni taklif qilmoqda. Savdo o'zgarmasa, uy egasiga qaysi variant foydali?","a":["Fiks 2500$ da qolish, bu 10%×15000=1500$ dan ko'proq","Turnoverga o'tish, bu 2500$ dan ko'proq beradi","Ikkala variant ham uy egasiga bir xil daromad beradi"],"c":0,"why":"15000$ dan 10% = 1500$, bu hozirgi fiks 2500$ dan kam, shuning uchun shu savdo darajasida o'tish uy egasiga foydali emas."},"en":{"q":"A tenant proposes replacing $2,500/month fixed rent with a 10% turnover rent at current sales of $15,000/month. Which is better for the landlord if sales stay unchanged?","a":["Keep the fixed $2,500, since it beats 10% x 15,000 = $1,500","Switch to turnover, as it yields more than $2,500","Both options give the landlord the same income"],"c":0,"why":"10% of $15,000 is $1,500, less than the current $2,500 fixed rent, so switching is not favorable for the landlord at this sales level."}},{"id":"LC023","cat":"logic","logic":true,"ru":{"q":"Доля вакантных площадей в галерее одежды выросла, при этом в зоне F&B — снизилась. Какой вывод о тенант-миксе центра наиболее обоснован?","a":["Спрос смещается в сторону F&B-операторов относительно фэшн-ритейла","Общая занятость центра точно выросла","Показатели никак не связаны с тенант-миксом"],"c":0,"why":"Разнонаправленная динамика вакансии по категориям — прямой сигнал смещения интереса арендаторов/спроса между сегментами тенант-микса."},"uz":{"q":"Kiyim-kechak galereyasida bo'sh maydonlar ulushi oshdi, F&B zonasida esa kamaydi. Markazning tenant-miksi haqida qaysi xulosa eng asosli?","a":["Talab fashion-riteyldan F&B operatorlariga qarab siljimoqda","Markazning umumiy bandligi aniq oshgan","Ko'rsatkichlar tenant-miks bilan bog'liq emas"],"c":0,"why":"Kategoriyalar bo'yicha bo'shliqning har xil yo'nalishda o'zgarishi ijarachilar/talabning tenant-miks segmentlari orasida siljiyotganining to'g'ridan-to'g'ri belgisidir."},"en":{"q":"Vacancy in the fashion gallery rises while vacancy in the F&B zone falls. Which conclusion about the mall's tenant mix is best supported?","a":["Demand is shifting toward F&B operators relative to fashion retail","Overall mall occupancy has definitely increased","The metrics are unrelated to tenant mix"],"c":0,"why":"Divergent vacancy trends by category directly signal a shift in tenant/demand interest between tenant-mix segments."}},{"id":"LC024","cat":"logic","logic":true,"ru":{"q":"ТРЦ снижает единый входной билет в развлекательный парк, из-за чего трафик в парк вырос на 25%, а средний чек на аттракцион упал на 20%. Что произойдёт с общей выручкой парка?","a":["Выручка вырастет примерно на 0%","Выручка вырастет примерно на 25%","Выручка снизится примерно на 20%"],"c":0,"why":"Выручка = трафик × чек; 1.25×0.8=1.0, то есть рост посещаемости почти полностью компенсируется падением среднего чека."},"uz":{"q":"TRC ko'ngilochar parkka yagona kirish chiptasini arzonlashtirdi, natijada parkka tashrif 25% ga oshdi, attraksionga o'rtacha chek esa 20% ga tushdi. Parkning umumiy daromadiga nima bo'ladi?","a":["Daromad taxminan 0% o'zgaradi","Daromad taxminan 25% ga oshadi","Daromad taxminan 20% ga kamayadi"],"c":0,"why":"Daromad = tashrif × chek; 1.25×0.8=1.0, ya'ni tashrifning oshishi o'rtacha chekning pasayishi bilan deyarli to'liq qoplanadi."},"en":{"q":"A mall cuts the single-entry ticket price for its entertainment park, driving park footfall up 25% while average spend per ride falls 20%. What happens to total park revenue?","a":["Revenue changes by roughly 0%","Revenue rises by roughly 25%","Revenue falls by roughly 20%"],"c":0,"why":"Revenue = footfall x average spend; 1.25 x 0.8 = 1.0, so the footfall gain nearly fully offsets the drop in average spend."}},{"id":"LC025","cat":"logic","logic":true,"ru":{"q":"Управляющая компания снижает эксплуатационные расходы (CAM) на 10% при неизменной валовой выручке от аренды. Что произойдёт с NOI центра?","a":["NOI вырастет","NOI снизится","NOI не изменится, так как CAM не входит в расчёт NOI"],"c":0,"why":"NOI = доходы минус операционные расходы; снижение расходов при неизменных доходах напрямую увеличивает NOI."},"uz":{"q":"Boshqaruv kompaniyasi ijaradan yalpi daromad o'zgarmagan holda ekspluatatsiya xarajatlarini (CAM) 10% ga kamaytirdi. Markazning NOI ko'rsatkichiga nima bo'ladi?","a":["NOI oshadi","NOI kamayadi","CAM NOI hisobiga kirmagani uchun NOI o'zgarmaydi"],"c":0,"why":"NOI = daromadlar minus operatsion xarajatlar; daromad o'zgarmagan holda xarajatlarning kamayishi NOI ni to'g'ridan-to'g'ri oshiradi."},"en":{"q":"A management company cuts operating expenses (CAM) by 10% while gross rental income stays unchanged. What happens to the mall's NOI?","a":["NOI increases","NOI decreases","NOI stays flat since CAM isn't part of the NOI calculation"],"c":0,"why":"NOI equals income minus operating expenses; cutting expenses while income holds steady directly boosts NOI."}},{"id":"LC026","cat":"logic","logic":true,"ru":{"q":"Договор предусматривает turnover rent 6% сверх breakpoint $80000 в год. Если годовой оборот арендатора равен ровно $80000, какая переменная часть аренды начисляется?","a":["$0, превышения над breakpoint нет","$4800, то есть 6% от всего оборота","$7200, максимум по условиям"],"c":0,"why":"Переменная часть считается только с суммы продаж СВЕРХ breakpoint; если оборот равен порогу, превышения нет, значит переменная часть равна нулю."},"uz":{"q":"Shartnomada yiliga 80000$ breakpoint dan oshgan qismiga 6% turnover rent ko'zda tutilgan. Ijarachining yillik aylanmasi aynan 80000$ bo'lsa, ijaraning o'zgaruvchan qismi qancha hisoblanadi?","a":["0$, breakpoint dan oshish yo'q","4800$, ya'ni butun aylanmadan 6%","7200$, shartlarga ko'ra maksimal"],"c":0,"why":"O'zgaruvchan qism faqat breakpoint dan OSHGAN savdo summasidan hisoblanadi; aylanma chegaraga teng bo'lsa, oshish yo'q, demak o'zgaruvchan qism nolga teng."},"en":{"q":"The lease sets a 6% turnover rent on sales above an $80,000 annual breakpoint. If the tenant's annual turnover is exactly $80,000, what is the variable rent component?","a":["$0, since there's no amount above the breakpoint","$4,800, i.e., 6% of total turnover","$7,200, the maximum under the terms"],"c":0,"why":"The variable component is charged only on sales ABOVE the breakpoint; if turnover equals the threshold exactly, there's no excess, so the variable rent is zero."}},{"id":"LC027","cat":"logic","logic":true,"ru":{"q":"В ТРЦ появился новый крупный конкурент по соседству. Трафик существующего центра упал на 15%, конверсия и средний чек не изменились. Что нужно ожидать от общей выручки арендаторов?","a":["Выручка упадёт примерно на 15%","Выручка останется прежней благодаря лояльным покупателям","Выручка вырастет из-за конкуренции, стимулирующей рынок"],"c":0,"why":"При неизменных конверсии и чеке выручка пропорциональна трафику, поэтому падение трафика на 15% ведёт к сопоставимому падению продаж."},"uz":{"q":"TRC yaqinida yangi yirik raqobatchi paydo bo'ldi. Mavjud markazga tashrif 15% ga tushdi, konversiya va o'rtacha chek o'zgarmadi. Ijarachilarning umumiy daromadidan nima kutish kerak?","a":["Daromad taxminan 15% ga tushadi","Sodiq xaridorlar tufayli daromad o'sha darajada qoladi","Bozorni rag'batlantiruvchi raqobat tufayli daromad oshadi"],"c":0,"why":"Konversiya va chek o'zgarmagan holda daromad tashrifga proporsional bo'ladi, shuning uchun tashrifning 15% ga tushishi shunga mos savdo pasayishiga olib keladi."},"en":{"q":"A large new competitor opens nearby. The existing mall's footfall drops 15%, while conversion and average basket stay unchanged. What should happen to total tenant revenue?","a":["Revenue drops by roughly 15%","Revenue stays the same thanks to loyal shoppers","Revenue rises because competition stimulates the market"],"c":0,"why":"With conversion and basket size unchanged, revenue is proportional to footfall, so a 15% footfall drop leads to a comparable sales decline."}},{"id":"LC028","cat":"logic","logic":true,"ru":{"q":"Арендатору дали 2 месяца бесплатной аренды в год по договору на $2000/мес. Как это скажется на фактическом годовом доходе против номинала $24000?","a":["Фактический доход составит $20000, то есть на $4000 меньше номинала","Фактический доход останется $24000, льгота не влияет на кассу","Фактический доход превысит $24000 за счёт компенсаций"],"c":0,"why":"2 месяца без оплаты означают недополучение 2×$2000=$4000 в год, поэтому реальный денежный поток ниже номинальной годовой ставки."},"uz":{"q":"Ijarachiga 2000$/oy shartnoma bo'yicha yiliga 2 oy bepul ijara berildi. Bu haqiqiy yillik daromadga nominal 24000$ bilan solishtirganda qanday ta'sir qiladi?","a":["Haqiqiy daromad 20000$ bo'ladi, ya'ni nominaldan 4000$ kam","Haqiqiy daromad 24000$ bo'lib qoladi, imtiyoz kassaga ta'sir qilmaydi","Kompensatsiyalar hisobiga haqiqiy daromad 24000$ dan oshadi"],"c":0,"why":"2 oy to'lovsiz degani yiliga 2×2000$=4000$ kam olish degani, shuning uchun haqiqiy pul oqimi nominal yillik stavkadan past bo'ladi."},"en":{"q":"A landlord grants a new tenant a 2-month rent-free period per year on a $2,000/month lease. How does this affect actual annual income versus the nominal annual rate of $24,000?","a":["Actual income is $20,000, or $4,000 below nominal","Actual income stays at $24,000, since concessions don't hit cash flow","Actual income exceeds $24,000 due to offsetting compensation"],"c":0,"why":"Two months of no payment means $4,000 (2 x $2,000) is forgone annually, so real cash flow falls below the nominal annual rate."}},{"id":"LC029","cat":"logic","logic":true,"ru":{"q":"В ТРЦ доля вакансии выросла именно в fashion-галерее рядом с якорным универмагом, который недавно закрылся. Какая связь здесь наиболее вероятна?","a":["Уход якоря снизил трафик и привлекательность этой зоны","Связи нет, вакансия никогда не зависит от якоря","Вакансия выросла из-за слишком высокого трафика"],"c":0,"why":"Потеря якоря снижает трафик и привлекательность соседних площадей, что затрудняет их сдачу и повышает вакансию именно в этой зоне."},"uz":{"q":"TRC da bo'sh maydonlar ulushi aynan yaqinda yopilgan langar universmag yonidagi fashion-galereyada oshdi. Bu yerda eng ehtimoliy bog'liqlik qanday?","a":["Langarning ketishi bu zona tashrifi va jozibasini kamaytirdi","Bog'liqlik yo'q, bo'shliq langarga bog'liq bo'lmaydi","Bo'shliq haddan tashqari yuqori tashrif tufayli oshgan"],"c":0,"why":"Langarni yo'qotish qo'shni maydonlarning tashrifi va jozibadorligini kamaytiradi, bu esa ularni ijaraga berishni qiyinlashtirib, aynan shu zonada bo'shlikni oshiradi."},"en":{"q":"Vacancy in a mall rose specifically in the fashion gallery next to an anchor department store that recently closed. What connection is most likely here?","a":["Losing the anchor cut this zone's traffic and appeal","There's no connection; vacancy never depends on anchors","Vacancy rose because that zone had excessive traffic"],"c":0,"why":"Losing an anchor reduces traffic and appeal for adjacent space, making it harder to lease and driving up vacancy specifically in that zone."}},{"id":"LC030","cat":"logic","logic":true,"ru":{"q":"Арендатор А занимает 200 м² по $15/м², арендатор Б занимает 100 м² по $25/м². У кого выше общая месячная аренда?","a":["У А ($3000 против $2500) — важна площадь×ставка","У Б, так как его ставка выше","Аренда одинаковая, площадь и ставка компенсируются"],"c":0,"why":"15×200=3000, 25×100=2500; общий доход зависит от произведения ставки на площадь, а не только от уровня ставки за м²."},"uz":{"q":"A ijarachisi 200 m² egallab 15$/m² to'laydi, B ijarachisi 100 m² egallab 25$/m² to'laydi. Kimning umumiy oylik ijarasi yuqori?","a":["A da ($3000 ga qarshi $2500) — muhimi maydon×stavka","B da, chunki uning stavkasi yuqori","Ijara bir xil, maydon va stavka qoplashadi"],"c":0,"why":"15×200=3000, 25×100=2500; umumiy daromad faqat m² uchun stavka darajasiga emas, stavka va maydon ko'paytmasiga bog'liq."},"en":{"q":"Tenant A occupies 200 m² at $15/m²; Tenant B occupies 100 m² at $25/m². Who pays more total monthly rent?","a":["A does ($3,000 vs $2,500) — area x rate is what counts","B does, since B's rate is higher","Rent is equal, area and rate offset"],"c":0,"why":"15 x 200 = 3,000 versus 25 x 100 = 2,500; total income depends on rate multiplied by area, not the per-m² rate alone."}},{"id":"LC031","cat":"logic","logic":true,"ru":{"q":"Занятость центра выросла с 90% до 95%, но NOI снизился по сравнению с прошлым годом. Что логичнее всего объясняет это противоречие?","a":["Расходы или скидки выросли сильнее дохода от занятости","Рост занятости всегда снижает NOI автоматически","NOI не связан с занятостью, противоречия нет"],"c":0,"why":"Рост занятости обычно увеличивает доход, поэтому снижение NOI при этом объясняется опережающим ростом расходов, скидок или снижением ставок у новых арендаторов."},"uz":{"q":"Markazning bandligi 90% dan 95% gacha oshdi, lekin NOI o'tgan yilga nisbatan kamaydi. Bu ziddiyatni nima eng mantiqiy izohlaydi?","a":["Xarajat yoki chegirmalar bandlik daromadidan tezroq oshgan","Bandlikning oshishi doim avtomatik NOI ni kamaytiradi","NOI bandlikka bog'liq emas, ziddiyat yo'q"],"c":0,"why":"Bandlikning oshishi odatda daromadni oshiradi, shuning uchun shu bilan birga NOI ning kamayishi xarajatlar, chegirmalar yoki yangi ijarachilarning past stavkalari tezroq o'sganini bildiradi."},"en":{"q":"Occupancy rose from 90% to 95%, yet NOI fell compared to last year. What most logically explains this contradiction?","a":["Expenses or concessions grew faster than occupancy income","Rising occupancy always automatically reduces NOI","NOI is unrelated to occupancy, so there's no contradiction"],"c":0,"why":"Rising occupancy normally increases income, so a simultaneous NOI decline points to expenses, concessions, or lower rates on new tenants growing even faster."}},{"id":"LC032","cat":"logic","logic":true,"ru":{"q":"Сравниваются два помещения одинаковой площади: одно у входа в проходной зоне, другое в дальнем углу второго этажа. При прочих равных, где ставка за м² обычно выше и почему?","a":["У входа — из-за более высокого трафика мимо витрины","В дальнем углу — там меньше конкурентов рядом","Ставка не должна отличаться, если площадь одинаковая"],"c":0,"why":"Ставка аренды тесно связана с проходимостью (foot traffic) конкретной точки: чем больше людей проходит мимо витрины, тем выше потенциальные продажи и, соответственно, ставка."},"uz":{"q":"Bir xil maydonli ikkita xona solishtiriladi: biri kirish oldida, ikkinchisi ikkinchi qavat uzoq burchagida. Boshqa shartlar teng bo'lsa, qaysi birida m² stavkasi odatda yuqori va nega?","a":["Kirish oldida — vitrina oldidan o'tuvchilar ko'proq bo'lgani uchun","Uzoq burchakda — u yerda raqobatchilar kamroq","Maydon bir xil bo'lsa, stavka farq qilmasligi kerak"],"c":0,"why":"Ijara stavkasi aniq nuqtaning o'tkinchi trafigiga chambarchas bog'liq: vitrina oldidan qancha ko'p odam o'tsa, potensial savdo va shunga mos stavka ham shuncha yuqori bo'ladi."},"en":{"q":"Two equal-sized units are compared: one near the entrance, the other in a far corner of the second floor. All else equal, which typically gets a higher rate per m², and why?","a":["The entrance unit, due to higher foot traffic past its storefront","The far-corner unit, since it has fewer nearby competitors","The rate should be identical since the area is the same"],"c":0,"why":"Rental rates are closely tied to a location's foot traffic: the more people pass a storefront, the higher its sales potential and thus its rate."}},{"id":"LC033","cat":"logic","logic":true,"ru":{"q":"Общая GLA центра — 20000 м², занято 17000 м². Средняя ставка по занятым площадям — $18/м²/мес. Какой примерно фактический ежемесячный арендный доход генерирует центр?","a":["$306000","$360000","$204000"],"c":0,"why":"Доход считается по фактически занятой площади: 17000×18=306000, а не по всей GLA 20000 м²."},"uz":{"q":"Markazning umumiy GLA maydoni 20000 m², shundan 17000 m² band. Band maydonlar bo'yicha o'rtacha stavka 18$/m²/oy. Markaz taxminan qancha oylik haqiqiy ijara daromadi keltiradi?","a":["306000$","360000$","204000$"],"c":0,"why":"Daromad haqiqatda band bo'lgan maydon bo'yicha hisoblanadi: 17000×18=306000, butun 20000 m² GLA bo'yicha emas."},"en":{"q":"A mall's total GLA is 20,000 m², of which 17,000 m² is occupied. The average rate on occupied space is $18/m²/month. Roughly what actual monthly rental income does the mall generate?","a":["$306,000","$360,000","$204,000"],"c":0,"why":"Income is calculated on actually occupied space: 17,000 x 18 = 306,000, not on the full 20,000 m² of GLA."}},{"id":"LC034","cat":"logic","logic":true,"ru":{"q":"Менеджмент вводит новую крупную детскую игровую зону (трафикогенератор) на пустующем месте. Продажи каких категорий арендаторов вероятнее всего вырастут в первую очередь по соседству?","a":["Детские товары и F&B рядом с зоной","Ювелирные магазины в другом крыле здания","Ни одна категория, зона развлекательная"],"c":0,"why":"Игровая зона как новый трафикогенератор в первую очередь увеличивает посещаемость и время пребывания рядом расположенных категорий — детских товаров и фудкорта."},"uz":{"q":"Menejment bo'sh joyda yangi yirik bolalar o'yin zonasini (tashrif generatori) ochmoqda. Qaysi kategoriya ijarachilarining savdosi qo'shni hududda birinchi navbatda oshishi ehtimoli ko'proq?","a":["Zona yaqinidagi bolalar tovarlari va F&B","Binoning boshqa qanotidagi zargarlik do'konlari","Hech qaysi kategoriya, zona ko'ngilochar"],"c":0,"why":"O'yin zonasi yangi tashrif generatori sifatida birinchi navbatda yaqin joylashgan kategoriyalar — bolalar tovarlari va fudkortning tashrifi va bo'lish vaqtini oshiradi."},"en":{"q":"Management opens a large new kids' play zone (a traffic generator) in previously vacant space. Which nearby tenant categories are most likely to see sales gains first?","a":["Kids' goods and F&B near the zone","Jewelry stores in another wing of the building","No category, since it's an entertainment zone"],"c":0,"why":"A play zone, as a new traffic generator, primarily boosts visits and dwell time for nearby categories such as kids' goods and food court operators."}},{"id":"LC035","cat":"logic","logic":true,"ru":{"q":"Ставка аренды $10,000/мес с эскалацией 5% в год. Какова будет ставка на 2-й год?","a":["$10,500/мес","$11,000/мес","$10,050/мес"],"c":0,"why":"Эскалация 5% применяется к базовой ставке: $10,000 × 1.05 = $10,500."},"uz":{"q":"Ijara stavkasi $10,000/oy, yillik eskalatsiya 5%. 2-yilda stavka qancha bo'ladi?","a":["$10,500/oy","$11,000/oy","$10,050/oy"],"c":0,"why":"5% eskalatsiya bazaviy stavkaga qo'llanadi: $10,000 × 1.05 = $10,500."},"en":{"q":"Rent is $10,000/month with 5% annual escalation. What is the rent in year 2?","a":["$10,500/month","$11,000/month","$10,050/month"],"c":0,"why":"The 5% escalation applies to the base rent: $10,000 × 1.05 = $10,500."}},{"id":"LC036","cat":"logic","logic":true,"ru":{"q":"Ставка $12,000/мес, эскалация 5% в год, начисляется на предыдущий год. Какова ставка на 3-й год?","a":["$13,230/мес","$13,200/мес","$12,600/мес"],"c":0,"why":"Компаундирование: $12,000×1.05=$12,600 (год2), $12,600×1.05=$13,230 (год3)."},"uz":{"q":"Stavka $12,000/oy, yillik eskalatsiya 5%, oldingi yil summasiga qo'shiladi. 3-yilda stavka qancha?","a":["$13,230/oy","$13,200/oy","$12,600/oy"],"c":0,"why":"Murakkab foiz: $12,000×1.05=$12,600 (2-yil), $12,600×1.05=$13,230 (3-yil)."},"en":{"q":"Rent is $12,000/month, escalating 5% annually on a compounding basis. What is the rent in year 3?","a":["$13,230/month","$13,200/month","$12,600/month"],"c":0,"why":"Compounding means each year grows on the prior year: $12,000→$12,600→$13,230."}},{"id":"LC037","cat":"logic","logic":true,"ru":{"q":"Арендатор получил 3 месяца арендных каникул на fit-out при годовой аренде. Ставка $20,000/мес. Как это влияет на эффективную годовую ставку?","a":["Снижает её примерно на 25%","Не влияет, ставка headline остаётся","Повышает её, т.к. арендатор дольше в объекте"],"c":0,"why":"Арендатор платит только за 9 из 12 месяцев, поэтому эффективная ставка падает примерно на четверть."},"uz":{"q":"Ijarachi fit-out uchun 3 oy ijara ta'tilini oldi, shartnoma 1 yilga. Stavka $20,000/oy. Bu samarali yillik stavkaga qanday ta'sir qiladi?","a":["Taxminan 25% ga kamaytiradi","Ta'sir qilmaydi, headline stavka saqlanadi","Oshiradi, chunki ijarachi uzoqroq turadi"],"c":0,"why":"Ijarachi 12 oydan faqat 9 oy uchun to'laydi, shuning uchun samarali stavka taxminan chorak qismga tushadi."},"en":{"q":"A tenant gets a 3-month rent-free fit-out period on a 1-year lease at $20,000/month headline rent. How does this affect the effective annual rent?","a":["It reduces it by about 25%","No effect, headline rate still applies","It increases it since the tenant stays longer"],"c":0,"why":"The tenant only pays for 9 of 12 months, so the effective rent drops by roughly a quarter versus the headline rate."}},{"id":"LC038","cat":"logic","logic":true,"ru":{"q":"Два брокера предлагают одинаковую headline-ставку $15,000/мес на 12 месяцев, но один даёт 2 месяца free fit-out, другой — 0. Какой контракт даёт меньший фактический доход владельцу?","a":["С 2 месяцами free fit-out","С 0 месяцами free fit-out","Оба дают одинаковый доход"],"c":0,"why":"Free fit-out означает, что арендатор не платит за эти месяцы, значит фактически собранная сумма меньше."},"uz":{"q":"Ikki broker bir xil headline stavka $15,000/oy, 12 oyga taklif qiladi, lekin biri 2 oy bepul fit-out beradi, ikkinchisi — yo'q. Qaysi shartnoma egasiga kamroq real daromad beradi?","a":["2 oy bepul fit-out bilan","0 oy bepul fit-out bilan","Ikkalasi ham bir xil daromad beradi"],"c":0,"why":"Bepul fit-out davri uchun ijarachi to'lamaydi, shuning uchun yig'ilgan real summa kamroq bo'ladi."},"en":{"q":"Two brokers offer the same $15,000/month headline rate for 12 months, but one includes 2 months rent-free fit-out and the other none. Which contract yields less actual income to the landlord?","a":["The one with 2 months rent-free","The one with 0 months rent-free","Both yield the same income"],"c":0,"why":"The rent-free months mean the tenant pays nothing during that period, so total collected rent is lower."}},{"id":"LC039","cat":"logic","logic":true,"ru":{"q":"Бюджет предполагал ставку $25/м² для юнита 200 м². По факту подписали $20/м². Какова месячная недостача дохода?","a":["$1,000","$5,000","$4,000"],"c":0,"why":"Разница в ставке $5/м² × 200 м² = $1,000 в месяц недополученного дохода."},"uz":{"q":"Byudjetda 200 m² birlik uchun $25/m² stavka rejalashtirilgan edi. Aslida $20/m² ga imzolandi. Oylik daromad kamomadi qancha?","a":["$1,000","$5,000","$4,000"],"c":0,"why":"Stavka farqi $5/m² × 200 m² = oyiga $1,000 yo'qotilgan daromad."},"en":{"q":"Budgeted rate was $25/m² for a 200 m² unit, but the actual signed rate was $20/m². What is the monthly revenue shortfall?","a":["$1,000","$5,000","$4,000"],"c":0,"why":"The rate gap of $5/m² × 200 m² equals a $1,000/month shortfall versus budget."}},{"id":"LC040","cat":"logic","logic":true,"ru":{"q":"Бюджет: 150 м² по $30/м². Факт: сдано по $28/м², но площадь после перепланировки стала 160 м². Как изменился месячный доход по сравнению с бюджетом?","a":["Вырос с $4,500 до $4,480 — почти без изменений","Вырос значительно, так как площадь больше","Упал вдвое"],"c":0,"why":"Бюджет: 150×$30=$4,500. Факт: 160×$28=$4,480 — разница минимальна, увеличение площади почти компенсировало снижение ставки."},"uz":{"q":"Byudjet: 150 m², $30/m². Fakt: $28/m² ga topshirilgan, lekin qayta rejalashtirishdan keyin maydon 160 m² bo'ldi. Oylik daromad byudjetga nisbatan qanday o'zgardi?","a":["$4,500 dan $4,480 gacha — deyarli o'zgarmadi","Maydon kattaroq bo'lgani uchun sezilarli o'sdi","Ikki barobar kamaydi"],"c":0,"why":"Byudjet: 150×$30=$4,500. Fakt: 160×$28=$4,480 — farq minimal, maydon o'sishi stavka pasayishini deyarli qoplagan."},"en":{"q":"Budget: 150 m² at $30/m². Actual: leased at $28/m² but the unit was reconfigured to 160 m². How does monthly income compare to budget?","a":["Went from $4,500 to $4,480 — nearly unchanged","Rose significantly because area is larger","Fell by half"],"c":0,"why":"Budget: 150×$30=$4,500. Actual: 160×$28=$4,480 — the area increase nearly offset the lower rate."}},{"id":"LC041","cat":"logic","logic":true,"ru":{"q":"Торговая точка платит фиксированную аренду $5,000/мес независимо от продаж. Продажи выросли с $50,000 до $100,000/мес. Что произошло с occupancy cost ratio?","a":["Снизился вдвое, с 10% до 5%","Остался неизменным, 10%","Вырос вдвое, до 20%"],"c":0,"why":"При фиксированной аренде рост продаж напрямую снижает долю аренды в выручке: $5,000/$100,000=5% против $5,000/$50,000=10%."},"uz":{"q":"Do'kon sotuvdan qat'i nazar $5,000/oy fiksirlangan ijara to'laydi. Sotuv $50,000 dan $100,000/oy gacha o'sdi. Occupancy cost ratio nima bo'ladi?","a":["Ikki baravar kamaydi, 10% dan 5% ga","O'zgarmaydi, 10%","Ikki baravar oshadi, 20% ga"],"c":0,"why":"Fiksirlangan ijarada sotuv o'sishi ijaraning daromaddagi ulushini kamaytiradi: $5,000/$100,000=5% ga qarshi $5,000/$50,000=10%."},"en":{"q":"A store pays a fixed $5,000/month rent regardless of sales. Sales grew from $50,000 to $100,000/month. What happens to the occupancy cost ratio?","a":["It halves, from 10% to 5%","It stays the same at 10%","It doubles to 20%"],"c":0,"why":"With fixed rent, higher sales directly lower rent's share of revenue: $5,000/$100,000=5% versus $5,000/$50,000=10%."}},{"id":"LC042","cat":"logic","logic":true,"ru":{"q":"У арендатора чисто turnover-rent договор (% от продаж). Продажи выросли на 40%, формула аренды не менялась. Как изменился occupancy cost ratio?","a":["Остался тем же самым процентом","Снизился пропорционально росту продаж","Вырос пропорционально росту продаж"],"c":0,"why":"При turnover rent аренда — это фиксированный процент от продаж, поэтому ratio (рента/продажи) не меняется при росте продаж."},"uz":{"q":"Ijarachida sof turnover-rent shartnoma bor (sotuvdan %). Sotuv 40% ga o'sdi, ijara formulasi o'zgarmadi. Occupancy cost ratio qanday o'zgardi?","a":["Xuddi shu foizda qoldi","Sotuv o'sishiga proporsional kamaydi","Sotuv o'sishiga proporsional oshdi"],"c":0,"why":"Turnover rentda ijara sotuvning belgilangan foizi bo'lgani uchun, sotuv o'sganda ratio (ijara/sotuv) o'zgarmaydi."},"en":{"q":"A tenant has a pure turnover-rent lease (% of sales). Sales rose 40% while the rent formula stayed the same. How does the occupancy cost ratio change?","a":["It stays exactly the same percentage","It falls proportionally to the sales increase","It rises proportionally to the sales increase"],"c":0,"why":"Under turnover rent, rent is a fixed percentage of sales, so the ratio (rent/sales) does not change when sales grow."}},{"id":"LC043","cat":"logic","logic":true,"ru":{"q":"Мол добавил 500 новых парковочных мест у главного входа. Какой наиболее вероятный эффект на пиковый трафик посетителей?","a":["Рост посещаемости в часы пик за счёт снятия барьера доступа","Снижение посещаемости из-за перегрузки въезда","Никакого эффекта, парковка не влияет на трафик"],"c":0,"why":"Нехватка парковки — частый барьер для посещения в пиковые часы; больше мест снимает это ограничение и увеличивает поток."},"uz":{"q":"Savdo markazi asosiy kirish oldida 500 ta yangi avtoturargoh joyi qo'shdi. Eng chinniqroq ta'sir tashrif buyuruvchilar oqimiga qanday bo'ladi?","a":["Kirish to'sig'i olib tashlangani uchun peak soatlarda tashrif o'sadi","Kirishda tirbandlik tufayli tashrif kamayadi","Hech qanday ta'sir yo'q, avtoturargoh trafikka ta'sir qilmaydi"],"c":0,"why":"Avtoturargoh yetishmasligi ko'pincha peak soatlarda tashrifga to'siq bo'ladi; ko'proq joy bu cheklovni olib tashlab, oqimni oshiradi."},"en":{"q":"A mall adds 500 new parking spaces near the main entrance. What is the most likely effect on peak-hour footfall?","a":["Footfall rises at peak hours as an access barrier is removed","Footfall falls due to entrance congestion","No effect, since parking doesn't influence footfall"],"c":0,"why":"Parking shortage is a common barrier to visiting during peak hours; more capacity removes that constraint and boosts footfall."}},{"id":"LC044","cat":"logic","logic":true,"ru":{"q":"Мол закрыл один из трёх входов на реконструкцию на 2 месяца. Какой наиболее вероятный краткосрочный эффект на общий footfall?","a":["Снижение footfall из-за уменьшения доступности объекта","Footfall не изменится, так как площадь та же","Footfall вырастет за счёт концентрации потока"],"c":0,"why":"Меньше точек входа снижает удобство доступа для части аудитории, что обычно снижает общий трафик, а не концентрирует его без потерь."},"uz":{"q":"Savdo markazi uchta kirishdan bittasini 2 oyga rekonstruksiya uchun yopdi. Umumiy footfallga eng ehtimoliy qisqa muddatli ta'siri qanday?","a":["Obyektga kirish qulayligi kamaygani uchun footfall pasayadi","Maydon o'zgarmagani uchun footfall o'zgarmaydi","Oqim konsentratsiyasi tufayli footfall oshadi"],"c":0,"why":"Kamroq kirish nuqtasi ba'zi tashrif buyuruvchilar uchun qulaylikni kamaytiradi, bu odatda umumiy trafikni kamaytiradi, yo'qotishsiz konsentratsiya qilmaydi."},"en":{"q":"A mall closes one of its three entrances for 2 months of renovation. What is the most likely short-term effect on total footfall?","a":["Footfall declines due to reduced accessibility","Footfall stays unchanged since GLA is the same","Footfall increases as traffic concentrates"],"c":0,"why":"Fewer entry points reduces convenience for part of the catchment, which typically lowers total traffic rather than losslessly concentrating it."}},{"id":"LC045","cat":"logic","logic":true,"ru":{"q":"Крупный якорный гипермаркет объявил об открытии в моле, где раньше якоря не было. Каков наиболее вероятный эффект на footfall соседних мелких арендаторов?","a":["Footfall вырастет за счёт эффекта якоря, притягивающего трафик","Footfall снизится, так как якорь заберёт всех покупателей себе","Footfall не изменится, якоря влияют только на свою зону"],"c":0,"why":"Якорные арендаторы генерируют базовый трафик, часть которого перетекает к соседним магазинам — это классический эффект якоря."},"uz":{"q":"Ilgari langar bo'lmagan savdo markazida yirik gipermarket langar sifatida ochilishi e'lon qilindi. Qo'shni kichik ijarachilar footfalliga eng ehtimoliy ta'sir qanday?","a":["Langar effekti trafikni tortgani uchun footfall oshadi","Langar barcha xaridorlarni o'ziga olgani uchun footfall kamayadi","Footfall o'zgarmaydi, langarlar faqat o'z zonasiga ta'sir qiladi"],"c":0,"why":"Langar ijarachilar bazaviy trafik yaratadi va uning bir qismi qo'shni do'konlarga oqib o'tadi — bu klassik langar effekti."},"en":{"q":"A major hypermarket anchor announces it will open in a mall that previously had no anchor. What is the most likely effect on footfall for nearby small tenants?","a":["Footfall rises due to the anchor's traffic-generating effect","Footfall falls as the anchor captures all shoppers","Footfall is unaffected since anchors only influence their own zone"],"c":0,"why":"Anchor tenants generate baseline traffic, part of which spills over to neighboring stores — the classic anchor draw effect."}},{"id":"LC046","cat":"logic","logic":true,"ru":{"q":"Доля F&B в галерее выросла с 10% до 25% арендопригодной площади за счёт сокращения fashion-операторов. Как это, скорее всего, повлияет на среднее время пребывания (dwell time)?","a":["Dwell time вырастет, так как F&B удерживает посетителей дольше","Dwell time снизится, так как еда быстрее покупки одежды","Dwell time не изменится, категория не влияет на время"],"c":0,"why":"F&B форматы (кафе, рестораны) предполагают более длительное пребывание, чем быстрый шопинг, поэтому рост доли F&B увеличивает dwell time."},"uz":{"q":"Fashion operatorlari qisqargani hisobiga galereyada F&B ulushi ijaraga yaroqli maydonning 10% dan 25% gacha o'sdi. Bu o'rtacha turish vaqtiga (dwell time) qanday ta'sir qiladi?","a":["Dwell time oshadi, chunki F&B tashrif buyuruvchilarni uzoqroq ushlab turadi","Dwell time kamayadi, chunki ovqatlanish kiyim xarid qilishdan tezroq","Dwell time o'zgarmaydi, kategoriya vaqtga ta'sir qilmaydi"],"c":0,"why":"F&B formatlari (kafe, restoranlar) tez xariddan ko'ra uzoqroq turishni nazarda tutadi, shuning uchun F&B ulushi o'sishi dwell time'ni oshiradi."},"en":{"q":"F&B share of GLA in a mall's gallery rose from 10% to 25%, replacing fashion tenants. What is the likely effect on average dwell time?","a":["Dwell time increases, since F&B keeps visitors longer","Dwell time decreases, since eating is faster than shopping","Dwell time is unaffected by category mix"],"c":0,"why":"F&B formats (cafes, restaurants) involve longer stays than quick shopping trips, so a higher F&B share increases dwell time."}},{"id":"LC047","cat":"logic","logic":true,"ru":{"q":"Мол увеличил долю развлекательных операторов (кино, детские зоны) на 2-м этаже. Какой эффект это, скорее всего, окажет на кросс-шопинг между этажами?","a":["Кросс-шопинг вырастет, так как посетители развлечений заходят и в другие магазины","Кросс-шопинг исчезнет, посетители останутся только в зоне развлечений","Эффекта не будет, этажи всегда изолированы"],"c":0,"why":"Развлечения увеличивают время в моле и мотивируют посетителей проходить через торговые зоны на пути к развлечениям, повышая кросс-шопинг."},"uz":{"q":"Savdo markazi 2-qavatda ko'ngilochar operatorlar (kino, bolalar zonasi) ulushini oshirdi. Bu qavatlar orasidagi cross-shopping'ga qanday ta'sir qiladi?","a":["Cross-shopping oshadi, chunki ko'ngilochar tashrif buyuruvchilar boshqa do'konlarga ham kiradi","Cross-shopping yo'qoladi, tashrif buyuruvchilar faqat ko'ngilochar zonada qoladi","Ta'siri bo'lmaydi, qavatlar har doim izolyatsiyalangan"],"c":0,"why":"Ko'ngilochar zonalar savdo markazidagi vaqtni oshiradi va tashrif buyuruvchilarni savdo zonalari orqali o'tishga undaydi, bu cross-shopping'ni kuchaytiradi."},"en":{"q":"A mall increases entertainment tenants (cinema, kids' zone) on the 2nd floor. What effect is this likely to have on cross-shopping between floors?","a":["Cross-shopping increases as entertainment visitors also browse other stores","Cross-shopping disappears as visitors stay only in the entertainment zone","No effect, floors are always isolated"],"c":0,"why":"Entertainment extends time spent in the mall and routes visitors through retail zones on the way, boosting cross-shopping."}},{"id":"LC048","cat":"logic","logic":true,"ru":{"q":"Портфель из 10 юнитов по 100 м² каждый сдаётся по $20/м². Один юнит освобождается. Насколько снижается месячный доход портфеля?","a":["На $2,000","На $20,000","На $200"],"c":0,"why":"Один юнит = 100 м² × $20/м² = $2,000/мес, именно эта сумма выпадает из общего дохода."},"uz":{"q":"10 ta 100 m² lik birlikdan iborat portfel har biri $20/m² ga ijaraga berilgan. Bitta birlik bo'shab qoladi. Portfelning oylik daromadi qancha kamayadi?","a":["$2,000 ga","$20,000 ga","$200 ga"],"c":0,"why":"Bitta birlik = 100 m² × $20/m² = $2,000/oy, aynan shu summa umumiy daromaddan yo'qoladi."},"en":{"q":"A portfolio of 10 units, each 100 m², is leased at $20/m². One unit becomes vacant. By how much does monthly portfolio income fall?","a":["$2,000","$20,000","$200"],"c":0,"why":"One unit equals 100 m² × $20/m² = $2,000/month, which is exactly the amount removed from total income."}},{"id":"LC049","cat":"logic","logic":true,"ru":{"q":"Два юнита по 100 м² каждый: юнит А на 1-м этаже сдан по $30/м², юнит Б на 3-м этаже — по $15/м². Если освобождается юнит Б, а не А, как это влияет на потерю портфельного дохода по сравнению с потерей юнита А?","a":["Потеря дохода вдвое меньше, чем если бы освободился юнит А","Потеря дохода одинакова, площадь та же","Потеря дохода больше, так как юнит Б менее ликвиден"],"c":0,"why":"Юнит Б приносит $1,500/мес против $3,000/мес у юнита А, поэтому его освобождение вдвое дешевле для портфеля по прямой потере дохода."},"uz":{"q":"Ikkita 100 m² lik birlik: A birligi 1-qavatda $30/m² ga, B birligi 3-qavatda $15/m² ga ijaraga berilgan. Agar A emas, B bo'shab qolsa, bu portfel daromadi yo'qotilishiga qanday ta'sir qiladi?","a":["Daromad yo'qotilishi A bo'shagandagidan ikki baravar kam bo'ladi","Daromad yo'qotilishi bir xil, chunki maydon bir xil","Daromad yo'qotilishi ko'proq, chunki B kam likvid"],"c":0,"why":"B birligi oyiga $1,500 keltiradi, A esa $3,000 — shuning uchun B bo'shashi portfel uchun to'g'ridan-to'g'ri daromad yo'qotilishi bo'yicha ikki baravar arzonroq."},"en":{"q":"Two 100 m² units: Unit A on the 1st floor leases at $30/m², Unit B on the 3rd floor at $15/m². If Unit B becomes vacant instead of Unit A, how does the portfolio income loss compare?","a":["The income loss is half of what Unit A's vacancy would cause","The income loss is the same since area is identical","The income loss is greater since Unit B is less liquid"],"c":0,"why":"Unit B generates $1,500/month versus Unit A's $3,000/month, so its vacancy costs the portfolio half as much in direct income loss."}},{"id":"LC050","cat":"logic","logic":true,"ru":{"q":"Сценарий 1: юнит 100 м² сдан на 12 мес по $25/м² без каникул. Сценарий 2: тот же юнит сдан по $28/м², но с 2 месяцами free fit-out. Какой сценарий даёт больший фактический годовой доход?","a":["Сценарий 1","Сценарий 2","Оба дают одинаковый доход"],"c":0,"why":"Сценарий 1: 100×$25×12=$30,000. Сценарий 2: 100×$28×10=$28,000. Более высокая ставка не компенсирует потерю 2 месяцев платежей."},"uz":{"q":"1-stsenariy: 100 m² birlik 12 oyga $25/m² ga, ta'tilsiz ijaraga berilgan. 2-stsenariy: xuddi shu birlik $28/m² ga, lekin 2 oy bepul fit-out bilan. Qaysi stsenariy ko'proq real yillik daromad beradi?","a":["1-stsenariy","2-stsenariy","Ikkalasi ham bir xil daromad beradi"],"c":0,"why":"1-stsenariy: 100×$25×12=$30,000. 2-stsenariy: 100×$28×10=$28,000. Yuqoriroq stavka 2 oylik to'lov yo'qotilishini qoplamaydi."},"en":{"q":"Scenario 1: a 100 m² unit leases for 12 months at $25/m² with no free period. Scenario 2: the same unit leases at $28/m² but with 2 months rent-free fit-out. Which scenario yields higher actual annual income?","a":["Scenario 1","Scenario 2","Both yield the same income"],"c":0,"why":"Scenario 1: 100×$25×12=$30,000. Scenario 2: 100×$28×10=$28,000. The higher rate doesn't offset the loss of 2 months of payments."}},{"id":"LC051","cat":"logic","logic":true,"ru":{"q":"Годовой бюджет дохода по юниту — $60,000. Фактически собрано $54,000 из-за задержки открытия на 2 месяца по исходной ставке. Каков процент недостачи от бюджета?","a":["10%","6%","15%"],"c":0,"why":"Недостача $6,000 от бюджета $60,000 составляет $6,000/$60,000=10%."},"uz":{"q":"Birlik bo'yicha yillik daromad byudjeti — $60,000. Ochilish 2 oyga kechikkani sababli asl stavka bo'yicha $54,000 yig'ildi. Byudjetdan kamomad foizi qancha?","a":["10%","6%","15%"],"c":0,"why":"$60,000 byudjetdan $6,000 kamomad $6,000/$60,000=10% ni tashkil qiladi."},"en":{"q":"The annual income budget for a unit is $60,000. Actual collection was $54,000 due to a 2-month delayed opening at the original rate. What is the shortfall as a percentage of budget?","a":["10%","6%","15%"],"c":0,"why":"A $6,000 shortfall against a $60,000 budget is $6,000/$60,000=10%."}},{"id":"LC052","cat":"logic","logic":true,"ru":{"q":"Ставка эскалации 5% годовых применяется каждые 2 года (а не ежегодно) к контракту $8,000/мес. Как это повлияет на средний фактический рост арендной ставки по сравнению с ежегодной эскалацией той же величины?","a":["Средний годовой рост будет ниже, чем при ежегодной эскалации","Средний годовой рост будет выше","Рост будет идентичным в любом случае"],"c":0,"why":"Реже применяемая эскалация означает, что ставка дольше остаётся неизменной, поэтому средний темп роста в пересчёте на год ниже."},"uz":{"q":"5% yillik eskalatsiya stavkasi $8,000/oy shartnomaga har yili emas, har 2 yilda bir qo'llaniladi. Bu bir xil miqdordagi yillik eskalatsiyaga nisbatan o'rtacha real ijara o'sishiga qanday ta'sir qiladi?","a":["O'rtacha yillik o'sish yillik eskalatsiyaga qaraganda past bo'ladi","O'rtacha yillik o'sish yuqori bo'ladi","O'sish har qanday holatda bir xil bo'ladi"],"c":0,"why":"Kamroq qo'llaniladigan eskalatsiya stavka uzoqroq o'zgarmasligini bildiradi, shuning uchun yillik hisobdagi o'rtacha o'sish sur'ati pastroq bo'ladi."},"en":{"q":"A 5% escalation is applied every 2 years (instead of annually) on an $8,000/month contract. How does this affect the average annual rent growth compared to yearly escalation of the same magnitude?","a":["Average annual growth is lower than with yearly escalation","Average annual growth is higher","Growth is identical either way"],"c":0,"why":"Less frequent escalation means the rate stays flat longer, so the average growth rate per year is lower than annual escalation."}},{"id":"LC053","cat":"logic","logic":true,"ru":{"q":"Арендатор с продажами $200,000/мес платит turnover rent 8%. Другой арендатор в таком же юните платит фикс $18,000/мес. При каких продажах turnover-арендатор платит столько же, сколько фиксированный?","a":["$225,000/мес","$200,000/мес","$144,000/мес"],"c":0,"why":"$18,000 / 0.08 = $225,000 — при таких продажах 8% дают ту же сумму, что и фиксированная ставка."},"uz":{"q":"Sotuvi $200,000/oy bo'lgan ijarachi 8% turnover rent to'laydi. Xuddi shu birlikdagi boshqa ijarachi $18,000/oy fiks to'laydi. Qanday sotuvda turnover ijarachi fiks ijarachi kabi to'laydi?","a":["$225,000/oy","$200,000/oy","$144,000/oy"],"c":0,"why":"$18,000 / 0.08 = $225,000 — shu sotuvda 8% fiksirlangan stavka bilan bir xil summani beradi."},"en":{"q":"A tenant with $200,000/month sales pays 8% turnover rent. Another tenant in an identical unit pays a fixed $18,000/month. At what sales level would the turnover tenant pay the same as the fixed tenant?","a":["$225,000/month","$200,000/month","$144,000/month"],"c":0,"why":"$18,000 / 0.08 = $225,000 — at that sales level, 8% produces the same rent as the fixed amount."}},{"id":"LC054","cat":"logic","logic":true,"ru":{"q":"Сценарий 1: юнит 80 м² сдан по $22/м² на 12 мес. Сценарий 2: юнит 80 м² сдан по $25/м², но с 3 месяцами free fit-out. Разница в фактическом годовом доходе?","a":["Сценарий 1 выше на $3,120","Сценарий 2 выше на $3,120","Доход одинаков"],"c":0,"why":"Сценарий 1: 80×$22×12=$21,120. Сценарий 2: 80×$25×9=$18,000. Разница: $21,120-$18,000=$3,120."},"uz":{"q":"1-stsenariy: 80 m² birlik $22/m² ga 12 oyga ijaraga berilgan. 2-stsenariy: 80 m² birlik $25/m² ga, lekin 3 oy bepul fit-out bilan. Real yillik daromad farqi qancha?","a":["1-stsenariy $3,120 ga yuqori","2-stsenariy $3,120 ga yuqori","Daromad bir xil"],"c":0,"why":"1-stsenariy: 80×$22×12=$21,120. 2-stsenariy: 80×$25×9=$18,000. Farq: $21,120-$18,000=$3,120."},"en":{"q":"Scenario 1: an 80 m² unit leases at $22/m² for 12 months. Scenario 2: the same unit leases at $25/m² but with 3 months rent-free fit-out. What is the difference in actual annual income?","a":["Scenario 1 is higher by $3,120","Scenario 2 is higher by $3,120","Income is the same"],"c":0,"why":"Scenario 1: 80×$22×12=$21,120. Scenario 2: 80×$25×9=$18,000. The difference is $21,120-$18,000=$3,120."}},{"id":"LC055","cat":"logic","logic":true,"ru":{"q":"Бюджет предполагал 0% вакансии по этажу с доходом $100,000/мес. Фактически один юнит на $8,000/мес простоял пустым весь месяц. Как это отразилось на факте выполнения бюджета по этажу?","a":["Факт составил 92% от бюджета","Факт составил 108% от бюджета","Факт равен бюджету, вакансия не считается"],"c":0,"why":"$92,000 факт от $100,000 бюджета = 92% выполнения, так как потеряны $8,000 из-за вакансии."},"uz":{"q":"Byudjet qavat bo'yicha 0% bo'sh joy va $100,000/oy daromadni nazarda tutgan edi. Aslida $8,000/oylik bitta birlik butun oy bo'sh turdi. Bu qavat byudjeti bajarilishiga qanday ta'sir qildi?","a":["Fakt byudjetning 92% ni tashkil etdi","Fakt byudjetning 108% ni tashkil etdi","Fakt byudjetga teng, bo'sh joy hisobga olinmaydi"],"c":0,"why":"$100,000 byudjetdan $92,000 fakt = 92% bajarilish, chunki bo'sh joy tufayli $8,000 yo'qotilgan."},"en":{"q":"The floor budget assumed 0% vacancy with $100,000/month income. Actually, one unit worth $8,000/month sat vacant the whole month. What was actual performance versus budget?","a":["Actual was 92% of budget","Actual was 108% of budget","Actual equals budget since vacancy isn't counted"],"c":0,"why":"Actual $92,000 against $100,000 budget equals 92% achievement, reflecting the $8,000 lost to vacancy."}},{"id":"LC056","cat":"logic","logic":true,"ru":{"q":"У арендатора продажи выросли на 20%, а occupancy cost ratio при этом снизился с 12% до 10%. Что из этого следует про формулу его аренды?","a":["Аренда фиксированная (не растёт вместе с продажами)","Аренда чисто turnover-based (растёт вместе с продажами)","Аренда индексируется по инфляции, равной росту продаж"],"c":0,"why":"Если бы аренда была чисто turnover-based, ratio остался бы неизменным; снижение ratio при росте продаж указывает на фиксированную (или менее чем пропорциональную) аренду."},"uz":{"q":"Ijarachining sotuvi 20% ga o'sdi, occupancy cost ratio esa 12% dan 10% ga tushdi. Bundan uning ijara formulasi haqida qanday xulosa chiqarish mumkin?","a":["Ijara fiksirlangan (sotuv bilan birga o'smaydi)","Ijara sof turnover-based (sotuv bilan birga o'sadi)","Ijara sotuv o'sishiga teng inflyatsiya bo'yicha indekslanadi"],"c":0,"why":"Agar ijara sof turnover-based bo'lganda, ratio o'zgarmas edi; sotuv o'sganda ratio pasayishi ijara fiksirlangan (yoki proportsionaldan kam o'sadigan) ekanligini ko'rsatadi."},"en":{"q":"A tenant's sales grew 20% while their occupancy cost ratio fell from 12% to 10%. What does this imply about their rent formula?","a":["Rent is fixed (does not grow with sales)","Rent is purely turnover-based (grows with sales)","Rent is indexed to inflation equal to the sales growth"],"c":0,"why":"If rent were purely turnover-based, the ratio would stay flat; a falling ratio as sales rise indicates a fixed (or less-than-proportional) rent."}},{"id":"LC057","cat":"logic","logic":true,"ru":{"q":"Мол планирует добавить супермаркет-якорь у второстепенного входа, который сейчас используется слабо. Какой наиболее вероятный эффект на распределение потока покупателей по молу?","a":["Поток перераспределится, часть трафика сместится к этому входу","Весь трафик останется у главного входа без изменений","Второстепенный вход закроется, так как он не нужен"],"c":0,"why":"Новый якорь у слабого входа создаёт причину заходить именно через него, перераспределяя посещаемость и разгружая главный вход."},"uz":{"q":"Savdo markazi hozir kam foydalaniladigan ikkinchi darajali kirish yonida supermarket-langar qo'shishni rejalashtirmoqda. Xaridorlar oqimi taqsimotiga eng ehtimoliy ta'sir qanday bo'ladi?","a":["Oqim qayta taqsimlanadi, trafikning bir qismi shu kirishga siljiydi","Barcha trafik asosiy kirishda o'zgarishsiz qoladi","Ikkinchi darajali kirish keraksiz bo'lgani uchun yopiladi"],"c":0,"why":"Kuchsiz kirish yonidagi yangi langar aynan shu joydan kirish uchun sabab yaratadi, tashrifni qayta taqsimlaydi va asosiy kirishni yengillashtiradi."},"en":{"q":"A mall plans to add a supermarket anchor near an underused secondary entrance. What is the most likely effect on visitor flow distribution?","a":["Flow redistributes, with some traffic shifting to that entrance","All traffic stays at the main entrance, unchanged","The secondary entrance will close since it's not needed"],"c":0,"why":"A new anchor near a weak entrance gives shoppers a reason to use it, redistributing footfall and easing pressure on the main entrance."}},{"id":"LC058","cat":"logic","logic":true,"ru":{"q":"Категорийный микс смещается в сторону детских товаров и семейных развлечений. Как это, скорее всего, повлияет на среднее время визита семейной аудитории?","a":["Увеличится, так как разные члены семьи посещают разные зоны","Уменьшится, так как дети быстро устают от шопинга","Не изменится, семейная аудитория ведёт себя как обычная"],"c":0,"why":"При наличии детских и семейных зон разные члены семьи могут заниматься разными активностями одновременно, что удлиняет общий визит."},"uz":{"q":"Kategoriya miksi bolalar tovarlari va oilaviy ko'ngilochar tomon siljimoqda. Bu oilaviy auditoriyaning o'rtacha tashrif vaqtiga qanday ta'sir qiladi?","a":["Oshadi, chunki oila a'zolari turli zonalarga tashrif buyuradi","Kamayadi, chunki bolalar xariddan tez charchaydi","O'zgarmaydi, oilaviy auditoriya odatdagidek harakat qiladi"],"c":0,"why":"Bolalar va oilaviy zonalar mavjud bo'lganda, oila a'zolari bir vaqtda turli faoliyat bilan shug'ullanishi mumkin, bu umumiy tashrif vaqtini uzaytiradi."},"en":{"q":"The category mix shifts toward kids' goods and family entertainment. How is this likely to affect average visit duration for family audiences?","a":["It increases, as different family members use different zones","It decreases, as kids tire of shopping quickly","It stays unchanged, family behavior doesn't differ"],"c":0,"why":"With kids' and family zones present, family members can engage in different activities simultaneously, extending the overall visit."}},{"id":"LC059","cat":"logic","logic":true,"ru":{"q":"Портфель из 5 этажей приносит $500,000/мес суммарно. Вакансия на одном этаже выросла с 5% до 15% при доходе полного этажа $120,000/мес. Насколько снизился общий доход портфеля?","a":["На $12,000/мес","На $18,000/мес","На $60,000/мес"],"c":0,"why":"Рост вакансии на 10 п.п. от базы $120,000 составляет доп. потерю 0.10×$120,000=$12,000/мес."},"uz":{"q":"5 qavatdan iborat portfel jami oyiga $500,000 keltiradi. Bitta qavatda bo'sh joy 5% dan 15% ga o'sdi, to'liq qavat daromadi $120,000/oy. Portfelning umumiy daromadi qancha kamaydi?","a":["$12,000/oy ga","$18,000/oy ga","$60,000/oy ga"],"c":0,"why":"$120,000 bazadan bo'sh joyning 10 foiz punktga o'sishi qo'shimcha 0.10×$120,000=$12,000/oy yo'qotishni tashkil qiladi."},"en":{"q":"A 5-floor portfolio generates $500,000/month total. Vacancy on one floor rose from 5% to 15%, where full-floor income is $120,000/month. How much did total portfolio income fall?","a":["$12,000/month","$18,000/month","$60,000/month"],"c":0,"why":"A 10 percentage-point rise in vacancy on a $120,000 base equals an additional loss of 0.10×$120,000=$12,000/month."}},{"id":"LC060","cat":"logic","logic":true,"ru":{"q":"Арендатор подписал контракт со ставкой $16,000/мес и эскалацией 4% в год, начиная со 2-го года. Каков совокупный доход владельца за первые 2 года?","a":["$391,680","$384,000","$399,360"],"c":0,"why":"Год1: $16,000×12=$192,000. Год2: $16,000×1.04=$16,640×12=$199,680. Итого $192,000+$199,680=$391,680."},"uz":{"q":"Ijarachi $16,000/oy stavka va 2-yildan boshlab 4% yillik eskalatsiya bilan shartnoma imzoladi. Egasining birinchi 2 yillik jami daromadi qancha?","a":["$391,680","$384,000","$399,360"],"c":0,"why":"1-yil: $16,000×12=$192,000. 2-yil: $16,000×1.04=$16,640×12=$199,680. Jami $192,000+$199,680=$391,680."},"en":{"q":"A tenant signs at $16,000/month with 4% annual escalation starting in year 2. What is the landlord's total income over the first 2 years?","a":["$391,680","$384,000","$399,360"],"c":0,"why":"Year 1: $16,000×12=$192,000. Year 2: $16,000×1.04=$16,640×12=$199,680. Total is $192,000+$199,680=$391,680."}},{"id":"LC061","cat":"logic","logic":true,"ru":{"q":"Мол добавляет фудкорт рядом с кинотеатром. Помимо роста dwell time, какой ещё эффект это создаёт для соседних fashion-операторов через кросс-шопинг?","a":["Дополнительный трафик к фэшн-магазинам от посетителей фудкорта/кино","Снижение трафика, так как посетители тратят весь бюджет на еду","Нет связи, категории никак не взаимодействуют"],"c":0,"why":"Фудкорт и кино увеличивают общее время и число посетителей в этой зоне мола, часть которых заходит и в соседние магазины по пути."},"uz":{"q":"Savdo markazi kinoteatr yonida fudkort qo'shmoqda. Dwell time o'sishidan tashqari, bu qo'shni fashion operatorlariga cross-shopping orqali qanday qo'shimcha ta'sir ko'rsatadi?","a":["Fudkort/kino tashrif buyuruvchilaridan fashion do'konlarga qo'shimcha trafik","Tashrif buyuruvchilar butun byudjetni ovqatga sarflagani uchun trafik kamayadi","Bog'liqlik yo'q, kategoriyalar bir-biriga ta'sir qilmaydi"],"c":0,"why":"Fudkort va kino ushbu zonada umumiy vaqt va tashrif buyuruvchilar sonini oshiradi, ularning bir qismi yo'lda qo'shni do'konlarga ham kiradi."},"en":{"q":"A mall adds a food court next to the cinema. Beyond increasing dwell time, what additional effect does this create for nearby fashion tenants via cross-shopping?","a":["Extra footfall to fashion stores from food court/cinema visitors","Reduced traffic since visitors spend their whole budget on food","No connection, categories don't interact"],"c":0,"why":"The food court and cinema increase overall time and visitor volume in that zone, some of whom browse neighboring stores along the way."}},{"id":"LC062","cat":"logic","logic":true,"ru":{"q":"Бюджет по объекту предполагал средний рейт $22/м² на 5,000 м² GLA. Фактически сдано по среднему $19/м². Каков месячный разрыв в доходе по всему объекту?","a":["$15,000","$5,000","$95,000"],"c":0,"why":"Разница ставки $3/м² × 5,000 м² = $15,000/мес недополученного дохода."},"uz":{"q":"Obyekt byudjeti 5,000 m² GLA uchun o'rtacha $22/m² stavkani nazarda tutgan edi. Aslida o'rtacha $19/m² ga ijaraga berildi. Butun obyekt bo'yicha oylik daromad farqi qancha?","a":["$15,000","$5,000","$95,000"],"c":0,"why":"Stavka farqi $3/m² × 5,000 m² = oyiga $15,000 kam olingan daromad."},"en":{"q":"The property budget assumed an average rate of $22/m² on 5,000 m² GLA. Actual average signed rate was $19/m². What is the monthly income gap for the whole property?","a":["$15,000","$5,000","$95,000"],"c":0,"why":"The rate gap of $3/m² × 5,000 m² equals a $15,000/month shortfall in income."}},{"id":"LC063","cat":"logic","logic":true,"ru":{"q":"Арендатор на 1-м этаже платит $40/м² за 50 м². Такой же арендатор на 2-м этаже платит $25/м² за 50 м². Если оба съедут одновременно, какова будет суммарная месячная потеря дохода портфеля?","a":["$3,250","$3,000","$2,000"],"c":0,"why":"1-й этаж: 50×$40=$2,000. 2-й этаж: 50×$25=$1,250. Сумма потерь: $2,000+$1,250=$3,250."},"uz":{"q":"1-qavatdagi ijarachi 50 m² uchun $40/m² to'laydi. 2-qavatdagi shunga o'xshash ijarachi 50 m² uchun $25/m² to'laydi. Agar ikkalasi bir vaqtda ko'chib ketsa, portfelning jami oylik daromad yo'qotishi qancha bo'ladi?","a":["$3,250","$3,000","$2,000"],"c":0,"why":"1-qavat: 50×$40=$2,000. 2-qavat: 50×$25=$1,250. Yo'qotishlar yig'indisi: $2,000+$1,250=$3,250."},"en":{"q":"A 1st-floor tenant pays $40/m² for 50 m². A similar 2nd-floor tenant pays $25/m² for 50 m². If both vacate simultaneously, what is the total monthly portfolio income loss?","a":["$3,250","$3,000","$2,000"],"c":0,"why":"1st floor: 50×$40=$2,000. 2nd floor: 50×$25=$1,250. Combined loss: $2,000+$1,250=$3,250."}},{"id":"LC064","cat":"logic","logic":true,"ru":{"q":"Арендатор подписал 5-летний договор с эскалацией 3% в год каждый год. Ставка стартовая $9,000/мес. Какова ставка в 4-й год (после 3 повышений)?","a":["Около $9,834.51/мес","$9,900/мес","$10,206/мес"],"c":0,"why":"$9,000×1.03³ = $9,000×1.092727 ≈ $9,834.51 — три последовательных повышения на 3% с компаундированием."},"uz":{"q":"Ijarachi 5 yillik shartnoma imzoladi, har yili 3% eskalatsiya bilan. Boshlang'ich stavka $9,000/oy. 4-yilda (3 marta oshirilgandan keyin) stavka qancha bo'ladi?","a":["Taxminan $9,834.51/oy","$9,900/oy","$10,206/oy"],"c":0,"why":"$9,000×1.03³ = $9,000×1.092727 ≈ $9,834.51 — murakkab foiz bilan ketma-ket uch marta 3% oshirish."},"en":{"q":"A tenant signs a 5-year lease with 3% annual escalation each year. Starting rent is $9,000/month. What is the rent in year 4 (after 3 increases)?","a":["About $9,834.51/month","$9,900/month","$10,206/month"],"c":0,"why":"$9,000×1.03³ = $9,000×1.092727 ≈ $9,834.51 — three consecutive 3% compounding increases."}},{"id":"LC065","cat":"logic","logic":true,"ru":{"q":"Мол снизил количество доступных парковочных мест на 30% из-за стройки на соседнем участке. Какой наиболее вероятный эффект на footfall в выходные дни?","a":["Footfall в выходные снизится сильнее, чем в будни, так как выходные более парковко-зависимы","Footfall вырастет, так как меньше машин — меньше пробок","Изменений не будет, посетители всегда найдут место"],"c":0,"why":"В выходные обычно выше доля автомобильных визитов и пиковая нагрузка на парковку, поэтому дефицит мест сильнее бьёт именно по выходному трафику."},"uz":{"q":"Qo'shni uchastkadagi qurilish tufayli savdo markazida avtoturargoh joylari 30% ga kamaydi. Dam olish kunlaridagi footfallga eng ehtimoliy ta'sir qanday?","a":["Dam olish kunlari footfall ish kunlariga qaraganda ko'proq pasayadi, chunki ular avtoturargohga ko'proq bog'liq","Footfall oshadi, chunki kamroq mashina — kamroq tirbandlik","O'zgarish bo'lmaydi, tashrif buyuruvchilar doim joy topadi"],"c":0,"why":"Dam olish kunlari odatda avtomobil bilan tashrif ulushi va avtoturargohga peak yuklama yuqori bo'ladi, shuning uchun joy yetishmasligi aynan dam olish kunlari trafikiga kuchliroq ta'sir qiladi."},"en":{"q":"A mall loses 30% of its parking capacity due to construction on an adjacent lot. What is the most likely effect on weekend footfall?","a":["Weekend footfall drops more than weekday footfall, being more parking-dependent","Footfall rises since fewer cars means less congestion","No change, visitors will always find a spot"],"c":0,"why":"Weekends typically have a higher share of car-based visits and peak parking demand, so a parking shortage hits weekend traffic harder."}},{"id":"LC066","cat":"logic","logic":true,"ru":{"q":"Арендатор занимает 120 м², платит $18/м², и получил 1 месяц free fit-out на контракте в 12 месяцев. Какова эффективная месячная ставка в пересчёте на весь год?","a":["$16.50/м²","$18/м²","$19.50/м²"],"c":0,"why":"Годовой платёж: 120×$18×11=$23,760. В пересчёте на 12 месяцев и площадь: $23,760/(120×12)=$16.50/м²."},"uz":{"q":"Ijarachi 120 m² egallaydi, $18/m² to'laydi va 12 oylik shartnomada 1 oy bepul fit-out oldi. Butun yilga hisoblangan samarali oylik stavka qancha?","a":["$16.50/m²","$18/m²","$19.50/m²"],"c":0,"why":"Yillik to'lov: 120×$18×11=$23,760. 12 oy va maydonga bo'linganda: $23,760/(120×12)=$16.50/m²."},"en":{"q":"A tenant occupies 120 m², pays $18/m², and receives 1 month of rent-free fit-out on a 12-month lease. What is the effective monthly rate spread across the full year?","a":["$16.50/m²","$18/m²","$19.50/m²"],"c":0,"why":"Annual payment: 120×$18×11=$23,760. Spread over 12 months and the area: $23,760/(120×12)=$16.50/m²."}},{"id":"LC067","cat":"logic","logic":true,"ru":{"q":"В бюджете заложена нулевая вакансия и доход $80,000/мес по крылу мола. Фактически 2 юнита из 10 (равной площади) простояли пустыми весь квартал. Как правильно оценить фактическое выполнение бюджета за квартал?","a":["80% от квартального бюджета, так как 2/10 площади не приносили доход","100%, так как остальные юниты работали по плану","60%, так как пустые юниты считаются вдвойне"],"c":0,"why":"Если 2 из 10 равных по доходу юнитов пустовали весь период, потеряно 20% дохода, значит фактическое выполнение — 80% от бюджета."},"uz":{"q":"Byudjetda savdo markazi qanotida 0% bo'sh joy va $80,000/oy daromad rejalashtirilgan edi. Aslida 10 tadan (bir xil maydonli) 2 ta birlik butun chorak davomida bo'sh turdi. Chorak bo'yicha byudjet bajarilishini qanday to'g'ri baholash kerak?","a":["Choraklik byudjetning 80% i, chunki maydonning 2/10 qismi daromad keltirmadi","100%, chunki qolgan birliklar reja bo'yicha ishladi","60%, chunki bo'sh birliklar ikki baravar hisoblanadi"],"c":0,"why":"Agar daromadi bir xil 10 tadan 2 birlik butun davr bo'sh tursa, daromadning 20% yo'qolgan, demak real bajarilish byudjetning 80% ini tashkil qiladi."},"en":{"q":"The budget assumed zero vacancy and $80,000/month income for a mall wing. Actually, 2 of 10 equal-sized units sat vacant the entire quarter. How should actual quarterly performance be assessed?","a":["80% of quarterly budget, since 2/10 of income-generating area was empty","100%, since the remaining units performed as planned","60%, since vacant units count double"],"c":0,"why":"If 2 of 10 equal-income units were vacant the whole period, 20% of income was lost, so actual performance is 80% of budget."}},{"id":"LC068","cat":"logic","logic":true,"ru":{"q":"Если средняя занятость ТРЦ упала с 95% до 85%, а арендные ставки не изменились, как примерно изменится арендный доход?","a":["Упадёт примерно на 10%","Упадёт примерно на 25%","Не изменится, так как ставки те же"],"c":0,"why":"Доход пропорционален занятости: падение с 95% до 85% — это снижение примерно на 10 процентных пунктов дохода при неизменных ставках."},"uz":{"q":"Agar TSMdagi o'rtacha bandlik 95% dan 85% ga tushsa va ijara stavkalari o'zgarmasa, ijaraviy daromad taxminan qanday o'zgaradi?","a":["Taxminan 10% ga kamayadi","Taxminan 25% ga kamayadi","O'zgarmaydi, chunki stavkalar bir xil"],"c":0,"why":"Daromad bandlikka proportsional: 95% dan 85% gacha tushish stavkalar o'zgarmasa daromadning taxminan 10 foizga kamayishini bildiradi."},"en":{"q":"If a mall's average occupancy drops from 95% to 85% while rental rates stay the same, how does rental income roughly change?","a":["Falls by about 10%","Falls by about 25%","Stays flat since rates are unchanged"],"c":0,"why":"Income scales with occupancy, so a 10-percentage-point drop in occupancy at flat rates cuts income by roughly the same proportion."}},{"id":"LC069","cat":"logic","logic":true,"ru":{"q":"Арендатор имеет месячные продажи $50,000, ставку с оборота 8% и минимальную гарантированную аренду $3,000. Сколько он заплатит?","a":["$3,000","$4,000","$7,000"],"c":1,"why":"8% от $50,000 = $4,000, что выше минимума $3,000, поэтому платится большая сумма."},"uz":{"q":"Ijarachining oylik savdosi $50,000, oborotdan stavka 8%, minimal kafolatlangan ijara esa $3,000. U qancha to'laydi?","a":["$3,000","$4,000","$7,000"],"c":1,"why":"$50,000 ning 8% i $4,000 bo'lib, bu $3,000 minimumdan yuqori, shuning uchun katta summa to'lanadi."},"en":{"q":"A tenant has $50,000 monthly sales, an 8% turnover rent, and a $3,000 minimum guaranteed rent. What do they pay?","a":["$3,000","$4,000","$7,000"],"c":1,"why":"8% of $50,000 is $4,000, which exceeds the $3,000 minimum, so the higher calculated amount is paid."}},{"id":"LC070","cat":"logic","logic":true,"ru":{"q":"Маркетинговый бюджет ТРЦ увеличен, трафик вырос на 15%, а конверсия осталась прежней. Что произойдёт с общими продажами ТРЦ?","a":["Продажи вырастут примерно на 15%","Продажи упадут","Продажи останутся без изменений"],"c":0,"why":"Продажи = трафик × конверсия × средний чек; при неизменной конверсии и чеке рост трафика на 15% даёт пропорциональный рост продаж."},"uz":{"q":"TSM marketing byudjeti oshirildi, tashrif 15% ga o'sdi, konversiya esa o'zgarmadi. TSMning umumiy savdosiga nima bo'ladi?","a":["Savdo taxminan 15% ga o'sadi","Savdo tushib ketadi","Savdo o'zgarmaydi"],"c":0,"why":"Savdo = tashrif × konversiya × o'rtacha chek; konversiya va chek o'zgarmasa, tashrifning 15% o'sishi savdoning proportsional o'sishiga olib keladi."},"en":{"q":"A mall increases marketing spend, footfall rises 15%, and conversion rate stays flat. What happens to total mall sales?","a":["Sales rise by about 15%","Sales fall","Sales stay unchanged"],"c":0,"why":"Sales equal footfall times conversion times average ticket; with conversion and ticket size flat, a 15% footfall gain drives a proportional sales increase."}},{"id":"LC071","cat":"logic","logic":true,"ru":{"q":"Брокер выбирает между арендатором А (выше ставка, слабая кредитоспособность) и Б (ниже ставка, сильный ковенант). Что важнее учитывать помимо цены?","a":["Только размер площади магазина","Надёжность и способность стабильно платить","Только визуальный дизайн витрины"],"c":1,"why":"Более низкая, но стабильно выплачиваемая аренда часто выгоднее номинально высокой ставки с риском неплатежей и досрочного ухода."},"uz":{"q":"Broker A ijarachi (yuqori stavka, kredit qobiliyati zaif) va B ijarachi (past stavka, kuchli kovenant) o'rtasida tanlamoqda. Narxdan tashqari nimaga eng ko'p e'tibor berish kerak?","a":["Faqat do'kon maydonining kattaligi","Ishonchlilik va barqaror to'lash qobiliyati","Faqat vitrina dizayni"],"c":1,"why":"Barqaror to'lanadigan pastroq ijara, to'lovsizlik va erta ketish xavfi bo'lgan nominal yuqori stavkadan ko'pincha foydaliroqdir."},"en":{"q":"A broker is choosing between Tenant A (higher rate, weak covenant) and Tenant B (lower rate, strong covenant). What should weigh most alongside price?","a":["Only the size of the retail unit","Reliability and ability to pay consistently","Only the storefront design"],"c":1,"why":"A lower but reliably paid rent is often worth more than a nominally higher rate carrying default and early-exit risk."}},{"id":"LC072","cat":"logic","logic":true,"ru":{"q":"GBA здания составляет 10,000 м², коэффициент эффективности (GLA/GBA) равен 80%. Чему равен GLA?","a":["8,000 м²","10,000 м²","12,500 м²"],"c":0,"why":"GLA = GBA × коэффициент эффективности = 10,000 × 0.80 = 8,000 м²."},"uz":{"q":"Binoning GBA si 10,000 m², samaradorlik koeffitsienti (GLA/GBA) 80% ni tashkil qiladi. GLA nechaga teng?","a":["8,000 m²","10,000 m²","12,500 m²"],"c":0,"why":"GLA = GBA × samaradorlik koeffitsienti = 10,000 × 0.80 = 8,000 m²."},"en":{"q":"A building's GBA is 10,000 sqm and the efficiency ratio (GLA/GBA) is 80%. What is the GLA?","a":["8,000 sqm","10,000 sqm","12,500 sqm"],"c":0,"why":"GLA equals GBA multiplied by the efficiency ratio: 10,000 x 0.80 = 8,000 sqm."}},{"id":"LC073","cat":"logic","logic":true,"ru":{"q":"Ставка аренды стартует на уровне $15/м² с ежегодной индексацией 3%. Какова ставка в 3-й год (после двух повышений)?","a":["$15.45/м²","$15.90/м²","$16.50/м²"],"c":1,"why":"Индексация начисляется сложно: $15 × 1.03 × 1.03 ≈ $15.90, а не простым сложением 6%."},"uz":{"q":"Ijara stavkasi $15/m² dan boshlanadi va har yili 3% indeksatsiya qo'llaniladi. 3-yilda (ikki oshirishdan keyin) stavka qancha bo'ladi?","a":["$15.45/m²","$15.90/m²","$16.50/m²"],"c":1,"why":"Indeksatsiya murakkab foiz bilan hisoblanadi: $15 × 1.03 × 1.03 ≈ $15.90, oddiy 6% qo'shish emas."},"en":{"q":"A lease starts at $15/sqm with 3% annual indexation. What is the rate in year 3 (after two increases)?","a":["$15.45/sqm","$15.90/sqm","$16.50/sqm"],"c":1,"why":"Indexation compounds: $15 x 1.03 x 1.03 is about $15.90, not a simple 6% addition."}},{"id":"LC074","cat":"logic","logic":true,"ru":{"q":"Сервисный сбор начисляется пропорционально доле GLA. Юнит арендатора увеличился со 150 м² до 250 м² после объединения с соседним. Как изменится его доля в общем сервисном сборе?","a":["Доля уменьшится","Доля увеличится пропорционально росту площади","Доля не изменится, так как ставка сбора фиксирована"],"c":1,"why":"Так как сбор считается по доле GLA от общей площади ТРЦ, рост площади юнита с 150 до 250 м² увеличивает его долю и итоговый счёт."},"uz":{"q":"Xizmat to'lovi GLA ulushiga mutanosib hisoblanadi. Bo'linma qo'shni bilan birlashtirilgach 150 m² dan 250 m² ga oshdi. Ulushi qanday o'zgaradi?","a":["Ulush kamayadi","Ulush maydon o'sishiga mutanosib oshadi","Ulush o'zgarmaydi, chunki stavka belgilangan"],"c":1,"why":"To'lov TSMning umumiy maydonidagi GLA ulushiga qarab hisoblangani uchun, 150 dan 250 m² gacha o'sish ulush va hisobni oshiradi."},"en":{"q":"Service charge is billed by GLA share. A tenant's unit grows from 150 sqm to 250 sqm after merging with a neighboring unit. How does their service charge bill change?","a":["Their share decreases","Their share increases proportionally to the area gain","Their share stays the same since the rate is fixed"],"c":1,"why":"Since the charge is based on the unit's share of total mall GLA, growing from 150 to 250 sqm raises both the share and the total bill."}},{"id":"LC075","cat":"logic","logic":true,"ru":{"q":"Два предложения на юнит на 3 года: А — $20/м² с 6 месяцами арендных каникул; Б — $18/м² без каникул. Что нужно сравнить, чтобы решить корректно?","a":["Только номинальную ставку за м²","Эффективную ставку за весь срок с учётом каникул","Только площадь юнита"],"c":1,"why":"Каникулы снижают фактический доход за период аренды, поэтому сравнивать нужно эффективную (усреднённую) ставку, а не номинальную цифру."},"uz":{"q":"Bir bo'linma uchun 3 yillik ikkita taklif: A — $20/m², 6 oylik ta'til bilan; B — $18/m², ta'tilsiz. To'g'ri qaror uchun nimani solishtirish kerak?","a":["Faqat nominal m² stavkasini","Ta'tilni hisobga olgan samarali stavkani","Faqat bo'linma maydonini"],"c":1,"why":"Ta'til ijara davri uchun haqiqiy daromadni kamaytiradi, shuning uchun nominal raqam emas, balki samarali (o'rtacha) stavkani solishtirish kerak."},"en":{"q":"Two 3-year offers for a unit: Option A at $20/sqm with a 6-month rent-free period; Option B at $18/sqm with no free period. What should be compared to decide correctly?","a":["Only the nominal rate per sqm","The effective rate over the full term","Only the size of the unit"],"c":1,"why":"The free period lowers actual income over the term, so the effective (averaged) rate must be compared rather than the headline rate."}},{"id":"LC076","cat":"logic","logic":true,"ru":{"q":"В ТРЦ занятость упала с 90% до 75% при GLA 20,000 м² и ставке $20/м². Насколько примерно упал месячный доход?","a":["Примерно на $60,000","Примерно на $30,000","Доход не изменился"],"c":0,"why":"Потеря 15 п.п. занятости на 20,000 м² = 3,000 м² пустующей площади × $20 = $60,000 в месяц."},"uz":{"q":"TSMda bandlik 90% dan 75% ga tushdi, GLA 20,000 m², stavka $20/m². Oylik daromad taxminan qancha kamaydi?","a":["Taxminan $60,000 ga","Taxminan $30,000 ga","Daromad o'zgarmadi"],"c":0,"why":"15 foizli bandlik yo'qotilishi 20,000 m² da 3,000 m² bo'sh maydonni bildiradi, 3,000 × $20 = $60,000 oyiga."},"en":{"q":"A mall's occupancy drops from 90% to 75%, with 20,000 sqm GLA and a $20/sqm rate. How much does monthly income roughly fall?","a":["By about $60,000","By about $30,000","Income is unchanged"],"c":0,"why":"A 15-point occupancy loss on 20,000 sqm equals 3,000 sqm vacant, and 3,000 x $20 = $60,000 per month."}},{"id":"LC077","cat":"logic","logic":true,"ru":{"q":"Арендатор платит 6% с оборота при минимуме $5,000/мес. В месяц с продажами $70,000 сколько он должен заплатить?","a":["$5,000","$4,200","$7,000"],"c":0,"why":"6% от $70,000 = $4,200, что ниже минимума $5,000, поэтому платится минимальная гарантированная сумма."},"uz":{"q":"Ijarachi oborotdan 6% to'laydi, minimal to'lov $5,000/oy. Savdo $70,000 bo'lgan oyda u qancha to'laydi?","a":["$5,000","$4,200","$7,000"],"c":0,"why":"$70,000 ning 6% i $4,200 bo'lib, bu $5,000 minimumdan past, shuning uchun minimal summa to'lanadi."},"en":{"q":"A tenant pays 6% of turnover with a $5,000/month minimum. In a month with $70,000 sales, what do they pay?","a":["$5,000","$4,200","$7,000"],"c":0,"why":"6% of $70,000 is $4,200, which is below the $5,000 minimum, so the higher minimum guaranteed rent is paid."}},{"id":"LC078","cat":"logic","logic":true,"ru":{"q":"ТРЦ повысил маркетинговый бюджет, но трафик не изменился, а конверсия выросла с 20% до 25%. Что произойдёт с продажами при том же среднем чеке?","a":["Продажи вырастут","Продажи упадут","Продажи останутся на прежнем уровне"],"c":0,"why":"При неизменном трафике и среднем чеке рост конверсии напрямую увеличивает число покупок и, следовательно, продажи."},"uz":{"q":"TSM marketing byudjetini oshirdi, lekin tashrif o'zgarmadi, konversiya esa 20% dan 25% ga o'sdi. O'rtacha chek o'zgarmasa, savdoga nima bo'ladi?","a":["Savdo o'sadi","Savdo tushadi","Savdo bir xil darajada qoladi"],"c":0,"why":"Tashrif va o'rtacha chek o'zgarmasa, konversiyaning o'sishi xaridlar sonini va shu bilan savdoni oshiradi."},"en":{"q":"A mall raises marketing spend but footfall stays flat while conversion rises from 20% to 25%. What happens to sales if average ticket is unchanged?","a":["Sales rise","Sales fall","Sales stay the same"],"c":0,"why":"With footfall and average ticket unchanged, a higher conversion rate directly increases the number of purchases and thus sales."}},{"id":"LC079","cat":"logic","logic":true,"ru":{"q":"Арендатор А платит на 20% выше рынка, но имеет историю просрочек. Арендатор Б платит рыночную ставку с безупречной платёжной историей. Что менее рискованно для денежного потока?","a":["Арендатор А, так как ставка выше","Арендатор Б, так как надёжность снижает риск потерь","Выбор не влияет на денежный поток"],"c":1,"why":"Более высокая ставка бесполезна, если платежи нерегулярны; стабильный платящий арендатор обеспечивает предсказуемый денежный поток."},"uz":{"q":"A ijarachi bozordan 20% yuqori to'laydi, ammo to'lovlarni kechiktirish tarixi bor. B ijarachi bozor stavkasida, to'lov tarixi benuqson. Pul oqimi uchun qaysi tanlov kamroq xavfli?","a":["A ijarachi, chunki stavka yuqori","B ijarachi, chunki ishonchlilik xavfni kamaytiradi","Tanlov pul oqimiga ta'sir qilmaydi"],"c":1,"why":"To'lovlar muntazam bo'lmasa, yuqori stavka foyda bermaydi; barqaror to'laydigan ijarachi bashorat qilinadigan pul oqimini ta'minlaydi."},"en":{"q":"Tenant A pays 20% above market but has a history of late payments. Tenant B pays market rate with a spotless payment history. Which is lower-risk for cash flow?","a":["Tenant A, because the rate is higher","Tenant B, because reliability reduces the risk of loss","It makes no difference to cash flow"],"c":1,"why":"A higher rate is worthless if payments are irregular; a reliably paying tenant delivers predictable cash flow."}},{"id":"LC080","cat":"logic","logic":true,"ru":{"q":"GBA торгового центра равна 8,000 м², а GLA — 6,000 м². Чему равен коэффициент эффективности?","a":["60%","75%","80%"],"c":1,"why":"Коэффициент эффективности = GLA/GBA = 6,000/8,000 = 75%."},"uz":{"q":"Savdo markazining GBA si 8,000 m², GLA si esa 6,000 m². Samaradorlik koeffitsienti nechaga teng?","a":["60%","75%","80%"],"c":1,"why":"Samaradorlik koeffitsienti = GLA/GBA = 6,000/8,000 = 75%."},"en":{"q":"A mall has a GBA of 8,000 sqm and a GLA of 6,000 sqm. What is the efficiency ratio?","a":["60%","75%","80%"],"c":1,"why":"Efficiency ratio equals GLA divided by GBA: 6,000/8,000 = 75%."}},{"id":"LC081","cat":"logic","logic":true,"ru":{"q":"Ставка аренды $10/м² индексируется на 5% ежегодно. Какова будет ставка в 4-й год (после трёх повышений)?","a":["$11.50/м²","$11.58/м²","$12.15/м²"],"c":1,"why":"Сложная индексация: $10 × 1.05³ ≈ $11.58, что меньше, чем при простом сложении 15%."},"uz":{"q":"$10/m² ijara stavkasi har yili 5% indeksatsiya qilinadi. 4-yilda (uch marta oshirilgandan keyin) stavka qanday bo'ladi?","a":["$11.50/m²","$11.58/m²","$12.15/m²"],"c":1,"why":"Murakkab indeksatsiya: $10 × 1.05³ ≈ $11.58, bu oddiy 15% qo'shishdan kamroq."},"en":{"q":"A $10/sqm rent is indexed 5% annually. What is the rate in year 4 (after three increases)?","a":["$11.50/sqm","$11.58/sqm","$12.15/sqm"],"c":1,"why":"Compounding gives $10 x 1.05^3, about $11.58, which is less than a simple 15% addition would suggest."}},{"id":"LC082","cat":"logic","logic":true,"ru":{"q":"Юнит арендатора уменьшился с 300 м² до 200 м² после раздела на два помещения. Сервисный сбор считается по доле GLA. Как изменится сумма сбора для этого арендатора?","a":["Сумма увеличится","Сумма уменьшится пропорционально площади","Сумма останется прежней"],"c":1,"why":"Меньшая площадь означает меньшую долю в общей GLA центра, а значит и меньший сервисный сбор."},"uz":{"q":"Ijarachining bo'linmasi ikkiga bo'linganidan so'ng 300 m² dan 200 m² ga qisqardi. Xizmat to'lovi GLA ulushi bo'yicha hisoblanadi. Bu ijarachi uchun to'lov summasi qanday o'zgaradi?","a":["Summa oshadi","Summa maydonga mutanosib kamayadi","Summa o'zgarmaydi"],"c":1,"why":"Kichikroq maydon markazning umumiy GLA sidagi kichikroq ulushni bildiradi, demak xizmat to'lovi ham kamayadi."},"en":{"q":"A tenant's unit shrinks from 300 sqm to 200 sqm after being split into two spaces. Service charge is billed by GLA share. How does this tenant's charge change?","a":["It increases","It decreases proportionally to the area","It stays the same"],"c":1,"why":"A smaller area means a smaller share of the mall's total GLA, so the service charge bill drops accordingly."}},{"id":"LC083","cat":"logic","logic":true,"ru":{"q":"Финансовый директор сравнивает: Банк А даёт кредит под 15% годовых с быстрым одобрением; Банк Б — под 12% годовых, но с более долгим оформлением и залогом. Что важно оценить помимо ставки?","a":["Только скорость одобрения","Полную стоимость кредита и условия залога/рисков","Только название банка"],"c":1,"why":"Более низкая ставка может обернуться дополнительными издержками или рисками по залогу, поэтому нужно сравнивать полную стоимость и условия, а не только процент."},"uz":{"q":"Moliya direktori solishtirmoqda: A bank 15% yillik stavka bilan tez tasdiqlaydi; B bank 12% stavka bilan, lekin uzoqroq rasmiylashtirish va garov bilan. Stavkadan tashqari nimani baholash muhim?","a":["Faqat tasdiqlash tezligini","Kreditning to'liq qiymati va garov/xavf shartlarini","Faqat bank nomini"],"c":1,"why":"Pastroq stavka qo'shimcha xarajatlar yoki garov xavfi bilan kelishi mumkin, shuning uchun faqat foizni emas, to'liq qiymat va shartlarni solishtirish kerak."},"en":{"q":"A CFO compares: Bank A offers a loan at 15% annual interest with fast approval; Bank B offers 12% but with a longer process and collateral requirements. What else matters besides the rate?","a":["Only the approval speed","The total cost of the loan and collateral/risk terms","Only the bank's name"],"c":1,"why":"A lower rate can come with added costs or collateral risk, so the full cost and terms must be weighed, not just the percentage."}},{"id":"LC084","cat":"logic","logic":true,"ru":{"q":"Арендатор с продажами $100,000/мес платит 5% с оборота при минимуме $4,000. В следующем месяце продажи упали до $60,000. Как изменится платёж?","a":["Останется $5,000, так как это минимум","Снизится до минимума $4,000, так как 5% меньше","Снизится до $3,000"],"c":1,"why":"5% от $60,000 = $3,000, что ниже минимума $4,000, поэтому арендатор платит минимальную гарантированную сумму $4,000."},"uz":{"q":"Oylik savdosi $100,000 bo'lgan ijarachi oborotdan 5% to'laydi, minimal to'lov $4,000. Keyingi oyda savdo $60,000 ga tushdi. To'lov qanday o'zgaradi?","a":["$5,000 da qoladi, chunki bu minimum","$4,000 minimumga tushadi, chunki 5% kamroq","$3,000 ga tushadi"],"c":1,"why":"$60,000 ning 5% i $3,000 bo'lib, bu $4,000 minimumdan past, shuning uchun ijarachi $4,000 minimal kafolatlangan summani to'laydi."},"en":{"q":"A tenant with $100,000/month sales pays 5% of turnover with a $4,000 minimum. Next month sales drop to $60,000. How does the payment change?","a":["Stays at $5,000 because that is the minimum","Drops to the $4,000 minimum, since 5% is lower","Drops to $3,000"],"c":1,"why":"5% of $60,000 is $3,000, which is below the $4,000 minimum, so the tenant pays the $4,000 minimum guaranteed rent instead."}},{"id":"LC085","cat":"logic","logic":true,"ru":{"q":"Трафик ТРЦ вырос на 20%, но конверсия упала с 25% до 20%. Средний чек не изменился. Что произойдёт с общими продажами?","a":["Продажи вырастут","Продажи останутся примерно на том же уровне","Продажи упадут"],"c":1,"why":"Число покупок = трафик × конверсия: рост трафика на 20% (×1.2) при падении конверсии с 25% до 20% (×0.8) почти полностью компенсируют друг друга (1.2×0.8=0.96)."},"uz":{"q":"TSM tashrifi 20% ga o'sdi, lekin konversiya 25% dan 20% ga tushdi. O'rtacha chek o'zgarmadi. Umumiy savdoga nima bo'ladi?","a":["Savdo o'sadi","Savdo taxminan bir xil darajada qoladi","Savdo tushadi"],"c":1,"why":"Xaridlar soni = tashrif × konversiya: tashrifning 20% o'sishi (×1.2) konversiyaning 25% dan 20% ga tushishi (×0.8) bilan deyarli bir-birini qoplaydi (1.2×0.8=0.96)."},"en":{"q":"Mall footfall rises 20%, but conversion falls from 25% to 20%. Average ticket is unchanged. What happens to total sales?","a":["Sales rise","Sales stay roughly the same","Sales fall"],"c":1,"why":"Purchases equal footfall times conversion: a 20% footfall rise (x1.2) and conversion drop from 25% to 20% (x0.8) nearly offset each other (1.2x0.8=0.96)."}},{"id":"LC086","cat":"logic","logic":true,"ru":{"q":"ТРЦ с GLA 15,000 м² имел занятость 88%, а через год — 96%. Ставка аренды $18/м². Насколько примерно вырос месячный доход?","a":["Примерно на $21,600","Примерно на $10,800","Доход не изменился, так как ставка та же"],"c":0,"why":"Рост занятости на 8 п.п. от 15,000 м² = 1,200 м² дополнительно сданной площади × $18 = $21,600 в месяц."},"uz":{"q":"GLA si 15,000 m² bo'lgan TSMda bandlik 88% edi, bir yildan keyin esa 96% ga yetdi. Ijara stavkasi $18/m². Oylik daromad taxminan qancha oshdi?","a":["Taxminan $21,600 ga","Taxminan $10,800 ga","Daromad o'zgarmadi"],"c":0,"why":"8 foizli bandlik o'sishi 15,000 m² da qo'shimcha 1,200 m² ijaraga berilgan maydonni bildiradi, 1,200 × $18 = $21,600 oyiga."},"en":{"q":"A mall with 15,000 sqm GLA had 88% occupancy, rising to 96% a year later. The rate is $18/sqm. How much did monthly income roughly increase?","a":["By about $21,600","By about $10,800","Income is unchanged since the rate is the same"],"c":0,"why":"An 8-point occupancy gain on 15,000 sqm equals 1,200 sqm of newly leased space, and 1,200 x $18 = $21,600 per month."}},{"id":"LC087","cat":"logic","logic":true,"ru":{"q":"Арендатор платит 7% с оборота, минимум $2,500. В месяц с продажами $40,000 сколько составит платёж?","a":["$2,500","$2,800","$4,000"],"c":1,"why":"7% от $40,000 = $2,800, что выше минимума $2,500, поэтому платится $2,800."},"uz":{"q":"Ijarachi oborotdan 7% to'laydi, minimum $2,500. Savdo $40,000 bo'lgan oyda to'lov qancha bo'ladi?","a":["$2,500","$2,800","$4,000"],"c":1,"why":"$40,000 ning 7% i $2,800 bo'lib, bu $2,500 minimumdan yuqori, shuning uchun $2,800 to'lanadi."},"en":{"q":"A tenant pays 7% of turnover with a $2,500 minimum. In a month with $40,000 sales, what is the payment?","a":["$2,500","$2,800","$4,000"],"c":1,"why":"7% of $40,000 is $2,800, which exceeds the $2,500 minimum, so $2,800 is paid."}},{"id":"LC088","cat":"logic","logic":true,"ru":{"q":"Управляющая компания снизила маркетинговый бюджет вдвое, и трафик упал на 10%. Конверсия и средний чек не изменились. Что произойдёт с продажами арендаторов?","a":["Продажи вырастут","Продажи упадут примерно на 10%","Продажи не изменятся"],"c":1,"why":"При постоянной конверсии и чеке продажи пропорциональны трафику, поэтому падение трафика на 10% ведёт к сопоставимому падению продаж."},"uz":{"q":"Boshqaruv kompaniyasi marketing byudjetini ikki barobar kamaytirdi va tashrif 10% ga tushdi. Konversiya va o'rtacha chek o'zgarmadi. Ijarachilarning savdosiga nima bo'ladi?","a":["Savdo o'sadi","Savdo taxminan 10% ga tushadi","Savdo o'zgarmaydi"],"c":1,"why":"Konversiya va chek doimiy bo'lganda savdo tashrifga proportsional, shuning uchun tashrifning 10% pasayishi savdoning ham shunga yaqin pasayishiga olib keladi."},"en":{"q":"Management cuts the marketing budget in half, and footfall falls 10%. Conversion and average ticket are unchanged. What happens to tenant sales?","a":["Sales rise","Sales fall by about 10%","Sales stay unchanged"],"c":1,"why":"With conversion and ticket size constant, sales are proportional to footfall, so a 10% footfall drop causes a comparable sales decline."}},{"id":"LC089","cat":"logic","logic":true,"ru":{"q":"Два арендатора предлагают одну ставку за один юнит. А — бренд с историей стабильных продаж, Б — новый бренд без опыта. При прочих равных что снижает риск для арендодателя?","a":["Выбор Б, так как локальный бизнес лоялен","Выбор А, так как есть подтверждённый послужной список","Риск одинаков, так как ставка одна и та же"],"c":1,"why":"Подтверждённая история стабильных продаж снижает неопределённость по способности платить аренду и держаться на рынке."},"uz":{"q":"Ikki ijarachi bir xil bo'linma uchun bir xil stavka taklif qilmoqda. A — barqaror savdo tarixiga ega brend, B — tajribasiz yangi brend. Shartlar teng bo'lsa, xavfni nima kamaytiradi?","a":["B ni tanlash, chunki mahalliy biznes sodiq","A ni tanlash, chunki tasdiqlangan tarix bor","Xavf bir xil, chunki stavka bir xil"],"c":1,"why":"Tasdiqlangan barqaror savdo tarixi ijarani to'lash qobiliyati va bozorda qolish borasidagi noaniqlikni kamaytiradi."},"en":{"q":"Two tenants offer the same rate for the same unit. Tenant A has a proven sales record; Tenant B is new with no track record. All else equal, what reduces landlord risk?","a":["Choosing Tenant B, since local business is loyal","Choosing Tenant A, since there is a proven track record","Risk is the same since the rate is identical"],"c":1,"why":"A proven history of stable sales reduces uncertainty about the tenant's ability to pay rent and remain viable."}},{"id":"LC090","cat":"logic","logic":true,"ru":{"q":"GBA торгового центра 25,000 м², коэффициент эффективности 72%. Чему равен GLA?","a":["16,000 м²","18,000 м²","20,000 м²"],"c":1,"why":"GLA = GBA × коэффициент эффективности = 25,000 × 0.72 = 18,000 м²."},"uz":{"q":"Savdo markazining GBA si 25,000 m², samaradorlik koeffitsienti 72%. GLA nechaga teng?","a":["16,000 m²","18,000 m²","20,000 m²"],"c":1,"why":"GLA = GBA × samaradorlik koeffitsienti = 25,000 × 0.72 = 18,000 m²."},"en":{"q":"A mall's GBA is 25,000 sqm with a 72% efficiency ratio. What is the GLA?","a":["16,000 sqm","18,000 sqm","20,000 sqm"],"c":1,"why":"GLA equals GBA multiplied by the efficiency ratio: 25,000 x 0.72 = 18,000 sqm."}},{"id":"LC091","cat":"logic","logic":true,"ru":{"q":"Ставка $12/м² индексируется на 4% в год. Какова ставка в год 3 (после двух повышений), округлённо?","a":["$12.96/м²","$12.98/м²","$13.44/м²"],"c":1,"why":"$12 × 1.04² ≈ $12.98 — сложное начисление даёт чуть больше, чем 8% простого сложения ($12.96)."},"uz":{"q":"$12/m² stavka har yili 4% indeksatsiya qilinadi. 3-yildagi (ikki oshirishdan keyin) stavka taxminan qancha?","a":["$12.96/m²","$12.98/m²","$13.44/m²"],"c":1,"why":"$12 × 1.04² ≈ $12.98 — murakkab foiz oddiy 8% qo'shishdan ($12.96) biroz ko'proq natija beradi."},"en":{"q":"A $12/sqm rate is indexed 4% annually. What is the rate in year 3 (after two increases), rounded?","a":["$12.96/sqm","$12.98/sqm","$13.44/sqm"],"c":1,"why":"$12 x 1.04^2 is about $12.98 — compounding yields slightly more than a simple 8% addition ($12.96) would suggest."}},{"id":"LC092","cat":"logic","logic":true,"ru":{"q":"Сервисный сбор рассчитывается как $2/м²/мес от доли GLA. Юнит увеличился с 100 м² до 180 м² после присоединения соседнего помещения. Насколько вырастет ежемесячный счёт?","a":["На $80","На $160","Счёт не изменится"],"c":0,"why":"Рост площади на 80 м² × $2/м² = дополнительные $80 в месяц к сервисному сбору."},"uz":{"q":"Xizmat to'lovi GLA ulushidan $2/m²/oy sifatida hisoblanadi. Bo'linma qo'shni xona bilan birlashtirilgach 100 m² dan 180 m² ga oshdi. Oylik hisob qancha oshadi?","a":["$80 ga","$160 ga","Hisob o'zgarmaydi"],"c":0,"why":"80 m² ga o'sish × $2/m² = xizmat to'loviga qo'shimcha $80 oyiga."},"en":{"q":"Service charge is calculated at $2/sqm/month based on GLA share. A unit grows from 100 sqm to 180 sqm after merging with a neighboring space. How much does the monthly bill increase?","a":["By $80","By $160","The bill stays the same"],"c":0,"why":"An 80 sqm increase times $2/sqm equals an extra $80 per month in service charge."}},{"id":"LC093","cat":"logic","logic":true,"ru":{"q":"Собственник сравнивает: Проект А — заём под 10% годовых с жёсткими ковенантами по DSCR; Проект Б — заём под 13%, но без строгих ковенантов. Что важно для гибкости в условиях падения дохода ТРЦ?","a":["Всегда выбирать более низкую ставку","Также учитывать жёсткость ковенантов при спаде дохода","Условия не влияют на риск"],"c":1,"why":"Жёсткие ковенанты по DSCR могут спровоцировать дефолт при временном падении дохода, даже если ставка ниже — это дополнительный риск, который нужно взвешивать."},"uz":{"q":"Egasi solishtirmoqda: A loyiha — 10% yillik stavkali, qattiq DSCR kovenantlari bilan kredit; B loyiha — 13%, lekin qattiq kovenantlarsiz. TSM daromadi pasayganda moslashuvchanlik uchun nima muhim?","a":["Har doim pastroq stavkani tanlash","Daromad pasayganda kovenant qattiqligini ham hisobga olish","Shartlar xavfga ta'sir qilmaydi"],"c":1,"why":"Qattiq DSCR kovenantlari daromad vaqtincha pasayganda defoltga olib kelishi mumkin, hatto stavka pastroq bo'lsa ham — bu qo'shimcha xavf sifatida baholanishi kerak."},"en":{"q":"An owner compares: Loan A at 10% with strict DSCR covenants; Loan B at 13% with no strict covenants. What matters for flexibility if mall income temporarily drops?","a":["Always pick the lower rate","Also weigh covenant strictness against income risk","Loan terms don't affect risk"],"c":1,"why":"Strict DSCR covenants can trigger default during a temporary income dip even at a lower rate, so covenant risk must be weighed alongside price."}},{"id":"LC094","cat":"logic","logic":true,"ru":{"q":"Арендатор с оборотом $80,000/мес платит 10% с оборота при минимуме $6,000. Сколько он заплатит в этом месяце?","a":["$6,000","$8,000","$14,000"],"c":1,"why":"10% от $80,000 = $8,000, что выше минимума $6,000, поэтому платится $8,000."},"uz":{"q":"Oylik oboroti $80,000 bo'lgan ijarachi oborotdan 10% to'laydi, minimum $6,000. Bu oy u qancha to'laydi?","a":["$6,000","$8,000","$14,000"],"c":1,"why":"$80,000 ning 10% i $8,000 bo'lib, bu $6,000 minimumdan yuqori, shuning uchun $8,000 to'lanadi."},"en":{"q":"A tenant with $80,000/month turnover pays 10% of turnover with a $6,000 minimum. What do they pay this month?","a":["$6,000","$8,000","$14,000"],"c":1,"why":"10% of $80,000 is $8,000, which exceeds the $6,000 minimum, so $8,000 is paid."}},{"id":"LC095","cat":"logic","logic":true,"ru":{"q":"ТРЦ запустил акцию, средний чек вырос на 10%, а трафик и конверсия не изменились. Как изменятся общие продажи?","a":["Вырастут примерно на 10%","Упадут примерно на 10%","Останутся без изменений"],"c":0,"why":"Продажи прямо пропорциональны среднему чеку при неизменных трафике и конверсии, поэтому рост чека на 10% даёт такой же рост продаж."},"uz":{"q":"TSM aksiya o'tkazdi, o'rtacha chek 10% ga o'sdi, tashrif va konversiya esa o'zgarmadi. Umumiy savdo qanday o'zgaradi?","a":["Taxminan 10% ga o'sadi","Taxminan 10% ga tushadi","O'zgarmaydi"],"c":0,"why":"Tashrif va konversiya o'zgarmasa, savdo o'rtacha chekka to'g'ridan-to'g'ri proportsional, shuning uchun chekning 10% o'sishi savdoning ham shuncha o'sishiga olib keladi."},"en":{"q":"A mall runs a promotion, average ticket rises 10%, while footfall and conversion stay flat. How do total sales change?","a":["Rise by about 10%","Fall by about 10%","Stay unchanged"],"c":0,"why":"Sales are directly proportional to average ticket when footfall and conversion are unchanged, so a 10% ticket increase drives a matching sales rise."}},{"id":"LC096","cat":"logic","logic":true,"ru":{"q":"Два предложения на один юнит: А — на 15% выше рынка, но с 5 месяцами арендных каникул; Б — рыночная ставка без каникул. Что нужно сравнить в первую очередь?","a":["Только номинальную ставку в объявлении","Совокупный доход за срок аренды с учётом каникул","Только имидж бренда арендатора"],"c":1,"why":"Каникулы уменьшают фактически полученный доход, поэтому нужно сравнивать совокупный (эффективный) доход за весь срок, а не заявленную ставку."},"uz":{"q":"Bir bo'linma uchun ikkita taklif: A — bozordan 15% yuqori, lekin 5 oylik ijara ta'tili bilan; B — ta'tilsiz bozor stavkasi. Avvalo nimani solishtirish kerak?","a":["Faqat e'londagi nominal stavkani","Ta'tilni hisobga olgan holda butun muddat daromadini","Faqat ijarachi brendining imijini"],"c":1,"why":"Ta'til haqiqatda olingan daromadni kamaytiradi, shuning uchun e'lon qilingan stavka emas, balki butun muddat uchun umumiy (samarali) daromadni solishtirish kerak."},"en":{"q":"Two offers for one unit: A is 15% above market with a 5-month rent-free period; B is at market rate with no free period. What should be compared first?","a":["Only the headline rate in the listing","Total income over the term, including the free period","Only the tenant's brand image"],"c":1,"why":"The free period reduces actual income received, so the total (effective) income over the term must be compared rather than the stated rate."}},{"id":"LC097","cat":"logic","logic":true,"ru":{"q":"Занятость ТРЦ выросла с 80% до 92% при GLA 12,000 м² и ставке $16/м². На сколько примерно вырос месячный доход?","a":["Примерно на $23,040","Примерно на $11,520","Доход не изменился"],"c":0,"why":"Рост на 12 п.п. от 12,000 м² = 1,440 м² дополнительно сданной площади × $16 = $23,040 в месяц."},"uz":{"q":"TSM bandligi 80% dan 92% ga oshdi, GLA 12,000 m², stavka $16/m². Oylik daromad taxminan qancha oshdi?","a":["Taxminan $23,040 ga","Taxminan $11,520 ga","Daromad o'zgarmadi"],"c":0,"why":"12,000 m² da 12 foizli o'sish qo'shimcha 1,440 m² ijaraga berilgan maydonni bildiradi, 1,440 × $16 = $23,040 oyiga."},"en":{"q":"A mall's occupancy rises from 80% to 92%, with 12,000 sqm GLA and a $16/sqm rate. How much does monthly income roughly increase?","a":["By about $23,040","By about $11,520","Income is unchanged"],"c":0,"why":"A 12-point occupancy gain on 12,000 sqm equals 1,440 sqm of newly leased space, and 1,440 x $16 = $23,040 per month."}},{"id":"LC098","cat":"logic","logic":true,"ru":{"q":"Ставка $25/м² индексируется на 6% в год. Чему равна ставка в год 4 (после трёх повышений), приблизительно?","a":["$29.77/м²","$30.50/м²","$32.50/м²"],"c":0,"why":"$25 × 1.06³ ≈ $29.77 — сложное начисление даёт результат ниже, чем при простом сложении 18%."},"uz":{"q":"$25/m² stavka har yili 6% indeksatsiya qilinadi. 4-yildagi (uch marta oshirilgandan keyin) stavka taxminan qancha?","a":["$29.77/m²","$30.50/m²","$32.50/m²"],"c":0,"why":"$25 × 1.06³ ≈ $29.77 — murakkab foiz oddiy 18% qo'shishdan pastroq natija beradi."},"en":{"q":"A $25/sqm rate is indexed 6% annually. What is the rate in year 4 (after three increases), approximately?","a":["$29.77/sqm","$30.50/sqm","$32.50/sqm"],"c":0,"why":"$25 x 1.06^3 is about $29.77 — compounding yields a lower figure than a simple 18% addition would."}},{"id":"LC099","cat":"logic","logic":true,"ru":{"q":"Два юнита объединены в один общей площадью 400 м² (было 180 м² и 220 м²). Сервисный сбор $3/м²/мес. Каким будет новый ежемесячный счёт объединённого арендатора?","a":["$1,200","$600","$1,800"],"c":0,"why":"400 м² × $3/м² = $1,200 в месяц — сумма считается по итоговой площади после объединения, а не по каждому юниту отдельно."},"uz":{"q":"Ikkita bo'linma umumiy 400 m² (avval 180 m² va 220 m² edi) bitta bo'linmaga birlashtirildi. Xizmat to'lovi $3/m²/oy. Birlashtirilgan ijarachining yangi oylik hisobi qancha bo'ladi?","a":["$1,200","$600","$1,800"],"c":0,"why":"400 m² × $3/m² = $1,200 oyiga — summa alohida bo'linmalar bo'yicha emas, birlashtirilgan yakuniy maydon bo'yicha hisoblanadi."},"en":{"q":"Two units are merged into one totaling 400 sqm (formerly 180 sqm and 220 sqm). Service charge is $3/sqm/month. What is the merged tenant's new monthly bill?","a":["$1,200","$600","$1,800"],"c":0,"why":"400 sqm x $3/sqm = $1,200 per month — the charge is based on the final combined area, not each former unit separately."}},{"id":"LC100","cat":"logic","logic":true,"ru":{"q":"Арендодатель выбирает между арендатором с фиксированной арендой $10,000/мес и арендатором с чисто оборотной арендой (10% продаж, без минимума), чьи ожидаемые продажи нестабильны. Что важно учитывать?","a":["Оборотная схема всегда выгоднее из-за процента","Фиксированная схема снижает риск волатильности дохода","Схема начисления не влияет на риск арендодателя"],"c":1,"why":"Без минимальной гарантии оборотная аренда полностью зависит от продаж арендатора, перенося весь риск волатильности на арендодателя, тогда как фиксированная ставка обеспечивает предсказуемость."},"uz":{"q":"Ijara beruvchi oylik $10,000 belgilangan ijara bilan, savdosi beqaror sof oborotli ijarachi (10%, minimumsiz) o'rtasida tanlamoqda. Nimani hisobga olish muhim?","a":["Oborotli sxema foiz tufayli har doim foydaliroq","Belgilangan sxema daromad beqarorligi xavfini kamaytiradi","Hisoblash sxemasi ijara beruvchi xavfiga ta'sir qilmaydi"],"c":1,"why":"Minimal kafolatsiz oborotli ijara to'liq ijarachi savdosiga bog'liq bo'lib, barcha beqarorlik xavfini ijara beruvchiga o'tkazadi, belgilangan stavka esa bashorat qilinadigan daromad beradi."},"en":{"q":"A landlord chooses between a tenant paying a fixed $10,000/month rent and a tenant on pure turnover rent (10% of sales, no minimum) whose expected sales are volatile. What matters here?","a":["The turnover scheme is always better due to the percentage","The fixed scheme reduces income volatility risk","The rent structure doesn't affect the landlord's risk"],"c":1,"why":"Without a minimum guarantee, turnover rent depends entirely on tenant sales, shifting all volatility risk to the landlord, while a fixed rate provides predictable income."}},{"id":"LG001","cat":"legal","logic":false,"ru":{"q":"Какое условие обязательно в договоре аренды торговой площади, иначе договор может считаться незаключённым?","a":["Предмет аренды и арендуемая площадь","Цвет вывески арендатора","Логотип торгового центра"],"c":0,"why":"Предмет договора (объект и его площадь) — существенное условие, без которого договор не считается заключённым."},"uz":{"q":"Savdo maydoni ijarasi shartnomasida qaysi shart albatta kelishilishi kerak, aks holda shartnoma tuzilmagan hisoblanadi?","a":["Ijara predmeti va maydon","Ijarachi peshtaxtasining rangi","SSM logotipi"],"c":0,"why":"Shartnoma predmeti (obyekt va maydon) muhim shart bo'lib, u bo'lmasa shartnoma tuzilmagan hisoblanadi."},"en":{"q":"Which term must be defined in a retail lease, otherwise the contract may be considered not concluded?","a":["The leased premises and its area","The color of the tenant's signage","The mall's logo design"],"c":0,"why":"The subject of the lease (premises and area) is a material term without which the contract is not validly formed."}},{"id":"LG002","cat":"legal","logic":false,"ru":{"q":"Какое из условий также считается существенным для договора аренды коммерческой недвижимости?","a":["Размер арендной платы","Часы работы фудкорта","Наличие Wi-Fi в общих зонах"],"c":0,"why":"Размер арендной платы — существенное условие возмездного договора аренды."},"uz":{"q":"Tijorat ko'chmas mulki ijarasi shartnomasi uchun yana qaysi shart muhim hisoblanadi?","a":["Ijara to'lovi miqdori","Fudkort ish vaqti","Umumiy zonalarda Wi-Fi bo'lishi"],"c":0,"why":"Ijara to'lovi miqdori pullik ijara shartnomasining muhim shartidir."},"en":{"q":"Which of the following is also a material term of a commercial lease agreement?","a":["The amount of rent","Food court operating hours","Availability of Wi-Fi in common areas"],"c":0,"why":"Rent amount is a material term of any lease agreement made for payment."}},{"id":"LG003","cat":"legal","logic":false,"ru":{"q":"Что обычно понимается под форс-мажором в договоре аренды?","a":["Обстоятельства непреодолимой силы вне контроля сторон","Любая просрочка платежа арендатором","Плановый ремонт торгового центра"],"c":0,"why":"Форс-мажор — это чрезвычайные и непредотвратимые обстоятельства, не зависящие от воли сторон."},"uz":{"q":"Ijara shartnomasida fors-major deganda odatda nima tushuniladi?","a":["Tomonlar nazoratidan tashqari yengib bo'lmas holatlar","Ijarachining har qanday to'lov kechikishi","SSMning rejalashtirilgan ta'miri"],"c":0,"why":"Fors-major — tomonlarning irodasiga bog'liq bo'lmagan favqulodda va oldini olib bo'lmaydigan holatlardir."},"en":{"q":"What is typically understood as force majeure in a lease agreement?","a":["Extraordinary events beyond either party's control","Any late payment by the tenant","A scheduled renovation of the mall"],"c":0,"why":"Force majeure refers to extraordinary, unforeseeable events outside the parties' control."}},{"id":"LG004","cat":"legal","logic":false,"ru":{"q":"Может ли арендатор ссылаться на форс-мажор, чтобы не платить аренду из-за своих финансовых трудностей?","a":["Нет, финансовые трудности не являются форс-мажором","Да, любые убытки автоматически считаются форс-мажором","Да, но только если арендодатель согласен"],"c":0,"why":"Финансовые затруднения арендатора — это предпринимательский риск, а не форс-мажорное обстоятельство."},"uz":{"q":"Ijarachi o'z moliyaviy qiyinchiliklari sababli ijarani to'lamaslik uchun fors-majorga tayanishi mumkinmi?","a":["Yo'q, moliyaviy qiyinchilik fors-major emas","Ha, har qanday zarar avtomatik fors-major hisoblanadi","Ha, faqat ijaraga beruvchi rozi bo'lsa"],"c":0,"why":"Ijarachining moliyaviy qiyinchiligi tadbirkorlik xavfi bo'lib, fors-major holati emas."},"en":{"q":"Can a tenant invoke force majeure to avoid paying rent due to their own financial difficulties?","a":["No, financial hardship is not force majeure","Yes, any business loss automatically qualifies","Yes, but only if the landlord agrees informally"],"c":0,"why":"A tenant's financial hardship is ordinary business risk, not an unforeseeable external event."}},{"id":"LG005","cat":"legal","logic":false,"ru":{"q":"Кто по общему правилу отвечает за капитальный ремонт помещения, если иное не указано в договоре?","a":["Арендодатель (собственник)","Арендатор","Управляющая компания за отдельную плату"],"c":0,"why":"По умолчанию капитальный ремонт — обязанность арендодателя как собственника имущества."},"uz":{"q":"Shartnomada boshqacha ko'rsatilmagan bo'lsa, xonaning kapital ta'miri uchun umumiy qoida bo'yicha kim javobgar?","a":["Ijaraga beruvchi (mulkdor)","Ijarachi","Boshqaruv kompaniyasi alohida to'lovga"],"c":0,"why":"Standart holatda kapital ta'mir mulk egasi sifatida ijaraga beruvchi zimmasida bo'ladi."},"en":{"q":"By default, who is responsible for major (capital) repairs unless the contract states otherwise?","a":["The landlord (owner)","The tenant","The management company, for an extra fee"],"c":0,"why":"As a default rule, major structural repairs are the landlord's responsibility as property owner."}},{"id":"LG006","cat":"legal","logic":false,"ru":{"q":"Что обычно относится к обязанностям арендатора в части содержания помещения?","a":["Текущий (косметический) ремонт и порядок","Замена несущих конструкций здания","Ремонт фасада всего торгового центра"],"c":0,"why":"Текущий ремонт и поддержание помещения в исправном состоянии — типичная обязанность арендатора."},"uz":{"q":"Xonani saqlash bo'yicha ijarachining majburiyatlariga odatda nima kiradi?","a":["Joriy (kosmetik) ta'mir va tozalik","Binoning tayanch konstruksiyalarini almashtirish","Butun SSM fasadini ta'mirlash"],"c":0,"why":"Joriy ta'mir va xonani ishlaydigan holatda saqlash odatda ijarachining majburiyatidir."},"en":{"q":"What typically falls under the tenant's obligations for upkeep of the premises?","a":["Cosmetic repairs and general upkeep","Replacing the building's load-bearing structures","Repairing the entire mall's facade"],"c":0,"why":"Routine cosmetic repairs and general upkeep of the unit are typically the tenant's responsibility."}},{"id":"LG007","cat":"legal","logic":false,"ru":{"q":"Договор аренды предусматривает пеню за просрочку арендной платы. Для чего служит это условие?","a":["Стимулировать оплату вовремя и компенсировать убытки","Полностью заменить арендную плату","Освободить арендатора от уплаты аренды"],"c":0,"why":"Пеня стимулирует своевременное исполнение обязательства и компенсирует арендодателю потери от просрочки."},"uz":{"q":"Ijara shartnomasida to'lov kechikishi uchun jarima nazarda tutilgan. Bu shart nima uchun xizmat qiladi?","a":["O'z vaqtida to'lashni rag'batlantirish va zararni qoplash","Ijara to'lovini butunlay almashtirish","Ijarachini to'lovdan ozod qilish"],"c":0,"why":"Jarima o'z vaqtida ijro etishni rag'batlantiradi va ijaraga beruvchi zararini qisman qoplaydi."},"en":{"q":"A lease includes a late-payment penalty clause. What is the main purpose of this clause?","a":["Encourage timely payment and compensate for losses","Replace the rent obligation entirely","Release the tenant from paying rent"],"c":0,"why":"A penalty clause incentivizes timely payment and compensates the landlord for losses caused by delay."}},{"id":"LG008","cat":"legal","logic":false,"ru":{"q":"На что стоит обратить внимание при проверке пункта о пене за просрочку платежа?","a":["Ставка пени разумна и чётко прописана","Пеня всегда должна превышать сумму долга","Пеня применяется только к арендодателю"],"c":0,"why":"Неустойка должна быть чётко определена и соразмерна, иначе её можно оспорить как чрезмерную."},"uz":{"q":"To'lov kechikishi uchun jarima bandini tekshirishda nimaga e'tibor berish kerak?","a":["Jarima stavkasi oqilona va aniq bo'lishi","Jarima har doim qarzdan katta bo'lishi kerak","Jarima faqat ijaraga beruvchiga qo'llaniladi"],"c":0,"why":"Jarima aniq belgilangan va oqilona bo'lishi kerak, aks holda u haddan tashqari sifatida bahslashilishi mumkin."},"en":{"q":"What should a consultant check when reviewing a late-payment penalty clause?","a":["The penalty rate is reasonable and clearly stated","The penalty always exceeds the outstanding debt","The penalty applies only to the landlord"],"c":0,"why":"A penalty must be clearly defined and proportionate, or it risks being challenged as excessive."}},{"id":"LG009","cat":"legal","logic":false,"ru":{"q":"Может ли арендатор сдать площадь в субаренду третьему лицу без согласия арендодателя?","a":["Нет, обычно нужно письменное согласие арендодателя","Да, это право арендатора по умолчанию","Да, если субарендатор работает в той же сфере"],"c":0,"why":"Субаренда, как правило, допускается только с письменного согласия арендодателя."},"uz":{"q":"Ijarachi maydonni ijaraga beruvchi roziligisiz uchinchi shaxsga subijaraga berishi mumkinmi?","a":["Yo'q, odatda yozma rozilik talab qilinadi","Ha, bu ijarachining standart huquqi","Ha, agar subijarachi bir xil sohada bo'lsa"],"c":0,"why":"Subijara odatda faqat ijaraga beruvchining yozma roziligi bilan ruxsat etiladi."},"en":{"q":"Can a tenant sublease the rented space to a third party without the landlord's consent?","a":["No, written landlord consent is generally required","Yes, this is the tenant's default right","Yes, if the subtenant operates in the same industry"],"c":0,"why":"Subletting is normally permitted only with the landlord's prior written consent."}},{"id":"LG010","cat":"legal","logic":false,"ru":{"q":"Почему арендодателю торгового центра важно контролировать субаренду?","a":["Чтобы управлять составом арендаторов и их качеством","Чтобы автоматически получать двойную аренду","Потому что субаренда всегда запрещена законом"],"c":0,"why":"Контроль субаренды позволяет ТРЦ управлять концепцией и качеством арендаторского пула (tenant mix)."},"uz":{"q":"Nima uchun SSM ijaraga beruvchisi uchun subijarani nazorat qilish muhim?","a":["Ijarachilar tarkibi va sifatini boshqarish uchun","Avtomatik ikki baravar ijara olish uchun","Chunki subijara har doim qonunda taqiqlangan"],"c":0,"why":"Subijarani nazorat qilish SSMga tenant-miks sifatini boshqarish imkonini beradi."},"en":{"q":"Why is controlling subleasing important for a shopping mall landlord?","a":["To manage tenant mix and overall retail quality","To automatically collect double rent","Because subleasing is universally illegal"],"c":0,"why":"Controlling subleases lets the mall manage its tenant mix and overall retail concept."}},{"id":"LG011","cat":"legal","logic":false,"ru":{"q":"Какое из оснований обычно даёт арендодателю право досрочно расторгнуть договор аренды?","a":["Систематическая неуплата аренды арендатором","Плохая погода в регионе","Снижение посещаемости торгового центра"],"c":0,"why":"Систематическая неуплата аренды — классическое основание для расторжения по инициативе арендодателя."},"uz":{"q":"Quyidagilardan qaysi biri ijaraga beruvchiga shartnomani muddatidan oldin bekor qilish huquqini beradi?","a":["Ijarachi tomonidan ijarani tizimli to'lamaslik","Mintaqadagi yomon ob-havo","SSM tashrif buyuruvchilar sonining kamayishi"],"c":0,"why":"Ijara haqini tizimli to'lamaslik ijaraga beruvchi tomonidan bekor qilish uchun odatiy asosdir."},"en":{"q":"Which of the following typically gives a landlord grounds to terminate a lease early?","a":["Repeated non-payment of rent by the tenant","Bad weather in the region","A decline in the mall's foot traffic"],"c":0,"why":"Repeated non-payment of rent is a standard, well-recognized ground for landlord-initiated termination."}},{"id":"LG012","cat":"legal","logic":false,"ru":{"q":"Какое основание обычно позволяет арендатору требовать досрочного расторжения договора?","a":["Помещение стало непригодным не по вине арендатора","Арендатор открывает похожий магазин в другом ТРЦ","Арендатор не согласен с рекламной кампанией ТРЦ"],"c":0,"why":"Если помещение стало непригодным для использования не по вине арендатора, это законное основание для расторжения."},"uz":{"q":"Qaysi asos ijarachiga shartnomani muddatidan oldin bekor qilishni talab qilish huquqini beradi?","a":["Xona ijarachi aybisiz yaroqsiz holga kelgani","Ijarachi boshqa SSMda shu kabi do'kon ochmoqchi","Ijarachi SSM reklama kampaniyasiga rozi emas"],"c":0,"why":"Xona ijarachining aybisiz yaroqsiz holga kelishi shartnomani bekor qilish uchun qonuniy asosdir."},"en":{"q":"Which ground typically allows a tenant to demand early termination of the lease?","a":["The premises become unusable through no fault of the tenant","The tenant opens a similar store in another mall","The tenant disagrees with the mall's marketing campaign"],"c":0,"why":"If the premises become unfit for use without the tenant's fault, this is valid grounds for termination."}},{"id":"LG013","cat":"legal","logic":false,"ru":{"q":"В чём основное отличие банковской гарантии от денежного депозита как обеспечения аренды?","a":["Гарантия — обещание банка, депозит — деньги у арендодателя","Депозит выдаёт банк, а гарантию — арендатор","Гарантия и депозит юридически идентичны"],"c":0,"why":"Банковская гарантия — это обязательство третьего лица (банка), а депозит — фактически внесённые деньги."},"uz":{"q":"Ijara ta'minoti sifatida bank kafolati bilan pul depoziti o'rtasidagi asosiy farq nimada?","a":["Kafolat — bank va'dasi, depozit — real pul mablag'i","Depozitni bank, kafolatni ijarachi beradi","Kafolat va depozit huquqiy jihatdan bir xil"],"c":0,"why":"Bank kafolati uchinchi shaxs (bank)ning majburiyati, depozit esa haqiqatda kiritilgan pul mablag'idir."},"en":{"q":"What is the key difference between a bank guarantee and a cash deposit as lease security?","a":["A guarantee is a bank promise; a deposit is funds held","A deposit is issued by a bank, a guarantee by the tenant","They are legally identical instruments"],"c":0,"why":"A bank guarantee is a third-party (bank) payment obligation, while a deposit is actual money already transferred."}},{"id":"LG014","cat":"legal","logic":false,"ru":{"q":"Какое преимущество банковской гарантии для арендатора по сравнению с денежным депозитом?","a":["Не нужно замораживать собственные оборотные средства","Гарантия всегда дешевле самой аренды","Гарантия отменяет обязанность платить аренду"],"c":0,"why":"При банковской гарантии арендатор не выводит из оборота крупную сумму наличных, в отличие от депозита."},"uz":{"q":"Bank kafolatining pul depozitiga nisbatan ijarachi uchun afzalligi nimada?","a":["Aylanma mablag'ni muzlatib qo'ymaslik","Kafolat har doim ijaradan arzon turadi","Kafolat ijara to'lash majburiyatini bekor qiladi"],"c":0,"why":"Bank kafolatida ijarachi katta naqd summani aylanmadan chiqarib qo'ymaydi, depozitdan farqli o'laroq."},"en":{"q":"What is an advantage of a bank guarantee over a cash deposit for the tenant?","a":["The tenant avoids tying up its own working capital","A guarantee always costs less than the rent itself","A guarantee eliminates the duty to pay rent"],"c":0,"why":"A bank guarantee lets the tenant avoid locking up significant cash, unlike a deposit."}},{"id":"LG015","cat":"legal","logic":false,"ru":{"q":"Для чего в первую очередь нужен обеспечительный депозит по договору аренды?","a":["Покрыть убытки арендодателя при неисполнении договора","Оплатить коммунальные услуги всего здания","Финансировать маркетинговые акции арендатора"],"c":0,"why":"Обеспечительный депозит защищает арендодателя от убытков, вызванных неисполнением обязательств арендатором."},"uz":{"q":"Ijara shartnomasi bo'yicha ta'minot depoziti birinchi navbatda nima uchun kerak?","a":["Ijarachi majburiyatni buzsa, zararni qoplash uchun","Butun binoning kommunal xarajatlarini to'lash uchun","Ijarachining marketing aksiyalarini moliyalash uchun"],"c":0,"why":"Ta'minot depoziti ijarachi majburiyatni bajarmagan taqdirda ijaraga beruvchini zarardan himoya qiladi."},"en":{"q":"What is the primary purpose of a security deposit under a lease agreement?","a":["Cover landlord losses from a tenant default","Pay for utilities across the entire building","Fund the tenant's marketing campaigns"],"c":0,"why":"A security deposit protects the landlord against losses arising from tenant default."}},{"id":"LG016","cat":"legal","logic":false,"ru":{"q":"Долгосрочные договоры аренды недвижимости часто подлежат какой процедуре для защиты сторон перед третьими лицами?","a":["Государственной регистрации","Нотариальному переводу на английский язык","Публикации в газете"],"c":0,"why":"Долгосрочные договоры аренды недвижимости обычно подлежат государственной регистрации, что защищает права сторон."},"uz":{"q":"Uzoq muddatli ko'chmas mulk ijarasi tomonlar huquqini uchinchi shaxslardan himoya qilish uchun qanday tartibdan o'tadi?","a":["Davlat ro'yxatidan o'tkazish","Ingliz tiliga notarial tarjima","Gazetada e'lon qilish"],"c":0,"why":"Ko'chmas mulkning uzoq muddatli ijarasi odatda davlat ro'yxatidan o'tkaziladi, bu tomonlar huquqini himoya qiladi."},"en":{"q":"Long-term property leases are often subject to which procedure to protect the parties against third parties?","a":["State registration","Notarized translation into English","Publication in a newspaper"],"c":0,"why":"Long-term property leases are typically subject to state registration, which protects the parties' rights."}},{"id":"LG017","cat":"legal","logic":false,"ru":{"q":"Почему важно проверить, зарегистрирован ли долгосрочный договор аренды в уполномоченном органе?","a":["Незарегистрированный договор не защищён от третьих лиц","Регистрация автоматически снижает арендную ставку","Регистрация нужна только для договоров до месяца"],"c":0,"why":"Без регистрации долгосрочный договор может не иметь силы против третьих лиц, например покупателя здания."},"uz":{"q":"Nima uchun uzoq muddatli ijara shartnomasi ro'yxatdan o'tganini tekshirish muhim?","a":["Ro'yxatsiz shartnoma uchinchi shaxsga kuchsiz bo'ladi","Ro'yxatga olish ijara stavkasini avtomatik kamaytiradi","Ro'yxatga olish faqat bir oygacha shartnomalar uchun kerak"],"c":0,"why":"Ro'yxatga olinmagan uzoq muddatli shartnoma uchinchi shaxslarga, masalan yangi mulkdorga qarshi kuchga ega bo'lmasligi mumkin."},"en":{"q":"Why should a consultant confirm a long-term lease is registered with the authorities?","a":["An unregistered lease may not bind third parties","Registration automatically lowers the rental rate","Registration is only required for leases under a month"],"c":0,"why":"Without proper registration, a long-term lease may not be binding on third parties, such as a new building owner."}},{"id":"LG018","cat":"legal","logic":false,"ru":{"q":"Кто обычно платит НДС при оказании арендодателем услуг аренды коммерческой площади?","a":["Арендодатель, начисляя НДС на арендную плату","Арендатор, напрямую в бюджет вместо арендодателя","Управляющая компания, независимо от собственника"],"c":0,"why":"Арендодатель, оказывающий услугу аренды, как правило, начисляет и уплачивает НДС с суммы аренды."},"uz":{"q":"Tijorat maydonini ijaraga berish xizmatida odatda QQSni kim hisoblab, to'laydi?","a":["Ijaraga beruvchi, ijara haqiga QQS qo'shib","Ijarachi, budjetga to'g'ridan-to'g'ri","SSM boshqaruv kompaniyasi, mulkdordan qat'i nazar"],"c":0,"why":"Ijara xizmatini ko'rsatuvchi ijaraga beruvchi odatda ijara summasiga QQS hisoblab, to'laydi."},"en":{"q":"Under a standard tax regime, who typically charges VAT on a commercial rental service?","a":["The landlord, adding VAT to the rental invoice","The tenant, paying VAT directly instead of the landlord","The mall's management company, regardless of ownership"],"c":0,"why":"The landlord providing the rental service typically charges and remits VAT on the rent amount."}},{"id":"LG019","cat":"legal","logic":false,"ru":{"q":"Кто обычно платит налог на имущество в отношении сдаваемых в аренду торговых площадей?","a":["Собственник объекта (арендодатель)","Арендатор, использующий помещение","Покупатели в торговом центре"],"c":0,"why":"Налог на имущество платит собственник объекта, а не арендатор, если иное прямо не установлено договором и законом."},"uz":{"q":"Ijaraga berilgan savdo maydonlari bo'yicha mulk solig'ini odatda kim to'laydi?","a":["Ko'chmas mulk egasi (ijaraga beruvchi)","Xonadan foydalanuvchi ijarachi","SSMdagi xaridorlar"],"c":0,"why":"Mulk solig'ini, shartnoma va qonunda boshqacha belgilanmasa, obyekt egasi to'laydi."},"en":{"q":"Who is typically liable for property tax on leased retail space?","a":["The owner of the real estate (landlord)","The tenant occupying the space","Shoppers visiting the mall"],"c":0,"why":"Property tax is owed by the property owner, not the tenant, unless the contract and law state otherwise."}},{"id":"LG020","cat":"legal","logic":false,"ru":{"q":"Договор указывает арендную ставку 'без учёта НДС'. Что это значит на практике для арендатора?","a":["К ставке дополнительно добавится сумма НДС","НДС уже включён, доплачивать не нужно","Арендатор освобождается от НДС навсегда"],"c":0,"why":"Формулировка 'без учёта НДС' означает, что налог начисляется сверх указанной суммы аренды."},"uz":{"q":"Shartnomada ijara stavkasi 'QQSsiz' deb ko'rsatilgan. Bu ijarachi uchun amalda nimani anglatadi?","a":["Stavkaga qo'shimcha QQS summasi qo'shiladi","QQS allaqachon kiritilgan, qo'shimcha to'lov shart emas","Ijarachi QQSdan butunlay ozod qilinadi"],"c":0,"why":"'QQSsiz' iborasi soliq ko'rsatilgan summadan tashqari qo'shilishini bildiradi."},"en":{"q":"A lease states the rent is 'exclusive of VAT.' What does this mean for the tenant?","a":["VAT will be added on top of the stated rent","VAT is already included, no extra payment is due","The tenant is permanently exempt from VAT"],"c":0,"why":"'Exclusive of VAT' means the tax is charged in addition to the stated rent figure."}},{"id":"LG021","cat":"legal","logic":false,"ru":{"q":"Что из перечисленного должен как минимум содержать трудовой договор сотрудника магазина в ТРЦ?","a":["Должность, оплату труда и режим рабочего времени","Список поставщиков магазина","Маркетинговый план арендатора"],"c":0,"why":"Трудовой договор должен фиксировать ключевые условия труда: должность, оплату и график работы."},"uz":{"q":"SSMdagi do'kon xodimi mehnat shartnomasida kamida nima bo'lishi kerak?","a":["Lavozim, maosh miqdori va ish vaqti tartibi","Do'konning yetkazib beruvchilar ro'yxati","Ijarachining marketing rejasi"],"c":0,"why":"Mehnat shartnomasida asosiy shartlar — lavozim, maosh va ish jadvali qayd etilishi kerak."},"en":{"q":"At minimum, what should an employment contract for a mall store employee include?","a":["Job position, salary, and working hours","The store's list of suppliers","The tenant's marketing plan"],"c":0,"why":"An employment contract must set out core terms of employment: role, pay, and working schedule."}},{"id":"LG022","cat":"legal","logic":false,"ru":{"q":"Какое общее правило действует при привлечении сотрудника магазина к сверхурочной работе?","a":["Она должна оплачиваться по повышенной ставке","Сверхурочная работа никогда не оплачивается","Она оплачивается лишь премией по желанию работодателя"],"c":0,"why":"Общий принцип трудового права — сверхурочная работа компенсируется по повышенной ставке."},"uz":{"q":"Do'kon xodimini qo'shimcha ishga jalb qilishda qanday umumiy qoida amal qiladi?","a":["Oshirilgan stavka bo'yicha to'lanishi kerak","Qo'shimcha ish hech qachon to'lanmaydi","Faqat ish beruvchi xohishiga ko'ra mukofot to'lanadi"],"c":0,"why":"Mehnat huquqining umumiy tamoyili — qo'shimcha ish oshirilgan stavka bo'yicha kompensatsiya qilinadi."},"en":{"q":"What is the general rule when a store employee is asked to work overtime?","a":["Overtime must be paid at an increased rate","Overtime is never compensated","It is paid only at the employer's discretion"],"c":0,"why":"A general labor-law principle is that overtime work must be compensated at a higher rate."}},{"id":"LG023","cat":"legal","logic":false,"ru":{"q":"Почему консультанту по аренде полезно базовое понимание трудового права по персоналу арендаторов?","a":["Чтобы оценивать риски, влияющие на работу арендатора","Чтобы самому нанимать продавцов в магазины арендаторов","Чтобы устанавливать зарплаты сотрудникам арендатора"],"c":0,"why":"Базовое понимание трудового права помогает консультанту оценивать риски арендатора, не подменяя его HR-службу."},"uz":{"q":"Nima uchun konsultant uchun ijarachi xodimlari bo'yicha mehnat huquqi asoslarini bilish foydali?","a":["Ijarachi faoliyatiga ta'sir etuvchi xavflarni baholash uchun","Ijarachi do'konlariga sotuvchilarni o'zi yollash uchun","Ijarachi xodimlarining maoshini belgilash uchun"],"c":0,"why":"Mehnat huquqi asoslari konsultantga ijarachi xavflarini baholashga yordam beradi, HR vazifasini bajarmasdan."},"en":{"q":"Why is basic labor-law awareness useful for a leasing consultant regarding tenant staff?","a":["It helps assess risks affecting the tenant's operations","So the consultant can hire the tenant's sales staff","So the consultant can set tenant employee salaries"],"c":0,"why":"Basic labor-law awareness helps a consultant evaluate tenant risk without replacing its HR function."}},{"id":"LG024","cat":"legal","logic":false,"ru":{"q":"Что из перечисленного обычно относится к минимальным трудовым гарантиям сотрудников магазина в ТРЦ?","a":["Право на ежегодный оплачиваемый отпуск","Право требовать процент от прибыли магазина","Право самостоятельно менять график работы ТРЦ"],"c":0,"why":"Ежегодный оплачиваемый отпуск — базовая трудовая гарантия для наёмных работников."},"uz":{"q":"Quyidagilardan qaysi biri SSMdagi do'kon xodimlari uchun minimal mehnat kafolatiga kiradi?","a":["Yillik pullik ta'til huquqi","Do'kon foydasidan ulush olish huquqi","SSM ish jadvalini mustaqil o'zgartirish huquqi"],"c":0,"why":"Yillik pullik ta'til yollanma xodimlar uchun asosiy mehnat kafolatidir."},"en":{"q":"Which of the following is typically a minimum labor guarantee for mall store employees?","a":["The right to annual paid leave","The right to a share of the store's profits","The right to change the mall's operating hours"],"c":0,"why":"Annual paid leave is a basic labor guarantee for employees under standard labor law."}},{"id":"LG025","cat":"legal","logic":false,"ru":{"q":"Арендатор держит персонал магазина без оформленных трудовых договоров. Какой риск это создаёт и для ТРЦ?","a":["Репутационный и юридический риск, включая штрафы","Никакого риска, это личное дело арендатора","Это автоматически повышает арендную ставку"],"c":0,"why":"Неоформленные трудовые отношения создают юридические и репутационные риски, которые затрагивают и имидж ТРЦ."},"uz":{"q":"Ijarachi xodimlarni rasmiy mehnat shartnomasisiz ishlatmoqda. Bu SSM uchun ham qanday xavf tug'diradi?","a":["Obro' va huquqiy xavf, jarima va tekshiruvlar","Hech qanday xavf yo'q, bu ijarachining ichki ishi","Bu avtomatik ijara stavkasini oshiradi"],"c":0,"why":"Rasmiylashtirilmagan mehnat munosabatlari huquqiy va obro' xavflarini keltirib chiqaradi, bu SSM imijiga ham ta'sir qiladi."},"en":{"q":"A tenant employs store staff without formal contracts. What risk does this pose that also affects the mall landlord?","a":["Reputational and legal risk, including fines","No risk at all, purely the tenant's internal matter","It automatically increases the rental rate"],"c":0,"why":"Informal employment arrangements create legal and reputational risks that can also reflect on the mall's image."}},{"id":"LG026","cat":"legal","logic":false,"ru":{"q":"Кто по общей практике коммерческой аренды обычно несёт капитальный ремонт здания ТРЦ (кровля, несущие конструкции, инженерные сети)?","a":["Арендодатель","Арендатор","Управляющая компания за счёт арендатора без согласования"],"c":0,"why":"Капитальный ремонт конструктивных элементов здания по умолчанию является обязанностью собственника (арендодателя)."},"uz":{"q":"Umumiy tijorat ijarasi amaliyotida TRC binosining kapital ta'mirini (tom, poydevor, muhandislik tarmoqlari) odatda kim zimmasiga oladi?","a":["Ijaraga beruvchi","Ijarachi","Boshqaruv kompaniyasi, kelishuvsiz ijarachi hisobidan"],"c":0,"why":"Binoning konstruktiv elementlarini kapital ta'mirlash odatda mulk egasi — ijaraga beruvchining vazifasidir."},"en":{"q":"Under standard commercial lease practice, who is typically responsible for major/structural repairs of a mall building (roof, load-bearing structures, utilities)?","a":["The landlord","The tenant","The management company, at tenant's cost without approval"],"c":0,"why":"Structural and capital repairs of the building are by default the landlord's (owner's) responsibility."}},{"id":"LG027","cat":"legal","logic":false,"ru":{"q":"Какой пункт договора аренды обычно определяет, что мелкий текущий ремонт арендуемого помещения выполняет арендатор?","a":["Пункт о содержании и текущем ремонте","Пункт о конфиденциальности","Пункт о форс-мажоре"],"c":0,"why":"Обязанности по текущему (косметическому) ремонту помещения прописываются в разделе о содержании арендуемой площади."},"uz":{"q":"Ijara shartnomasining qaysi bandi odatda ijara maydonining joriy (kichik) ta'mirini ijarachi bajarishini belgilaydi?","a":["Saqlash va joriy ta'mir bandi","Maxfiylik bandi","Fors-major bandi"],"c":0,"why":"Joriy (kosmetik) ta'mir bo'yicha majburiyatlar ijara maydonini saqlash bandida belgilanadi."},"en":{"q":"Which lease clause typically specifies that the tenant performs minor/cosmetic repairs within the leased premises?","a":["Maintenance and minor repairs clause","Confidentiality clause","Force majeure clause"],"c":0,"why":"Responsibility for cosmetic/minor repairs of the unit is set out in the maintenance obligations section."}},{"id":"LG028","cat":"legal","logic":false,"ru":{"q":"Что из перечисленного корректно описывает форс-мажор в договоре аренды?","a":["Непреодолимая сила вне контроля сторон","Любая просрочка платежа арендатором","Плановое повышение арендной ставки"],"c":0,"why":"Форс-мажор — это чрезвычайное и непредотвратимое обстоятельство, наступление которого стороны не могли предвидеть или предотвратить."},"uz":{"q":"Quyidagilardan qaysi biri ijara shartnomasidagi fors-major tushunchasini to'g'ri tavsiflaydi?","a":["Tomonlar nazoratidan tashqari yengib bo'lmas kuch","Ijarachining har qanday to'lov kechikishi","Ijara stavkasining rejalashtirilgan oshishi"],"c":0,"why":"Fors-major — bu tomonlar oldindan ko'ra olmagan va oldini ololmagan favqulodda holatdir."},"en":{"q":"Which statement correctly describes force majeure in a lease agreement?","a":["An extraordinary event beyond the parties' control","Any late payment by the tenant","A scheduled increase in the rental rate"],"c":0,"why":"Force majeure refers to extraordinary, unforeseeable events outside the parties' control that prevent performance."}},{"id":"LG029","cat":"legal","logic":false,"ru":{"q":"Что обычно должна сделать сторона, ссылающаяся на форс-мажор, чтобы освободиться от ответственности?","a":["Уведомить другую сторону и подтвердить документом","Просто прекратить платить аренду без объяснений","Расторгнуть договор в одностороннем порядке немедленно"],"c":0,"why":"Договоры обычно требуют письменного уведомления в установленный срок и документального подтверждения форс-мажора (например, от торгово-промышленной палаты)."},"uz":{"q":"Fors-major holatiga tayanuvchi tomon javobgarlikdan ozod bo'lish uchun odatda nima qilishi kerak?","a":["Xabar berish va hujjat bilan tasdiqlash","Tushuntirishsiz ijarani to'lashni to'xtatish","Shartnomani darhol bir tomonlama bekor qilish"],"c":0,"why":"Shartnomalar odatda belgilangan muddatda yozma xabar berish va fors-majorni hujjat bilan tasdiqlashni talab qiladi."},"en":{"q":"What must a party invoking force majeure typically do to be excused from liability?","a":["Notify the other party and provide proof","Simply stop paying rent without explanation","Terminate the contract unilaterally and immediately"],"c":0,"why":"Leases generally require timely written notice plus documentary proof (e.g., from a chamber of commerce) of the force majeure event."}},{"id":"LG030","cat":"legal","logic":false,"ru":{"q":"Как обычно рассчитывается неустойка (пеня) за просрочку арендного платежа?","a":["Процент от долга за каждый день просрочки","Фиксированная сумма, равная годовой аренде","Автоматическое расторжение договора без штрафа"],"c":0,"why":"Стандартная практика — начисление пени в виде процента (например, 0,1%) от просроченной суммы за каждый день задержки."},"uz":{"q":"Ijara to'lovi kechiktirilganda penya (jarima) odatda qanday hisoblanadi?","a":["Kechiktirilgan summadan har kunlik foiz sifatida","Yillik ijaraga teng qat'iy summa","Jarimasiz shartnomani avtomatik bekor qilish"],"c":0,"why":"Odatiy amaliyot — kechiktirilgan summadan har kun uchun foiz (masalan, 0,1%) shaklida penya hisoblash."},"en":{"q":"How is a late-payment penalty (interest) on overdue rent typically calculated?","a":["A percentage of the overdue amount per day of delay","A fixed sum equal to a full year's rent","Automatic termination with no penalty at all"],"c":0,"why":"Standard practice charges a daily percentage (e.g., 0.1%) of the outstanding amount for each day of delay."}},{"id":"LG031","cat":"legal","logic":false,"ru":{"q":"Зачем в договоре аренды обычно устанавливают предельный размер (потолок) неустойки за просрочку?","a":["Чтобы избежать несоразмерно высоких штрафов","Чтобы арендатор мог не платить аренду вовсе","Чтобы арендодатель мог повышать ставку без уведомления"],"c":0,"why":"Потолок неустойки защищает стороны от несоразмерно высоких штрафов, накопленных за длительный период просрочки."},"uz":{"q":"Ijara shartnomasida kechikish uchun penyaning yuqori chegarasi nima uchun belgilanadi?","a":["Nomutanosib yuqori jarimalarning oldini olish uchun","Ijarachi ijarani umuman to'lamasligi uchun","Ijaraga beruvchi stavkani xabarsiz oshirishi uchun"],"c":0,"why":"Penyaning yuqori chegarasi tomonlarni uzoq muddatli kechikish natijasida to'plangan nomutanosib jarimalardan himoya qiladi."},"en":{"q":"Why is a cap on late-payment penalties typically included in a lease agreement?","a":["To avoid disproportionately large penalties","So the tenant never has to pay rent","So the landlord can raise rent without notice"],"c":0,"why":"A penalty cap protects parties from disproportionately large fines accumulating over an extended delay."}},{"id":"LG032","cat":"legal","logic":false,"ru":{"q":"Что требуется арендатору по стандартному договору перед передачей арендуемой площади в субаренду?","a":["Получить предварительное письменное согласие арендодателя","Ничего, субаренда разрешена автоматически","Только устное уведомление управляющего ТРЦ"],"c":0,"why":"Субаренда третьим лицам обычно требует предварительного письменного согласия арендодателя."},"uz":{"q":"Standart shartnoma bo'yicha ijarachi maydonni subijaraga berishdan oldin nima qilishi kerak?","a":["Ijaraga beruvchidan oldindan yozma rozilik olish","Hech narsa, subijara avtomatik ruxsat etilgan","Faqat TRC boshqaruvchisiga og'zaki xabar berish"],"c":0,"why":"Uchinchi shaxsga subijaraga berish odatda ijaraga beruvchining oldindan yozma roziligini talab qiladi."},"en":{"q":"What must a tenant typically do before subletting the leased premises under a standard lease?","a":["Obtain the landlord's prior written consent","Nothing, subletting is automatically permitted","Only verbally notify the mall manager"],"c":0,"why":"Subletting to a third party generally requires the landlord's prior written approval."}},{"id":"LG033","cat":"legal","logic":false,"ru":{"q":"Чем принципиально отличается уступка прав по договору аренды (assignment) от субаренды?","a":["Новый арендатор полностью заменяет прежнего","Уступка не требует согласия арендодателя","Уступка возможна только устно"],"c":0,"why":"При уступке (assignment) права и обязанности переходят к новому лицу, которое заменяет прежнего арендатора; при субаренде первоначальный арендатор остаётся стороной договора."},"uz":{"q":"Ijara huquqlarini o'tkazish (assignment) subijaradan tub jihatdan nimasi bilan farq qiladi?","a":["Yangi ijarachi asl ijarachi o'rnini to'liq egallaydi","O'tkazish ijaraga beruvchi roziligini talab qilmaydi","O'tkazish faqat og'zaki shaklda amalga oshiriladi"],"c":0,"why":"Huquqlarni o'tkazishda yangi shaxs asl ijarachining o'rnini butunlay egallaydi, subijarada esa asl ijarachi shartnoma tomoni bo'lib qoladi."},"en":{"q":"What is the key difference between an assignment of a lease and a sublease?","a":["The new tenant fully replaces the original tenant","An assignment never requires landlord consent","An assignment can only be made verbally"],"c":0,"why":"Assignment transfers the lease so the new party steps into the original tenant's position, whereas in a sublease the original tenant remains a party to the head lease."}},{"id":"LG034","cat":"legal","logic":false,"ru":{"q":"Какой минимальный срок предварительного письменного уведомления обычно требуется для досрочного расторжения договора аренды по инициативе одной из сторон?","a":["Срок, согласованный в договоре (напр., 30-90 дней)","Уведомление не требуется вовсе","Ровно один календарный год без исключений"],"c":0,"why":"Срок уведомления о досрочном расторжении определяется договором и обычно составляет от одного до трёх месяцев."},"uz":{"q":"Shartnomani bir tomon tashabbusi bilan muddatidan oldin bekor qilish uchun odatda qanday oldindan yozma ogohlantirish muddati talab etiladi?","a":["Shartnomada aniq kelishilgan muddat (masalan, 30-90 kun)","Hech qanday ogohlantirish talab qilinmaydi","Istisnosiz aynan bir taqvim yili"],"c":0,"why":"Muddatidan oldin bekor qilish haqida ogohlantirish muddati shartnomada belgilanadi va odatda bir oydan uch oygacha bo'ladi."},"en":{"q":"What minimum prior written notice period is typically required for early termination initiated by one party?","a":["A period expressly agreed in the contract (e.g., 30-90 days)","No notice is required at all","Exactly one calendar year with no exceptions"],"c":0,"why":"The early-termination notice period is set by the contract and commonly ranges from one to three months."}},{"id":"LG035","cat":"legal","logic":false,"ru":{"q":"Что происходит с обеспечительным депозитом, если арендатор досрочно расторгает договор без установленных договором оснований и без уведомления?","a":["Депозит обычно удерживается арендодателем как компенсация","Депозит автоматически удваивается","Депозит переходит в собственность третьей стороны"],"c":0,"why":"При необоснованном одностороннем досрочном расторжении обеспечительный депозит, как правило, остаётся у арендодателя в качестве компенсации убытков."},"uz":{"q":"Agar ijarachi shartnomada ko'rsatilmagan asos va ogohlantirishsiz muddatidan oldin shartnomani bekor qilsa, ta'minot depoziti nima bo'ladi?","a":["Depozit ijaraga beruvchida kompensatsiya sifatida qoladi","Depozit avtomatik ikki barobar oshadi","Depozit uchinchi shaxs mulkiga o'tadi"],"c":0,"why":"Asossiz bir tomonlama muddatidan oldin bekor qilishda ta'minot depoziti odatda zararni qoplash sifatida ijaraga beruvchida qoladi."},"en":{"q":"What typically happens to the security deposit if the tenant terminates early without a contractual ground and without proper notice?","a":["The landlord usually retains the deposit as compensation","The deposit automatically doubles","The deposit is transferred to an unrelated third party"],"c":0,"why":"In an unjustified unilateral early termination, the landlord generally keeps the security deposit to offset resulting losses."}},{"id":"LG036","cat":"legal","logic":false,"ru":{"q":"В чём ключевое отличие банковской гарантии от обеспечительного депозита в договоре аренды?","a":["Гарантия — обязательство банка, а не средства арендатора","Банковская гарантия всегда дешевле депозита","Депозит выдаётся банком, а гарантия — арендатором"],"c":0,"why":"Банковская гарантия — это независимое обязательство банка произвести выплату, тогда как депозит — это реальные средства арендатора, переданные арендодателю."},"uz":{"q":"Ijara shartnomasida bank kafolati bilan ta'minot depozitining asosiy farqi nimada?","a":["Kafolat — bankning majburiyati, ijarachi puli emas","Bank kafolati har doim depozitdan arzon","Depozitni bank beradi, kafolatni ijarachi beradi"],"c":0,"why":"Bank kafolati — bankning mustaqil to'lov majburiyati, depozit esa ijarachining ijaraga beruvchiga topshirilgan real mablag'idir."},"en":{"q":"What is the key difference between a bank guarantee and a security deposit in a lease?","a":["A guarantee is the bank's promise to pay, not tenant cash","A bank guarantee is always cheaper than a deposit","A deposit is issued by a bank, a guarantee by the tenant"],"c":0,"why":"A bank guarantee is an independent payment undertaking by a bank, while a deposit consists of the tenant's actual funds held by the landlord."}},{"id":"LG037","cat":"legal","logic":false,"ru":{"q":"Какое преимущество банковской гарантии для арендатора по сравнению с внесением денежного депозита?","a":["Не отвлекает оборотные средства арендатора из бизнеса","Полностью освобождает арендатора от ответственности за ущерб","Гарантия не имеет срока действия"],"c":0,"why":"Банковская гарантия позволяет арендатору не замораживать собственные денежные средства, в отличие от депозита."},"uz":{"q":"Pul depozitiga nisbatan bank kafolatining ijarachi uchun afzalligi nimada?","a":["Ijarachining aylanma mablag'ini biznesdan chetlashtirmaydi","Ijarachini zarar uchun javobgarlikdan to'liq ozod qiladi","Kafolat amal qilish muddatiga ega emas"],"c":0,"why":"Bank kafolati ijarachiga o'z naqd mablag'ini muzlatib qo'ymaslik imkonini beradi, depozitdan farqli o'laroq."},"en":{"q":"What is an advantage of a bank guarantee for the tenant compared to a cash deposit?","a":["It does not tie up the tenant's working capital","It fully exempts the tenant from liability for damages","It never has an expiry date"],"c":0,"why":"A bank guarantee lets the tenant avoid freezing its own cash, unlike a cash deposit."}},{"id":"LG038","cat":"legal","logic":false,"ru":{"q":"Что такое преимущественное право на продление договора аренды (right of first refusal to renew)?","a":["Приоритет арендатора на продление на прежних условиях","Право арендодателя выселить арендатора без причины","Право арендатора не платить аренду в последний месяц"],"c":0,"why":"Такое право даёт добросовестному арендатору приоритет на продление аренды перед новыми претендентами."},"uz":{"q":"Ijara shartnomasini uzaytirishda ustuvor huquq (right of first refusal) nima?","a":["Ijarachining kelishilgan shartlarda birinchi uzaytirish huquqi","Ijaraga beruvchining ijarachini sababsiz chiqarish huquqi","Ijarachining oxirgi oy uchun to'lamaslik huquqi"],"c":0,"why":"Bu huquq vijdonan ijara to'lagan ijarachiga yangi nomzodlardan oldin ijarani uzaytirishda ustuvorlik beradi."},"en":{"q":"What is a tenant's right of first refusal to renew a lease?","a":["Priority to renew the lease on agreed terms","The landlord's right to evict the tenant without cause","The tenant's right to skip paying rent in the final month"],"c":0,"why":"This right gives a compliant tenant priority to renew the lease ahead of new prospective tenants."}},{"id":"LG039","cat":"legal","logic":false,"ru":{"q":"Что обычно должен сделать арендатор, желающий воспользоваться правом на продление договора, до истечения его срока?","a":["Направить письменное уведомление в срок по договору","Ничего не делать — продление происходит автоматически всегда","Расторгнуть текущий договор и заключить его заново с нуля"],"c":0,"why":"Право на продление, как правило, реализуется через письменное уведомление арендодателя в срок, зафиксированный в договоре."},"uz":{"q":"Shartnomani uzaytirish huquqidan foydalanmoqchi bo'lgan ijarachi muddat tugashidan oldin odatda nima qilishi kerak?","a":["Belgilangan muddatda yozma xabar yuborish","Hech narsa qilmaslik, chunki u avtomatik sodir bo'ladi","Shartnomani bekor qilib, uni noldan qayta tuzish"],"c":0,"why":"Uzaytirish huquqi odatda shartnomada belgilangan muddatda ijaraga beruvchiga yozma xabar yuborish orqali amalga oshiriladi."},"en":{"q":"What must a tenant wishing to exercise a renewal right typically do before the lease term expires?","a":["Send written notice within the contract deadline","Do nothing, as renewal always happens automatically","Terminate the contract and negotiate an entirely new one"],"c":0,"why":"A renewal right is normally exercised by giving the landlord written notice within the deadline specified in the contract."}},{"id":"LG040","cat":"legal","logic":false,"ru":{"q":"Что означает автоматическая пролонгация (тацитное возобновление) договора аренды?","a":["Договор продолжается на тех же условиях без возражений сторон","Арендная ставка автоматически удваивается","Договор прекращается автоматически без права продления"],"c":0,"why":"Условие об автопролонгации означает, что при отсутствии уведомления об обратном договор продолжает действовать на прежних условиях."},"uz":{"q":"Ijara shartnomasining avtomatik uzaytirilishi (tatsit uzaytirish) nimani anglatadi?","a":["E'tiroz bo'lmasa, shartnoma o'sha shartlarda davom etadi","Ijara stavkasi avtomatik ikki barobar oshadi","Shartnoma uzaytirish huquqisiz avtomatik tugaydi"],"c":0,"why":"Avtomatik uzaytirish sharti — bildirishnoma bo'lmasa, shartnoma avvalgi shartlarda davom etishini anglatadi."},"en":{"q":"What does automatic renewal (tacit extension) of a lease mean?","a":["The lease continues on the same terms absent objection","The rental rate automatically doubles","The lease automatically ends with no possibility of renewal"],"c":0,"why":"An automatic renewal clause means the contract continues on prior terms absent a notice to the contrary."}},{"id":"LG041","cat":"legal","logic":false,"ru":{"q":"Какой способ разрешения споров чаще всего указывается первым шагом в разделе договора аренды о спорах?","a":["Переговоры до обращения в суд или арбитраж","Немедленное обращение в арбитраж без переговоров","Расторжение договора без объяснений"],"c":0,"why":"Стандартная договорная практика предусматривает обязательный досудебный (претензионный) порядок урегулирования спора."},"uz":{"q":"Ijara shartnomasining nizolarni hal qilish bo'limida odatda birinchi bosqich sifatida qaysi usul ko'rsatiladi?","a":["Sud yoki arbitrajgacha muzokaralar","Muzokarasiz darhol arbitrajga murojaat qilish","Tushuntirishsiz shartnomani bekor qilish"],"c":0,"why":"Standart shartnoma amaliyoti nizoni sudgacha (da'vo) tartibda hal qilishni majburiy bosqich sifatida belgilaydi."},"en":{"q":"What dispute-resolution step is typically listed first in a lease's dispute clause?","a":["Negotiation before court or arbitration","Immediate recourse to arbitration, no negotiation","Termination of the contract without explanation"],"c":0,"why":"Standard contract practice requires a mandatory pre-litigation negotiation or claims stage before formal proceedings."}},{"id":"LG042","cat":"legal","logic":false,"ru":{"q":"Зачем в договоре аренды указывают применимое право и место рассмотрения споров (например, суд Узбекистана)?","a":["Заранее определить юрисдикцию и снизить неопределённость","Чтобы полностью исключить возможность любых споров","Чтобы автоматически освободить арендатора от уплаты аренды"],"c":0,"why":"Определение применимого права и подсудности заранее устраняет неопределённость и споры о том, где и по каким нормам разрешать конфликт."},"uz":{"q":"Ijara shartnomasida qo'llaniladigan huquq va nizolarni ko'rib chiqish joyi (masalan, O'zbekiston sudi) nima uchun ko'rsatiladi?","a":["Yurisdiktsiyani oldindan aniqlash uchun","Har qanday nizo ehtimolini butunlay istisno qilish uchun","Ijarachini ijara to'lashdan avtomatik ozod qilish uchun"],"c":0,"why":"Qo'llaniladigan huquq va sudlanishni oldindan belgilash nizo yuzaga kelganda qayerda va qaysi qoidalar bo'yicha hal qilinishi haqidagi noaniqlikni yo'qotadi."},"en":{"q":"Why does a lease specify governing law and the forum for disputes (e.g., courts of Uzbekistan)?","a":["To fix jurisdiction and reduce uncertainty in advance","To completely eliminate any possibility of disputes","To automatically exempt the tenant from paying rent"],"c":0,"why":"Fixing governing law and jurisdiction in advance removes uncertainty over where and under what rules a dispute will be resolved."}},{"id":"LG043","cat":"legal","logic":false,"ru":{"q":"Что обычно защищает пункт о конфиденциальности в договоре аренды между арендатором и ТРЦ?","a":["Коммерческие условия и данные о товарообороте","Право арендатора не платить коммунальные услуги","Обязанность публиковать все ставки аренды"],"c":0,"why":"Пункт о конфиденциальности защищает чувствительную коммерческую информацию (ставки, товарооборот, условия) от раскрытия третьим лицам."},"uz":{"q":"Ijarachi va TRC o'rtasidagi shartnomadagi maxfiylik bandi odatda nimani himoya qiladi?","a":["Tijorat shartlari va savdo aylanmasi ma'lumotlarini","Ijarachining kommunal xizmatlarni to'lamaslik huquqini","Barcha stavkalarni ommaga e'lon qilish majburiyatini"],"c":0,"why":"Maxfiylik bandi nozik tijorat ma'lumotlarini (stavkalar, aylanma, shartlar) uchinchi shaxslarga oshkor bo'lishidan himoya qiladi."},"en":{"q":"What does a confidentiality clause in a mall lease typically protect?","a":["Commercial terms and turnover data","The tenant's right to avoid paying utility charges","The obligation to publish all rental rates publicly"],"c":0,"why":"A confidentiality clause shields sensitive commercial information (rates, turnover, terms) from disclosure to outside parties."}},{"id":"LG044","cat":"legal","logic":false,"ru":{"q":"Какое типичное исключение предусматривается в пункте о конфиденциальности договора аренды?","a":["Раскрытие по законному требованию госорганов","Разглашение условий конкурентам без ограничений","Публикация условий в соцсетях арендатора"],"c":0,"why":"Стандартное исключение из конфиденциальности — обязательное раскрытие информации по требованию суда, налоговых или иных уполномоченных органов."},"uz":{"q":"Ijara shartnomasidagi maxfiylik bandida odatda qanday istisno nazarda tutiladi?","a":["Davlat organlarining qonuniy talabiga ko'ra oshkor qilish","Shartlarni raqobatchilarga cheklovsiz oshkor qilish","Shartlarni ijtimoiy tarmoqlarda e'lon qilish"],"c":0,"why":"Maxfiylikning odatiy istisnosi — sud, soliq yoki boshqa vakolatli organlarning qonuniy talabiga binoan ma'lumot berish majburiyatidir."},"en":{"q":"What typical exception applies to a lease confidentiality clause?","a":["Disclosure required by lawful government request","Freely sharing all terms with competitors","Publishing the terms on the tenant's social media"],"c":0,"why":"A standard carve-out from confidentiality is mandatory disclosure required by courts, tax authorities, or other competent bodies."}},{"id":"LG045","cat":"legal","logic":false,"ru":{"q":"Какой вид страхования чаще всего требуют от арендатора магазина в ТРЦ по договору аренды?","a":["Страхование ответственности и имущества/товара","Личное медицинское страхование сотрудников арендодателя","Страхование автотранспорта посетителей ТРЦ"],"c":0,"why":"Договоры аренды в ТРЦ обычно требуют страхование гражданской ответственности и имущества (товарных остатков, оборудования) арендатора."},"uz":{"q":"TRCdagi do'kon ijarachisidan shartnoma bo'yicha ko'pincha qanday sug'urta turi talab qilinadi?","a":["Javobgarlik va mulk/tovar sug'urtasi","Ijaraga beruvchi xodimlarining tibbiy sug'urtasi","TRC tashrif buyuruvchilari avtotransportining sug'urtasi"],"c":0,"why":"TRCdagi ijara shartnomalari odatda fuqarolik javobgarligi va ijarachi mulki (tovar qoldig'i, jihozlar) sug'urtasini talab qiladi."},"en":{"q":"What type of insurance is a mall store tenant most commonly required to carry under the lease?","a":["Third-party liability insurance and property/stock insurance","Personal health insurance for the landlord's staff","Motor vehicle insurance for mall visitors"],"c":0,"why":"Mall leases typically require the tenant to carry general liability insurance and property insurance covering stock and equipment."}},{"id":"LG046","cat":"legal","logic":false,"ru":{"q":"Почему арендодатель ТРЦ обычно требует указать себя выгодоприобретателем (доп. застрахованным лицом) в страховом полисе арендатора?","a":["Чтобы иметь прямое возмещение при ущербе общему имуществу","Чтобы полностью снять с себя обязанность страховать здание","Чтобы арендатор мог не платить страховую премию"],"c":0,"why":"Указание арендодателя как дополнительного застрахованного лица позволяет ему получать защиту и возмещение при случаях, затрагивающих общие зоны или конструкции здания."},"uz":{"q":"TRC ijaraga beruvchisi nima uchun odatda ijarachining sug'urta polisida o'zini qo'shimcha sug'urtalangan shaxs sifatida ko'rsatishni talab qiladi?","a":["Umumiy mulk zararida to'g'ridan-to'g'ri qoplama olish uchun","Binoni sug'urtalash majburiyatidan butunlay ozod bo'lish uchun","Ijarachi sug'urta mukofotini to'lamasligi uchun"],"c":0,"why":"Ijaraga beruvchini qo'shimcha sug'urtalangan shaxs sifatida ko'rsatish umumiy zonalar yoki bino konstruksiyasiga ta'sir qiluvchi hodisalarda unga himoya va qoplama olish imkonini beradi."},"en":{"q":"Why does a mall landlord commonly require being named as an additional insured on the tenant's insurance policy?","a":["To have direct recourse for damage to shared property","To fully eliminate its own obligation to insure the building","So the tenant can avoid paying the insurance premium"],"c":0,"why":"Naming the landlord as additional insured gives it protection and recourse for incidents affecting common areas or the building structure."}},{"id":"LG047","cat":"legal","logic":false,"ru":{"q":"Что арендатор обычно обязан получить перед началом строительно-отделочных работ (fit-out) в своём помещении?","a":["Согласованный проект и разрешение управляющей компании","Ничего, работы можно начинать без согласования","Только устное разрешение охраны ТРЦ"],"c":0,"why":"Перед фит-аутом арендатор обязан согласовать проект отделки с управляющей компанией и получить письменное разрешение на производство работ."},"uz":{"q":"Ijarachi o'z maydonida ta'mirlash-jihozlash (fit-out) ishlarini boshlashdan oldin odatda nimani olishi kerak?","a":["Kelishilgan loyiha va boshqaruv kompaniyasi ruxsati","Hech narsa, ishlarni kelishuvsiz boshlash mumkin","Faqat TRC qo'riqchisining og'zaki ruxsati"],"c":0,"why":"Fit-out ishlaridan oldin ijarachi bezash loyihasini boshqaruv kompaniyasi bilan kelishib, ishlarni bajarish uchun yozma ruxsatnoma olishi shart."},"en":{"q":"What must a tenant typically obtain before starting fit-out/construction works in its unit?","a":["An approved design plan and management company permit","Nothing, works can begin without any approval","Only verbal permission from mall security"],"c":0,"why":"Before fit-out, the tenant must have its design plan approved by the management company and secure written permission to carry out works."}},{"id":"LG048","cat":"legal","logic":false,"ru":{"q":"Почему в договоре аренды или регламенте фит-аута ограничивают виды работ, требующих изменения несущих конструкций?","a":["Угроза безопасности здания, нужно согласование инженера","Потому что несущие конструкции нельзя показывать посетителям","Потому что это увеличивает арендную ставку автоматически"],"c":0,"why":"Изменения несущих конструкций могут нарушить целостность и безопасность всего здания, поэтому требуют отдельного технического согласования."},"uz":{"q":"Nima uchun ijara shartnomasi yoki fit-out reglamentida yuk ko'taruvchi konstruksiyalarni o'zgartiruvchi ishlar cheklanadi?","a":["Bino xavfsizligiga tahdid, muhandis kelishuvi kerak","Konstruksiyalarni tashrif buyuruvchilarga ko'rsatib bo'lmaydi","Bu ijara stavkasini avtomatik oshiradi"],"c":0,"why":"Yuk ko'taruvchi konstruksiyalardagi o'zgarishlar butun binoning yaxlitligi va xavfsizligini buzishi mumkin, shu sabab alohida texnik kelishuvni talab qiladi."},"en":{"q":"Why do lease agreements or fit-out guidelines restrict works that alter load-bearing structures?","a":["It threatens building safety and needs engineer approval","Because load-bearing structures cannot be shown to visitors","Because it automatically increases the rental rate"],"c":0,"why":"Alterations to load-bearing elements can compromise the structural integrity and safety of the whole building, requiring separate technical approval."}},{"id":"LG049","cat":"legal","logic":false,"ru":{"q":"Что обычно должен предоставить арендатор управляющей компании до допуска подрядчиков на объект для фит-аута?","a":["Документы подрядчика и график производства работ","Только копию своего паспорта","Ничего, достаточно устной договорённости с охраной"],"c":0,"why":"Управляющая компания обычно требует пакет документов на подрядчика (допуски СРО/лицензии, страхование) и согласованный график работ для обеспечения безопасности объекта."},"uz":{"q":"Fit-out uchun pudratchilarni ob'ektga kiritishdan oldin ijarachi boshqaruv kompaniyasiga odatda nima taqdim etishi kerak?","a":["Pudratchi hujjatlari va ishlar jadvali","Faqat o'z pasporti nusxasi","Hech narsa, qo'riqchi bilan og'zaki kelishuv yetarli"],"c":0,"why":"Boshqaruv kompaniyasi ob'ekt xavfsizligini ta'minlash uchun pudratchining hujjatlari (litsenziya/ruxsatnomalar, sug'urta) va kelishilgan ish jadvalini talab qiladi."},"en":{"q":"What must a tenant typically submit to the management company before contractors are allowed on-site for fit-out?","a":["Contractor documentation and a works schedule","Only a copy of the tenant's passport","Nothing, a verbal arrangement with security is enough"],"c":0,"why":"The management company usually requires contractor credentials (licenses/permits, insurance) and an approved works schedule to ensure site safety."}},{"id":"LG050","cat":"legal","logic":false,"ru":{"q":"Что из перечисленного является существенным условием договора аренды, без согласования которого договор может считаться незаключённым?","a":["Точное описание объекта аренды (адрес, площадь)","Цвет фирменной вывески арендатора","Название рекламного агентства арендатора"],"c":0,"why":"Предмет договора — точное описание арендуемого объекта — является существенным условием, без согласования которого договор аренды не считается заключённым."},"uz":{"q":"Quyidagilardan qaysi biri ijara shartnomasining muhim shartiga kiradi, uni kelishmasdan shartnoma tuzilgan hisoblanmaydi?","a":["Ijara ob'ektining aniq ta'rifi (manzil, maydon)","Ijarachining firma lavhasi rangi","Ijarachining reklama agentligi nomi"],"c":0,"why":"Shartnoma predmeti — ijaraga beriladigan ob'ektning aniq tavsifi — muhim shart bo'lib, uni kelishmasdan shartnoma tuzilgan hisoblanmaydi."},"en":{"q":"Which of the following is a material term of a lease, without which the contract may be deemed not concluded?","a":["Precise description of the leased object (address, area)","The color of the tenant's storefront signage","The name of the tenant's advertising agency"],"c":0,"why":"The lease subject matter — a precise description of the leased premises — is a material term without which the contract is not considered validly formed."}},{"id":"LS001","cat":"leasing","logic":false,"ru":{"q":"Чем GLA отличается от GBA в торговом центре?","a":["GLA — арендопригодная площадь, GBA — общая площадь здания","GLA — площадь парковки, GBA — площадь магазинов","GLA и GBA — синонимы одного показателя"],"c":0,"why":"GLA (Gross Leasable Area) учитывает только сдаваемые в аренду площади, а GBA (Gross Building Area) — всё здание, включая технические и общие зоны."},"uz":{"q":"GLA va GBA ko'rsatkichlari savdo markazida nimasi bilan farqlanadi?","a":["GLA — ijaraga beriladigan maydon, GBA — binoning umumiy maydoni","GLA — avtoturargoh maydoni, GBA — do'konlar maydoni","GLA va GBA bir xil ko'rsatkich"],"c":0,"why":"GLA (Gross Leasable Area) faqat ijaraga beriladigan maydonni, GBA (Gross Building Area) esa texnik va umumiy zonalar bilan birga butun binoni qamrab oladi."},"en":{"q":"What is the key difference between GLA and GBA in a shopping mall?","a":["GLA is leasable area; GBA is the building's total area","GLA is parking area; GBA is shop area only","GLA and GBA are the same metric"],"c":0,"why":"GLA (Gross Leasable Area) counts only leasable space, while GBA (Gross Building Area) covers the entire building including common and technical zones."}},{"id":"LS002","cat":"leasing","logic":false,"ru":{"q":"Что означает ставка аренды, выраженная в $/м² в месяц?","a":["Стоимость аренды одного квадратного метра площади за месяц","Общая сумма аренды за весь срок договора","Стоимость коммунальных услуг на квадратный метр"],"c":0,"why":"Ставка $/м²/месяц показывает, сколько арендатор платит за один квадратный метр арендуемой площади в месяц."},"uz":{"q":"Ijara stavkasi $/m² oyiga deb ko'rsatilganda bu nimani anglatadi?","a":["Bir kvadrat metr maydon uchun oylik ijara narxi","Shartnoma muddati davomidagi umumiy ijara summasi","Bir kvadrat metrga to'g'ri keladigan kommunal xarajat"],"c":0,"why":"$/m²/oy stavkasi ijarachi bir oyda bir kvadrat metr maydon uchun qancha to'lashini ko'rsatadi."},"en":{"q":"What does a rent rate quoted as $/m² per month represent?","a":["The monthly cost of renting one square meter of space","The total rent due over the entire lease term","The utility cost per square meter"],"c":0,"why":"The $/m²/month rate expresses how much a tenant pays monthly for each square meter of leased area."}},{"id":"LS003","cat":"leasing","logic":false,"ru":{"q":"Какова основная цель обеспечительного депозита (security deposit) в договоре аренды?","a":["Покрыть убытки арендодателя при неисполнении обязательств","Заменить собой ежемесячный арендный платеж","Оплатить государственную регистрацию договора"],"c":0,"why":"Депозит служит финансовой гарантией арендодателю на случай неплатежей или порчи имущества арендатором."},"uz":{"q":"Ijara shartnomasidagi ta'minot depoziti (security deposit) ning asosiy maqsadi nima?","a":["Ijarachi majburiyatlarini bajarmasa, ijaraga beruvchi zararini qoplash","Oylik ijara to'lovining o'rnini bosish","Shartnomani davlat ro'yxatidan o'tkazish uchun to'lov"],"c":0,"why":"Depozit ijarachi to'lovni amalga oshirmasa yoki mulkka zarar yetkazsa, ijaraga beruvchi uchun moliyaviy kafolat vazifasini bajaradi."},"en":{"q":"What is the primary purpose of a security deposit in a lease agreement?","a":["To cover the landlord's potential losses if the tenant defaults","To replace the monthly rent payment","To pay for government registration of the contract"],"c":0,"why":"The deposit acts as financial protection for the landlord against tenant default or property damage."}},{"id":"LS004","cat":"leasing","logic":false,"ru":{"q":"Что представляет собой пункт об эскалации арендной платы (rent escalation clause)?","a":["Условие о плановом повышении ставки аренды через определенные периоды","Право арендатора досрочно расторгнуть договор","Условие о снижении ставки при низкой посещаемости"],"c":0,"why":"Эскалационная оговорка фиксирует заранее согласованный рост ставки аренды со временем, например ежегодно на 5%."},"uz":{"q":"Ijara to'lovini eskalatsiya qilish bandi (rent escalation clause) nimani nazarda tutadi?","a":["Belgilangan davrlarda ijara stavkasini rejali oshirish sharti","Ijarachining shartnomani muddatidan oldin bekor qilish huquqi","Tashrif kam bo'lsa stavkani pasaytirish sharti"],"c":0,"why":"Eskalatsiya bandi vaqt o'tishi bilan ijara stavkasining oldindan kelishilgan tartibda, masalan yiliga 5% ga oshishini belgilaydi."},"en":{"q":"What does a rent escalation clause typically define?","a":["A scheduled, pre-agreed increase in the rent rate over time","The tenant's right to terminate the lease early","A reduction in rent if foot traffic is low"],"c":0,"why":"An escalation clause sets out a predetermined rent increase over time, such as an annual 5% step-up."}},{"id":"LS005","cat":"leasing","logic":false,"ru":{"q":"Что дает арендатору break clause (пункт о досрочном расторжении)?","a":["Право прекратить договор аренды раньше срока при выполнении условий","Обязанность продлить договор автоматически","Право требовать снижения ставки аренды"],"c":0,"why":"Break clause позволяет одной из сторон (чаще арендатору) выйти из договора до истечения его срока при соблюдении оговоренных условий."},"uz":{"q":"Break clause (muddatidan oldin bekor qilish bandi) ijarachiga nima huquq beradi?","a":["Belgilangan shartlar bajarilganda shartnomani muddatidan oldin tugatish","Shartnomani avtomatik ravishda uzaytirish majburiyati","Ijara stavkasini pasaytirishni talab qilish huquqi"],"c":0,"why":"Break clause tomonlardan biriga (ko'pincha ijarachiga) kelishilgan shartlar asosida shartnoma muddati tugashidan oldin undan chiqish imkonini beradi."},"en":{"q":"What does a break clause give the tenant?","a":["The right to terminate the lease early if conditions are met","An obligation to automatically renew the lease","The right to demand a lower rent rate"],"c":0,"why":"A break clause allows a party, typically the tenant, to exit the lease before its natural expiry once agreed conditions are satisfied."}},{"id":"LS006","cat":"leasing","logic":false,"ru":{"q":"Какой срок аренды типичен для якорного арендатора (anchor tenant) в ТРЦ?","a":["Долгосрочный, обычно 10 лет и более","Краткосрочный, 3-6 месяцев","Только на период проведения промо-акции"],"c":0,"why":"Якорные арендаторы подписывают долгосрочные договоры, поскольку обеспечивают стабильный трафик и являются якорем проекта."},"uz":{"q":"SMda asosiy (langar) ijarachi uchun odatiy ijara muddati qancha bo'ladi?","a":["Uzoq muddatli, odatda 10 yil va undan ortiq","Qisqa muddatli, 3-6 oy","Faqat aksiya davri uchun"],"c":0,"why":"Langar ijarachilar loyihaga barqaror tashrif oqimini ta'minlagani uchun odatda uzoq muddatli shartnoma tuzadi."},"en":{"q":"What is a typical lease term for an anchor tenant in a shopping mall?","a":["Long-term, usually 10 years or more","Short-term, 3-6 months","Only for the duration of a promotional campaign"],"c":0,"why":"Anchor tenants sign long-term leases because they anchor the project and drive stable footfall."}},{"id":"LS007","cat":"leasing","logic":false,"ru":{"q":"Для чего арендатору предоставляется fit-out период?","a":["Для отделки и подготовки помещения перед открытием магазина","Для бесплатного проживания сотрудников арендатора","Для продления гарантийного срока оборудования"],"c":0,"why":"Fit-out период — это время, в течение которого арендатор обустраивает помещение под свой бренд до начала торговли, часто с льготной или нулевой арендной ставкой."},"uz":{"q":"Ijarachiga fit-out (jihozlash) davri nima uchun beriladi?","a":["Do'kon ochilishidan oldin ta'mirlash va joyni tayyorlash uchun","Ijarachi xodimlari uchun bepul turar joy sifatida","Jihozlarning kafolat muddatini uzaytirish uchun"],"c":0,"why":"Fit-out davri — bu ijarachi savdoni boshlashdan oldin joyni o'z brendiga moslab tayyorlaydigan vaqt bo'lib, ko'pincha imtiyozli yoki nol stavka bilan beriladi."},"en":{"q":"What is the purpose of the fit-out period granted to a tenant?","a":["To allow build-out and preparation of the unit before store opening","To provide free housing for the tenant's staff","To extend the warranty period on equipment"],"c":0,"why":"The fit-out period is the time a tenant uses to build out the space to its brand standard before opening, often at a reduced or zero rent."}},{"id":"LS008","cat":"leasing","logic":false,"ru":{"q":"Какова роль LOI (Letter of Intent) / term sheet в процессе аренды?","a":["Фиксирует ключевые условия до подписания полного договора","Является окончательным юридически обязывающим договором аренды","Заменяет собой акт приема-передачи помещения"],"c":0,"why":"LOI/term sheet — предварительный документ, где стороны согласовывают ключевые условия (ставку, площадь, срок) до заключения полноценного договора."},"uz":{"q":"Ijara jarayonida LOI (Letter of Intent) / term sheet qanday rol o'ynaydi?","a":["To'liq shartnomadan oldin asosiy shartlarni belgilaydi","Yakuniy, huquqiy jihatdan bog'lovchi ijara shartnomasi hisoblanadi","Xonani topshirish-qabul qilish aktining o'rnini bosadi"],"c":0,"why":"LOI/term sheet — tomonlar to'liq shartnoma tuzishdan oldin asosiy shartlarni (stavka, maydon, muddat) kelishadigan dastlabki hujjat."},"en":{"q":"What is the role of a Letter of Intent (LOI) / term sheet in the leasing process?","a":["It sets out key commercial terms before the full lease is signed","It is the final legally binding lease contract","It replaces the unit handover certificate"],"c":0,"why":"An LOI/term sheet is a preliminary document where parties agree on key terms such as rate, area, and term before executing the full lease."}},{"id":"LS009","cat":"leasing","logic":false,"ru":{"q":"Что означает субординация (subordination) в контексте договора аренды?","a":["Права арендатора подчинены правам залогодержателя здания","Арендатор автоматически становится совладельцем здания","Арендная ставка привязывается к курсу иностранной валюты"],"c":0,"why":"Subordination clause устанавливает, что права арендатора по договору аренды уступают по приоритету правам банка-залогодержателя объекта."},"uz":{"q":"Ijara shartnomasi kontekstida subordinatsiya (subordination) nimani anglatadi?","a":["Ijarachi huquqlari binoning garov ushlovchisi huquqlariga bo'ysunadi","Ijarachi avtomatik ravishda binoning hammuallifiga aylanishi","Ijara stavkasining chet el valyutasiga bog'lanishi"],"c":0,"why":"Subordinatsiya bandi ijarachining shartnoma bo'yicha huquqlari binoni garovga oluvchi bank huquqlaridan ustuvorligi past ekanligini belgilaydi."},"en":{"q":"What does a subordination clause establish in a lease agreement?","a":["The tenant's lease rights rank below the mortgage lender's rights","That the tenant automatically becomes a co-owner of the building","That the rent is pegged to a foreign currency exchange rate"],"c":0,"why":"A subordination clause makes the tenant's lease interest subordinate in priority to the landlord's mortgage lender or lienholder."}},{"id":"LS010","cat":"leasing","logic":false,"ru":{"q":"Что регулирует co-tenancy clause (пункт о со-арендаторах) в договоре крупного арендатора?","a":["Право снизить платеж или выйти при уходе ключевых арендаторов","Порядок совместного использования склада между арендаторами","Право арендатора выбирать соседние по этажу магазины"],"c":0,"why":"Co-tenancy clause защищает арендатора, если общая заполняемость ТРЦ или присутствие якорных арендаторов падает ниже согласованного уровня."},"uz":{"q":"Yirik ijarachi shartnomasidagi co-tenancy (hamijarachilik) bandi nimani tartibga soladi?","a":["Asosiy ijarachilar chiqsa to'lovni kamaytirish yoki chiqish huquqini","Ijarachilar o'rtasida ombordan birgalikda foydalanish tartibini","Ijarachining qavatdagi qo'shni do'konlarni tanlash huquqini"],"c":0,"why":"Co-tenancy bandi savdo markazidagi umumiy to'ldirilganlik yoki langar ijarachilar mavjudligi kelishilgan darajadan pasaysa, ijarachini himoya qiladi."},"en":{"q":"What does a co-tenancy clause typically regulate for a major tenant?","a":["Conditions letting the tenant reduce rent or exit if other key tenants leave","How tenants share a common warehouse facility","The tenant's right to choose neighboring stores on its floor"],"c":0,"why":"A co-tenancy clause protects a tenant if overall mall occupancy or anchor tenant presence falls below an agreed threshold."}},{"id":"LS011","cat":"leasing","logic":false,"ru":{"q":"Что обеспечивает пункт об эксклюзивности (exclusivity clause) арендатору?","a":["Гарантию отсутствия прямого конкурента в том же ТРЦ","Право занимать любое свободное помещение в здании","Освобождение от уплаты коммунальных платежей"],"c":0,"why":"Exclusivity clause запрещает арендодателю сдавать площади конкурентам арендатора в пределах того же торгового центра."},"uz":{"q":"Eksklyuzivlik bandi (exclusivity clause) ijarachiga nimani kafolatlaydi?","a":["O'sha SMda to'g'ridan-to'g'ri raqib bo'lmasligini","Binodagi istalgan bo'sh joyni egallash huquqini","Kommunal to'lovlardan ozod etilishini"],"c":0,"why":"Eksklyuzivlik bandi ijaraga beruvchiga o'sha savdo markazi ichida ijarachining raqibiga joy berishni taqiqlaydi."},"en":{"q":"What does an exclusivity clause guarantee a tenant?","a":["That the landlord will not lease space to a direct competitor in the same mall","The right to occupy any vacant unit in the building","Exemption from paying utility charges"],"c":0,"why":"An exclusivity clause prevents the landlord from leasing space within the same mall to the tenant's direct competitors."}},{"id":"LS012","cat":"leasing","logic":false,"ru":{"q":"Когда обычно применяется kick-out clause (пункт о праве выхода по показателям продаж)?","a":["Когда продажи не достигают оговоренного порога","Когда арендодатель вправе выселить арендатора за неуплату немедленно","Когда договор автоматически продлевается при высоких продажах"],"c":0,"why":"Kick-out clause дает арендатору право прекратить аренду, если фактические продажи в течение установленного периода не достигают порогового значения."},"uz":{"q":"Kick-out bandi (savdo ko'rsatkichi bo'yicha chiqish huquqi) odatda qachon qo'llaniladi?","a":["Savdo kelishilgan chegaraga yetmaganda","Ijaraga beruvchi to'lov qilmagan ijarachini darhol chiqarib yuborganda","Yuqori savdo bo'lganda shartnoma avtomatik uzaytirilganda"],"c":0,"why":"Kick-out bandi belgilangan davrda haqiqiy savdo hajmi chegaraviy ko'rsatkichga yetmasa, ijarachiga shartnomani tugatish huquqini beradi."},"en":{"q":"When does a kick-out clause typically apply?","a":["When the tenant may terminate the lease if agreed sales targets are not met","When the landlord may evict a tenant instantly for non-payment","When the lease automatically renews due to high sales"],"c":0,"why":"A kick-out clause lets a tenant end the lease if actual sales over a defined period fall short of an agreed threshold."}},{"id":"LS013","cat":"leasing","logic":false,"ru":{"q":"Что дает арендатору право первого отказа (right of first refusal)?","a":["Приоритет на аренду соседнего помещения раньше третьих лиц","Право первым выбрать дизайн фасада здания","Право отказаться от уплаты депозита"],"c":0,"why":"Right of first refusal позволяет арендатору получить предложение об аренде свободного соседнего помещения раньше внешних претендентов."},"uz":{"q":"Birinchi bo'lib rad etish huquqi (right of first refusal) ijarachiga nima imkoniyat beradi?","a":["Qo'shni joyni uchinchi shaxslardan oldin ijaraga olish ustuvorligini","Bino fasadi dizaynini birinchi bo'lib tanlash huquqini","Depozit to'lashdan bosh tortish huquqini"],"c":0,"why":"Right of first refusal ijarachiga qo'shni bo'sh joy tashqi nomzodlarga taklif qilinishidan oldin uni ijaraga olish imkonini beradi."},"en":{"q":"What does a right of first refusal give a tenant?","a":["Priority to lease an adjacent unit before it is offered to third parties","The right to choose the building's facade design first","The right to waive payment of the security deposit"],"c":0,"why":"A right of first refusal ensures the tenant gets the first offer on an available adjacent unit before outside parties."}},{"id":"LS014","cat":"leasing","logic":false,"ru":{"q":"Что обычно включают в CAM (Common Area Maintenance) charges?","a":["Расходы на содержание, уборку и эксплуатацию общих зон ТРЦ","Полную стоимость аренды торгового помещения","Расходы на маркетинг только одного арендатора"],"c":0,"why":"CAM charges покрывают эксплуатационные расходы на общие площади — коридоры, парковки, освещение, уборку, охрану."},"uz":{"q":"CAM (Common Area Maintenance) to'lovlariga odatda nimalar kiradi?","a":["SMning umumiy zonalarini saqlash, tozalash va ekspluatatsiya qilish xarajatlari","Savdo joyining to'liq ijara qiymati","Faqat bitta ijarachining marketing xarajatlari"],"c":0,"why":"CAM to'lovlari umumiy maydonlar — yo'laklar, avtoturargoh, yoritish, tozalash va xavfsizlik uchun ekspluatatsion xarajatlarni qoplaydi."},"en":{"q":"What do CAM (Common Area Maintenance) charges typically cover?","a":["The costs of maintaining, cleaning, and operating the mall's common areas","The full rental cost of the retail unit","The marketing expenses of a single tenant only"],"c":0,"why":"CAM charges reimburse operating costs for shared spaces such as corridors, parking, lighting, cleaning, and security."}},{"id":"LS015","cat":"leasing","logic":false,"ru":{"q":"Как в Узбекистане обычно применяется НДС к арендной плате по коммерческой аренде?","a":["Начисляется дополнительно к согласованной ставке аренды","НДС включен в депозит и больше не взимается отдельно","Аренда полностью освобождена от НДС во всех случаях"],"c":0,"why":"Арендная плата, как правило, облагается НДС сверх базовой ставки, если иное прямо не предусмотрено законодательством или льготным режимом."},"uz":{"q":"O'zbekistonda tijorat ijarasida QQS odatda qanday qo'llaniladi?","a":["QQS kelishilgan ijara stavkasi ustiga belgilangan stavka bo'yicha qo'shiladi","QQS depozitga kiritilgan va alohida undirilmaydi","Ijara barcha holatlarda QQSdan to'liq ozod qilingan"],"c":0,"why":"Qonunchilikda maxsus imtiyoz nazarda tutilmagan bo'lsa, ijara to'lovi odatda asosiy stavka ustiga QQS bilan hisoblanadi."},"en":{"q":"How is VAT typically applied to commercial rent in Uzbekistan?","a":["VAT is charged in addition to the agreed rent rate at the statutory rate","VAT is bundled into the security deposit and not charged separately","Rent is fully VAT-exempt in all cases"],"c":0,"why":"Rent is generally subject to VAT on top of the base rate unless a specific legal exemption applies."}},{"id":"LS016","cat":"leasing","logic":false,"ru":{"q":"Зачем в договоры аренды в Узбекистане часто включают валютную оговорку (currency clause)?","a":["Привязать платеж в сумах к курсу доллара против девальвации","Чтобы разрешить арендатору платить в любой валюте по своему выбору","Чтобы полностью отменить необходимость платить аренду в сумах"],"c":0,"why":"Валютная оговорка фиксирует ставку в у.е./долларах, а оплата производится в сумах по курсу ЦБ на дату платежа, защищая стороны от курсовых колебаний."},"uz":{"q":"O'zbekistondagi ijara shartnomalarida valyuta bandi (currency clause) nima uchun kiritiladi?","a":["So'm to'lovini dollar kursiga bog'lab devalvatsiyadan himoyalash","Ijarachiga istalgan valyutada to'lash huquqini berish uchun","So'mda to'lash zaruratini butunlay bekor qilish uchun"],"c":0,"why":"Valyuta bandi stavkani u.e./dollarga bog'lab, kurs bo'yicha so'mda to'lash ijara daromadini mahalliy valyuta qadrsizlanishidan himoya qiladi."},"en":{"q":"Why do lease contracts in Uzbekistan often include a currency clause?","a":["To peg the local-currency payment to USD against devaluation","To let the tenant pay in any currency of its choosing","To eliminate the need to pay rent in local currency altogether"],"c":0,"why":"A currency clause fixes the rate in USD equivalent while payment is made in local currency at the central bank rate on the payment date, hedging both parties against FX swings."}},{"id":"LS017","cat":"leasing","logic":false,"ru":{"q":"Что такое индексация арендной платы (rent indexation)?","a":["Периодическая корректировка ставки по индексу инфляции","Единовременное снижение ставки в первый год аренды","Процесс присвоения помещению кадастрового номера"],"c":0,"why":"Индексация привязывает изменение ставки к внешнему показателю, например индексу потребительских цен, чтобы сохранить реальную стоимость аренды."},"uz":{"q":"Ijara to'lovini indeksatsiya qilish (rent indexation) nima?","a":["Stavkani inflyatsiya indeksiga muvofiq davriy o'zgartirish","Ijaraning birinchi yilida stavkani bir martalik pasaytirish","Xonaga kadastr raqami berish jarayoni"],"c":0,"why":"Indeksatsiya stavka o'zgarishini iste'mol narxlari indeksi kabi tashqi ko'rsatkichga bog'lab, ijaraning real qiymatini saqlab qoladi."},"en":{"q":"What is rent indexation?","a":["Periodic rate adjustment tied to an inflation index","A one-time rent reduction in the first year of the lease","The process of assigning a cadastral number to the unit"],"c":0,"why":"Indexation links rate changes to an external benchmark, such as CPI, to preserve the real value of rent over time."}},{"id":"LS018","cat":"leasing","logic":false,"ru":{"q":"Чем отличается ставка аренды 'triple net' (NNN) от 'gross' ставки?","a":["При NNN арендатор отдельно оплачивает налоги, страховку и эксплуатацию","При NNN арендодатель оплачивает все расходы, включая коммуналку арендатора","NNN и gross ставки идентичны по составу платежей"],"c":0,"why":"В структуре triple net арендатор несет дополнительные расходы (налоги, страхование, CAM) помимо базовой ставки аренды, в отличие от gross-ставки, где всё включено."},"uz":{"q":"'Triple net' (NNN) stavkasi 'gross' stavkadan nimasi bilan farq qiladi?","a":["NNN da ijarachi soliq, sug'urta va ekspluatatsiyani alohida to'laydi","NNN da ijaraga beruvchi ijarachining kommunal xarajatlarini ham o'z zimmasiga oladi","NNN va gross stavkalar to'lov tarkibi bo'yicha bir xil"],"c":0,"why":"Triple net tuzilmasida ijarachi asosiy stavkadan tashqari qo'shimcha xarajatlarni (soliq, sug'urta, CAM) to'laydi, gross stavkada esa hammasi kiritilgan bo'ladi."},"en":{"q":"How does a 'triple net' (NNN) rent rate differ from a 'gross' rate?","a":["Under NNN, the tenant separately pays taxes, insurance, and operating costs","Under NNN, the landlord covers all costs including the tenant's utilities","NNN and gross rates have identical payment structures"],"c":0,"why":"In a triple net structure the tenant bears additional costs (taxes, insurance, CAM) beyond the base rate, unlike a gross rate where everything is bundled."}},{"id":"LS019","cat":"leasing","logic":false,"ru":{"q":"Что из перечисленного корректно описывает 'percentage rent' (процент от товарооборота)?","a":["Часть арендной платы рассчитывается как процент от выручки арендатора","Арендная ставка фиксирована и не зависит от выручки","Это скидка, применяемая только к депозиту"],"c":0,"why":"Percentage rent — модель, при которой арендатор платит фиксированную базовую ставку плюс процент от товарооборота сверх определенного порога."},"uz":{"q":"Quyidagilardan qaysi biri 'percentage rent' (aylanmadan foiz) tushunchasini to'g'ri tavsiflaydi?","a":["Ijara to'lovining bir qismi ijarachi tushumidan foiz sifatida hisoblanadi","Ijara stavkasi qat'iy belgilanadi va tushumga bog'liq emas","Bu faqat depozitga qo'llaniladigan chegirma"],"c":0,"why":"Percentage rent — ijarachi asosiy stavkadan tashqari belgilangan chegaradan oshgan aylanmaning bir qismini foiz sifatida to'laydigan model."},"en":{"q":"Which statement correctly describes 'percentage rent'?","a":["Part of the rent is calculated as a percentage of the tenant's sales turnover","The rent rate is fixed and unrelated to turnover","It is a discount applied only to the security deposit"],"c":0,"why":"Percentage rent is a model where the tenant pays a base rate plus a percentage of turnover above an agreed breakpoint."}},{"id":"LS020","cat":"leasing","logic":false,"ru":{"q":"Какова цель гарантийного письма от материнской компании (parent company guarantee) в договоре аренды?","a":["Обеспечить обязательства арендатора, если он — дочерняя структура с малыми активами","Заменить собой подписание договора аренды","Снизить арендную ставку для крупных сетей"],"c":0,"why":"Гарантия материнской компании служит дополнительным обеспечением для арендодателя, когда договор подписывает локальное юрлицо с небольшим капиталом."},"uz":{"q":"Ijara shartnomasidagi bosh kompaniya kafolati (parent company guarantee) nima maqsadda beriladi?","a":["Ijarachi cheklangan aktivli sho'ba tashkilot bo'lsa, majburiyatlarni ta'minlash","Ijara shartnomasini imzolash o'rniga qo'llash uchun","Yirik tarmoqlar uchun ijara stavkasini pasaytirish uchun"],"c":0,"why":"Bosh kompaniya kafolati ijaraga beruvchi uchun qo'shimcha ta'minot bo'lib, shartnomani kapitali kam mahalliy yuridik shaxs imzolaganda foydalaniladi."},"en":{"q":"What is the purpose of a parent company guarantee in a lease agreement?","a":["To secure tenant obligations when the signer is a low-asset subsidiary","To substitute for signing the lease agreement itself","To reduce the rent rate for large retail chains"],"c":0,"why":"A parent company guarantee gives the landlord extra security when the lease is signed by a local subsidiary with limited capital."}},{"id":"LS021","cat":"leasing","logic":false,"ru":{"q":"Что описывает термин 'zoning' / mix-план арендаторов в ТРЦ?","a":["Распределение арендаторов по этажам и зонам для оптимального трафика","Юридическую процедуру регистрации договора аренды","Систему видеонаблюдения в общих зонах"],"c":0,"why":"Tenant mix / zoning определяет расположение категорий арендаторов (фуд-корт, фэшн, развлечения) для равномерного распределения потока посетителей."},"uz":{"q":"SMdagi ijarachilar 'zoning' / mix-rejasi atamasi nimani anglatadi?","a":["Ijarachilarni qavat va zonalar bo'yicha oqim uchun joylashtirish","Ijara shartnomasini ro'yxatdan o'tkazish huquqiy tartibi","Umumiy zonalardagi videokuzatuv tizimi"],"c":0,"why":"Tenant mix / zoning tashrif buyuruvchilar oqimini teng taqsimlash uchun ijarachi toifalari (fud-kort, moda, ko'ngilochar)ning joylashuvini belgilaydi."},"en":{"q":"What does the term 'zoning' / tenant mix plan describe in a mall?","a":["The placement of tenant categories across floors to optimize shopper flow","The legal procedure for registering the lease contract","The CCTV system covering common areas"],"c":0,"why":"Tenant mix / zoning arranges categories such as food court, fashion, and entertainment to distribute visitor traffic evenly across the mall."}},{"id":"LS022","cat":"leasing","logic":false,"ru":{"q":"Какой пункт договора определяет, кто несет расходы на капитальный ремонт здания?","a":["Пункт о распределении эксплуатационных и капитальных расходов","Пункт об эксклюзивности","Пункт о праве первого отказа"],"c":0,"why":"Ответственность за капитальные и текущие ремонты обычно детально прописывается отдельным разделом договора об эксплуатационных расходах."},"uz":{"q":"Shartnomaning qaysi bandi bino kapital ta'mirlash xarajatlarini kim to'lashini belgilaydi?","a":["Ekspluatatsion va kapital xarajatlarni taqsimlash bandi","Eksklyuzivlik bandi","Birinchi bo'lib rad etish huquqi bandi"],"c":0,"why":"Kapital va joriy ta'mirlash bo'yicha javobgarlik odatda shartnomaning ekspluatatsion xarajatlarga bag'ishlangan alohida bo'limida batafsil yoziladi."},"en":{"q":"Which lease clause defines who bears the cost of major building repairs?","a":["The clause allocating operating and capital expenditure responsibilities","The exclusivity clause","The right of first refusal clause"],"c":0,"why":"Responsibility for capital and routine repairs is typically detailed in a dedicated operating expense allocation clause."}},{"id":"LS023","cat":"leasing","logic":false,"ru":{"q":"Что означает 'grace period' в контексте оплаты аренды?","a":["Льготный срок после даты платежа без штрафных санкций","Период, когда аренда полностью бесплатна на весь срок договора","Срок уведомления о расторжении договора"],"c":0,"why":"Grace period — короткий дополнительный срок после даты платежа, до истечения которого пеня или штраф не начисляются."},"uz":{"q":"Ijara to'lovi kontekstida 'grace period' nimani anglatadi?","a":["To'lov sanasidan keyingi jarimasiz imtiyozli muddat","Butun shartnoma muddati davomida ijara to'liq bepul bo'ladigan davr","Shartnomani bekor qilish haqida ogohlantirish muddati"],"c":0,"why":"Grace period — to'lov sanasidan keyingi qisqa qo'shimcha muddat bo'lib, shu vaqt ichida kechikish uchun jarima yoki peniya qo'llanilmaydi."},"en":{"q":"What does a 'grace period' mean in the context of rent payment?","a":["A short window after the due date with no late penalty","A period when rent is entirely free for the whole lease term","The notice period required to terminate the lease"],"c":0,"why":"A grace period is a brief extra window after the due date during which no late fee or penalty applies."}},{"id":"LS024","cat":"leasing","logic":false,"ru":{"q":"Для чего в договоре аренды прописывается пункт о 'permitted use' (разрешенное использование)?","a":["Чтобы ограничить деятельность арендатора конкретным видом торговли","Чтобы разрешить арендатору сдавать помещение в субаренду без согласия","Чтобы установить размер обеспечительного депозита"],"c":0,"why":"Пункт о разрешенном использовании фиксирует профиль деятельности арендатора и не позволяет менять его без согласия арендодателя."},"uz":{"q":"Ijara shartnomasida 'permitted use' (ruxsat etilgan foydalanish) bandi nima uchun kiritiladi?","a":["Ijarachi faoliyatini aniq savdo yoki xizmat turi bilan cheklash uchun","Ijarachiga roziliksiz subijaraga berish huquqini berish uchun","Ta'minot depoziti miqdorini belgilash uchun"],"c":0,"why":"Ruxsat etilgan foydalanish bandi ijarachining faoliyat profilini belgilaydi va ijaraga beruvchi roziligisiz uni o'zgartirishga yo'l qo'ymaydi."},"en":{"q":"Why does a lease include a 'permitted use' clause?","a":["To restrict the tenant's activity to a specific retail category","To allow the tenant to sublease the unit without consent","To set the amount of the security deposit"],"c":0,"why":"A permitted use clause defines the tenant's business profile and prevents changing it without the landlord's consent."}},{"id":"LS025","cat":"leasing","logic":false,"ru":{"q":"Что подразумевает 'turnover report' (отчет о товарообороте), который арендатор предоставляет арендодателю?","a":["Периодическую отчетность о выручке для расчета percentage rent","Годовой финансовый аудит всей компании арендатора","Отчет о состоянии оборудования в помещении"],"c":0,"why":"Отчет о товарообороте позволяет арендодателю проверять выручку арендатора для расчета процентной части аренды и оценки эффективности точки."},"uz":{"q":"Ijarachi ijaraga beruvchiga taqdim etadigan 'turnover report' (aylanma hisoboti) nimani anglatadi?","a":["Percentage rent hisoblash uchun davriy tushum hisoboti","Ijarachi kompaniyasining yillik moliyaviy auditi","Xonadagi jihozlar holati haqida hisobot"],"c":0,"why":"Aylanma hisoboti ijaraga beruvchiga foizli ijara qismini hisoblash va do'kon samaradorligini baholash uchun ijarachi tushumini tekshirish imkonini beradi."},"en":{"q":"What does a 'turnover report' provided by the tenant to the landlord involve?","a":["Periodic revenue reporting used to calculate percentage rent","An annual financial audit of the tenant's entire company","A report on the condition of equipment in the unit"],"c":0,"why":"A turnover report lets the landlord verify tenant revenue to calculate the percentage rent component and evaluate store performance."}},{"id":"LS026","cat":"leasing","logic":false,"ru":{"q":"Что означает пункт о 'relocation' (переезд) в договоре аренды ТРЦ?","a":["Право арендодателя переместить арендатора в другое помещение того же ТРЦ","Обязанность арендатора самостоятельно найти новое помещение вне ТРЦ","Право арендатора требовать открытия второй точки бесплатно"],"c":0,"why":"Relocation clause дает арендодателю возможность реорганизовать зонирование, переместив арендатора в сопоставимое помещение с компенсацией расходов."},"uz":{"q":"SM ijara shartnomasidagi 'relocation' (ko'chirish) bandi nimani anglatadi?","a":["Ijaraga beruvchining ijarachini o'sha SM ichida boshqa joyga ko'chirish huquqi","Ijarachining SM tashqarisida mustaqil yangi joy topish majburiyati","Ijarachining bepul ikkinchi filial ochishni talab qilish huquqi"],"c":0,"why":"Relocation bandi ijaraga beruvchiga zonalashtirishni qayta tashkil etish uchun ijarachini teng qiymatdagi boshqa joyga, xarajatlarni qoplagan holda ko'chirish imkonini beradi."},"en":{"q":"What does a 'relocation' clause mean in a mall lease agreement?","a":["The landlord's right to move the tenant to another unit in the same mall","The tenant's obligation to independently find a new unit outside the mall","The tenant's right to demand a free second outlet"],"c":0,"why":"A relocation clause lets the landlord reorganize tenant zoning by moving a tenant to a comparable unit, usually compensating relocation costs."}},{"id":"LS027","cat":"leasing","logic":false,"ru":{"q":"Чем открытая ставка аренды (open market rent review) отличается от фиксированной эскалации?","a":["Ставка пересматривается по рынку на момент ревизии, а не по проценту","Открытая ставка всегда ниже фиксированной эскалации","Открытая ставка применяется только к депозиту, а не к аренде"],"c":0,"why":"При open market rent review ставка привязывается к текущим рыночным условиям на дату пересмотра, а не к заранее зафиксированному проценту роста."},"uz":{"q":"Ochiq bozor stavkasini qayta ko'rib chiqish (open market rent review) qat'iy eskalatsiyadan nimasi bilan farq qiladi?","a":["Stavka bozor ko'rsatkichlariga, oldindan belgilangan foizga emas, bog'liq","Ochiq bozor stavkasi doimo qat'iy eskalatsiyadan past bo'ladi","Ochiq bozor stavkasi faqat depozitga tegishli bo'ladi"],"c":0,"why":"Open market rent review'da stavka qayta ko'rib chiqish sanasidagi joriy bozor sharoitlariga bog'lanadi, oldindan belgilangan o'sish foiziga emas."},"en":{"q":"How does an open market rent review differ from a fixed escalation clause?","a":["The rate resets to current market conditions rather than a preset percentage","Open market review rates are always lower than fixed escalation","Open market review applies only to the deposit, not the rent"],"c":0,"why":"An open market rent review resets the rate to prevailing market conditions at the review date, rather than applying a pre-agreed fixed increase."}},{"id":"LS028","cat":"leasing","logic":false,"ru":{"q":"Что из перечисленного является характерным признаком договора аренды с 'triple net' структурой затрат для ТРЦ?","a":["Арендатор возмещает свою долю CAM, налогов и страховки сверх ставки","Все расходы, включая коммунальные и налоговые, несет только арендодатель","Ставка аренды включает в себя все возможные расходы без исключений"],"c":0,"why":"В triple net структуре арендатор несет пропорциональную долю операционных расходов ТРЦ сверх согласованной базовой ставки."},"uz":{"q":"SM uchun 'triple net' xarajat tuzilmasiga ega ijara shartnomasining o'ziga xos belgisi nima?","a":["Ijarachi asosiy stavkadan tashqari CAM, soliq va sug'urta ulushini qoplaydi","Barcha xarajatlarni, jumladan kommunal va soliqlarni faqat ijaraga beruvchi to'laydi","Ijara stavkasi barcha xarajatlarni istisnosiz o'z ichiga oladi"],"c":0,"why":"Triple net tuzilmasida ijarachi kelishilgan asosiy stavkadan tashqari SMning operatsion xarajatlaridagi mutanosib ulushini to'laydi."},"en":{"q":"Which is a defining feature of a 'triple net' cost structure in a mall lease?","a":["The tenant reimburses its share of CAM, taxes, and insurance above base rent","The landlord alone bears all costs, including utilities and taxes","The rent rate includes every possible cost with no exceptions"],"c":0,"why":"In a triple net structure, the tenant pays a proportional share of the mall's operating costs in addition to the agreed base rate."}},{"id":"LS029","cat":"leasing","logic":false,"ru":{"q":"Какова цель уведомительного срока (notice period) перед расторжением договора аренды?","a":["Дать сторонам заранее оговоренное время для подготовки к расторжению","Установить размер штрафа за досрочный съезд","Определить валюту, в которой будет выплачен депозит"],"c":0,"why":"Notice period требует заблаговременного письменного уведомления другой стороны о намерении расторгнуть договор, что дает время на поиск замены арендатора или нового помещения."},"uz":{"q":"Ijara shartnomasini bekor qilishdan oldingi ogohlantirish muddati (notice period) qanday maqsadga xizmat qiladi?","a":["Tomonlarga munosabatni tugatishga tayyorlanish uchun vaqt berish","Muddatidan oldin ko'chib ketish uchun jarima miqdorini belgilash","Depozit qaysi valyutada to'lanishini aniqlash"],"c":0,"why":"Notice period boshqa tomonni shartnomani bekor qilish niyati haqida oldindan yozma ravishda ogohlantirishni talab qiladi, bu yangi ijarachi yoki joy topishga vaqt beradi."},"en":{"q":"What is the purpose of a notice period before lease termination?","a":["To give both parties agreed advance time to prepare for ending the lease","To set the penalty amount for vacating early","To determine the currency in which the deposit will be refunded"],"c":0,"why":"A notice period requires advance written notice of intent to terminate, giving time to find a replacement tenant or new premises."}},{"id":"LS030","cat":"leasing","logic":false,"ru":{"q":"Что описывает термин 'holdover tenancy' в аренде торговых площадей?","a":["Арендатор продолжает занимать помещение после истечения срока без нового договора","Период, в течение которого арендатор не платит аренду по договоренности","Право арендатора выкупить помещение в собственность"],"c":0,"why":"Holdover tenancy возникает, когда арендатор остается в помещении после окончания срока аренды, обычно на условиях повышенной ставки до заключения нового договора."},"uz":{"q":"Savdo maydonlarini ijaraga berishda 'holdover tenancy' atamasi nimani tavsiflaydi?","a":["Ijarachi muddat tugagach ham yangi kelishuvsiz joyni band qilib turishi","Kelishuv bo'yicha ijarachi ijara to'lamaydigan davrni","Ijarachining xonani mulk sifatida sotib olish huquqini"],"c":0,"why":"Holdover tenancy ijarachi ijara muddati tugagandan so'ng ham joyni egallashda davom etganda yuzaga keladi, odatda yangi shartnoma tuzilguncha yuqori stavka bilan."},"en":{"q":"What does the term 'holdover tenancy' describe in retail leasing?","a":["A tenant continuing to occupy the unit after lease expiry without a new lease","A period when the tenant is contractually exempt from paying rent","The tenant's right to purchase the unit outright"],"c":0,"why":"Holdover tenancy occurs when a tenant remains in possession after lease expiry, typically at an increased rate until a new lease is signed."}},{"id":"LS031","cat":"leasing","logic":false,"ru":{"q":"Чем отличается состояние передачи «shell & core» от «fully-fitted» при сдаче помещения в ТРЦ?","a":["Shell&core — только базовые конструкции и инженерия, без отделки","Fully-fitted — только бетонный пол и голые стены","Оба варианта идентичны по объёму отделки"],"c":0,"why":"Shell&core предполагает только базовую конструкцию и подведённые инженерные сети, отделку арендатор делает сам."},"uz":{"q":"TRC maydonini topshirishda «shell & core» holati «fully-fitted» holatidan nimasi bilan farq qiladi?","a":["Shell&core — faqat asosiy konstruksiya va tarmoqlar, pardozsiz","Fully-fitted — faqat beton pol va yalang devorlar","Ikkala holat pardoz hajmi bo'yicha bir xil"],"c":0,"why":"Shell&core holatida faqat bino konstruksiyasi va muhandislik tarmoqlari beriladi, pardozni ijarachi o'zi bajaradi."},"en":{"q":"What distinguishes a 'shell & core' handover condition from a 'fully-fitted' one in a mall unit?","a":["Shell&core provides only base structure and MEP, no finishes","Fully-fitted means only a bare concrete floor is delivered","Both conditions include identical finish levels"],"c":0,"why":"Shell&core delivers only the base building structure and utility connections, leaving finishes to the tenant."}},{"id":"LS032","cat":"leasing","logic":false,"ru":{"q":"Какой тип арендатора обычно получает наиболее выгодную ставку $/м² благодаря своей роли генератора трафика?","a":["Якорный арендатор (anchor tenant)","Мелкий линейный арендатор (in-line)","Арендатор фуд-корта площадью 15 м²"],"c":0,"why":"Якорные арендаторы привлекают основной поток посетителей, поэтому получают сниженную ставку в обмен на трафик."},"uz":{"q":"Trafik generatori vazifasini bajarishi tufayli qaysi ijarachi turi odatda eng qulay $/m² stavkasini oladi?","a":["Asosiy ijarachi (langar-ijarachi)","Kichik chiziqli ijarachi (in-line)","15 m² fud-kort ijarachisi"],"c":0,"why":"Langar ijarachilar tashrifchilar oqimini shakllantiradi, shu sababli trafik evaziga pasaytirilgan stavka oladi."},"en":{"q":"Which tenant type typically secures the most favorable $/m² rate due to its role as a traffic generator?","a":["Anchor tenant","Small in-line tenant","A 15 m² food court kiosk operator"],"c":0,"why":"Anchors drive footfall for the whole center, so landlords offer them reduced rates in exchange for traffic."}},{"id":"LS033","cat":"leasing","logic":false,"ru":{"q":"Почему договоры с якорными арендаторами обычно заключаются на более длительный срок, чем с in-line арендаторами?","a":["Якорь требует крупных инвестиций и долгосрочной окупаемости","Якорные договоры проще расторгнуть в любой момент","Срок аренды не зависит от размера инвестиций арендатора"],"c":0,"why":"Крупные капиталовложения якоря в fit-out окупаются только при длительном сроке аренды, поэтому договоры долгосрочные."},"uz":{"q":"Nega langar ijarachilar bilan shartnomalar in-line ijarachilarga qaraganda odatda uzoqroq muddatga tuziladi?","a":["Langar katta investitsiya qiladi va uzoq muddatda qoplaydi","Langar shartnomalarini istalgan vaqtda bekor qilish oson","Ijaraga muddat ijarachi investitsiyasi hajmiga bog'liq emas"],"c":0,"why":"Langarning fit-out uchun katta xarajatlari faqat uzoq muddatli ijarada o'zini oqlaydi."},"en":{"q":"Why are anchor tenant leases usually signed for much longer terms than in-line tenant leases?","a":["Anchors make large capex investments needing long payback periods","Anchor leases are easier to terminate at any time","Lease term has no relation to a tenant's investment size"],"c":0,"why":"An anchor's heavy fit-out capex only pays back over a long lease term, justifying extended agreements."}},{"id":"LS034","cat":"leasing","logic":false,"ru":{"q":"В отличие от in-line арендаторов, якорные арендаторы часто платят аренду по какой модели?","a":["Фиксированная низкая ставка вместо процента с оборота","Только процент с оборота без фиксированной части","Ставка привязана исключительно к CAM-сборам"],"c":0,"why":"Якорям часто устанавливают низкую фиксированную ставку без или с минимальной привязкой к обороту, в отличие от in-line, где чаще применяется комбинация фикс+процент."},"uz":{"q":"In-line ijarachilardan farqli o'laroq, langar ijarachilar ko'pincha qanday model bo'yicha ijara to'laydi?","a":["Aylanma bilan bog'liq bo'lmagan past belgilangan stavka","Faqat aylanma foizi, belgilangan qismisiz","Stavka faqat CAM to'lovlariga bog'liq"],"c":0,"why":"Langarlarga ko'pincha aylanmadan deyarli mustaqil past belgilangan stavka qo'llanadi, in-line uchun esa fiks+foiz kombinatsiyasi keng tarqalgan."},"en":{"q":"Unlike in-line tenants, anchor tenants are often charged rent under which model?","a":["A low fixed rate largely independent of turnover","Turnover percentage only, with no fixed component","A rate tied exclusively to CAM charges"],"c":0,"why":"Anchors typically get a low fixed rate reflecting their traffic value, while in-line leases more often blend base rent with turnover rent."}},{"id":"LS035","cat":"leasing","logic":false,"ru":{"q":"Что из перечисленного является ключевым риском для арендодателя при передаче помещения в состоянии shell & core?","a":["Более длительный период fit-out до открытия магазина","Отсутствие необходимости согласовывать проект отделки","Гарантированное открытие магазина в день подписания"],"c":0,"why":"При shell&core арендатору требуется больше времени на отделку, что откладывает начало торговли и поступление оборотной аренды."},"uz":{"q":"Maydonni shell & core holatida topshirishda ijaraga beruvchi uchun asosiy xavf nimadan iborat?","a":["Do'kon ochilishigacha fit-out davri uzayadi","Pardoz loyihasini kelishish zarurati yo'qoladi","Shartnoma imzolangan kuni do'kon ochilishi kafolatlanadi"],"c":0,"why":"Shell&core holatida ijarachiga pardoz uchun ko'proq vaqt kerak, bu savdo boshlanishi va aylanma ijarani kechiktiradi."},"en":{"q":"What is a key risk for the landlord when handing over units in shell & core condition?","a":["A longer fit-out period delays store opening","There is no need to approve the tenant's fit-out design","Store opening on signing day is guaranteed"],"c":0,"why":"Shell&core requires tenants to complete more construction work themselves, pushing back opening and turnover rent collection."}},{"id":"LS036","cat":"leasing","logic":false,"ru":{"q":"Что обычно включает в себя состояние отделки «fully-fitted» (turn-key) при передаче торгового помещения?","a":["Готовые полы, потолок, освещение и инженерные системы","Только несущие стены и фасад здания","Только подведённое электричество без остальной отделки"],"c":0,"why":"Fully-fitted/turn-key означает, что помещение готово к работе: с чистовой отделкой, освещением и оборудованием."},"uz":{"q":"Savdo maydonini topshirishda «fully-fitted» (turn-key) holati odatda nimalarni o'z ichiga oladi?","a":["Tayyor pol, shift, yoritish va muhandislik tizimlari","Faqat yuk ko'taruvchi devorlar va bino fasadi","Faqat elektr ta'minoti, boshqa pardozsiz"],"c":0,"why":"Fully-fitted/turn-key holatda maydon to'liq tayyor: chiziq pardoz, yoritish va jihozlar bilan."},"en":{"q":"What does a 'fully-fitted' (turn-key) handover condition typically include for a retail unit?","a":["Finished floors, ceiling, lighting, and MEP systems ready","Only load-bearing walls and the building facade","Only an electrical connection with no other finishes"],"c":0,"why":"Fully-fitted/turn-key means the unit is ready to trade, with finishes, lighting, and fixtures installed."}},{"id":"LS037","cat":"leasing","logic":false,"ru":{"q":"Какая единица измерения площади используется при расчёте ставки аренды $/м² и распределении CAM-сборов между арендаторами?","a":["GLA (арендопригодная площадь)","GBA (общая строительная площадь)","Площадь паркинга здания"],"c":0,"why":"Ставки аренды и CAM распределяются пропорционально GLA — площади, которую фактически занимает и использует арендатор."},"uz":{"q":"Ijara stavkasi ($/m²) va CAM to'lovlarini ijarachilar o'rtasida taqsimlashda qaysi yuza ko'rsatkichi ishlatiladi?","a":["GLA (ijaraga yaroqli yuza)","GBA (umumiy qurilish yuzasi)","Binoning avtoturargoh yuzasi"],"c":0,"why":"Ijara stavkasi va CAM ijarachi haqiqatda egallagan GLA yuzasiga proporsional taqsimlanadi."},"en":{"q":"Which area metric is used to calculate the $/m² rent rate and to allocate CAM charges among tenants?","a":["GLA (Gross Leasable Area)","GBA (Gross Building Area)","The building's parking area"],"c":0,"why":"Rent and CAM charges are allocated pro-rata to GLA, the area a tenant actually occupies and uses."}},{"id":"LS038","cat":"leasing","logic":false,"ru":{"q":"Почему GBA превышает GLA в проекте ТРЦ?","a":["GBA включает общие зоны, техпомещения и конструктивные элементы","GLA всегда больше GBA в любом ТРЦ","GBA учитывает только площади, сдаваемые в аренду"],"c":0,"why":"GBA — это вся построенная площадь здания, включая коридоры, техпомещения и конструкции, не сдаваемые в аренду."},"uz":{"q":"TRC loyihasida nega GBA ko'rsatkichi GLA dan katta bo'ladi?","a":["GBA umumiy zonalar, texnik xonalar va konstruksiyalarni o'z ichiga oladi","Har qanday TRC da GLA doim GBA dan katta bo'ladi","GBA faqat ijaraga beriladigan maydonlarni hisobga oladi"],"c":0,"why":"GBA binoning butun qurilgan yuzasi bo'lib, ijaraga berilmaydigan yo'lak, texnik xona va konstruksiyalarni ham qamrab oladi."},"en":{"q":"Why is GBA larger than GLA in a shopping mall project?","a":["GBA includes common areas, technical rooms, and structural elements","GLA is always larger than GBA in any mall","GBA counts only the areas that are leased to tenants"],"c":0,"why":"GBA is the total constructed floor area, including corridors, plant rooms, and structure that are not leasable."}},{"id":"LS039","cat":"leasing","logic":false,"ru":{"q":"Что означает эффективность планировки ТРЦ, выражаемая как соотношение GLA к GBA?","a":["Долю здания, реально приносящую арендный доход","Долю здания, занятую парковкой","Скорость строительства объекта"],"c":0,"why":"Соотношение GLA/GBA показывает, какая часть общей площади здания фактически сдаётся в аренду и генерирует доход."},"uz":{"q":"TRC rejalashtirish samaradorligi GLA/GBA nisbati sifatida ifodalanganda bu nimani anglatadi?","a":["Binoning haqiqatda ijara daromadi keltiradigan qismini","Binoning avtoturargoh egallagan qismini","Obyekt qurilish tezligini"],"c":0,"why":"GLA/GBA nisbati binoning umumiy yuzasidan qancha qismi haqiqatda ijaraga berilib daromad keltirishini ko'rsatadi."},"en":{"q":"What does a mall's planning efficiency ratio, expressed as GLA divided by GBA, indicate?","a":["The share of the building actually generating rental income","The share of the building occupied by parking","The speed of the construction process"],"c":0,"why":"The GLA/GBA ratio shows what portion of total building area is actually leasable and income-generating."}},{"id":"LS040","cat":"leasing","logic":false,"ru":{"q":"На что чаще всего рассчитывается сумма обеспечительного депозита (security deposit) в договорах аренды ТРЦ?","a":["На 2–3 месяца базовой арендной платы","На полную сумму аренды за весь срок договора","На стоимость fit-out работ арендатора"],"c":0,"why":"Стандартная практика — депозит в размере 2–3 месячных арендных платежей как защита от неисполнения обязательств."},"uz":{"q":"TRC ijara shartnomalarida garov depoziti (security deposit) summasi ko'pincha nimaga asoslanib hisoblanadi?","a":["2–3 oylik asosiy ijara to'lovi miqdoriga","Shartnoma butun muddati uchun umumiy ijara summasiga","Ijarachining fit-out ishlari qiymatiga"],"c":0,"why":"Standart amaliyot — majburiyatlar bajarilmaganda himoya sifatida 2-3 oylik ijara to'lovi miqdorida depozit belgilash."},"en":{"q":"How is the security deposit amount most commonly calculated in mall lease contracts?","a":["Equivalent to 2-3 months of base rent","Equal to the total rent for the entire lease term","Equal to the cost of the tenant's fit-out works"],"c":0,"why":"Standard practice sets the deposit at 2-3 months' base rent as protection against tenant default."}},{"id":"LS041","cat":"leasing","logic":false,"ru":{"q":"Чем обеспечительный депозит принципиально отличается от банковской гарантии (bank guarantee) в аренде?","a":["Депозит — это денежные средства, гарантия — обязательство банка","Депозит выдаёт банк, а гарантию — сам арендатор","Оба инструмента идентичны и взаимозаменяемы юридически"],"c":0,"why":"Депозит — реальные деньги, удерживаемые арендодателем, а банковская гарантия — обязательство банка выплатить при наступлении случая."},"uz":{"q":"Ijarada garov depoziti bank kafolatnomasidan (bank guarantee) tub mohiyatan nimasi bilan farq qiladi?","a":["Depozit — pul mablag'i, kafolatnoma — bankning majburiyati","Depozitni bank, kafolatnomani esa ijarachi beradi","Ikkala vosita yuridik jihatdan bir xil va almashtiriladigan"],"c":0,"why":"Depozit ijaraga beruvchida saqlanadigan real pul, kafolatnoma esa bankning to'lov bo'yicha majburiyati."},"en":{"q":"How does a security deposit fundamentally differ from a bank guarantee in a lease structure?","a":["A deposit is actual cash held; a guarantee is the bank's obligation to pay","A deposit is issued by a bank while a guarantee is issued by the tenant","Both instruments are legally identical and interchangeable"],"c":0,"why":"A deposit is real cash held by the landlord, whereas a bank guarantee is a bank's promise to pay upon a trigger event."}},{"id":"LS042","cat":"leasing","logic":false,"ru":{"q":"В каком случае арендодатель, как правило, вправе удержать часть обеспечительного депозита при расторжении договора?","a":["При наличии задолженности арендатора по арендной плате или ущербе","Если арендатор досрочно продлил договор на новый срок","Если арендатор своевременно уведомил о продлении аренды"],"c":0,"why":"Депозит используется для покрытия задолженностей или ущерба помещению, выявленных на момент выезда арендатора."},"uz":{"q":"Shartnoma bekor qilinganda ijaraga beruvchi odatda qanday holatda depozitning bir qismini ushlab qolish huquqiga ega?","a":["Ijarachining ijara qarzi yoki maydonga yetkazilgan zarar mavjud bo'lsa","Ijarachi shartnomani muddatidan oldin yangi muddatga uzaytirsa","Ijarachi ijarani uzaytirish haqida o'z vaqtida xabar bersa"],"c":0,"why":"Depozit ijarachi ko'chib chiqqanda aniqlangan qarzlar yoki maydonga yetkazilgan zararni qoplash uchun ishlatiladi."},"en":{"q":"In which situation can a landlord typically withhold part of the security deposit upon lease termination?","a":["When the tenant has unpaid rent or has caused damage to the unit","When the tenant renewed the lease for a new term early","When the tenant gave timely notice of lease renewal"],"c":0,"why":"The deposit covers outstanding rent or damage discovered when the tenant vacates the premises."}},{"id":"LS043","cat":"leasing","logic":false,"ru":{"q":"Какая формулировка индексации арендной платы наиболее типична для долларовых договоров аренды в ТРЦ Узбекистана?","a":["Фиксированный ежегодный рост ставки на 3–5%","Индексация исключительно по курсу узбекского сума","Полный запрет любого изменения ставки за весь срок"],"c":0,"why":"На практике часто применяется фиксированный процент ежегодного роста ставки как простая и предсказуемая форма индексации."},"uz":{"q":"O'zbekiston TRC larida dollar ijara shartnomalari uchun eng odatiy indeksatsiya formulasi qaysi?","a":["Stavkani har yili 3–5% ga belgilangan tarzda oshirish","Faqat so'm kursi bo'yicha indeksatsiya qilish","Butun shartnoma muddatida stavkani o'zgartirishni butunlay taqiqlash"],"c":0,"why":"Amaliyotda oddiy va bashorat qilinadigan shakl sifatida har yili belgilangan foizga stavkani oshirish ko'p qo'llaniladi."},"en":{"q":"Which rent indexation formula is most typical for USD-denominated lease contracts in Uzbekistan malls?","a":["A fixed annual rent increase of around 3-5%","Indexation tied solely to the Uzbek som exchange rate","A complete prohibition on any rate change for the whole term"],"c":0,"why":"A fixed annual escalation percentage is commonly used in practice as a simple, predictable indexation method."}},{"id":"LS044","cat":"leasing","logic":false,"ru":{"q":"Чем эскалация арендной ставки (escalation clause) отличается от индексации по инфляционному индексу?","a":["Эскалация — заранее фиксированный процент, индексация привязана к индексу цен","Эскалация применяется только к CAM, а индексация — только к аренде","Это два названия одного и того же условия без различий"],"c":0,"why":"Эскалация задаёт фиксированный шаг роста ставки, тогда как индексация привязывает рост к внешнему индексу, например ИПЦ."},"uz":{"q":"Ijara stavkasi eskalatsiyasi (escalation clause) inflyatsiya indeksi bo'yicha indeksatsiyadan nimasi bilan farq qiladi?","a":["Eskalatsiya oldindan belgilangan foiz, indeksatsiya narx indeksiga bog'liq","Eskalatsiya faqat CAM ga, indeksatsiya faqat ijaraga tegishli","Bu ikki atama farqsiz, bir xil shartni anglatadi"],"c":0,"why":"Eskalatsiya stavka o'sishining oldindan belgilangan qadamini beradi, indeksatsiya esa o'sishni tashqi indeksga, masalan IICHga, bog'laydi."},"en":{"q":"How does a rent escalation clause differ from indexation tied to an inflation index?","a":["Escalation is a pre-set fixed percentage; indexation follows a price index","Escalation applies only to CAM while indexation applies only to base rent","They are two names for exactly the same clause with no difference"],"c":0,"why":"Escalation sets a predetermined step increase, while indexation links rent growth to an external index such as CPI."}},{"id":"LS045","cat":"leasing","logic":false,"ru":{"q":"Что из перечисленного — типичный триггер для активации co-tenancy clause в пользу in-line арендатора?","a":["Съезд ключевого якорного арендатора из ТРЦ","Повышение ставки аренды у соседнего магазина","Продление договора аренды самого арендатора"],"c":0,"why":"Co-tenancy обычно защищает арендатора при уходе якоря или падении общей заполняемости ниже порога, давая право на снижение аренды или расторжение."},"uz":{"q":"Quyidagilardan qaysi biri in-line ijarachi foydasiga co-tenancy bandini ishga tushiruvchi odatiy sabab hisoblanadi?","a":["Asosiy langar ijarachining TRC dan chiqib ketishi","Qo'shni do'konning ijara stavkasi oshishi","Ijarachining o'z shartnomasini uzaytirishi"],"c":0,"why":"Co-tenancy odatda langar chiqib ketganda yoki umumiy to'ldirilganlik chegaradan pasayganda ijarachini himoya qilib, stavkani kamaytirish yoki shartnomani bekor qilish huquqini beradi."},"en":{"q":"Which of the following is a typical trigger activating a co-tenancy clause in an in-line tenant's favor?","a":["Departure of a key anchor tenant from the mall","A rent increase at a neighboring store","The tenant's own renewal of its lease term"],"c":0,"why":"Co-tenancy clauses typically protect tenants when an anchor leaves or overall occupancy drops below a threshold, allowing rent relief or termination."}},{"id":"LS046","cat":"leasing","logic":false,"ru":{"q":"Какое условие обычно закрепляется в exclusivity clause в пользу арендатора?","a":["Запрет арендодателю сдавать площади прямым конкурентам арендатора","Обязанность арендатора не работать в других ТРЦ города","Право арендодателя произвольно менять расположение магазина"],"c":0,"why":"Exclusivity clause защищает арендатора от прямой конкуренции в том же ТРЦ, ограничивая арендодателя в сдаче площадей конкурентам."},"uz":{"q":"Exclusivity (eksklyuzivlik) bandi odatda ijarachi foydasiga qanday shartni mustahkamlaydi?","a":["Ijaraga beruvchiga ijarachining bevosita raqobatchilariga maydon berishni taqiqlash","Ijarachiga shahardagi boshqa TRC larda faoliyat yuritmaslik majburiyatini yuklash","Ijaraga beruvchiga do'kon joylashuvini istalgancha o'zgartirish huquqini berish"],"c":0,"why":"Exclusivity bandi ijarachini bir xil TRC ichida bevosita raqobatdan himoya qilib, ijaraga beruvchiga raqobatchilarga maydon berishni cheklaydi."},"en":{"q":"What does an exclusivity clause typically secure in the tenant's favor?","a":["A ban on the landlord leasing space to the tenant's direct competitors","An obligation for the tenant not to trade in other malls citywide","A landlord right to relocate the tenant's store at will"],"c":0,"why":"An exclusivity clause protects a tenant from direct competition within the same mall by restricting the landlord from leasing to rivals."}},{"id":"LS047","cat":"leasing","logic":false,"ru":{"q":"Какое условие типично для kick-out clause в договоре аренды ТРЦ?","a":["Право арендатора расторгнуть договор при недостижении оборота","Право арендодателя выселить арендатора без причины","Обязанность арендатора автоматически продлить аренду"],"c":0,"why":"Kick-out clause даёт арендатору право досрочно выйти из договора, если его продажи/оборот не достигают согласованного порога."},"uz":{"q":"TRC ijara shartnomasida kick-out bandi uchun qanday shart odatiy hisoblanadi?","a":["Aylanma ko'rsatkichiga yetmasa, ijarachining shartnomani bekor qilish huquqi","Ijaraga beruvchining sababsiz ijarachini chiqarib yuborish huquqi","Ijarachining ijarani avtomatik uzaytirish majburiyati"],"c":0,"why":"Kick-out bandi ijarachiga kelishilgan savdo/aylanma ko'rsatkichiga yetmagan taqdirda shartnomadan muddatidan oldin chiqish huquqini beradi."},"en":{"q":"What condition is typical of a kick-out clause in a mall lease?","a":["The tenant's right to terminate early if sales fail to meet a threshold","The landlord's right to evict the tenant without cause","The tenant's obligation to automatically renew the lease"],"c":0,"why":"A kick-out clause gives the tenant an early termination right if sales or turnover fall below an agreed threshold."}},{"id":"LS048","cat":"leasing","logic":false,"ru":{"q":"В чём принципиальное отличие break clause от kick-out clause?","a":["Break clause — общее право досрочного выхода любой стороны по сроку","Break clause применяется только к якорным арендаторам","Break clause привязана исключительно к финансовым показателям оборота"],"c":0,"why":"Break clause — это общее право прервать договор в определённую дату независимо от оборота, тогда как kick-out обусловлен именно недостижением показателей продаж."},"uz":{"q":"Break clause bilan kick-out clause o'rtasidagi tub farq nimada?","a":["Break clause — muayyan sanada har ikki tomon uchun umumiy erta bekor qilish huquqi","Break clause faqat langar ijarachilarga qo'llaniladi","Break clause faqat aylanma ko'rsatkichlariga bog'liq"],"c":0,"why":"Break clause aylanmadan qat'i nazar belgilangan sanada shartnomani bekor qilish umumiy huquqi, kick-out esa aynan savdo ko'rsatkichiga bog'liq."},"en":{"q":"What is the key difference between a break clause and a kick-out clause?","a":["A break clause is a general early-exit right at a set date, regardless of sales","A break clause applies only to anchor tenants","A break clause is triggered solely by turnover performance"],"c":0,"why":"A break clause allows either party to exit at a fixed date irrespective of sales, while a kick-out clause is specifically tied to underperforming turnover."}},{"id":"LS049","cat":"leasing","logic":false,"ru":{"q":"Что означает right of first refusal (RoFR), включённое в договор аренды арендатора?","a":["Приоритетное право арендатора арендовать соседнюю освободившуюся площадь","Право арендатора отказаться от уплаты аренды за первый месяц","Право арендодателя первым выбрать нового арендатора без переговоров"],"c":0,"why":"RoFR даёт действующему арендатору приоритет на аренду дополнительной площади прежде, чем она будет предложена третьим лицам."},"uz":{"q":"Ijarachi shartnomasiga kiritilgan right of first refusal (RoFR) nimani anglatadi?","a":["Bo'shagan qo'shni maydonni ijaraga olishda ijarachining ustuvor huquqi","Ijarachining birinchi oy ijara to'lovidan bosh tortish huquqi","Ijaraga beruvchining muzokarasiz yangi ijarachini birinchi tanlash huquqi"],"c":0,"why":"RoFR mavjud ijarachiga bo'shagan qo'shimcha maydon uchinchi shaxslarga taklif qilinishidan oldin ustuvor huquq beradi."},"en":{"q":"What does a right of first refusal (RoFR) clause grant to an existing tenant?","a":["Priority to lease adjoining space that becomes vacant before it's offered elsewhere","The right to skip paying rent for the first month","The landlord's right to pick a new tenant without negotiation"],"c":0,"why":"RoFR gives the incumbent tenant priority to lease newly available adjacent space before it is offered to third parties."}},{"id":"LS050","cat":"leasing","logic":false,"ru":{"q":"Что подразумевает subordination clause в контексте отношений арендатора с ипотечным кредитором арендодателя?","a":["Договор аренды признаётся подчинённым правам залогодержателя здания","Арендатор получает приоритет перед банком при обращении взыскания","Арендодатель обязан выплатить арендатору ипотеку здания"],"c":0,"why":"Subordination означает, что права арендатора по договору стоят ниже прав кредитора, обеспеченного залогом на здание."},"uz":{"q":"Subordination bandi ijarachining ijaraga beruvchi ipoteka krediteri bilan munosabatida nimani anglatadi?","a":["Ijara shartnomasi bino garovga qo'yilgan kreditor huquqlariga bo'ysunadi","Undirish yuzasidan ijarachi bankdan ustun huquqqa ega bo'ladi","Ijaraga beruvchi ijarachiga binoning ipotekasini to'lashga majbur bo'ladi"],"c":0,"why":"Subordination shartnoma bo'yicha ijarachi huquqlari bino garov bilan ta'minlangan kreditor huquqlaridan past turishini bildiradi."},"en":{"q":"What does a subordination clause mean regarding a tenant's relationship to the landlord's mortgage lender?","a":["The lease is subordinated to the rights of the lender holding a mortgage on the building","The tenant gains priority over the bank in a foreclosure","The landlord must repay the building's mortgage on the tenant's behalf"],"c":0,"why":"Subordination means the tenant's lease rights rank below the rights of the lender secured against the property."}},{"id":"LS051","cat":"leasing","logic":false,"ru":{"q":"Какой документ обычно подписывается до основного договора аренды и фиксирует ключевые коммерческие условия сделки?","a":["LOI (Letter of Intent) / term sheet","Акт приёма-передачи помещения","Дополнительное соглашение о продлении"],"c":0,"why":"LOI/term sheet фиксирует основные согласованные условия (ставка, срок, депозит) до подготовки полного договора аренды."},"uz":{"q":"Bitimning asosiy tijorat shartlarini mustahkamlab, asosiy ijara shartnomasidan oldin imzolanadigan hujjat qaysi?","a":["LOI (niyat xati) / term sheet","Maydonni qabul qilib topshirish akti","Ijarani uzaytirish bo'yicha qo'shimcha kelishuv"],"c":0,"why":"LOI/term sheet to'liq shartnoma tayyorlanishidan oldin asosiy kelishilgan shartlarni (stavka, muddat, depozit) mustahkamlaydi."},"en":{"q":"Which document is typically signed before the full lease agreement to lock in the key commercial terms of a deal?","a":["LOI (Letter of Intent) / term sheet","The premises handover acceptance certificate","A supplementary agreement on lease renewal"],"c":0,"why":"An LOI/term sheet captures agreed core terms (rate, term, deposit) before the full lease contract is drafted."}},{"id":"LS052","cat":"leasing","logic":false,"ru":{"q":"Какова основная юридическая природа LOI по сравнению с подписанным договором аренды?","a":["LOI обычно не имеет полной юридической силы контракта","LOI полностью заменяет договор аренды навсегда","LOI автоматически регистрируется как право аренды"],"c":0,"why":"LOI в большинстве случаев носит предварительный, часто необязывающий характер и не заменяет полноценный договор аренды."},"uz":{"q":"LOI ning imzolangan ijara shartnomasiga nisbatan asosiy yuridik mohiyati qanday?","a":["LOI odatda to'liq shartnoma kabi majburiy yuridik kuchga ega emas","LOI ijara shartnomasini butunlay va abadiy almashtiradi","LOI avtomatik ravishda ijara huquqi sifatida ro'yxatdan o'tadi"],"c":0,"why":"LOI ko'pincha dastlabki, ko'p hollarda majburiy bo'lmagan xususiyatga ega va to'liq ijara shartnomasini almashtirmaydi."},"en":{"q":"What is the basic legal nature of an LOI compared to a signed lease agreement?","a":["An LOI is typically not fully binding like a complete contract","An LOI permanently replaces the need for a lease agreement","An LOI is automatically registered as a lease right"],"c":0,"why":"An LOI is generally a preliminary, often non-binding document and does not substitute for the full lease agreement."}},{"id":"LS053","cat":"leasing","logic":false,"ru":{"q":"Как обычно определяется длительность fit-out периода в договоре аренды ТРЦ?","a":["Как льготный срок без арендной платы для проведения отделочных работ","Как период, в течение которого арендатор обязан платить двойную аренду","Как срок, следующий сразу после окончания гарантийного периода здания"],"c":0,"why":"Fit-out период — это согласованный срок (часто с арендными каникулами), в течение которого арендатор готовит магазин к открытию."},"uz":{"q":"TRC ijara shartnomasida fit-out davri muddati odatda qanday belgilanadi?","a":["Pardoz ishlarini bajarish uchun ijarasiz imtiyozli muddat sifatida","Ijarachi ikki baravar ijara to'lashi shart bo'lgan davr sifatida","Bino kafolat muddati tugagandan keyingi davr sifatida"],"c":0,"why":"Fit-out davri — ijarachi do'konni ochilishga tayyorlaydigan, ko'pincha ijara ta'tili bilan kelishilgan muddat."},"en":{"q":"How is the fit-out period typically defined in a mall lease agreement?","a":["As a rent-free grace period for the tenant to complete interior works","As a period during which the tenant must pay double rent","As the period immediately following the building's warranty expiry"],"c":0,"why":"The fit-out period is an agreed timeframe, often rent-free, during which the tenant prepares the store for opening."}},{"id":"LS054","cat":"leasing","logic":false,"ru":{"q":"Почему срок fit-out периода для якорного арендатора обычно значительно длиннее, чем для in-line магазина?","a":["Объём строительных и монтажных работ якоря существенно больше","Якорь никогда не проводит собственных строительных работ","Регулятор устанавливает единый срок fit-out для всех форматов"],"c":0,"why":"Якорные форматы (гипермаркет, DIY, кинотеатр) требуют значительно больше времени на монтаж оборудования и отделку, чем небольшой in-line магазин."},"uz":{"q":"Nega langar ijarachi uchun fit-out davri odatda in-line do'konnikiga qaraganda ancha uzoq bo'ladi?","a":["Langarning qurilish-montaj ishlari hajmi sezilarli darajada katta","Langar hech qachon o'z qurilish ishlarini olib bormaydi","Tartibga soluvchi barcha formatlar uchun bir xil fit-out muddatini belgilaydi"],"c":0,"why":"Langar formatlar (gipermarket, DIY, kinoteatr) kichik in-line do'konga qaraganda jihoz o'rnatish va pardozga ancha ko'p vaqt talab qiladi."},"en":{"q":"Why is the fit-out period for an anchor tenant usually much longer than for an in-line store?","a":["The anchor's construction and installation scope is significantly larger","Anchors never carry out their own construction works","Regulations mandate one uniform fit-out period for all formats"],"c":0,"why":"Anchor formats (hypermarkets, DIY, cinemas) require far more time for equipment installation and fit-out than a small in-line unit."}},{"id":"LS055","cat":"leasing","logic":false,"ru":{"q":"Что обычно покрывают CAM-сборы (common area maintenance) помимо клининга общих зон?","a":["Охрану, освещение, лифты и обслуживание инженерных систем","Персональный ремонт торгового зала арендатора","Маркетинговый бюджет только одного конкретного арендатора"],"c":0,"why":"CAM включает расходы на содержание общих зон и инфраструктуры здания: охрану, освещение, лифты, эскалаторы, инженерные системы."},"uz":{"q":"CAM (umumiy maydonlarni saqlash) to'lovlari umumiy zonalarni tozalashdan tashqari yana nimalarni qamrab oladi?","a":["Xavfsizlik, yoritish, liftlar va muhandislik tizimlarini saqlash","Ijarachining savdo zalidagi shaxsiy ta'mirlashi","Faqat bitta muayyan ijarachining marketing byudjeti"],"c":0,"why":"CAM binoning umumiy zonalari va infratuzilmasini saqlash xarajatlarini — xavfsizlik, yoritish, lift, eskalator, muhandislik tizimlarini — qamrab oladi."},"en":{"q":"Besides cleaning common areas, what else do CAM (common area maintenance) charges typically cover?","a":["Security, lighting, elevators, and building systems maintenance","The tenant's own personal shop-fit repairs","The marketing budget of one specific tenant only"],"c":0,"why":"CAM covers costs of maintaining shared infrastructure: security, lighting, elevators, escalators, and mechanical/electrical systems."}},{"id":"LS056","cat":"leasing","logic":false,"ru":{"q":"Как чаще всего распределяются CAM-сборы между арендаторами ТРЦ?","a":["Пропорционально доле GLA арендатора в общей арендопригодной площади","Равными частями независимо от размера арендуемой площади","Только на арендаторов фуд-корта, остальные освобождены"],"c":0,"why":"Наиболее распространённый подход — пропорциональное распределение CAM исходя из доли GLA каждого арендатора."},"uz":{"q":"TRC ijarachilari o'rtasida CAM to'lovlari eng ko'p qanday taqsimlanadi?","a":["Ijarachining umumiy GLA dagi ulushiga proporsional ravishda","Ijaraga olingan maydon hajmidan qat'i nazar teng ulushlarda","Faqat fud-kort ijarachilariga, qolganlari ozod qilinadi"],"c":0,"why":"Eng keng tarqalgan yondashuv — CAM ni har bir ijarachining GLA dagi ulushiga proporsional taqsimlash."},"en":{"q":"How are CAM charges most commonly allocated among mall tenants?","a":["Pro-rata based on each tenant's share of total GLA","In equal shares regardless of the leased area size","Only charged to food court tenants, others exempt"],"c":0,"why":"The most common approach is to allocate CAM costs proportionally to each tenant's share of GLA."}},{"id":"LS057","cat":"leasing","logic":false,"ru":{"q":"Какая практика по НДС на арендную плату типична для коммерческой аренды в Узбекистане?","a":["НДС начисляется дополнительно к базовой ставке аренды по установленной ставке","Аренда коммерческой недвижимости полностью освобождена от НДС всегда","НДС включается только в CAM-сборы, но не в саму аренду"],"c":0,"why":"Как правило, услуга по аренде облагается НДС, который начисляется сверх базовой ставки согласно налоговому законодательству."},"uz":{"q":"O'zbekistonda tijorat ijarasi uchun ijara to'loviga QQS qo'llanilishi bo'yicha odatiy amaliyot qanday?","a":["QQS asosiy ijara stavkasi ustiga qonunda belgilangan stavka bo'yicha qo'shiladi","Tijorat ko'chmas mulki ijarasi har doim QQS dan butunlay ozod","QQS faqat CAM to'lovlariga qo'llaniladi, ijaraning o'ziga emas"],"c":0,"why":"Odatda ijara xizmati soliq qonunchiligiga muvofiq QQS bilan soliqqa tortiladi va bu asosiy stavka ustiga qo'shiladi."},"en":{"q":"What is the typical VAT treatment of rent in commercial leasing practice in Uzbekistan?","a":["VAT is charged on top of the base rent at the statutory rate","Commercial property rent is always fully VAT-exempt","VAT applies only to CAM charges, never to the rent itself"],"c":0,"why":"Rental services are generally subject to VAT under tax law, charged in addition to the base rent amount."}},{"id":"LS058","cat":"leasing","logic":false,"ru":{"q":"Зачем в договорах аренды ТРЦ Узбекистана часто указывают ставку в долларах с оплатой в сумах по курсу ЦБ?","a":["Чтобы защитить арендодателя от валютных рисков девальвации сума","Чтобы полностью исключить любые расчёты в национальной валюте","Чтобы арендатор мог платить в любой иностранной валюте по своему выбору"],"c":0,"why":"Валютная привязка ставки к доллару с оплатой в сумах по курсу защищает арендный доход от обесценения местной валюты."},"uz":{"q":"Nega O'zbekiston TRC ijara shartnomalarida stavka dollarda ko'rsatilib, MB kursi bo'yicha so'mda to'lanadi?","a":["Ijaraga beruvchini so'm devalvatsiyasi valyuta xatarlaridan himoya qilish uchun","Milliy valyutadagi har qanday hisob-kitobni butunlay istisno qilish uchun","Ijarachiga xohlagan chet el valyutasida to'lash imkonini berish uchun"],"c":0,"why":"Stavkani dollarga bog'lab, kurs bo'yicha so'mda to'lash ijara daromadini mahalliy valyuta qadrsizlanishidan himoya qiladi."},"en":{"q":"Why do Uzbekistan mall leases often quote the rate in USD while payment is made in soum at the central bank rate?","a":["To protect the landlord's rental income from soum devaluation risk","To completely eliminate any payments in the local currency","To let the tenant pay in any foreign currency of its choosing"],"c":0,"why":"Pegging the rate to USD while settling in soum at the exchange rate shields rental income from local currency depreciation."}},{"id":"LS059","cat":"leasing","logic":false,"ru":{"q":"Что является характерным риском валютной оговорки (currency clause) для арендатора с выручкой в сумах?","a":["Рост суммы аренды в сумах при девальвации национальной валюты","Полное отсутствие влияния курса валют на арендные платежи","Автоматическое снижение ставки при укреплении сума"],"c":0,"why":"Если арендатор зарабатывает в сумах, а платит по курсу доллара, девальвация сума увеличивает реальную нагрузку по аренде."},"uz":{"q":"Daromadi so'mda bo'lgan ijarachi uchun valyuta bandi (currency clause) qanday xarakterli xavf tug'diradi?","a":["Milliy valyuta devalvatsiyasida so'mdagi ijara summasi oshib ketishi","Valyuta kursining ijara to'lovlariga hech qanday ta'sir qilmasligi","So'm mustahkamlanganda stavkaning avtomatik pasayishi"],"c":0,"why":"Ijarachi so'mda daromad topsa-yu, dollar kursi bo'yicha to'lasa, so'm devalvatsiyasi ijaraning real og'irligini oshiradi."},"en":{"q":"What is a characteristic risk of a currency clause for a tenant earning revenue in local soum?","a":["A rising soum rent burden if the national currency devalues","No impact whatsoever of exchange rates on rent payments","An automatic rate reduction whenever the soum strengthens"],"c":0,"why":"If the tenant earns in soum but pays based on the USD rate, soum devaluation increases the real rent burden in local currency terms."}},{"id":"LS060","cat":"leasing","logic":false,"ru":{"q":"Чем портфель условий якорного договора аренды принципиально отличается от in-line в части операционного контроля арендодателя?","a":["Якорь получает больше автономии и меньше операционных ограничений","Якорь всегда подчиняется единым правилам мерчандайзинга без исключений","Якорь не имеет права определять часы работы своего магазина"],"c":0,"why":"Благодаря переговорной силе якорные арендаторы обычно получают больше свободы по режиму работы, вывескам и планировке, чем in-line."},"uz":{"q":"Langar ijara shartnomasi shartlari operatsion nazorat borasida in-line shartnomadan tub jihatdan nimasi bilan farq qiladi?","a":["Langar ko'proq erkinlik va kamroq operatsion cheklovlarga ega bo'ladi","Langar har doim yagona merchandayzing qoidalariga istisnosiz bo'ysunadi","Langar o'z do'konining ish vaqtini belgilash huquqiga ega emas"],"c":0,"why":"Kuchli muzokara pozitsiyasi tufayli langar ijarachilar ish vaqti, tashqi reklama va rejalashtirish bo'yicha in-line ga qaraganda ko'proq erkinlik oladi."},"en":{"q":"How does an anchor lease's terms fundamentally differ from an in-line lease regarding the landlord's operational control?","a":["Anchors typically gain more autonomy and fewer operational restrictions","Anchors always follow identical merchandising rules with no exceptions","Anchors have no say over their own store's operating hours"],"c":0,"why":"Due to their negotiating leverage, anchor tenants usually secure more freedom over hours, signage, and layout than in-line tenants."}},{"id":"MK001","cat":"marketing","logic":false,"ru":{"q":"Как рассчитывается коэффициент конверсии посетителей ТРЦ?","a":["Число покупок ÷ число посетителей × 100%","Выручка ÷ число арендаторов","Число посетителей ÷ площадь ТРЦ"],"c":0,"why":"Конверсия показывает долю посетителей, совершивших покупку, и считается как отношение числа транзакций к общему трафику."},"uz":{"q":"TRC (savdo markazi) tashrifchilarining konversiya koeffitsienti qanday hisoblanadi?","a":["Xaridlar soni ÷ tashrifchilar soni × 100%","Tushum ÷ ijarachilar soni","Tashrifchilar soni ÷ TRC maydoni"],"c":0,"why":"Konversiya xaridni amalga oshirgan tashrifchilar ulushini ko'rsatadi va tranzaksiyalar sonini umumiy trafikka nisbati sifatida hisoblanadi."},"en":{"q":"How is the conversion rate of mall visitors calculated?","a":["Number of transactions ÷ footfall × 100%","Revenue ÷ number of tenants","Footfall ÷ mall area"],"c":0,"why":"Conversion rate measures the share of visitors who made a purchase, calculated as transactions divided by total footfall."}},{"id":"MK002","cat":"marketing","logic":false,"ru":{"q":"Что такое footfall (пешеходный трафик) в контексте ТРЦ?","a":["Общее количество посетителей за период","Средний чек покупателя","Площадь арендуемых помещений"],"c":0,"why":"Footfall — это метрика, фиксирующая общее число людей, посетивших торговый центр за определённый период времени."},"uz":{"q":"TRC kontekstida \"footfall\" (piyodalar trafigi) nimani anglatadi?","a":["Ma'lum davr uchun umumiy tashrifchilar soni","Xaridorning o'rtacha cheki","Ijaraga berilgan maydonlar hajmi"],"c":0,"why":"Footfall — bu ma'lum vaqt oralig'ida savdo markaziga tashrif buyurgan odamlarning umumiy sonini ko'rsatuvchi ko'rsatkich."},"en":{"q":"What does \"footfall\" mean in the context of a shopping mall?","a":["The total number of visitors over a period","The average customer receipt value","The total leasable area"],"c":0,"why":"Footfall is a metric that tracks the total number of people entering the mall during a given period."}},{"id":"MK003","cat":"marketing","logic":false,"ru":{"q":"Какой инструмент чаще всего используется для автоматического подсчёта посетителей на входах в ТРЦ?","a":["Инфракрасные/видео счётчики трафика","Ручные опросные листы охраны","Данные кассовых чеков магазинов"],"c":0,"why":"Счётчики трафика (инфракрасные датчики или видеоаналитика) на входах — стандартный способ автоматического подсчёта посетителей."},"uz":{"q":"TRC kirish joylarida tashrifchilarni avtomatik hisoblash uchun eng ko'p qo'llaniladigan vosita qaysi?","a":["Infraqizil/video trafik hisoblagichlari","Xavfsizlik xodimlarining qo'lda so'rovnomasi","Do'konlarning kassa cheklari ma'lumotlari"],"c":0,"why":"Kirish joylaridagi trafik hisoblagichlari (infraqizil sensorlar yoki video analitika) tashrifchilarni avtomatik hisoblashning standart usuli hisoblanadi."},"en":{"q":"Which tool is most commonly used to automatically count visitors at mall entrances?","a":["Infrared/video traffic counters","Manual security guard tally sheets","Store checkout receipt data"],"c":0,"why":"Traffic counters (infrared sensors or video analytics) installed at entrances are the standard method for automated visitor counting."}},{"id":"MK004","cat":"marketing","logic":false,"ru":{"q":"Что означает термин \"dwell time\" применительно к торговому центру?","a":["Среднее время, проведённое посетителем в ТРЦ","Время ожидания в очереди на кассе","Срок действия арендного договора"],"c":0,"why":"Dwell time — это среднее время пребывания посетителя на территории торгового центра, важный показатель вовлечённости."},"uz":{"q":"Savdo markaziga nisbatan \"dwell time\" atamasi nimani anglatadi?","a":["Tashrifchining TRCda o'tkazgan o'rtacha vaqti","Kassada navbatda kutish vaqti","Ijara shartnomasining amal qilish muddati"],"c":0,"why":"Dwell time — tashrifchining savdo markazi hududida bo'lgan o'rtacha vaqti bo'lib, jalb qilish darajasining muhim ko'rsatkichidir."},"en":{"q":"What does the term \"dwell time\" mean for a shopping mall?","a":["The average time a visitor spends inside the mall","The time spent waiting in a checkout line","The duration of a lease agreement"],"c":0,"why":"Dwell time refers to the average length of time a visitor spends on the mall premises, an important engagement metric."}},{"id":"MK005","cat":"marketing","logic":false,"ru":{"q":"Почему увеличение dwell time обычно выгодно управляющей компании ТРЦ?","a":["Больше времени в ТРЦ повышает вероятность покупок","Это снижает затраты на клининг","Это автоматически увеличивает арендную ставку"],"c":0,"why":"Чем дольше посетитель находится в ТРЦ, тем выше шанс, что он зайдёт в несколько магазинов и совершит покупку."},"uz":{"q":"Dwell time (bo'lish vaqti)ning oshishi nima uchun odatda TRC boshqaruv kompaniyasi uchun foydali?","a":["TRCda ko'proq vaqt o'tkazish xarid ehtimolini oshiradi","Bu tozalash xarajatlarini kamaytiradi","Bu avtomatik ravishda ijara stavkasini oshiradi"],"c":0,"why":"Tashrifchi TRCda qancha ko'p vaqt o'tkazsa, u bir nechta do'konga kirib xarid qilish ehtimoli shuncha yuqori bo'ladi."},"en":{"q":"Why is an increase in dwell time generally beneficial for a mall's management company?","a":["More time spent increases the likelihood of purchases","It reduces cleaning costs","It automatically raises the lease rate"],"c":0,"why":"The longer a visitor stays in the mall, the higher the chance they will visit multiple stores and make a purchase."}},{"id":"MK006","cat":"marketing","logic":false,"ru":{"q":"Что представляет собой маркетинговый фонд (МФ) ТРЦ, формируемый арендаторами?","a":["Общий бюджет для совместного продвижения ТРЦ","Резерв на ремонт инженерных систем","Страховой взнос на случай форс-мажора"],"c":0,"why":"Маркетинговый фонд формируется за счёт взносов арендаторов и используется на общую рекламу и продвижение торгового центра."},"uz":{"q":"Ijarachilar tomonidan shakllantiriladigan TRC marketing fondi (MF) nimani anglatadi?","a":["TRCni birgalikda targ'ib qilish uchun umumiy byudjet","Muhandislik tizimlarini ta'mirlash uchun zaxira","Fors-major holatlari uchun sug'urta badali"],"c":0,"why":"Marketing fondi ijarachilarning badallari hisobidan shakllantiriladi va savdo markazini umumiy reklama qilish hamda targ'ib qilishga sarflanadi."},"en":{"q":"What is a mall's marketing fund (MF), funded by tenants?","a":["A shared budget for joint mall promotion","A reserve for repairing engineering systems","An insurance premium for force majeure"],"c":0,"why":"The marketing fund is financed by tenant contributions and used to promote and advertise the shopping center as a whole."}},{"id":"MK007","cat":"marketing","logic":false,"ru":{"q":"Как чаще всего рассчитывается взнос арендатора в маркетинговый фонд ТРЦ?","a":["Процент от товарооборота или фиксированная сумма за м²","Фиксированный процент от прибыли управляющей компании","Случайным образом по решению арендодателя"],"c":0,"why":"Стандартная практика — взнос в МФ как процент от товарооборота арендатора или фиксированная ставка за квадратный метр площади."},"uz":{"q":"Ijarachining TRC marketing fondiga badali odatda qanday hisoblanadi?","a":["Aylanmadan foiz yoki 1 m² uchun belgilangan summa","Boshqaruv kompaniyasi foydasidan qat'iy foiz","Ijaraga beruvchi qarori bilan tasodifiy tarzda"],"c":0,"why":"Standart amaliyot — MF badalini ijarachining tovar aylanmasidan foiz yoki maydon kvadrat metriga qat'iy stavka sifatida belgilash."},"en":{"q":"How is a tenant's contribution to the mall marketing fund typically calculated?","a":["A percentage of turnover or a fixed fee per sq.m","A fixed percentage of the management company's profit","Randomly, at the landlord's discretion"],"c":0,"why":"Standard practice sets the MF contribution as a percentage of the tenant's turnover or a fixed rate per square meter."}},{"id":"MK008","cat":"marketing","logic":false,"ru":{"q":"На что в первую очередь должны расходоваться средства маркетингового фонда ТРЦ?","a":["Реклама, события и продвижение всего ТРЦ","Выплата зарплаты продавцам арендаторов","Погашение кредита управляющей компании"],"c":0,"why":"Средства МФ предназначены для коллективного маркетинга, рекламных кампаний и мероприятий, приносящих пользу всем арендаторам."},"uz":{"q":"TRC marketing fondi mablag'lari birinchi navbatda nimaga sarflanishi kerak?","a":["Butun TRCni reklama qilish, tadbirlar va targ'ibot","Ijarachilarning sotuvchilariga maosh to'lash","Boshqaruv kompaniyasining kreditini to'lash"],"c":0,"why":"MF mablag'lari barcha ijarachilarga foyda keltiruvchi jamoaviy marketing, reklama kampaniyalari va tadbirlarga mo'ljallangan."},"en":{"q":"What should mall marketing fund resources primarily be spent on?","a":["Advertising, events, and promotion of the whole mall","Paying salaries of tenants' sales staff","Repaying the management company's loan"],"c":0,"why":"MF resources are intended for collective marketing, ad campaigns, and events that benefit all tenants."}},{"id":"MK009","cat":"marketing","logic":false,"ru":{"q":"Какая основная цель программы лояльности ТРЦ?","a":["Повышение частоты визитов и среднего чека постоянных клиентов","Снижение затрат на охрану","Уменьшение числа арендаторов"],"c":0,"why":"Программы лояльности направлены на удержание клиентов, стимулируя их чаще посещать ТРЦ и тратить больше."},"uz":{"q":"TRC sodiqlik dasturining asosiy maqsadi nima?","a":["Doimiy mijozlarning tashrif chastotasi va o'rtacha chekini oshirish","Xavfsizlik xarajatlarini kamaytirish","Ijarachilar sonini kamaytirish"],"c":0,"why":"Sodiqlik dasturlari mijozlarni ushlab qolishga qaratilgan bo'lib, ularni TRCga tez-tez tashrif buyurishga va ko'proq xarajat qilishga undaydi."},"en":{"q":"What is the main goal of a mall loyalty program?","a":["Increasing visit frequency and average spend of regular customers","Reducing security costs","Reducing the number of tenants"],"c":0,"why":"Loyalty programs aim to retain customers by encouraging more frequent visits and higher spending."}},{"id":"MK010","cat":"marketing","logic":false,"ru":{"q":"Какой механизм чаще всего лежит в основе программы лояльности ТРЦ?","a":["Начисление баллов/кешбэка за покупки у арендаторов","Автоматическая скидка на аренду для магазинов","Бесплатная парковка для сотрудников ТРЦ"],"c":0,"why":"Типичная модель лояльности ТРЦ — начисление баллов или кешбэка за чеки из магазинов-арендаторов с последующим обменом на бонусы."},"uz":{"q":"TRC sodiqlik dasturining asosida ko'pincha qanday mexanizm yotadi?","a":["Ijarachilardan xarid uchun ball/keshbek to'plash","Do'konlar uchun ijaraga avtomatik chegirma","TRC xodimlari uchun bepul avtoturargoh"],"c":0,"why":"TRC sodiqlik dasturining odatiy modeli — ijarachi do'konlardagi cheklar uchun ball yoki keshbek to'plash va keyin ularni bonusga almashtirish."},"en":{"q":"What mechanism most commonly underlies a mall loyalty program?","a":["Earning points/cashback for purchases at tenant stores","Automatic rent discounts for stores","Free parking for mall staff"],"c":0,"why":"The typical mall loyalty model awards points or cashback for receipts from tenant stores, redeemable for bonuses."}},{"id":"MK011","cat":"marketing","logic":false,"ru":{"q":"Какая сезонная кампания наиболее актуальна для ТРЦ Узбекистана в марте?","a":["Кампания к празднику Навруз","Кампания \"Чёрная пятница\"","Кампания \"Back to school\""],"c":0,"why":"Навруз отмечается 21 марта и является ключевым национальным праздником, вокруг которого ТРЦ строят весенние кампании."},"uz":{"q":"O'zbekiston TRClari uchun mart oyida eng dolzarb mavsumiy kampaniya qaysi?","a":["Navro'z bayramiga bag'ishlangan kampaniya","\"Qora juma\" kampaniyasi","\"Maktabga tayyorgarlik\" kampaniyasi"],"c":0,"why":"Navro'z 21 martda nishonlanadi va TRClar bahorgi kampaniyalarini shu milliy bayram atrofida quradi."},"en":{"q":"Which seasonal campaign is most relevant for Uzbekistan malls in March?","a":["A Navruz holiday campaign","A Black Friday campaign","A back-to-school campaign"],"c":0,"why":"Navruz is celebrated on March 21 and is a key national holiday around which malls build spring campaigns."}},{"id":"MK012","cat":"marketing","logic":false,"ru":{"q":"Когда ТРЦ обычно запускают кампанию \"Back to school\"?","a":["В конце лета, перед началом учебного года","В середине зимы","Сразу после Навруза"],"c":0,"why":"Кампания \"Back to school\" ориентирована на подготовку к учебному году и запускается в августе."},"uz":{"q":"TRClar odatda \"Maktabga tayyorgarlik\" kampaniyasini qachon boshlaydi?","a":["Yoz oxirida, o'quv yili boshlanishidan oldin","Qish o'rtasida","Navro'zdan darhol keyin"],"c":0,"why":"\"Maktabga tayyorgarlik\" kampaniyasi o'quv yiliga tayyorgarlikka qaratilgan bo'lib, avgust oyida boshlanadi."},"en":{"q":"When do malls typically launch a \"back-to-school\" campaign?","a":["Late summer, before the school year starts","In mid-winter","Right after Navruz"],"c":0,"why":"The back-to-school campaign focuses on preparation for the school year and launches in August."}},{"id":"MK013","cat":"marketing","logic":false,"ru":{"q":"Какая цель сезонной новогодней кампании ТРЦ с точки зрения трафика?","a":["Максимизировать пиковый трафик и продажи в декабре","Снизить трафик для проведения ремонта","Перенести весь трафик на онлайн-каналы"],"c":0,"why":"Новогодняя кампания направлена на использование пика потребительской активности перед праздниками для роста продаж и трафика."},"uz":{"q":"TRCning Yangi yil mavsumiy kampaniyasi trafik nuqtai nazaridan qanday maqsadga ega?","a":["Dekabrda eng yuqori trafik va savdoni ta'minlash","Ta'mirlash ishlari uchun trafikni kamaytirish","Barcha trafikni onlayn kanallarga o'tkazish"],"c":0,"why":"Yangi yil kampaniyasi bayram oldidan iste'molchilar faolligining eng yuqori nuqtasidan foydalanib, savdo va trafikni oshirishga qaratilgan."},"en":{"q":"What is the traffic-related goal of a mall's New Year seasonal campaign?","a":["Maximize peak footfall and sales in December","Reduce footfall to allow renovations","Shift all traffic to online channels"],"c":0,"why":"The New Year campaign aims to capitalize on peak pre-holiday consumer activity to boost sales and footfall."}},{"id":"MK014","cat":"marketing","logic":false,"ru":{"q":"Какой канал цифрового маркетинга наиболее эффективен для геотаргетированного привлечения посетителей ТРЦ?","a":["Таргетированная реклама в соцсетях по геолокации","Печатные листовки в почтовых ящиках","Радиореклама без указания адреса"],"c":0,"why":"Геотаргетинг в соцсетях позволяет показывать рекламу пользователям в радиусе от ТРЦ, повышая точность охвата."},"uz":{"q":"TRCga tashrifchilarni geo-manzil bo'yicha jalb qilish uchun qaysi raqamli marketing kanali eng samarali?","a":["Ijtimoiy tarmoqlarda geolokatsiya bo'yicha maqsadli reklama","Pochta qutilariga tarqatilgan bukletlar","Manzilsiz radio reklama"],"c":0,"why":"Ijtimoiy tarmoqlardagi geotargetlash TRC atrofidagi foydalanuvchilarga reklama ko'rsatish orqali qamrov aniqligini oshiradi."},"en":{"q":"Which digital marketing channel is most effective for geo-targeted mall visitor acquisition?","a":["Geo-targeted social media advertising","Printed flyers in mailboxes","Radio ads without location targeting"],"c":0,"why":"Social media geo-targeting shows ads to users within a defined radius of the mall, improving reach precision."}},{"id":"MK015","cat":"marketing","logic":false,"ru":{"q":"Какой показатель SMM наиболее важен для оценки вовлечённости аудитории ТРЦ в Instagram?","a":["Engagement rate (лайки, комментарии, репосты к охвату)","Количество символов в подписи к посту","Число хэштегов в публикации"],"c":0,"why":"Engagement rate отражает реальную вовлечённость подписчиков и точнее оценивает эффективность контента, чем формальные метрики."},"uz":{"q":"TRCning Instagramdagi auditoriya jalb qilinganligini baholash uchun eng muhim SMM ko'rsatkichi qaysi?","a":["Engagement rate (layk, izoh, repostlarning qamrovga nisbati)","Post tavsifidagi belgilar soni","Postdagi xeshteglar soni"],"c":0,"why":"Engagement rate obunachilarning haqiqiy faolligini aks ettiradi va kontent samaradorligini rasmiy ko'rsatkichlardan aniqroq baholaydi."},"en":{"q":"Which SMM metric is most important for evaluating a mall's Instagram audience engagement?","a":["Engagement rate (likes, comments, shares vs. reach)","The number of characters in a post caption","The number of hashtags used in a post"],"c":0,"why":"Engagement rate reflects genuine follower interaction and more accurately measures content effectiveness than formal metrics."}},{"id":"MK016","cat":"marketing","logic":false,"ru":{"q":"Зачем ТРЦ ведут аккаунты в социальных сетях (SMM)?","a":["Для информирования о событиях, акциях и удержания аудитории","Только для публикации финансовой отчётности","Чтобы заменить сайт управляющей компании"],"c":0,"why":"SMM позволяет напрямую коммуницировать с аудиторией, анонсировать акции и мероприятия, формируя лояльность."},"uz":{"q":"TRClar nima uchun ijtimoiy tarmoqlarda sahifa yuritadi (SMM)?","a":["Tadbirlar, aksiyalar haqida xabar berish va auditoriyani ushlab qolish uchun","Faqat moliyaviy hisobotlarni e'lon qilish uchun","Boshqaruv kompaniyasi veb-saytini almashtirish uchun"],"c":0,"why":"SMM auditoriya bilan bevosita muloqot qilish, aksiya va tadbirlarni e'lon qilish imkonini beradi va sodiqlikni shakllantiradi."},"en":{"q":"Why do malls maintain social media accounts (SMM)?","a":["To announce events, promotions, and retain audience engagement","Only to publish financial statements","To replace the management company's website"],"c":0,"why":"SMM enables direct communication with the audience, promoting events and offers while building loyalty."}},{"id":"MK017","cat":"marketing","logic":false,"ru":{"q":"Что такое ивент-маркетинг (событийный маркетинг) в ТРЦ?","a":["Организация мероприятий и активаций для привлечения посетителей","Учёт событий на кассовых аппаратах","Расчёт годового бюджета арендной платы"],"c":0,"why":"Ивент-маркетинг — это проведение мероприятий (выставок, конкурсов, встреч с брендами) для повышения трафика и вовлечённости."},"uz":{"q":"TRCda tadbir-marketing (event marketing) nima?","a":["Tashrifchilarni jalb qilish uchun tadbirlar va aktivatsiyalar tashkil etish","Kassa apparatlaridagi voqealarni hisobga olish","Yillik ijara byudjetini hisoblash"],"c":0,"why":"Tadbir-marketing — trafik va jalb qilinganlikni oshirish uchun tadbirlar (ko'rgazmalar, tanlovlar, brendlar bilan uchrashuvlar) o'tkazishdir."},"en":{"q":"What is event marketing in a shopping mall context?","a":["Organizing events and activations to attract visitors","Logging transactions on POS systems","Calculating the annual rent budget"],"c":0,"why":"Event marketing involves hosting events (exhibitions, contests, brand activations) to drive traffic and engagement."}},{"id":"MK018","cat":"marketing","logic":false,"ru":{"q":"Какой пример ивент-активации типичен для атриума крупного ТРЦ в выходные дни?","a":["Детский мастер-класс или концерт с промо-акциями","Собрание совета директоров арендаторов","Плановая инвентаризация складов магазинов"],"c":0,"why":"Атриумные активации на выходных (мастер-классы, концерты, выставки) традиционно используются для привлечения семейной аудитории."},"uz":{"q":"Yirik TRC atriumida dam olish kunlari uchun qanday tadbir-aktivatsiya odatiy hisoblanadi?","a":["Bolalar uchun master-klass yoki aksiyalar bilan konsert","Ijarachilar direktorlar kengashining yig'ilishi","Do'konlar omborida rejali inventarizatsiya"],"c":0,"why":"Dam olish kunlaridagi atrium aktivatsiyalari (master-klasslar, konsertlar, ko'rgazmalar) an'anaviy ravishda oilaviy auditoriyani jalb qilish uchun ishlatiladi."},"en":{"q":"What is a typical weekend atrium event activation in a large mall?","a":["A children's workshop or concert with promotions","A tenant board of directors meeting","A scheduled store warehouse inventory count"],"c":0,"why":"Weekend atrium activations (workshops, concerts, exhibitions) are traditionally used to attract family audiences."}},{"id":"MK019","cat":"marketing","logic":false,"ru":{"q":"Что подразумевает понятие \"брендинг ТРЦ\" (mall branding)?","a":["Формирование узнаваемого образа и позиционирования ТРЦ","Установка вывесок с логотипами арендаторов","Оформление кассовых чеков магазинов"],"c":0,"why":"Брендинг ТРЦ — это создание уникального образа, ценностного предложения и позиционирования на рынке для целевой аудитории."},"uz":{"q":"\"TRC brendingi\" (mall branding) tushunchasi nimani anglatadi?","a":["TRCning tanib olinadigan qiyofasi va pozitsiyasini shakllantirish","Ijarachilarning logotipli lavhalarini o'rnatish","Do'konlarning kassa cheklarini bezash"],"c":0,"why":"TRC brendingi — bu maqsadli auditoriya uchun bozorda o'ziga xos qiyofa, qadriyat taklifi va pozitsiyani yaratishdir."},"en":{"q":"What does the concept of \"mall branding\" involve?","a":["Building a recognizable image and market positioning for the mall","Installing signage with tenant logos","Designing store checkout receipts"],"c":0,"why":"Mall branding is about creating a unique identity, value proposition, and market positioning for the target audience."}},{"id":"MK020","cat":"marketing","logic":false,"ru":{"q":"Почему чёткое позиционирование ТРЦ (например, \"семейный\" или \"премиальный\") важно для его успеха?","a":["Оно определяет подбор арендаторов и целевую аудиторию","Оно снижает налоговую нагрузку на ТРЦ","Оно заменяет необходимость в маркетинге"],"c":0,"why":"Позиционирование задаёт tenant-mix и коммуникацию с целевой аудиторией, влияя на весь маркетинговый план."},"uz":{"q":"TRCning aniq pozitsiyalanishi (masalan, \"oilaviy\" yoki \"premium\") nima uchun muvaffaqiyat uchun muhim?","a":["U ijarachilar tarkibi va maqsadli auditoriyani belgilaydi","U TRC uchun soliq yukini kamaytiradi","U marketingga bo'lgan ehtiyojni yo'qqa chiqaradi"],"c":0,"why":"Pozitsiyalanish tenant-mix va maqsadli auditoriya bilan kommunikatsiyani belgilaydi hamda butun marketing rejasiga ta'sir qiladi."},"en":{"q":"Why is clear mall positioning (e.g., \"family-oriented\" or \"premium\") important for success?","a":["It shapes the tenant mix and target audience","It reduces the mall's tax burden","It eliminates the need for marketing"],"c":0,"why":"Positioning determines the tenant mix and communication with the target audience, shaping the whole marketing plan."}},{"id":"MK021","cat":"marketing","logic":false,"ru":{"q":"Что такое зона охвата (catchment area) торгового центра?","a":["Территория, откуда ТРЦ привлекает основную массу посетителей","Площадь парковки перед ТРЦ","Список арендаторов на первом этаже"],"c":0,"why":"Catchment area — это географическая территория, население которой формирует основной поток посетителей и покупателей ТРЦ."},"uz":{"q":"Savdo markazining qamrov zonasi (catchment area) nima?","a":["TRC asosiy tashrifchilar oqimini jalb qiladigan hudud","TRC oldidagi avtoturargoh maydoni","Birinchi qavatdagi ijarachilar ro'yxati"],"c":0,"why":"Catchment area — aholisi TRCning asosiy tashrifchilar va xaridorlar oqimini shakllantiradigan geografik hududdir."},"en":{"q":"What is a mall's catchment area?","a":["The geographic area from which the mall draws most of its visitors","The parking lot area in front of the mall","The list of tenants on the ground floor"],"c":0,"why":"The catchment area is the geographic zone whose population generates the majority of the mall's visitor and customer flow."}},{"id":"MK022","cat":"marketing","logic":false,"ru":{"q":"Чем первичная зона охвата (primary catchment) отличается от третичной (tertiary)?","a":["Первичная ближе и даёт наибольшую долю посетителей","Первичная всегда больше по площади, чем третичная","Третичная зона включает только сотрудников ТРЦ"],"c":0,"why":"Первичная зона расположена ближе к ТРЦ и обеспечивает наибольшую концентрацию постоянных посетителей, в отличие от удалённой третичной."},"uz":{"q":"Birlamchi qamrov zonasi (primary catchment) uchlamchi zonadan (tertiary) nimasi bilan farq qiladi?","a":["Birlamchi zona yaqinroq bo'lib, tashrifchilarning eng katta ulushini beradi","Birlamchi zona har doim uchlamchidan kattaroq maydonga ega","Uchlamchi zona faqat TRC xodimlarini o'z ichiga oladi"],"c":0,"why":"Birlamchi zona TRCga yaqinroq joylashgan bo'lib, doimiy tashrifchilarning eng yuqori konsentratsiyasini ta'minlaydi, uchlamchi zona esa uzoqroqdir."},"en":{"q":"How does a primary catchment area differ from a tertiary catchment area?","a":["The primary is closer and generates the largest visitor share","The primary is always larger in size than the tertiary","The tertiary area includes only mall employees"],"c":0,"why":"The primary zone lies closer to the mall and provides the highest concentration of regular visitors, unlike the more distant tertiary zone."}},{"id":"MK023","cat":"marketing","logic":false,"ru":{"q":"Какой метод маркетингового исследования лучше всего подходит для изучения профиля посетителей ТРЦ?","a":["Опросы (интервью) посетителей на территории ТРЦ","Изучение только финансовой отчётности арендаторов","Анализ погодных условий за прошлый год"],"c":0,"why":"Опросы посетителей позволяют напрямую собрать данные о демографии, предпочтениях и поведении целевой аудитории."},"uz":{"q":"TRC tashrifchilari profilini o'rganish uchun qaysi marketing tadqiqoti usuli eng mos keladi?","a":["TRC hududida tashrifchilar orasida so'rovnoma (intervyu) o'tkazish","Faqat ijarachilarning moliyaviy hisobotini o'rganish","O'tgan yilgi ob-havo sharoitlarini tahlil qilish"],"c":0,"why":"Tashrifchilar so'rovnomasi maqsadli auditoriyaning demografiyasi, afzalliklari va xatti-harakati haqida bevosita ma'lumot to'plash imkonini beradi."},"en":{"q":"Which market research method is best suited to study a mall's visitor profile?","a":["On-site visitor surveys/interviews","Reviewing only tenants' financial statements","Analyzing last year's weather patterns"],"c":0,"why":"Visitor surveys allow direct collection of data on demographics, preferences, and behavior of the target audience."}},{"id":"MK024","cat":"marketing","logic":false,"ru":{"q":"Зачем при открытии нового ТРЦ проводится анализ торговой зоны (trade area analysis)?","a":["Чтобы оценить потенциальный спрос и конкуренцию в районе","Чтобы определить цвет фасада здания","Чтобы рассчитать зарплату персонала клининга"],"c":0,"why":"Анализ торговой зоны помогает оценить численность населения, доходы и конкурентов, чтобы спрогнозировать потенциальный трафик и выручку."},"uz":{"q":"Yangi TRC ochilishida savdo zonasini tahlil qilish (trade area analysis) nima uchun o'tkaziladi?","a":["Hududdagi potensial talab va raqobatni baholash uchun","Bino fasadi rangini aniqlash uchun","Tozalash xodimlari maoshini hisoblash uchun"],"c":0,"why":"Savdo zonasi tahlili aholi soni, daromad darajasi va raqobatchilarni baholab, potensial trafik va tushumni bashorat qilishga yordam beradi."},"en":{"q":"Why is trade area analysis conducted when opening a new mall?","a":["To assess potential demand and competition in the area","To determine the building facade color","To calculate cleaning staff salaries"],"c":0,"why":"Trade area analysis evaluates population, income levels, and competitors to forecast potential footfall and revenue."}},{"id":"MK025","cat":"marketing","logic":false,"ru":{"q":"Какой показатель наиболее полезен управляющей компании для оценки эффективности рекламной кампании ТРЦ?","a":["Прирост трафика и продаж арендаторов за период кампании","Количество сотрудников отдела маркетинга","Число этажей в здании ТРЦ"],"c":0,"why":"Эффективность кампании оценивается по фактическому росту посещаемости и товарооборота арендаторов, а не по внутренним ресурсам."},"uz":{"q":"TRC reklama kampaniyasi samaradorligini baholash uchun boshqaruv kompaniyasi uchun qaysi ko'rsatkich eng foydali?","a":["Kampaniya davomida trafik va ijarachilar savdosining o'sishi","Marketing bo'limi xodimlari soni","TRC binosidagi qavatlar soni"],"c":0,"why":"Kampaniya samaradorligi ichki resurslar bilan emas, balki tashrifchilar oqimi va ijarachilar aylanmasining haqiqiy o'sishi bilan baholanadi."},"en":{"q":"Which metric is most useful for a management company to assess a mall ad campaign's effectiveness?","a":["Growth in footfall and tenant sales during the campaign","The number of employees in the marketing department","The number of floors in the mall building"],"c":0,"why":"Campaign effectiveness is measured by actual growth in visitor traffic and tenant turnover, not internal resources."}},{"id":"MK026","cat":"marketing","logic":false,"ru":{"q":"Что измеряет метрика 'конверсия' (conversion rate) в торговом центре?","a":["Долю посетителей, совершивших покупку","Общее число посетителей за день","Среднюю сумму чека"],"c":0,"why":"Конверсия — это отношение числа покупателей к общему числу посетителей."},"uz":{"q":"SSMdagi 'konversiya' ko'rsatkichi nimani o'lchaydi?","a":["Xarid qilgan tashrif buyuruvchilar ulushini","Kunlik umumiy tashrif sonini","O'rtacha chek summasini"],"c":0,"why":"Konversiya — xaridorlar sonining umumiy tashrif buyuruvchilar soniga nisbati."},"en":{"q":"What does the 'conversion rate' metric measure in a shopping mall?","a":["The share of visitors who make a purchase","Total daily visitor count","Average receipt value"],"c":0,"why":"Conversion rate is the ratio of buyers to total visitors."}},{"id":"MK027","cat":"marketing","logic":false,"ru":{"q":"Какая технология подсчёта посетителей наиболее точно различает входящих и выходящих людей в условиях высокой плотности потока?","a":["Инфракрасные лучи-барьеры","3D-стереоскопические счётчики","Ручной подсчёт охраной"],"c":1,"why":"3D-стереоскопические счётчики используют глубину изображения и лучше справляются с плотными потоками и группами людей."},"uz":{"q":"Yuqori zichlikdagi oqimda kiruvchi va chiquvchilarni eng aniq farqlaydigan tashrif hisoblash texnologiyasi qaysi?","a":["Infraqizil nur to'siqlari","3D-stereoskopik hisoblagichlar","Qo'riqchilar tomonidan qo'lda hisoblash"],"c":1,"why":"3D-stereoskopik hisoblagichlar tasvir chuqurligidan foydalanadi va zich oqimda, guruhlarda yaxshiroq ishlaydi."},"en":{"q":"Which footfall counting technology most accurately distinguishes entries from exits under high-density traffic?","a":["Infrared beam counters","3D stereoscopic counters","Manual counting by security staff"],"c":1,"why":"3D stereoscopic counters use image depth and handle dense crowds and groups more accurately."}},{"id":"MK028","cat":"marketing","logic":false,"ru":{"q":"Как называется среднее время, которое посетитель проводит внутри торгового центра за один визит?","a":["Dwell time (время пребывания)","Lead time (время выполнения заказа)","Lag time (время отклика)"],"c":0,"why":"Dwell time — стандартный термин для среднего времени пребывания посетителя в ТЦ."},"uz":{"q":"Tashrif buyuruvchining bir tashrif davomida SSMda o'tkazadigan o'rtacha vaqti qanday ataladi?","a":["Dwell time (bo'lish vaqti)","Lead time (bajarish vaqti)","Lag time (javob vaqti)"],"c":0,"why":"Dwell time — mijozning savdo markazida o'tkazgan o'rtacha vaqtini bildiruvchi standart atama."},"en":{"q":"What is the term for the average amount of time a visitor spends inside a mall per visit?","a":["Dwell time","Lead time","Lag time"],"c":0,"why":"Dwell time is the standard term for average in-mall visit duration."}},{"id":"MK029","cat":"marketing","logic":false,"ru":{"q":"Каким образом планировка (layout) ТЦ обычно увеличивает время пребывания и охват магазинов?","a":["Размещением якорных арендаторов по краям с извилистым проходом между ними","Размещением всех магазинов у одного входа","Сокращением числа этажей до одного"],"c":0,"why":"Размещение якорей по разным концам заставляет посетителей проходить мимо большего числа магазинов, увеличивая dwell time и охват."},"uz":{"q":"SSM rejalashtiruvi (layout) odatda qanday usulda tashrif vaqti va do'konlar qamrovini oshiradi?","a":["Langar ijarachilarni chetlarga joylashtirib, o'rtada uzun yo'l yaratish orqali","Barcha do'konlarni bitta kirish joyida jamlash orqali","Qavatlar sonini bittaga qisqartirish orqali"],"c":0,"why":"Langarlarni turli uchlarga joylashtirish mijozlarni ko'proq do'kon oldidan o'tishga majburlaydi va dwell time'ni oshiradi."},"en":{"q":"How does mall layout typically increase dwell time and store exposure?","a":["Placing anchor tenants at opposite ends with a winding path between them","Clustering all stores near a single entrance","Reducing the mall to a single floor"],"c":0,"why":"Anchors placed at opposite ends force shoppers past more stores, increasing dwell time and exposure."}},{"id":"MK030","cat":"marketing","logic":false,"ru":{"q":"Что такое 'marketing fund' (маркетинговый фонд) в договоре аренды ТЦ?","a":["Регулярный взнос арендаторов на общие маркетинговые активности центра","Штраф за просрочку арендной платы","Депозит на ремонт помещения"],"c":0,"why":"Marketing fund — это отдельный сбор с арендаторов, направляемый на общую рекламу и продвижение ТЦ."},"uz":{"q":"SSM ijara shartnomasidagi 'marketing fondi' nima?","a":["Ijarachilarning markaz umumiy marketingi uchun muntazam badali","Ijara to'lovini kechiktirgani uchun jarima","Xonani ta'mirlash uchun depozit"],"c":0,"why":"Marketing fondi ijarachilardan yig'iladigan va SSMning umumiy reklamasiga sarflanadigan alohida to'lov."},"en":{"q":"What is a 'marketing fund' in a mall lease agreement?","a":["A recurring tenant contribution funding the mall's joint marketing activities","A penalty fee for late rent payment","A deposit for unit renovation"],"c":0,"why":"The marketing fund is a separate tenant contribution used for the mall's collective advertising and promotion."}},{"id":"MK031","cat":"marketing","logic":false,"ru":{"q":"Как обычно рассчитывается размер взноса арендатора в маркетинговый фонд ТЦ?","a":["Фиксированная ставка за кв.м арендуемой площади","Процент от прибыли управляющей компании","Случайная сумма по решению арендатора"],"c":0,"why":"Чаще всего взнос в маркетинговый фонд устанавливается как фиксированная ставка за квадратный метр, аналогично CAM-сборам."},"uz":{"q":"Ijarachining SSM marketing fondiga badali odatda qanday hisoblanadi?","a":["Ijaraga olingan maydonning kvadrat metriga qat'iy stavka bo'yicha","Boshqaruv kompaniyasi foydasidan foiz sifatida","Ijarachi qarori bo'yicha tasodifiy summa"],"c":0,"why":"Odatda marketing fondiga badal CAM to'lovlariga o'xshab, har kvadrat metr uchun qat'iy stavka asosida belgilanadi."},"en":{"q":"How is a tenant's marketing fund contribution typically calculated?","a":["A fixed rate per square meter of leased area","A percentage of the management company's profit","An arbitrary amount chosen by the tenant"],"c":0,"why":"Marketing fund contributions are usually a fixed rate per square meter, similar to CAM charges."}},{"id":"MK032","cat":"marketing","logic":false,"ru":{"q":"В чём главное отличие CRM-программы лояльности от простой дисконтной карты?","a":["CRM собирает данные о покупках для персонализированных предложений","CRM даёт скидку только в день рождения","CRM работает только для VIP-арендаторов"],"c":0,"why":"CRM-система накапливает историю покупок и поведения, позволяя делать таргетированные персональные предложения, а не просто фиксированную скидку."},"uz":{"q":"CRM sodiqlik dasturi oddiy chegirma kartasidan asosan nimasi bilan farq qiladi?","a":["CRM shaxsiylashtirilgan takliflar uchun xarid ma'lumotlarini yig'adi","CRM faqat tug'ilgan kunida chegirma beradi","CRM faqat VIP ijarachilar uchun ishlaydi"],"c":0,"why":"CRM tizimi xarid tarixi va xatti-harakatlarni to'playdi, bu esa oddiy qat'iy chegirmadan farqli, maqsadli shaxsiy takliflar berish imkonini beradi."},"en":{"q":"What is the main difference between a CRM loyalty program and a simple discount card?","a":["CRM collects purchase data to enable personalized offers","CRM only gives a discount on the customer's birthday","CRM only applies to VIP tenants"],"c":0,"why":"A CRM system builds a purchase and behavior history enabling targeted personal offers, unlike a flat discount card."}},{"id":"MK033","cat":"marketing","logic":false,"ru":{"q":"Какая метрика лояльности показывает вероятность того, что клиент порекомендует ТЦ другим?","a":["NPS (индекс потребительской лояльности)","ROI (возврат инвестиций)","CPM (стоимость за тысячу показов)"],"c":0,"why":"NPS (Net Promoter Score) измеряет готовность клиентов рекомендовать бренд или ТЦ окружающим."},"uz":{"q":"Qaysi sodiqlik ko'rsatkichi mijozning SSMni boshqalarga tavsiya qilish ehtimolini ko'rsatadi?","a":["NPS (mijozlar sodiqligi indeksi)","ROI (investitsiya qaytimi)","CPM (ming ko'rsatish narxi)"],"c":0,"why":"NPS (Net Promoter Score) mijozlarning brend yoki SSMni boshqalarga tavsiya qilishga tayyorligini o'lchaydi."},"en":{"q":"Which loyalty metric measures the likelihood that a customer will recommend the mall to others?","a":["NPS (Net Promoter Score)","ROI (return on investment)","CPM (cost per mille)"],"c":0,"why":"NPS measures customers' willingness to recommend the brand or mall to others."}},{"id":"MK034","cat":"marketing","logic":false,"ru":{"q":"Почему единая CRM-система на уровне всего ТЦ выгоднее, чем отдельные программы лояльности каждого арендатора?","a":["Она объединяет данные о покупках по всем магазинам и повышает точность аналитики","Она полностью отменяет необходимость скидок","Она снимает с арендаторов обязанность платить аренду"],"c":0,"why":"Единая CRM объединяет транзакции всех арендаторов, давая управляющей компании полную картину поведения покупателя."},"uz":{"q":"Nima uchun butun SSM darajasidagi yagona CRM tizimi har bir ijarachining alohida sodiqlik dasturidan foydaliroq?","a":["U barcha do'konlar bo'yicha xarid ma'lumotlarini birlashtirib, tahlil aniqligini oshiradi","U chegirmalarga bo'lgan ehtiyojni butunlay yo'q qiladi","U ijarachilarni ijara to'lashdan ozod qiladi"],"c":0,"why":"Yagona CRM barcha ijarachilarning tranzaksiyalarini birlashtirib, boshqaruv kompaniyasiga xaridor xatti-harakati haqida to'liq tasavvur beradi."},"en":{"q":"Why is a mall-wide unified CRM system more valuable than each tenant running a separate loyalty program?","a":["It consolidates purchase data across all stores for richer analytics","It eliminates the need for any discounts","It exempts tenants from paying rent"],"c":0,"why":"A unified CRM aggregates transactions across all tenants, giving management a complete view of shopper behavior."}},{"id":"MK035","cat":"marketing","logic":false,"ru":{"q":"Какая цель сезонной кампании 'Back to School' (к началу учебного года) в ТЦ?","a":["Стимулировать спрос на товары для школы в узкий временной период","Распродать неликвидные летние товары через год","Привлечь только оптовых покупателей"],"c":0,"why":"Кампания 'Back to School' направлена на концентрированный спрос родителей на школьные товары перед началом учёбы."},"uz":{"q":"SSMdagi 'Maktabga tayyorgarlik' mavsumiy kampaniyasining maqsadi nima?","a":["Qisqa vaqt oralig'ida maktab tovarlariga bo'lgan talabni rag'batlantirish","Bir yildan keyin sotilmagan yozgi tovarlarni sotish","Faqat ulgurji xaridorlarni jalb qilish"],"c":0,"why":"'Maktabga tayyorgarlik' kampaniyasi o'quv yili boshlanishi oldidan ota-onalarning maktab buyumlariga talabini jamlaydi."},"en":{"q":"What is the goal of a mall's 'Back to School' seasonal campaign?","a":["Drive concentrated demand for school-related items in a narrow window","Clear unsold summer stock a year later","Attract only wholesale buyers"],"c":0,"why":"Back to School campaigns concentrate parents' demand for school items right before the academic year starts."}},{"id":"MK036","cat":"marketing","logic":false,"ru":{"q":"Почему период Навруза особенно важен для планирования маркетинговых кампаний ТЦ в Узбекистане?","a":["Это крупный национальный праздник с высоким потребительским спросом и семейными покупками","Это единственный день в году, когда ТЦ закрыт","Это период, когда арендаторы не платят маркетинговый взнос"],"c":0,"why":"Навруз — один из главных национальных праздников Узбекистана, сопровождающийся ростом покупательской активности и семейных трат."},"uz":{"q":"Nima uchun Navro'z davri O'zbekistondagi SSM marketing kampaniyalarini rejalashtirishda alohida ahamiyatga ega?","a":["Bu yuqori iste'mol talabi va oilaviy xaridlar bilan bog'liq yirik milliy bayram","Bu yilda SSM yopiladigan yagona kun","Bu davrda ijarachilar marketing badalini to'lamaydi"],"c":0,"why":"Navro'z — O'zbekistonning asosiy milliy bayramlaridan biri bo'lib, xarid faolligi va oilaviy xarajatlar sezilarli oshadi."},"en":{"q":"Why is the Navruz holiday period especially important for mall marketing campaign planning in Uzbekistan?","a":["It is a major national holiday driving high consumer demand and family shopping","It is the only day of the year the mall closes","It is the period when tenants are exempt from marketing fees"],"c":0,"why":"Navruz is one of Uzbekistan's major national holidays, associated with a strong rise in shopping activity and family spending."}},{"id":"MK037","cat":"marketing","logic":false,"ru":{"q":"Какой показатель наиболее полезен для оценки эффективности праздничной (сезонной) кампании ТЦ?","a":["Сравнение трафика и продаж год к году (year-over-year) за период кампании","Количество сотрудников, работавших в праздники","Число арендаторов, продливших договор"],"c":0,"why":"Сравнение трафика и продаж с аналогичным периодом прошлого года показывает реальный эффект сезонной кампании."},"uz":{"q":"SSMning bayramona (mavsumiy) kampaniyasi samaradorligini baholash uchun eng foydali ko'rsatkich qaysi?","a":["Kampaniya davridagi tashrif va savdoni o'tgan yil bilan solishtirish (year-over-year)","Bayramda ishlagan xodimlar soni","Shartnomani uzaytirgan ijarachilar soni"],"c":0,"why":"Tashrif va savdoni o'tgan yilning shu davri bilan solishtirish mavsumiy kampaniyaning real ta'sirini ko'rsatadi."},"en":{"q":"Which metric is most useful for evaluating the effectiveness of a holiday (seasonal) mall campaign?","a":["Year-over-year comparison of traffic and sales during the campaign period","The number of staff working during the holiday","The number of tenants who renewed their lease"],"c":0,"why":"Comparing traffic and sales against the same period last year shows the campaign's real impact."}},{"id":"MK038","cat":"marketing","logic":false,"ru":{"q":"Что такое геотаргетинг в digital-маркетинге торгового центра?","a":["Показ рекламы пользователям, находящимся в определённом радиусе от ТЦ","Реклама, показываемая только ночью","Массовая рассылка без учёта местоположения"],"c":0,"why":"Геотаргетинг настраивает показ рекламы пользователям в конкретной географической зоне вокруг ТЦ."},"uz":{"q":"SSMning raqamli marketingida geotargeting nima?","a":["SSM atrofidagi ma'lum radiusdagi foydalanuvchilarga reklama ko'rsatish","Faqat kechqurun ko'rsatiladigan reklama","Joylashuvni hisobga olmagan ommaviy xabar tarqatish"],"c":0,"why":"Geotargeting SSM atrofidagi aniq geografik hududdagi foydalanuvchilarga reklama ko'rsatishni sozlaydi."},"en":{"q":"What is geotargeting in a shopping mall's digital marketing?","a":["Serving ads to users located within a defined radius of the mall","Ads that are only displayed at night","Mass messaging that ignores user location"],"c":0,"why":"Geotargeting configures ad delivery to users within a specific geographic zone around the mall."}},{"id":"MK039","cat":"marketing","logic":false,"ru":{"q":"Какой канал digital-маркетинга ТЦ обычно даёт наиболее точную атрибуцию 'от клика до визита' (click-to-visit)?","a":["Мобильные push-уведомления с геолокацией через приложение ТЦ","Билборды на въезде в город","Радиореклама на местной станции"],"c":0,"why":"Приложение с геолокацией позволяет отследить, пришёл ли пользователь в ТЦ после получения push-уведомления."},"uz":{"q":"SSMning qaysi raqamli marketing kanali odatda 'bosishdan tashrifgacha' (click-to-visit) eng aniq atributsiyani beradi?","a":["SSM ilovasi orqali geolokatsiyali mobil push-bildirishnomalar","Shahar chekkasidagi bilbordlar","Mahalliy radiostansiyadagi reklama"],"c":0,"why":"Geolokatsiyaga ega ilova push-bildirishnoma yuborilgandan keyin foydalanuvchi SSMga kelganini kuzatish imkonini beradi."},"en":{"q":"Which digital marketing channel typically gives the most accurate click-to-visit attribution for a mall?","a":["Location-based mobile push notifications via the mall's app","Billboards at the city entrance","Local radio advertising"],"c":0,"why":"A location-enabled app can track whether a user actually visited the mall after receiving a push notification."}},{"id":"MK040","cat":"marketing","logic":false,"ru":{"q":"Что понимается под 'активацией бренда' (brand activation) во время ивент-маркетинга в ТЦ?","a":["Интерактивное мероприятие, вовлекающее посетителей в прямой контакт с брендом","Замена вывески магазина на новую","Подписание договора аренды с новым арендатором"],"c":0,"why":"Brand activation — это интерактивные события (промо, дегустации, инсталляции), создающие живой опыт взаимодействия с брендом."},"uz":{"q":"SSMdagi tadbir-marketing doirasida 'brend aktivatsiyasi' deganda nima tushuniladi?","a":["Tashrif buyuruvchilarni brend bilan to'g'ridan-to'g'ri muloqotga jalb qiluvchi interaktiv tadbir","Do'kon peshlavhasini yangisiga almashtirish","Yangi ijarachi bilan ijara shartnomasini imzolash"],"c":0,"why":"Brend aktivatsiyasi — bu brend bilan jonli o'zaro ta'sir tajribasini yaratuvchi interaktiv tadbirlar (aksiyalar, degustatsiyalar, instalyatsiyalar)."},"en":{"q":"What is meant by 'brand activation' in mall event marketing?","a":["An interactive event engaging visitors in direct contact with a brand","Replacing a store's signage with a new one","Signing a lease agreement with a new tenant"],"c":0,"why":"Brand activation refers to interactive events (promotions, sampling, installations) that create a live brand experience."}},{"id":"MK041","cat":"marketing","logic":false,"ru":{"q":"Какая цель проведения детских мастер-классов и семейных активаций в выходные дни в ТЦ?","a":["Увеличить dwell time семей и стимулировать сопутствующие покупки","Снизить арендную плату для детских магазинов","Заменить необходимость в охране торгового центра"],"c":0,"why":"Семейные активации удерживают семьи дольше в ТЦ, что повышает вероятность дополнительных покупок в разных магазинах."},"uz":{"q":"SSMda dam olish kunlari bolalar uchun mahorat darslari va oilaviy aktivatsiyalar o'tkazishdan maqsad nima?","a":["Oilalarning dwell time'ini oshirish va qo'shimcha xaridlarni rag'batlantirish","Bolalar do'konlari uchun ijara to'lovini kamaytirish","SSM xavfsizlik xizmatiga bo'lgan ehtiyojni yo'q qilish"],"c":0,"why":"Oilaviy aktivatsiyalar oilalarni SSMda uzoqroq ushlab turadi, bu esa turli do'konlarda qo'shimcha xarid qilish ehtimolini oshiradi."},"en":{"q":"What is the purpose of running children's workshops and family activations on weekends in a mall?","a":["Increase family dwell time and stimulate additional purchases","Reduce rent for children's stores","Replace the need for mall security staff"],"c":0,"why":"Family activations keep families in the mall longer, increasing the chance of additional purchases across multiple stores."}},{"id":"MK042","cat":"marketing","logic":false,"ru":{"q":"Что такое позиционирование торгового центра (mall positioning)?","a":["Уникальное место ТЦ в сознании потребителя относительно конкурентов","Физическое расположение ТЦ на карте города","Расположение якорных арендаторов на плане этажей"],"c":0,"why":"Позиционирование — это то, как ТЦ воспринимается целевой аудиторией по сравнению с конкурентами (например, премиум, семейный, дискаунтер)."},"uz":{"q":"Savdo markazi positioning (pozitsiyalash) tushunchasi nimani anglatadi?","a":["SSMning raqobatchilarga nisbatan iste'molchi ongidagi noyob o'rni","SSMning shahar xaritasidagi jismoniy joylashuvi","Langar ijarachilarning qavat rejasidagi joylashuvi"],"c":0,"why":"Positioning — SSMning maqsadli auditoriya tomonidan raqobatchilarga nisbatan qanday qabul qilinishini bildiradi (masalan, premium, oilaviy, diskaunter)."},"en":{"q":"What does 'mall positioning' mean?","a":["The mall's distinct place in consumers' minds relative to competitors","The mall's physical location on the city map","The arrangement of anchor tenants on the floor plan"],"c":0,"why":"Positioning refers to how the target audience perceives the mall compared to competitors (e.g., premium, family-oriented, discount)."}},{"id":"MK043","cat":"marketing","logic":false,"ru":{"q":"Какой из вариантов является примером успешного ребрендинга ТЦ, а не просто косметического обновления?","a":["Изменение концепции, tenant-mix и коммуникации под новую целевую аудиторию","Покраска фасада в новый цвет без изменения ассортимента арендаторов","Замена вывесок на входе без изменения стратегии"],"c":0,"why":"Настоящий ребрендинг затрагивает концепцию, состав арендаторов и позиционирование, а не только визуальные элементы."},"uz":{"q":"Quyidagilardan qaysi biri faqat kosmetik yangilanish emas, balki SSMning muvaffaqiyatli rebrendingiga misol bo'ladi?","a":["Yangi maqsadli auditoriya uchun kontseptsiya, tenant-mix va kommunikatsiyani o'zgartirish","Ijarachilar assortimentini o'zgartirmasdan fasadni yangi rangga bo'yash","Strategiyani o'zgartirmasdan kirishdagi peshlavhalarni almashtirish"],"c":0,"why":"Haqiqiy rebrending kontseptsiya, ijarachilar tarkibi va positioning'ni qamrab oladi, faqat vizual elementlarni emas."},"en":{"q":"Which of the following is an example of genuine mall rebranding rather than a cosmetic refresh?","a":["Redefining the concept, tenant mix, and messaging for a new target audience","Repainting the facade a new color without changing the tenant lineup","Replacing entrance signage without changing strategy"],"c":0,"why":"True rebranding involves reshaping the concept, tenant mix, and positioning, not just visual elements."}},{"id":"MK044","cat":"marketing","logic":false,"ru":{"q":"Какая метрика в социальных сетях ТЦ лучше всего отражает реальное вовлечение аудитории, а не просто охват?","a":["Engagement rate (лайки, комментарии, репосты относительно подписчиков)","Общее число подписчиков","Количество опубликованных постов за месяц"],"c":0,"why":"Engagement rate показывает активное взаимодействие аудитории с контентом, а не просто размер базы подписчиков."},"uz":{"q":"SSMning ijtimoiy tarmoqlaridagi qaysi ko'rsatkich faqat qamrovni emas, balki auditoriyaning real jalb qilinganligini yaxshiroq aks ettiradi?","a":["Engagement rate (layk, izoh, repostlarning obunachilarga nisbati)","Umumiy obunachilar soni","Oyda joylangan postlar soni"],"c":0,"why":"Engagement rate auditoriyaning kontent bilan faol o'zaro ta'sirini ko'rsatadi, shunchaki obunachilar bazasi hajmini emas."},"en":{"q":"Which social media metric best reflects genuine audience engagement rather than just reach?","a":["Engagement rate (likes, comments, shares relative to followers)","Total follower count","Number of posts published per month"],"c":0,"why":"Engagement rate reflects active audience interaction with content, not merely the size of the follower base."}},{"id":"MK045","cat":"marketing","logic":false,"ru":{"q":"Зачем ТЦ сотрудничает с локальными инфлюенсерами (микро-блогерами) в Instagram/Telegram?","a":["Для доверительного охвата целевой аудитории через рекомендации от лидеров мнений","Чтобы полностью заменить традиционную рекламу","Чтобы снизить размер маркетингового фонда"],"c":0,"why":"Микро-инфлюенсеры обеспечивают более доверительную коммуникацию с локальной аудиторией через рекомендации, чем прямая реклама."},"uz":{"q":"Nima uchun SSM Instagram/Telegram'dagi mahalliy influenserlar (mikro-blogerlar) bilan hamkorlik qiladi?","a":["Fikr yetakchilari tavsiyalari orqali maqsadli auditoriyaga ishonchli qamrov olish uchun","An'anaviy reklamani butunlay almashtirish uchun","Marketing fondi hajmini kamaytirish uchun"],"c":0,"why":"Mikro-influenserlar to'g'ridan-to'g'ri reklamaga qaraganda mahalliy auditoriya bilan tavsiyalar orqali ishonchliroq muloqot ta'minlaydi."},"en":{"q":"Why do malls partner with local influencers (micro-bloggers) on Instagram/Telegram?","a":["To reach the target audience with trusted recommendations from opinion leaders","To fully replace traditional advertising","To reduce the size of the marketing fund"],"c":0,"why":"Micro-influencers provide more trusted communication with local audiences through recommendations than direct advertising."}},{"id":"MK046","cat":"marketing","logic":false,"ru":{"q":"Что такое анализ зоны охвата (catchment area analysis) при оценке ТЦ?","a":["Определение географической территории, откуда приходит основная масса покупателей","Подсчёт числа этажей и общей площади ТЦ","Оценка средней зарплаты сотрудников арендаторов"],"c":0,"why":"Catchment area — это территория, с которой ТЦ привлекает большинство своих посетителей, обычно делится на первичную, вторичную и третичную зоны."},"uz":{"q":"SSMni baholashda 'qamrov hududi tahlili' (catchment area analysis) nima?","a":["Asosiy xaridorlar kelib chiquvchi geografik hududni aniqlash","SSM qavatlari soni va umumiy maydonini hisoblash","Ijarachi xodimlarining o'rtacha maoshini baholash"],"c":0,"why":"Catchment area — SSM asosiy tashrif buyuruvchilarini jalb qiladigan hudud bo'lib, odatda birlamchi, ikkilamchi va uchlamchi zonalarga bo'linadi."},"en":{"q":"What is 'catchment area analysis' when evaluating a mall?","a":["Identifying the geographic area from which most shoppers originate","Counting the number of floors and total mall area","Assessing tenant employees' average salary"],"c":0,"why":"The catchment area is the territory from which a mall draws most of its visitors, typically divided into primary, secondary, and tertiary zones."}},{"id":"MK047","cat":"marketing","logic":false,"ru":{"q":"Какой фактор обычно НЕ учитывается при делении catchment area на первичную и вторичную зоны?","a":["Время в пути до ТЦ и плотность населения","Цвет логотипа конкурирующего ТЦ","Наличие конкурирующих торговых объектов на пути"],"c":1,"why":"Зоны охвата определяются транспортной доступностью, демографией и конкуренцией, а не визуальными атрибутами бренда конкурента."},"uz":{"q":"Qamrov hududini birlamchi va ikkilamchi zonalarga bo'lishda odatda qaysi omil hisobga olinmaydi?","a":["SSMgacha bo'lgan yo'l vaqti va aholi zichligi","Raqobatchi SSM logotipining rangi","Yo'l bo'yidagi raqobatchi savdo obyektlari mavjudligi"],"c":1,"why":"Qamrov zonalari transport qulayligi, demografiya va raqobat asosida belgilanadi, raqobatchi brendning vizual atributlari asosida emas."},"en":{"q":"Which factor is typically NOT considered when dividing a catchment area into primary and secondary zones?","a":["Travel time to the mall and population density","The logo color of a competing mall","The presence of competing retail options along the route"],"c":1,"why":"Catchment zones are defined by travel accessibility, demographics, and competition, not a competitor's visual branding."}},{"id":"MK048","cat":"marketing","logic":false,"ru":{"q":"Какова цель конкурентного бенчмаркинга (competitor benchmarking) для управляющей компании ТЦ?","a":["Сравнить tenant-mix, трафик и цены с конкурентами для выявления своих преимуществ и слабых мест","Скопировать дизайн фасада конкурента без изменений","Установить одинаковые цены аренды со всеми конкурентами города"],"c":0,"why":"Бенчмаркинг помогает объективно оценить позицию ТЦ на рынке относительно конкурентов и выявить зоны для улучшения."},"uz":{"q":"SSM boshqaruv kompaniyasi uchun raqobatchilarni benchmarking qilishning maqsadi nima?","a":["Tenant-mix, tashrif va narxlarni raqobatchilar bilan solishtirib, kuchli va zaif tomonlarni aniqlash","Raqobatchi fasad dizaynini o'zgarishsiz nusxalash","Shahardagi barcha raqobatchilar bilan bir xil ijara narxini belgilash"],"c":0,"why":"Benchmarking SSMning bozordagi o'rnini raqobatchilarga nisbatan xolisona baholash va yaxshilash zonalarini aniqlashga yordam beradi."},"en":{"q":"What is the purpose of competitor benchmarking for a mall's management company?","a":["Compare tenant mix, traffic, and pricing with competitors to identify strengths and gaps","Copy a competitor's facade design without changes","Set identical rental rates to all competitors in the city"],"c":0,"why":"Benchmarking objectively assesses the mall's market position relative to competitors and highlights areas for improvement."}},{"id":"MK049","cat":"marketing","logic":false,"ru":{"q":"Что из перечисленного является ключевым показателем при бенчмаркинге эффективности арендаторов (tenant performance benchmarking)?","a":["Продажи с квадратного метра (sales per sq.m)","Количество окон в торговом зале","Цвет вывески магазина"],"c":0,"why":"Sales per sq.m — стандартный показатель, позволяющий сравнивать эффективность разных арендаторов независимо от размера площади."},"uz":{"q":"Ijarachilar samaradorligini benchmarking qilishda quyidagilardan qaysi biri asosiy ko'rsatkich hisoblanadi?","a":["Kvadrat metrga savdo (sales per sq.m)","Savdo zalidagi derazalar soni","Do'kon peshlavhasining rangi"],"c":0,"why":"Sales per sq.m — turli hajmdagi ijarachilarni maydonidan qat'i nazar solishtirish imkonini beruvchi standart ko'rsatkich."},"en":{"q":"Which of the following is a key metric in tenant performance benchmarking?","a":["Sales per square meter","The number of windows in the sales area","The color of the store's signage"],"c":0,"why":"Sales per sq.m is a standard metric that allows comparing tenant performance regardless of unit size."}},{"id":"MK050","cat":"marketing","logic":false,"ru":{"q":"Что представляет собой co-marketing (совместный маркетинг) между ТЦ и арендатором?","a":["Совместное финансирование и проведение рекламных кампаний, выгодных обеим сторонам","Полный перевод расходов на рекламу с ТЦ на арендатора","Запрет арендатору вести собственную рекламу"],"c":0,"why":"Co-marketing предполагает совместные усилия и бюджет ТЦ и арендатора для взаимовыгодного продвижения."},"uz":{"q":"SSM va ijarachi o'rtasidagi co-marketing (hamkorlikdagi marketing) nimani anglatadi?","a":["Ikkala tomonga foydali reklama kampaniyalarini birgalikda moliyalashtirish va o'tkazish","Reklama xarajatlarini to'liq SSMdan ijarachiga o'tkazish","Ijarachining o'z reklamasini olib borishini taqiqlash"],"c":0,"why":"Co-marketing SSM va ijarachining o'zaro manfaatli reklama uchun birgalikdagi harakat va byudjetini nazarda tutadi."},"en":{"q":"What does co-marketing between a mall and a tenant involve?","a":["Jointly funding and running promotional campaigns that benefit both parties","Shifting all advertising costs from the mall entirely onto the tenant","Prohibiting the tenant from running its own advertising"],"c":0,"why":"Co-marketing involves shared effort and budget between mall and tenant for mutually beneficial promotion."}},{"id":"MR001","cat":"market","logic":false,"ru":{"q":"Согласно классификации ICSC, какой тип торгового центра обслуживает жителей в радиусе 1.5-3 км с товарами повседневного спроса?","a":["Neighborhood center","Super-regional center","Outlet center"],"c":0,"why":"Neighborhood center рассчитан на ближайшую жилую застройку и товары первой необходимости."},"uz":{"q":"ICSC tasnifiga ko'ra, 1.5-3 km radiusdagi aholiga kundalik tovarlarni taqdim etuvchi markaz turi qanday?","a":["Neighborhood center","Super-regional center","Outlet center"],"c":0,"why":"Neighborhood center yaqin turar-joy hududiga va kundalik tovarlarga mo'ljallangan."},"en":{"q":"Under ICSC classification, which mall type serves residents within a 1.5-3 km radius with everyday convenience goods?","a":["Neighborhood center","Super-regional center","Outlet center"],"c":0,"why":"A neighborhood center serves the immediate surrounding area with daily necessities."}},{"id":"MR002","cat":"market","logic":false,"ru":{"q":"Что отличает community center от neighborhood center по площади и составу арендаторов?","a":["Больше GLA и шире ассортимент товаров","Нет продуктового якоря вообще","Только люксовые бренды"],"c":0,"why":"Community center крупнее и включает более широкий tenant mix, чем neighborhood center."},"uz":{"q":"Community center neighborhood center'dan maydoni va ijarachilar tarkibi bo'yicha nimasi bilan farqlanadi?","a":["GLA kattaroq, assortiment kengroq","Oziq-ovqat langari umuman yo'q","Faqat lyuks brendlar"],"c":0,"why":"Community center neighborhood center'dan kattaroq va kengroq tenant mix'ga ega."},"en":{"q":"How does a community center differ from a neighborhood center in size and tenant mix?","a":["Larger GLA and a wider tenant assortment","It has no grocery anchor at all","Only luxury brands are present"],"c":0,"why":"A community center is larger and features a broader tenant mix than a neighborhood center."}},{"id":"MR003","cat":"market","logic":false,"ru":{"q":"Какой формат ТРЦ по ICSC обычно имеет 2+ якоря и GLA от 40,000 до 80,000 м²?","a":["Regional center","Convenience center","Strip center"],"c":0,"why":"Regional center — крупный ТРЦ с несколькими якорями и GLA 40-80 тыс. м²."},"uz":{"q":"ICSC bo'yicha qaysi TRTS formati odatda 2+ langar va 40,000-80,000 m² GLA'ga ega?","a":["Regional center","Convenience center","Strip center"],"c":0,"why":"Regional center bir nechta langar va 40-80 ming m² GLA'ga ega yirik TRTSdir."},"en":{"q":"Which ICSC mall format typically has 2+ anchors and a GLA of 40,000-80,000 sqm?","a":["Regional center","Convenience center","Strip center"],"c":0,"why":"A regional center is a large mall with multiple anchors and 40,000-80,000 sqm of GLA."}},{"id":"MR004","cat":"market","logic":false,"ru":{"q":"Какой признак отличает super-regional center от regional center по стандартам ICSC?","a":["Свыше 80,000 м² GLA и 3+ якоря","Отсутствие развлечений","Расположение только в пригороде"],"c":0,"why":"Super-regional center превышает 80,000 м² и имеет минимум три якоря."},"uz":{"q":"ICSC standartlariga ko'ra super-regional center regional center'dan qaysi belgisi bilan farqlanadi?","a":["80,000 m² dan katta GLA va 3+ langar","Ko'ngilochar qismning yo'qligi","Faqat shahar chetida joylashuvi"],"c":0,"why":"Super-regional center 80,000 m² dan oshadi va kamida uchta langarga ega."},"en":{"q":"What distinguishes a super-regional center from a regional center under ICSC standards?","a":["Over 80,000 sqm of GLA and 3+ anchors","No entertainment component at all","Located exclusively in the suburbs"],"c":0,"why":"A super-regional center exceeds 80,000 sqm and has at least three anchors."}},{"id":"MR005","cat":"market","logic":false,"ru":{"q":"Что в терминологии ICSC означает термин GLA?","a":["Общая арендопригодная площадь","Типовой договор аренды","Уровень доступа с земли"],"c":0,"why":"GLA (Gross Leasable Area) — суммарная сдаваемая в аренду площадь."},"uz":{"q":"ICSC terminologiyasida GLA atamasi nimani anglatadi?","a":["Umumiy ijaraga yaroqli maydon","Standart ijara shartnomasi","Yer sathidan kirish darajasi"],"c":0,"why":"GLA (Gross Leasable Area) — ijaraga topshiriladigan umumiy maydon ko'rsatkichi."},"en":{"q":"In ICSC terminology, what does the term GLA stand for?","a":["Gross Leasable Area","General Lease Agreement","Ground Level Access"],"c":0,"why":"GLA (Gross Leasable Area) is the standard metric for total rentable floor space."}},{"id":"MR006","cat":"market","logic":false,"ru":{"q":"Что означает показатель footfall (трафик) в аналитике торговой недвижимости?","a":["Число посетителей объекта за период","Площадь пешеходных проходов","Средний чек покупателя"],"c":0,"why":"Footfall — метрика посещаемости, число визитов за определённый период."},"uz":{"q":"Savdo ko'chmas mulki tahlilida footfall (trafik) ko'rsatkichi nimani anglatadi?","a":["Ma'lum davrdagi tashrif buyuruvchilar soni","Piyodalar yo'laklariga ajratilgan maydon","Xaridorning o'rtacha cheki"],"c":0,"why":"Footfall — bu ma'lum davr uchun tashriflar sonini ko'rsatuvchi ko'rsatkich."},"en":{"q":"What does the metric 'footfall' mean in retail real estate analytics?","a":["The number of visitors to a property over a period","The floor area used for pedestrian walkways","The average transaction value per shopper"],"c":0,"why":"Footfall measures the number of visits to a property over a defined period."}},{"id":"MR007","cat":"market","logic":false,"ru":{"q":"Что такое conversion rate применительно к магазину в ТРЦ?","a":["Доля посетителей, совершивших покупку","Доля площади под кассы","Скорость обновления коллекции"],"c":0,"why":"Conversion rate показывает, какая доля посетителей стала покупателями."},"uz":{"q":"TRTSdagi do'konga nisbatan conversion rate nimani bildiradi?","a":["Xarid qilgan tashrif buyuruvchilar ulushi","Kassa zonasiga ajratilgan maydon ulushi","Kolleksiyani yangilash tezligi"],"c":0,"why":"Conversion rate tashrif buyuruvchilarning qanchasi xaridorga aylanganini ko'rsatadi."},"en":{"q":"What does 'conversion rate' mean for a store within a shopping mall?","a":["The share of visitors who make a purchase","The share of floor area used for checkout","The speed of seasonal collection changes"],"c":0,"why":"Conversion rate shows what proportion of visitors become buyers."}},{"id":"MR008","cat":"market","logic":false,"ru":{"q":"Что подразумевает термин 'omnichannel retail' в современном ритейле?","a":["Интеграцию офлайн и онлайн каналов продаж","Продажу только через маркетплейсы","Один канал связи с клиентом"],"c":0,"why":"Омниканальность объединяет физическую розницу и онлайн в единый клиентский путь."},"uz":{"q":"Zamonaviy chakana savdoda 'omnichannel retail' atamasi nimani anglatadi?","a":["Oflayn va onlayn kanallarni birlashtirish","Faqat marketpleyslar orqali sotish","Mijoz bilan bitta aloqa kanali"],"c":0,"why":"Omnikanallik jismoniy va onlayn savdoni yagona mijoz yo'liga birlashtiradi."},"en":{"q":"What does the term 'omnichannel retail' mean in modern retail practice?","a":["Integrating offline and online sales channels","Selling only through marketplaces","Using a single customer contact channel"],"c":0,"why":"Omnichannel retail unifies physical and online channels into one customer journey."}},{"id":"MR009","cat":"market","logic":false,"ru":{"q":"Что такое click-and-collect в омниканальной стратегии ТРЦ?","a":["Онлайн-заказ с самовывозом из магазина","Программа лояльности онлайн-клиентов","Доставка товара дронами"],"c":0,"why":"Click-and-collect объединяет онлайн-заказ и офлайн-получение товара."},"uz":{"q":"TRTSning omnikanal strategiyasida click-and-collect nima?","a":["Onlayn buyurtma va do'kondan o'zi olib ketish","Onlayn xaridorlar uchun sodiqlik dasturi","Tovarni dronlar bilan yetkazish"],"c":0,"why":"Click-and-collect onlayn buyurtma va oflayn olishni birlashtiradi."},"en":{"q":"What is 'click-and-collect' in the context of a mall's omnichannel strategy?","a":["Online order picked up at the physical store","A loyalty program for online shoppers","Delivery of goods exclusively by drones"],"c":0,"why":"Click-and-collect combines online ordering with in-store pickup."}},{"id":"MR010","cat":"market","logic":false,"ru":{"q":"Почему e-commerce не вытесняет офлайн-ритейл полностью, а формирует гибридную модель?","a":["Покупатели ценят примерку и мгновенное владение товаром","Онлайн-магазины не принимают оплату картой","Продажа одежды онлайн запрещена законом"],"c":0,"why":"Тактильный опыт и немедленное владение товаром остаются преимуществом офлайна."},"uz":{"q":"E-commerce oflayn savdoni to'liq siqib chiqarmasdan, gibrid modelni shakllantirishining sababi nima?","a":["Xaridorlar kiyib ko'rish va tovarni darhol olishni qadrlaydi","Onlayn do'konlar karta orqali to'lovni qabul qilmaydi","Onlayn kiyim sotish qonun bilan taqiqlangan"],"c":0,"why":"Kiyib ko'rish va tovarni darhol olish imkoniyati oflaynning ustunligicha qolmoqda."},"en":{"q":"Why does e-commerce not fully replace offline retail but instead create a hybrid model?","a":["Shoppers value fitting and instant product ownership","Online stores cannot process card payments","Selling apparel online is banned by law"],"c":0,"why":"The ability to try on products and take instant ownership remains offline retail's advantage."}},{"id":"MR011","cat":"market","logic":false,"ru":{"q":"Какую роль ТРЦ всё чаще берут на себя, конкурируя с e-commerce?","a":["Центры впечатлений с развлечениями и гастрономией","Полный отказ от продажи одежды","Сокращение часов работы"],"c":0,"why":"Чтобы конкурировать с онлайн-удобством, ТРЦ делают ставку на офлайн-впечатления."},"uz":{"q":"TRTSlar e-commerce bilan raqobatlashar ekan, tobora qanday rolni o'z zimmasiga olmoqda?","a":["Ko'ngilochar va gastronomiya markazlariga aylanish","Kiyim sotishdan butunlay voz kechish","Ish soatlarini qisqartirish"],"c":0,"why":"Onlayn qulaylik bilan raqobatlashish uchun TRTSlar taassurotlarga urg'u bermoqda."},"en":{"q":"What role are modern malls increasingly adopting to compete with e-commerce?","a":["Becoming experience centers with entertainment and dining","Abandoning apparel sales entirely","Cutting their operating hours"],"c":0,"why":"To compete with online convenience, malls are leaning into in-person experiences."}},{"id":"MR012","cat":"market","logic":false,"ru":{"q":"Что такое 'showrooming' как поведенческий тренд покупателей?","a":["Тестирует товар офлайн, покупает дешевле онлайн","Ритейлер устраивает показ мод в магазине","Заказ товара только по каталогу"],"c":0,"why":"Showrooming — использование магазина как демозала перед онлайн-покупкой."},"uz":{"q":"'Showrooming' xaridorlar xulq-atvor trendi sifatida nimani anglatadi?","a":["Tovarni oflayn sinab, arzonroq onlayn oladi","Sotuvchi do'konda moda shousi o'tkazadi","Faqat katalog orqali buyurtma berish"],"c":0,"why":"Showrooming — do'kondan onlayn xariddan oldin namoyish maydoni sifatida foydalanish."},"en":{"q":"What does 'showrooming' mean as a consumer behavior trend?","a":["Testing a product offline, then buying cheaper online","A retailer staging a fashion show in-store","Ordering products purely from a catalog"],"c":0,"why":"Showrooming means using a physical store as a demo space before buying online."}},{"id":"MR013","cat":"market","logic":false,"ru":{"q":"Что такое 'webrooming' (ROPO — research online, purchase offline)?","a":["Изучение товара онлайн, покупка в магазине","Онлайн-магазин в виде виртуальной комнаты","Отказ от посещения магазинов"],"c":0,"why":"Webrooming/ROPO — обратный showrooming: исследование в сети, покупка офлайн."},"uz":{"q":"'Webrooming' (ROPO — research online, purchase offline) nimani anglatadi?","a":["Tovarni onlayn o'rganib, do'konda sotib olish","Virtual xona ko'rinishidagi onlayn do'kon","Do'konlarga tashrifdan butunlay voz kechish"],"c":0,"why":"Webrooming/ROPO showrooming'ga teskari: tadqiqot onlayn, xarid oflayn."},"en":{"q":"What does 'webrooming' (or ROPO — research online, purchase offline) mean?","a":["Researching a product online, then buying in-store","An online store designed as a virtual showroom","Completely avoiding physical store visits"],"c":0,"why":"Webrooming/ROPO is the reverse of showrooming: research online, purchase offline."}},{"id":"MR014","cat":"market","logic":false,"ru":{"q":"В чём принципиальное отличие street retail от торговли в ТРЦ?","a":["Отдельные помещения с прямым входом с улицы","Обязательный общий фуд-корт","Единый график работы для всех"],"c":0,"why":"Street retail — формат с отдельным входом с улицы, без общей инфраструктуры ТРЦ."},"uz":{"q":"Street retail formatining TRTSdagi savdodan tubdan farqi nimada?","a":["Ko'chadan to'g'ridan-to'g'ri kirish bilan alohida joy","Majburiy umumiy fud-kort","Barcha uchun yagona ish jadvali"],"c":0,"why":"Street retail — ko'chadan alohida kirishi bo'lgan, umumiy TRTS infratuzilmasisiz format."},"en":{"q":"What is the fundamental difference between street retail and mall-based retail?","a":["Standalone units with direct street access","A mandatory shared food court","A single operating schedule for all"],"c":0,"why":"Street retail consists of standalone units with direct street access, without shared mall infrastructure."}},{"id":"MR015","cat":"market","logic":false,"ru":{"q":"Какое ключевое преимущество street retail перед ТРЦ отмечают ритейлеры для бренд-присутствия?","a":["Полный контроль над фасадом и вывеской","Автоматически более низкая ставка","Гарантированный трафик от соседей"],"c":0,"why":"В street retail бренд контролирует внешний вид точки без единых правил ТРЦ."},"uz":{"q":"Chakana sotuvchilar brend mavjudligi uchun street retail'ning TRTSga nisbatan ustunligini qanday belgilaydi?","a":["Fasad va lavhani to'liq nazorat qilish","Avtomatik ravishda pastroq stavka","Qo'shnilardan kafolatlangan trafik"],"c":0,"why":"Street retailda brend nuqtaning ko'rinishini yagona TRTS qoidalarisiz to'liq nazorat qiladi."},"en":{"q":"What key advantage do retailers cite for street retail over malls in terms of brand presence?","a":["Full control over facade and signage","Automatically lower rental rates","Guaranteed traffic from neighboring stores"],"c":0,"why":"In street retail, brands control their storefront appearance without mall-wide design rules."}},{"id":"MR016","cat":"market","logic":false,"ru":{"q":"Какой риск чаще всего связывают со street retail по сравнению с ТРЦ?","a":["Зависимость от локального пешеходного потока","Обязательное участие в акциях центра","Единые часы работы для всех"],"c":0,"why":"Street retail зависит от органического трафика конкретной локации, а не от единого управления."},"uz":{"q":"Street retail TRTSga nisbatan ko'pincha qanday xavf bilan bog'lanadi?","a":["Mahalliy piyodalar oqimiga bog'liqlik","Markazning aksiyalarida majburiy ishtirok","Barcha uchun yagona ish soatlari"],"c":0,"why":"Street retail mahalliy piyodalar oqimiga bog'liq, TRTSdagidek boshqariladigan trafik yo'q."},"en":{"q":"What risk is most commonly associated with street retail compared to mall-based retail?","a":["Dependence on organic local foot traffic","Mandatory participation in mall promotions","Fixed operating hours enforced for all"],"c":0,"why":"Street retail relies on a location's organic foot traffic rather than managed mall-wide traffic."}},{"id":"MR017","cat":"market","logic":false,"ru":{"q":"На каком этапе девелопмента ТРЦ определяется концепция и целевая аудитория?","a":["На предпроектной стадии","После завершения строительства","Через год после открытия"],"c":0,"why":"Концепция закладывается на самой ранней стадии проекта."},"uz":{"q":"TRTS devolopmentining qaysi bosqichida kontseptsiya va maqsadli auditoriya belgilanadi?","a":["Loyihalashtirishdan oldingi bosqichda","Qurilish tugagach","Ochilgandan bir yil o'tib"],"c":0,"why":"Kontseptsiya loyihaning eng dastlabki bosqichida belgilanadi."},"en":{"q":"At which stage of mall development is the concept and target audience defined?","a":["At the pre-design stage","After construction is completed","A year after opening"],"c":0,"why":"The concept is established at the earliest stage of the project."}},{"id":"MR018","cat":"market","logic":false,"ru":{"q":"Почему pre-leasing с якорями часто начинается до завершения проектирования здания?","a":["Требования якорей влияют на архитектуру","Закон обязывает подписать всех за год","Банки не финансируют без 100% лизинга"],"c":0,"why":"Технические требования якорей нужно учесть ещё на стадии проектирования."},"uz":{"q":"Nega langarlar bilan pre-leasing ko'pincha loyihalashtirish tugamasdan boshlanadi?","a":["Langarlar talabi arxitekturaga ta'sir qiladi","Qonun bir yil oldin imzolashni talab qiladi","Banklar 100% lizingsiz moliyalashtirmaydi"],"c":0,"why":"Langarlarning texnik talablari loyihalashtirish bosqichida hisobga olinishi kerak."},"en":{"q":"Why does anchor pre-leasing often begin before the building design is finalized?","a":["Anchor requirements shape the building's architecture","Law requires signing tenants a year ahead","Banks won't finance without full pre-leasing"],"c":0,"why":"Anchor technical requirements must be factored in at the design stage."}},{"id":"MR019","cat":"market","logic":false,"ru":{"q":"Какова цель этапа 'soft opening' перед полноценным открытием ТРЦ?","a":["Протестировать процессы при малом потоке","Распродать товар по себестоимости","Передать здание инвестору"],"c":0,"why":"Soft opening выявляет операционные проблемы до масштабного открытия."},"uz":{"q":"TRTSning to'liq ochilishidan oldingi 'soft opening' bosqichining maqsadi nima?","a":["Kam trafikda jarayonlarni sinab ko'rish","Tovarlarni tannarxda sotish","Binoni investorga topshirish"],"c":0,"why":"Soft opening to'liq ochilishdan oldin operatsion muammolarni aniqlaydi."},"en":{"q":"What is the purpose of a 'soft opening' phase before a mall's grand opening?","a":["Testing processes under limited visitor flow","Selling merchandise at cost price","Transferring the building to the investor"],"c":0,"why":"A soft opening reveals operational issues before the full-scale grand opening."}},{"id":"MR020","cat":"market","logic":false,"ru":{"q":"Какой этап ТРЦ обычно занимает больше всего времени между открытием и полным заполнением?","a":["Lease-up period (стабилизация лизинга)","Демонтаж временных конструкций","Согласование логотипа УК"],"c":0,"why":"Lease-up period — период постепенного достижения стабильной заполняемости."},"uz":{"q":"TRTSning ochilishi va to'liq bandligi orasida qaysi bosqich odatda eng ko'p vaqt oladi?","a":["Lease-up period (lizing stabillashuvi)","Vaqtinchalik konstruksiyalarni demontaj qilish","Boshqaruv kompaniyasi logotipini kelishish"],"c":0,"why":"Lease-up period — barqaror bandlikka bosqichma-bosqich erishish davri."},"en":{"q":"Which stage typically takes the longest between a mall's opening and reaching full occupancy?","a":["The lease-up period","Dismantling temporary construction structures","Approving the management company's logo"],"c":0,"why":"The lease-up period is the phase of gradually reaching stabilized occupancy."}},{"id":"MR021","cat":"market","logic":false,"ru":{"q":"Чем международный якорный бренд привлекателен для девелопера по сравнению с локальным?","a":["Узнаваемость, генерирующая трафик","Гарантированно более низкая ставка","Нет требований к дизайну витрины"],"c":0,"why":"Международные бренды приносят готовую узнаваемость, снижая риск для девелопера."},"uz":{"q":"Xalqaro langar brend mahalliy analogiga nisbatan devoloper uchun nima bilan jozibali?","a":["Trafik yaratuvchi tanilganlik","Kafolatlangan pastroq stavka","Vitrina dizayniga talab yo'qligi"],"c":0,"why":"Xalqaro brendlar tayyor tanilganlikni olib kelib, devoloper xavfini kamaytiradi."},"en":{"q":"Why is an international anchor brand typically attractive to a developer compared to a local one?","a":["Recognition that generates destination traffic","A guaranteed lower rental rate","No storefront design requirements"],"c":0,"why":"International brands bring built-in recognition that lowers the developer's risk."}},{"id":"MR022","cat":"market","logic":false,"ru":{"q":"Какое преимущество локальных брендов используют девелоперы для уникальности ТРЦ?","a":["Гибкие условия и адаптация под потребителя","Выше узнаваемость, чем у сетей","Не нужен договор аренды"],"c":0,"why":"Локальные бренды гибче в переговорах и лучше знают вкусы местной аудитории."},"uz":{"q":"Devoloperlar TRTS o'ziga xosligi uchun mahalliy brendlarning qaysi ustunligidan foydalanadi?","a":["Moslashuvchan shartlar va mahalliy moslashuv","Tarmoqlardan yuqori tanilganlik","Ijara shartnomasi shart emas"],"c":0,"why":"Mahalliy brendlar muzokaralarda moslashuvchanroq va mahalliy didni yaxshi biladi."},"en":{"q":"What advantage of local brands do developers often leverage to differentiate a mall?","a":["Flexible terms and local consumer fit","Higher recognition than international chains","No lease agreement is required"],"c":0,"why":"Local brands tend to be more flexible in negotiations and better attuned to local tastes."}},{"id":"MR023","cat":"market","logic":false,"ru":{"q":"Что означает термин 'master franchise' при выходе бренда на рынок Узбекистана?","a":["Партнёр получает эксклюзив на страну","Бренд управляется только головным офисом","Договор заключается с производителем"],"c":0,"why":"Мастер-франшиза даёт локальному оператору эксклюзивное право на страну."},"uz":{"q":"Brend O'zbekiston bozoriga chiqishida 'master franchise' atamasi nimani anglatadi?","a":["Hamkor mamlakat bo'yicha eksklyuziv oladi","Brend faqat bosh ofis tomonidan boshqariladi","Shartnoma ishlab chiqaruvchi bilan tuziladi"],"c":0,"why":"Master franshiza mahalliy operatorga mamlakat bo'yicha eksklyuziv huquq beradi."},"en":{"q":"What does 'master franchise' mean when a brand enters the Uzbekistan market?","a":["A partner gets exclusive rights for the country","The brand is run solely by headquarters","The lease is signed with the manufacturer"],"c":0,"why":"A master franchise gives a local operator exclusive rights within the country."}},{"id":"MR024","cat":"market","logic":false,"ru":{"q":"Какая фаза рыночного цикла характеризуется избытком предложения и падением ставок аренды?","a":["Рецессия / спад","Восстановление","Экспансия"],"c":0,"why":"В рецессии спрос отстаёт от предложения, растёт вакантность и падают ставки."},"uz":{"q":"Bozor siklining qaysi fazasi taklif ortiqchaligi va ijara stavkalari pasayishi bilan tavsiflanadi?","a":["Retsessiya / pasayish","Tiklanish","Kengayish"],"c":0,"why":"Retsessiyada talab taklifdan orqada qoladi, bo'sh joylar oshib, stavkalar tushadi."},"en":{"q":"Which market cycle phase is characterized by oversupply and falling rental rates?","a":["Recession","Recovery","Expansion"],"c":0,"why":"In a recession, demand lags supply, driving up vacancy and lowering rents."}},{"id":"MR025","cat":"market","logic":false,"ru":{"q":"Какая фаза цикла обычно предшествует активному строительству новых ТРЦ?","a":["Экспансия — рост спроса и ставок","Рецессия — рост вакантности","Стагнация без сделок"],"c":0,"why":"Строительство активизируется в фазе экспансии на фоне роста спроса и ставок."},"uz":{"q":"Bozor siklining qaysi fazasi odatda yangi TRTSlar faol qurilishidan oldin keladi?","a":["Kengayish — talab va stavkalar o'sishi","Retsessiya — bo'sh joylar o'sishi","Bitimlarsiz stagnatsiya"],"c":0,"why":"Faol qurilish talab va stavkalar o'sib borayotgan kengayish fazasida boshlanadi."},"en":{"q":"Which cycle phase typically precedes a new wave of active mall construction?","a":["Expansion — rising demand and rents","Recession — rising vacancy","Stagnation with no transactions"],"c":0,"why":"Active construction ramps up during expansion, as demand and rents rise."}},{"id":"MR026","cat":"market","logic":false,"ru":{"q":"Что является типичным индикатором фазы 'пик рынка' в коммерческой недвижимости?","a":["Минимальная вакантность, максимальные ставки","Массовое закрытие объектов","Отсутствие интереса инвесторов"],"c":0,"why":"Пик цикла — максимальные ставки и минимальная вакантность перед насыщением рынка."},"uz":{"q":"Tijorat ko'chmas mulkida 'bozor cho'qqisi' fazasining odatiy ko'rsatkichi qaysi?","a":["Minimal bo'sh joy, maksimal stavkalar","Obyektlarning ommaviy yopilishi","Investorlar qiziqishining yo'qligi"],"c":0,"why":"Sikl cho'qqisi eng yuqori stavkalar va minimal bo'sh joylar bilan tavsiflanadi."},"en":{"q":"Which of the following is a typical indicator of the 'market peak' phase in commercial real estate?","a":["Minimal vacancy and peak rental rates","Widespread closures of retail properties","A complete lack of investor interest"],"c":0,"why":"The market peak is marked by the lowest vacancy and highest rents before saturation."}},{"id":"MR027","cat":"market","logic":false,"ru":{"q":"Какой фактор считают основным драйвером роста рынка торговой недвижимости Ташкента?","a":["Рост доходов при низкой обеспеченности ТРЦ","Исчезновение уличной торговли","Запрет на новое строительство"],"c":0,"why":"Низкая обеспеченность качественными площадями на фоне роста доходов стимулирует рынок."},"uz":{"q":"Toshkent savdo ko'chmas mulki bozori o'sishining asosiy omili sifatida nima ko'rsatiladi?","a":["TRTS bilan ta'minlanganlik pastligi fonida daromad o'sishi","Ko'cha savdosining yo'qolishi","Yangi qurilishga taqiq"],"c":0,"why":"Sifatli maydonlar bilan past ta'minlanganlik daromad o'sishi fonida bozorni rag'batlantiradi."},"en":{"q":"What factor is considered the main driver of Tashkent's retail real estate market growth?","a":["Rising incomes amid low mall supply per capita","The disappearance of street retail","A ban on new construction"],"c":0,"why":"Low quality retail supply per capita combined with rising incomes is fueling market growth."}},{"id":"MR028","cat":"market","logic":false,"ru":{"q":"Какие районы Ташкента чаще всего приоритетны для новых ТРЦ благодаря плотности и транспорту?","a":["Юнусабад, Мирзо-Улугбек, Чиланзар","Только Ичан-Кала","Только промзоны за городом"],"c":0,"why":"Эти районы плотнонаселены и обладают развитой транспортной сетью."},"uz":{"q":"Zichlik va transport tufayli devoloperlar Toshkentning qaysi tumanlarini ustuvor deb hisoblaydi?","a":["Yunusobod, Mirzo Ulug'bek, Chilonzor","Faqat Ichan-Qal'a","Faqat shahar tashqarisidagi sanoat zonalari"],"c":0,"why":"Bu tumanlar zich aholi va rivojlangan transport tarmog'iga ega."},"en":{"q":"Which Tashkent districts are most often prioritized for new malls due to density and transport access?","a":["Yunusabad, Mirzo Ulugbek, Chilanzar","Only the Ichan-Kala historic center","Only industrial zones outside the city"],"c":0,"why":"These districts are densely populated with strong transport networks."}},{"id":"MR029","cat":"market","logic":false,"ru":{"q":"Как изменился профиль потребителя в Ташкенте с точки зрения ожиданий от ТРЦ?","a":["Выросли требования к сервису и брендам","Потребители не интересуются брендами","Спрос сместился на оптовые рынки"],"c":0,"why":"Рост доходов повысил требовательность ташкентского потребителя."},"uz":{"q":"Toshkentda iste'molchi profili TRTSlardan kutilayotgan narsalar bo'yicha qanday o'zgardi?","a":["Xizmat va brendlarga talab oshdi","Iste'molchilar brendlarga qiziqmaydi","Talab ulgurji bozorlarga siljidi"],"c":0,"why":"Daromadlar o'sishi Toshkent iste'molchisining talabchanligini oshirdi."},"en":{"q":"How has the Tashkent consumer profile shifted in terms of expectations from malls?","a":["Expectations for service and brands have risen","Consumers have lost interest in brands","Demand has shifted to wholesale markets"],"c":0,"why":"Rising incomes have raised the sophistication of Tashkent consumers."}},{"id":"MR030","cat":"market","logic":false,"ru":{"q":"Чем рынок торговой недвижимости Узбекистана отличается от зрелых рынков Европы по насыщенности ТРЦ?","a":["Ниже обеспеченность площадями на 1000 жителей","Нет спроса на международные бренды","Запрет аренды иностранцам"],"c":0,"why":"GLA на 1000 жителей в Узбекистане ниже, чем в развитых европейских рынках."},"uz":{"q":"TRTS to'yinganligi bo'yicha O'zbekiston bozori Yevropa bozorlaridan nima bilan farqlanadi?","a":["1000 kishiga maydon ta'minoti pastroq","Xalqaro brendlarga talab yo'q","Chet elliklarga ijara taqiqlangan"],"c":0,"why":"O'zbekistonda 1000 kishiga GLA rivojlangan Yevropa bozorlariga qaraganda past."},"en":{"q":"How does Uzbekistan's retail market differ from mature European markets in terms of mall saturation?","a":["Lower retail space supply per 1,000 residents","No demand for international brands","A ban on leasing to foreign firms"],"c":0,"why":"GLA per 1,000 residents in Uzbekistan is lower than in developed European markets."}},{"id":"MR031","cat":"market","logic":false,"ru":{"q":"Что такое trade area (торговая зона) объекта при анализе рынка ТРЦ?","a":["Зона, откуда приходит основной поток посетителей","Граница земельного участка","Площадь под торговлю внутри здания"],"c":0,"why":"Trade area — зона охвата, откуда приходит большинство покупателей объекта."},"uz":{"q":"TRTS bozorini tahlil qilishda trade area (savdo zonasi) nima?","a":["Asosiy tashrif buyuruvchilar kelib chiqadigan hudud","Yer uchastkasi chegarasi","Bino ichidagi savdo maydoni"],"c":0,"why":"Trade area — obyektga xaridorlarning aksariyati kelib chiquvchi qamrov zonasi."},"en":{"q":"What is the 'trade area' of a property in shopping mall market analysis?","a":["The zone from which most visitors originate","The legal boundary of the land plot","The retail floor area inside the building"],"c":0,"why":"The trade area is the catchment zone from which most shoppers originate."}},{"id":"MR032","cat":"market","logic":false,"ru":{"q":"Что такое каннибализация при открытии нового ТРЦ в городе?","a":["Переток трафика от старых объектов к новому","Рост продаж во всех объектах сразу","Закрытие всех конкурентов"],"c":0,"why":"Каннибализация — новый объект оттягивает покупателей у существующих, не создавая новый спрос."},"uz":{"q":"Shaharda yangi TRTS ochilishida kannibalizatsiya nima?","a":["Trafikning eski obyektlardan yangisiga o'tishi","Barcha obyektlarda savdoning bir vaqtda o'sishi","Barcha raqobatchilarning yopilishi"],"c":0,"why":"Kannibalizatsiya yangi talab yaratmasdan mavjud obyektlardan xaridor tortib olishdir."},"en":{"q":"What does 'cannibalization' mean when a new mall opens in a city?","a":["Traffic shifts from older properties to the new one","Sales grow across all properties at once","All competing centers are forced to close"],"c":0,"why":"Cannibalization means the new property draws customers away from existing ones without creating new demand."}},{"id":"MR033","cat":"market","logic":false,"ru":{"q":"Какой показатель используют для сравнения арендных ставок разных ТРЦ независимо от площади?","a":["Ставка аренды за квадратный метр","Сумма всех подписанных договоров","Количество этажей здания"],"c":0,"why":"Ставка за м² — универсальный показатель для сравнения объектов разного масштаба."},"uz":{"q":"Turli TRTSlarning ijara stavkalarini maydonidan qat'i nazar solishtirish uchun qaysi ko'rsatkich ishlatiladi?","a":["Bir kvadrat metr uchun ijara stavkasi","Barcha shartnomalarning umumiy summasi","Binoning qavatlar soni"],"c":0,"why":"M² uchun stavka turli miqyosdagi obyektlarni solishtirish imkonini beradi."},"en":{"q":"Which metric is used to compare rental rates across different malls regardless of size?","a":["Rent per square meter","The total sum of all signed leases","The number of floors in the building"],"c":0,"why":"Rent per sqm is a universal metric for comparing properties of different scale."}},{"id":"MR034","cat":"market","logic":false,"ru":{"q":"Что означает 'turnover rent' в договорах с арендаторами ТРЦ?","a":["Процент от выручки сверх базовой ставки","Только фиксированная сумма без учёта продаж","УК забирает всю выручку арендатора"],"c":0,"why":"Turnover rent привязывает часть аренды к обороту магазина."},"uz":{"q":"TRTS ijarachilar shartnomalarida 'turnover rent' nimani anglatadi?","a":["Bazaviy stavkadan tashqari tushumdan foiz","Faqat qat'iy summa, savdosiz","Boshqaruv kompaniyasi butun tushumni oladi"],"c":0,"why":"Turnover rent ijara to'lovining bir qismini do'kon aylanmasiga bog'laydi."},"en":{"q":"What does 'turnover rent' mean in mall tenant lease agreements?","a":["A percentage of revenue on top of the base rent","A fixed amount regardless of sales","The landlord takes all tenant revenue"],"c":0,"why":"Turnover rent ties part of the rent to the tenant's store sales."}},{"id":"MR035","cat":"market","logic":false,"ru":{"q":"Почему консалтинговые компании вроде CASE Advisory важны для рынка ТРЦ Узбекистана?","a":["Приносят международную экспертизу по лизингу и tenant mix","Заменяют органы выдачи разрешений","Единственные, кому разрешено сдавать площади"],"c":0,"why":"Консультанты передают международный опыт, снижая риски девелопмента на формирующемся рынке."},"uz":{"q":"Nega CASE Advisory kabi konsalting kompaniyalari O'zbekiston TRTS bozori uchun muhim?","a":["Lizing va tenant mix bo'yicha xalqaro tajriba olib kiradi","Ruxsat beruvchi davlat organlarini almashtiradi","Maydon ijaraga berishga ruxsat etilgan yagona kompaniya"],"c":0,"why":"Konsultantlar xalqaro tajribani olib kirib, shakllanayotgan bozorda devolopment xavflarini kamaytiradi."},"en":{"q":"Why are consulting firms like CASE Advisory important for Uzbekistan's mall market?","a":["They bring international expertise on leasing and tenant mix","They replace government permitting bodies","They are the only firms allowed to lease space"],"c":0,"why":"Consultants transfer international expertise, reducing development risk in an emerging market."}},{"id":"MR036","cat":"market","logic":false,"ru":{"q":"Какой GLA (арендопригодная площадь) обычно характерен для суперрегионального торгового центра?","a":["Более 80 000 м²","5 000–10 000 м²","До 3 000 м²"],"c":0,"why":"Суперрегиональные ТРЦ имеют самую крупную площадь среди всех форматов, обычно свыше 80 000 м²."},"uz":{"q":"Super-mintaqaviy savdo markazi uchun odatda qanday GLA (ijaraga yaroqli maydon) xos?","a":["80 000 m² dan ortiq","5 000–10 000 m²","3 000 m² gacha"],"c":0,"why":"Super-mintaqaviy MMlar barcha formatlar orasida eng katta maydonga, odatda 80 000 m² dan ortiqqa ega."},"en":{"q":"Which GLA range is typical for a super-regional shopping center?","a":["Over 80,000 sq m","5,000–10,000 sq m","Up to 3,000 sq m"],"c":0,"why":"Super-regional centers are the largest format, typically exceeding 80,000 sq m of GLA."}},{"id":"MR037","cat":"market","logic":false,"ru":{"q":"Каков типичный радиус охвата (catchment area) для регионального торгового центра?","a":["8–24 км","1–2 км","500 метров"],"c":0,"why":"Региональные ТРЦ рассчитаны на покупателей, приезжающих издалека, с радиусом охвата 8–24 км."},"uz":{"q":"Mintaqaviy savdo markazi uchun odatiy tortishuv zonasi (catchment area) radiusi qanday?","a":["8–24 km","1–2 km","500 metr"],"c":0,"why":"Mintaqaviy MMlar uzoqdan keladigan xaridorlarga mo'ljallangan bo'lib, 8–24 km radiusga ega."},"en":{"q":"What is a typical primary catchment radius for a regional shopping center?","a":["8–24 km","1–2 km","500 meters"],"c":0,"why":"Regional centers draw shoppers from a wide area, typically within an 8–24 km radius."}},{"id":"MR038","cat":"market","logic":false,"ru":{"q":"Что отличает convenience center (центр повседневного спроса) от community center?","a":["Меньшую площадь и фокус на товарах первой необходимости","Наличие крупного якорного гипермаркета","Обязательное наличие кинотеатра"],"c":0,"why":"Convenience center — самый малый формат, ориентированный на ежедневные покупки рядом с домом."},"uz":{"q":"Convenience center (kundalik ehtiyoj markazi) community center'dan nimasi bilan farq qiladi?","a":["Kichikroq maydoni va kundalik tovarlarga yo'nalganligi","Yirik gipermarket langar arendatorining mavjudligi","Kinoteatrning majburiy mavjudligi"],"c":0,"why":"Convenience center eng kichik format bo'lib, uy yaqinidagi kundalik xaridlarga mo'ljallangan."},"en":{"q":"What distinguishes a convenience center from a community center?","a":["Smaller size focused on daily necessity goods","A large hypermarket anchor tenant","A mandatory multiplex cinema"],"c":0,"why":"Convenience centers are the smallest format, serving daily, close-to-home shopping needs."}},{"id":"MR039","cat":"market","logic":false,"ru":{"q":"Какой якорный арендатор наиболее типичен для neighborhood center (районного центра)?","a":["Супермаркет продуктов повседневного спроса","Универмаг класса люкс","Мультиплекс с 15 залами"],"c":0,"why":"Районные центры строятся вокруг супермаркета как основного генератора трафика."},"uz":{"q":"Neighborhood center (mahalla markazi) uchun eng odatiy langar arendator qaysi?","a":["Kundalik oziq-ovqat supermarketi","Hashamatli universmag","15 zalli multipleks kinoteatr"],"c":0,"why":"Mahalla markazlari asosiy trafik generatori sifatida supermarket atrofida quriladi."},"en":{"q":"Which anchor tenant is most typical for a neighborhood center?","a":["A daily-needs supermarket","A luxury department store","A 15-screen multiplex cinema"],"c":0,"why":"Neighborhood centers are built around a supermarket as the primary traffic driver."}},{"id":"MR040","cat":"market","logic":false,"ru":{"q":"В чём главная особенность формата аутлет-центра (outlet center)?","a":["Продажа брендовых товаров прошлых коллекций со скидкой","Расположение исключительно в центре города","Отсутствие парковочных мест"],"c":0,"why":"Аутлет-центры специализируются на продаже товаров известных брендов прошлых сезонов по сниженным ценам."},"uz":{"q":"Outlet-markaz (outlet center) formatining asosiy xususiyati nimada?","a":["Brendlarning o'tgan kolleksiyalarini chegirma bilan sotish","Faqat shahar markazida joylashishi","Avtoturargoh joylarining yo'qligi"],"c":0,"why":"Outlet-markazlar mashhur brendlarning o'tgan mavsum tovarlarini arzon narxda sotishga ixtisoslashgan."},"en":{"q":"What is the core feature of the outlet center format?","a":["Selling branded past-season goods at a discount","Being located exclusively in city centers","Having no on-site parking"],"c":0,"why":"Outlet centers specialize in selling branded, past-season merchandise at reduced prices."}},{"id":"MR041","cat":"market","logic":false,"ru":{"q":"Чем factory outlet отличается от classic outlet-центра в международной практике?","a":["Товар продаётся напрямую от производителя, минуя ритейлера","Он всегда расположен внутри жилого комплекса","В нём отсутствуют бренды одежды"],"c":0,"why":"Factory outlet предполагает прямые продажи от фабрики-производителя без посредника-ритейлера."},"uz":{"q":"Xalqaro amaliyotda factory outlet klassik outlet-markazdan nimasi bilan farq qiladi?","a":["Tovar chakana sotuvchisiz to'g'ridan-to'g'ri ishlab chiqaruvchidan sotiladi","U doim turar-joy majmuasi ichida joylashadi","Unda kiyim-kechak brendlari bo'lmaydi"],"c":0,"why":"Factory outlet ishlab chiqaruvchi zavoddan vositachisiz to'g'ridan-to'g'ri sotuvni anglatadi."},"en":{"q":"How does a factory outlet differ from a classic outlet center internationally?","a":["Goods are sold directly from the manufacturer, bypassing a retailer","It is always located inside a residential complex","It never carries apparel brands"],"c":0,"why":"A factory outlet involves direct sales from the manufacturing factory without a retail intermediary."}},{"id":"MR042","cat":"market","logic":false,"ru":{"q":"Что означает термин «click-and-collect» в омниканальной розничной торговле?","a":["Онлайн-заказ с последующим самовывозом в физической точке","Доставку товара дроном на дом","Оплату покупки только наличными"],"c":0,"why":"Click-and-collect — модель, при которой покупатель заказывает онлайн, а забирает товар офлайн."},"uz":{"q":"Omnikanal chakana savdoda «click-and-collect» atamasi nimani anglatadi?","a":["Onlayn buyurtma berib, jismoniy nuqtadan o'zi olib ketish","Tovarni dron orqali uyga yetkazib berish","Xaridni faqat naqd pulda to'lash"],"c":0,"why":"Click-and-collect — xaridor onlayn buyurtma berib, tovarni oflayn do'kondan olib ketadigan model."},"en":{"q":"What does the term \"click-and-collect\" mean in omnichannel retail?","a":["Ordering online and picking up the item at a physical store","Delivering the item to the home by drone","Paying for a purchase only in cash"],"c":0,"why":"Click-and-collect is a model where customers order online and collect the item in-store."}},{"id":"MR043","cat":"market","logic":false,"ru":{"q":"Какую роль торговый центр может выполнять для ритейлера в омниканальной стратегии, помимо продаж?","a":["Служить пунктом выдачи и возврата онлайн-заказов","Полностью заменять складскую логистику страны","Заменять необходимость в веб-сайте бренда"],"c":0,"why":"Физический магазин в ТРЦ всё чаще используется как пункт выдачи/возврата онлайн-заказов."},"uz":{"q":"Savdo markazi omnikanal strategiyada sotuvdan tashqari chakana sotuvchi uchun qanday rol o'ynashi mumkin?","a":["Onlayn buyurtmalarni topshirish va qaytarish nuqtasi bo'lish","Mamlakat ombor logistikasini to'liq almashtirish","Brendning veb-saytiga ehtiyojni yo'qqa chiqarish"],"c":0,"why":"TRC dagi jismoniy do'kon tobora onlayn buyurtmalarni topshirish/qaytarish nuqtasi sifatida ishlatilmoqda."},"en":{"q":"Beyond sales, what role can a mall store play for a retailer's omnichannel strategy?","a":["Act as a pickup and return point for online orders","Fully replace the retailer's national warehousing","Eliminate the need for the brand's website"],"c":0,"why":"Physical stores in malls are increasingly used as pickup/return points for online orders."}},{"id":"MR044","cat":"market","logic":false,"ru":{"q":"Что такое dark store в логистике ритейла?","a":["Закрытая для покупателей точка, работающая только на сборку онлайн-заказов","Магазин, торгующий исключительно ночью","Витрина без товара для рекламы бренда"],"c":0,"why":"Dark store — это помещение, оформленное как склад для быстрой сборки онлайн-заказов, куда покупатели не заходят."},"uz":{"q":"Chakana savdo logistikasida dark store nima?","a":["Faqat onlayn buyurtmalarni yig'ish uchun ishlaydigan, xaridorlarga yopiq nuqta","Faqat kechasi ishlaydigan do'kon","Brend reklamasi uchun tovarsiz vitrina"],"c":0,"why":"Dark store — xaridorlar kirmaydigan, onlayn buyurtmalarni tez yig'ish uchun ombor sifatida jihozlangan joy."},"en":{"q":"What is a \"dark store\" in retail logistics?","a":["A customer-closed facility used only to fulfill online orders","A store that only operates at night","An empty display window used purely for branding"],"c":0,"why":"A dark store is a fulfillment facility set up like a warehouse to pick online orders quickly, without customer access."}},{"id":"MR045","cat":"market","logic":false,"ru":{"q":"Как развитие dark stores и last-mile логистики влияет на торговую недвижимость в городах?","a":["Растёт спрос на небольшие складские/логистические помещения рядом с жилыми районами","Полностью исчезает потребность в стрит-ритейле","Торговые центры перестают нуждаться в парковках"],"c":0,"why":"Быстрая доставка требует близких к потребителю мини-хабов, что повышает спрос на локальные логистические площади."},"uz":{"q":"Dark store va last-mile logistikaning rivojlanishi shahar savdo ko'chmas mulkiga qanday ta'sir qiladi?","a":["Turar-joy hududlariga yaqin kichik ombor/logistika joylariga talab oshadi","Strit-riteylga ehtiyoj butunlay yo'qoladi","Savdo markazlariga avtoturargoh kerak bo'lmay qoladi"],"c":0,"why":"Tezkor yetkazib berish iste'molchiga yaqin mini-xablarni talab qiladi, bu esa mahalliy logistika maydonlariga talabni oshiradi."},"en":{"q":"How does the rise of dark stores and last-mile logistics affect urban retail real estate?","a":["It increases demand for small logistics space near residential areas","It eliminates the need for street retail entirely","It removes the need for mall parking"],"c":0,"why":"Fast delivery requires mini-hubs close to consumers, raising demand for local logistics space."}},{"id":"MR046","cat":"market","logic":false,"ru":{"q":"Что подразумевает концепция mixed-use development в контексте торговой недвижимости?","a":["Совмещение торговли, офисов и жилья в едином проекте","Строительство только одноэтажных торговых павильонов","Использование здания исключительно под склад"],"c":0,"why":"Mixed-use объединяет несколько функций — ритейл, офисы, жильё, иногда гостиницы — в одном комплексе."},"uz":{"q":"Savdo ko'chmas mulki kontekstida mixed-use development kontseptsiyasi nimani anglatadi?","a":["Savdo, ofis va turar-joyni yagona loyihada birlashtirish","Faqat bir qavatli savdo pavilonlarini qurish","Binoni faqat ombor sifatida ishlatish"],"c":0,"why":"Mixed-use bir necha funksiyani — riteyl, ofis, turar-joy, ba'zan mehmonxonani — bitta majmuada birlashtiradi."},"en":{"q":"What does the concept of mixed-use development mean in retail real estate?","a":["Combining retail, office, and residential functions in one project","Building only single-story retail pavilions","Using a building solely as a warehouse"],"c":0,"why":"Mixed-use combines several functions—retail, office, residential, sometimes hospitality—within one complex."}},{"id":"MR047","cat":"market","logic":false,"ru":{"q":"Какое главное преимущество mixed-use проекта для торговой составляющей?","a":["Постоянный органический трафик от жителей и офисных работников","Полное отсутствие необходимости в рекламе","Освобождение от арендной платы"],"c":0,"why":"Проживающие и работающие в комплексе люди создают стабильный ежедневный поток посетителей для магазинов."},"uz":{"q":"Mixed-use loyihaning savdo qismi uchun asosiy afzalligi nimada?","a":["Turar-joy va ofis xodimlaridan doimiy tabiiy trafik","Reklamaga umuman ehtiyoj yo'qligi","Ijara to'lovidan ozod bo'lish"],"c":0,"why":"Majmuada yashovchi va ishlovchi odamlar do'konlar uchun barqaror kundalik tashrifchilar oqimini yaratadi."},"en":{"q":"What is the main advantage of a mixed-use project for its retail component?","a":["Steady organic foot traffic from residents and office workers","Complete exemption from marketing spend","Freedom from paying rent"],"c":0,"why":"Residents and workers living and working on-site generate a stable daily flow of shoppers for stores."}},{"id":"MR048","cat":"market","logic":false,"ru":{"q":"Какой международный ритейлер одним из первых стал ассоциироваться с активной экспансией в Центральную Азию через франшизу?","a":["Крупные турецкие и российские сети одежды","Только японские автопроизводители","Исключительно скандинавская мебельная розница"],"c":0,"why":"Турецкие и российские сети одежды и общепита традиционно были одними из первых крупных международных игроков, заходящих в регион через франчайзинг."},"uz":{"q":"Markaziy Osiyoga franshiza orqali faol kirib kelgan xalqaro riteylerlar sifatida birinchilardan qaysilar tanilgan?","a":["Yirik turk va rossiya kiyim tarmoqlari","Faqat yapon avtomobil ishlab chiqaruvchilari","Faqat skandinaviya mebel do'konlari"],"c":0,"why":"Turk va rossiya kiyim hamda umumiy ovqatlanish tarmoqlari franchayzing orqali mintaqaga birinchi kirgan yirik xalqaro o'yinchilardan bo'lgan."},"en":{"q":"Which international retailers were among the first to expand actively into Central Asia via franchising?","a":["Major Turkish and Russian apparel chains","Only Japanese automakers","Exclusively Scandinavian furniture retailers"],"c":0,"why":"Turkish and Russian apparel and food-service chains were traditionally among the first major international players entering the region via franchising."}},{"id":"MR049","cat":"market","logic":false,"ru":{"q":"Какая бизнес-модель наиболее распространена при выходе международных брендов на рынок Узбекистана?","a":["Франчайзинг через местного мастер-франчайзи","Прямые полные инвестиции без местного партнёра","Продажа лицензии государству"],"c":0,"why":"Большинство международных брендов заходят в Узбекистан через локального мастер-франчайзи, знающего специфику рынка."},"uz":{"q":"Xalqaro brendlar O'zbekiston bozoriga kirishda eng ko'p qo'llaydigan biznes-model qaysi?","a":["Mahalliy master-franchayzi orqali franchayzing","Mahalliy hamkorsiz to'liq to'g'ridan-to'g'ri investitsiya","Litsenziyani davlatga sotish"],"c":0,"why":"Ko'pchilik xalqaro brendlar O'zbekistonga bozor xususiyatlarini biladigan mahalliy master-franchayzi orqali kiradi."},"en":{"q":"Which business model is most common for international brands entering the Uzbek market?","a":["Franchising through a local master franchisee","Full direct investment without a local partner","Selling a license to the government"],"c":0,"why":"Most international brands enter Uzbekistan through a local master franchisee familiar with market specifics."}},{"id":"MR050","cat":"market","logic":false,"ru":{"q":"Что чаще всего сдерживает более быструю экспансию глобальных брендов в Узбекистан?","a":["Ограниченное число качественных торговых площадей и валютные риски","Отсутствие интереса населения к брендовым товарам","Запрет на аренду помещений иностранцами"],"c":0,"why":"Нехватка качественного GLA и валютные риски — ключевые сдерживающие факторы для международных ритейлеров."},"uz":{"q":"Global brendlarning O'zbekistonga tezroq kirib kelishiga ko'pincha nima to'sqinlik qiladi?","a":["Sifatli savdo maydonlarining cheklanganligi va valyuta xatarlari","Aholining brend tovarlariga qiziqishi yo'qligi","Xorijiylarga joy ijaraga olishni taqiqlash"],"c":0,"why":"Sifatli GLA yetishmasligi va valyuta xatarlari xalqaro riteylerlar uchun asosiy to'siq hisoblanadi."},"en":{"q":"What most often slows faster expansion of global brands into Uzbekistan?","a":["Limited quality retail space and currency risk","Lack of consumer interest in branded goods","A ban on foreigners leasing premises"],"c":0,"why":"Scarcity of quality GLA and currency risk are key constraints for international retailers entering Uzbekistan."}},{"id":"MR051","cat":"market","logic":false,"ru":{"q":"Как локальные узбекские бренды одежды чаще всего конкурируют с международными сетями в ТРЦ?","a":["Ценой и знанием локальных предпочтений покупателей","Более высокими ценами на аналогичный товар","Отказом от размещения в торговых центрах"],"c":0,"why":"Локальные бренды конкурируют за счёт более доступной цены и понимания вкусов местного покупателя."},"uz":{"q":"Mahalliy o'zbek kiyim brendlari TRClarda xalqaro tarmoqlar bilan ko'pincha qanday raqobatlashadi?","a":["Narx va mahalliy xaridor didini bilish orqali","Xuddi shunday tovarga yuqoriroq narx qo'yish orqali","Savdo markazlarida joylashishdan bosh tortish orqali"],"c":0,"why":"Mahalliy brendlar arzonroq narx va mahalliy xaridor didini yaxshi bilish hisobiga raqobatlashadi."},"en":{"q":"How do local Uzbek apparel brands most often compete with international chains in malls?","a":["On price and understanding of local consumer preferences","By pricing similar goods higher","By avoiding mall locations altogether"],"c":0,"why":"Local brands compete mainly through more accessible pricing and better understanding of local shopper tastes."}},{"id":"MR052","cat":"market","logic":false,"ru":{"q":"Какая категория арендаторов в узбекских ТРЦ традиционно занимает наибольшую долю GLA?","a":["Одежда и обувь (fashion)","Ювелирные бутики","Книжные магазины"],"c":0,"why":"Как и в большинстве развивающихся рынков, сегмент fashion занимает наибольшую долю арендуемых площадей."},"uz":{"q":"O'zbekiston TRClarida qaysi arendator kategoriyasi an'anaviy ravishda GLAning eng katta ulushini egallaydi?","a":["Kiyim va poyabzal (fashion)","Zargarlik butiklari","Kitob do'konlari"],"c":0,"why":"Ko'pgina rivojlanayotgan bozorlarda bo'lgani kabi, fashion segmenti ijara maydonining eng katta ulushini egallaydi."},"en":{"q":"Which tenant category typically occupies the largest share of GLA in Uzbek malls?","a":["Fashion and footwear","Jewelry boutiques","Bookstores"],"c":0,"why":"As in most emerging markets, the fashion segment occupies the largest share of leasable area."}},{"id":"MR053","cat":"market","logic":false,"ru":{"q":"Что такое ставка капитализации (cap rate) в оценке доходности торговой недвижимости?","a":["Отношение чистого операционного дохода к стоимости объекта","Ставка НДС на аренду коммерческой недвижимости","Процент вакантных площадей в здании"],"c":0,"why":"Cap rate рассчитывается как NOI, делённый на стоимость объекта, и отражает ожидаемую доходность инвестора."},"uz":{"q":"Savdo ko'chmas mulki daromadliligini baholashda kapitalizatsiya stavkasi (cap rate) nima?","a":["Sof operatsion daromadning obyekt qiymatiga nisbati","Tijorat ko'chmas mulkini ijaraga berishdagi QQS stavkasi","Binodagi bo'sh maydonlar foizi"],"c":0,"why":"Cap rate NOI ni obyekt qiymatiga bo'lish orqali hisoblanadi va investorning kutilayotgan daromadliligini aks ettiradi."},"en":{"q":"What is a capitalization (cap) rate in retail real estate valuation?","a":["Net operating income divided by the property's value","The VAT rate applied to commercial leases","The percentage of vacant space in a building"],"c":0,"why":"The cap rate is calculated as NOI divided by property value and reflects an investor's expected return."}},{"id":"MR054","cat":"market","logic":false,"ru":{"q":"Почему ставки капитализации на развивающихся рынках, включая Узбекистан, обычно выше, чем в Европе?","a":["Более высокие риски компенсируются более высокой ожидаемой доходностью","Аренда в развивающихся странах ниже европейской в разы","В Европе торговая недвижимость не приносит дохода"],"c":0,"why":"Более высокий страновой и рыночный риск требует более высокой доходности для привлечения инвесторов."},"uz":{"q":"Nega O'zbekiston kabi rivojlanayotgan bozorlarda kapitalizatsiya stavkalari Yevropadagiga qaraganda yuqoriroq bo'ladi?","a":["Yuqoriroq xatarlar yuqoriroq kutilgan daromadlilik bilan qoplanadi","Rivojlanayotgan mamlakatlarda ijara Yevropadan bir necha marta past","Yevropada savdo ko'chmas mulki daromad keltirmaydi"],"c":0,"why":"Yuqoriroq mamlakat va bozor xatari investorlarni jalb qilish uchun yuqoriroq daromadlilikni talab qiladi."},"en":{"q":"Why are cap rates in emerging markets like Uzbekistan typically higher than in Europe?","a":["Higher risk is compensated by higher expected returns","Rents in emerging markets are several times lower than in Europe","Retail real estate in Europe generates no income"],"c":0,"why":"Higher country and market risk requires a higher expected yield to attract investors."}},{"id":"MR055","cat":"market","logic":false,"ru":{"q":"Что характеризует «зрелый» (mature) рынок торговой недвижимости в отличие от развивающегося?","a":["Насыщенность качественным предложением и стабильно низкая доходность","Полное отсутствие международных брендов","Отсутствие какой-либо статистики по рынку"],"c":0,"why":"Зрелые рынки насыщены качественными объектами, что снижает риски и, соответственно, доходность (cap rate)."},"uz":{"q":"«Yetuk» (mature) savdo ko'chmas mulk bozorini rivojlanayotgan bozordan nima ajratib turadi?","a":["Sifatli takliflarning to'yinganligi va barqaror past daromadlilik","Xalqaro brendlarning umuman yo'qligi","Bozor bo'yicha har qanday statistikaning yo'qligi"],"c":0,"why":"Yetuk bozorlar sifatli obyektlar bilan to'yingan, bu xatarlarni va shu bilan kapitalizatsiya stavkasini pasaytiradi."},"en":{"q":"What characterizes a \"mature\" retail real estate market compared to an emerging one?","a":["Saturation with quality supply and consistently lower yields","A total absence of international brands","A complete lack of market statistics"],"c":0,"why":"Mature markets are saturated with quality stock, which lowers risk and therefore cap rates."}},{"id":"MR056","cat":"market","logic":false,"ru":{"q":"Какой показатель инвесторы используют для оценки эффективности продаж арендатора относительно занимаемой площади?","a":["Продажи на квадратный метр (sales per sq m)","Общая площадь здания","Количество этажей в здании"],"c":0,"why":"Sales per sq m позволяет сравнивать эффективность разных арендаторов независимо от размера их площади."},"uz":{"q":"Investorlar arendatorning egallagan maydoniga nisbatan sotuv samaradorligini baholash uchun qaysi ko'rsatkichdan foydalanadi?","a":["Kvadrat metrga sotuv (sales per sq m)","Binoning umumiy maydoni","Binodagi qavatlar soni"],"c":0,"why":"Kvadrat metrga sotuv ko'rsatkichi turli arendatorlarning maydonidan qat'i nazar samaradorligini solishtirish imkonini beradi."},"en":{"q":"Which metric do investors use to assess a tenant's sales performance relative to space occupied?","a":["Sales per square meter","Total building floor area","Number of floors in the building"],"c":0,"why":"Sales per sq m allows comparison of tenant performance independent of the size of space occupied."}},{"id":"MR057","cat":"market","logic":false,"ru":{"q":"Что такое occupancy cost ratio (доля затрат на аренду в выручке арендатора)?","a":["Отношение суммы аренды и коммунальных платежей к товарообороту арендатора","Процент свободных площадей в торговом центре","Стоимость строительства одного квадратного метра"],"c":0,"why":"Occupancy cost ratio показывает, какую долю выручки арендатор тратит на аренду и связанные расходы."},"uz":{"q":"Occupancy cost ratio (arendatorning aylanmasidagi ijara xarajatlari ulushi) nima?","a":["Ijara va kommunal to'lovlar summasining arendator aylanmasiga nisbati","Savdo markazidagi bo'sh maydonlar foizi","Bir kvadrat metr qurilish narxi"],"c":0,"why":"Occupancy cost ratio arendator aylanmasining qancha qismi ijara va bog'liq xarajatlarga sarflanishini ko'rsatadi."},"en":{"q":"What is the occupancy cost ratio in retail leasing?","a":["Rent plus service charges as a percentage of tenant turnover","The percentage of vacant space in a mall","The construction cost per square meter"],"c":0,"why":"The occupancy cost ratio shows what share of a tenant's turnover is spent on rent and related costs."}},{"id":"MR058","cat":"market","logic":false,"ru":{"q":"Почему институциональные инвесторы обычно предпочитают долгосрочные договоры аренды с якорными арендаторами?","a":["Это обеспечивает стабильный и предсказуемый денежный поток","Это позволяет им ежемесячно менять ставку аренды","Это освобождает их от уплаты налогов"],"c":0,"why":"Долгосрочные контракты с надёжными якорями снижают риск вакантности и обеспечивают предсказуемый доход."},"uz":{"q":"Institutsional investorlar nega odatda langar arendatorlar bilan uzoq muddatli ijara shartnomalarini afzal ko'radi?","a":["Bu barqaror va bashorat qilinadigan pul oqimini ta'minlaydi","Bu ularga ijara stavkasini har oy o'zgartirish imkonini beradi","Bu ularni soliqlardan ozod qiladi"],"c":0,"why":"Ishonchli langarlar bilan tuzilgan uzoq muddatli shartnomalar bo'shliq xatarini kamaytiradi va bashorat qilinadigan daromad beradi."},"en":{"q":"Why do institutional investors typically prefer long-term leases with anchor tenants?","a":["They provide a stable and predictable cash flow","They allow monthly rent renegotiation","They exempt the landlord from taxation"],"c":0,"why":"Long-term contracts with reliable anchors reduce vacancy risk and ensure predictable income."}},{"id":"MR059","cat":"market","logic":false,"ru":{"q":"Что означает сертификация LEED применительно к зданию торгового центра?","a":["Подтверждение соответствия здания стандартам экологичности и энергоэффективности","Разрешение на розничную торговлю алкоголем","Гарантию пожарной безопасности от МЧС"],"c":0,"why":"LEED (Leadership in Energy and Environmental Design) — международная система сертификации «зелёных» зданий."},"uz":{"q":"Savdo markazi binosiga nisbatan LEED sertifikati nimani anglatadi?","a":["Binoning ekologiklik va energiya samaradorligi standartlariga mosligini tasdiqlash","Alkogol chakana savdosiga ruxsatnoma","Favqulodda vaziyatlar vazirligining yong'in xavfsizligi kafolati"],"c":0,"why":"LEED (Leadership in Energy and Environmental Design) — «yashil» binolarni sertifikatlashning xalqaro tizimi."},"en":{"q":"What does LEED certification mean for a shopping mall building?","a":["Confirmation that the building meets sustainability and energy-efficiency standards","A license to sell alcohol at retail","A fire-safety clearance from emergency authorities"],"c":0,"why":"LEED (Leadership in Energy and Environmental Design) is an international green building certification system."}},{"id":"MR060","cat":"market","logic":false,"ru":{"q":"Чем система BREEAM похожа на LEED в контексте коммерческой недвижимости?","a":["Обе оценивают устойчивость и экологичность здания по системе баллов","Обе регулируют минимальную арендную ставку","Обе выдаются только жилым домам"],"c":0,"why":"BREEAM и LEED — конкурирующие международные системы оценки экологичности зданий по системе баллов/рейтингов."},"uz":{"q":"Tijorat ko'chmas mulki kontekstida BREEAM tizimi LEED bilan nimasi o'xshash?","a":["Ikkalasi ham binoning barqarorligi va ekologikligini ball tizimi orqali baholaydi","Ikkalasi ham minimal ijara stavkasini tartibga soladi","Ikkalasi ham faqat turar-joy binolariga beriladi"],"c":0,"why":"BREEAM va LEED — binolarning ekologikligini ball/reyting tizimi orqali baholaydigan raqobatchi xalqaro tizimlar."},"en":{"q":"How is the BREEAM system similar to LEED in commercial real estate?","a":["Both assess a building's sustainability using a scoring system","Both regulate the minimum rental rate","Both are issued only to residential buildings"],"c":0,"why":"BREEAM and LEED are competing international rating systems that score a building's environmental performance."}},{"id":"MR061","cat":"market","logic":false,"ru":{"q":"Какая практическая выгода для владельца ТРЦ от внедрения энергоэффективных технологий (LED-освещение, умный климат-контроль)?","a":["Снижение операционных расходов на эксплуатацию здания","Автоматическое повышение арендных ставок в договорах","Полное освобождение от налога на имущество"],"c":0,"why":"Энергоэффективные решения напрямую снижают эксплуатационные расходы (OPEX) собственника."},"uz":{"q":"Energiya samaradorligi texnologiyalarini (LED yoritish, aqlli iqlim nazorati) joriy etishdan TRC egasi uchun amaliy foyda nimada?","a":["Binoni ishlatish bo'yicha operatsion xarajatlarning kamayishi","Shartnomalarda ijara stavkasining avtomatik oshishi","Mulk solig'idan to'liq ozod bo'lish"],"c":0,"why":"Energiya samarali yechimlar egasining operatsion xarajatlarini (OPEX) bevosita kamaytiradi."},"en":{"q":"What is a practical benefit for a mall owner from adopting energy-efficient technologies (LED lighting, smart HVAC)?","a":["Lower operating expenses for running the building","Automatic increases in contractual rental rates","Full exemption from property tax"],"c":0,"why":"Energy-efficient solutions directly reduce the owner's operating expenses (OPEX)."}},{"id":"MR062","cat":"market","logic":false,"ru":{"q":"Почему международные ритейлеры и фонды всё чаще требуют от девелоперов ТРЦ соответствия ESG-принципам?","a":["Это влияет на их собственную корпоративную репутацию и доступ к финансированию","Это единственный способ получить разрешение на строительство","ESG требуется только для складской недвижимости"],"c":0,"why":"Соответствие ESG важно для репутации международных брендов и часто является условием привлечения зелёного финансирования."},"uz":{"q":"Nega xalqaro riteylerlar va fondlar TRC devoloperlaridan ESG tamoyillariga mosligini tobora ko'proq talab qilmoqda?","a":["Bu ularning korporativ obro'si va moliyalashtirishga kirish imkoniga ta'sir qiladi","Bu qurilish ruxsatnomasini olishning yagona yo'li","ESG faqat ombor ko'chmas mulki uchun talab qilinadi"],"c":0,"why":"ESGga muvofiqlik xalqaro brendlarning obro'si uchun muhim va ko'pincha yashil moliyalashtirishni jalb qilish sharti hisoblanadi."},"en":{"q":"Why do international retailers and funds increasingly require mall developers to meet ESG principles?","a":["It affects their own corporate reputation and access to financing","It is the only way to obtain a construction permit","ESG is required only for warehouse real estate"],"c":0,"why":"ESG compliance matters for international brands' reputations and is often a condition for green financing."}},{"id":"MR063","cat":"market","logic":false,"ru":{"q":"Какой демографический фактор является ключевым драйвером роста спроса на торговые площади в Ташкенте?","a":["Высокая доля молодого населения и рост численности города","Устойчивое сокращение населения города","Массовый отток молодёжи из страны"],"c":0,"why":"Молодая и растущая демография Ташкента формирует высокий текущий и будущий спрос на розничную торговлю."},"uz":{"q":"Toshkentda savdo maydonlariga talab o'sishining asosiy demografik omili qaysi?","a":["Yosh aholi ulushining yuqoriligi va shahar aholisi sonining o'sishi","Shahar aholisining barqaror kamayishi","Yoshlarning mamlakatdan ommaviy chiqib ketishi"],"c":0,"why":"Toshkentning yosh va o'sib boruvchi demografiyasi chakana savdoga yuqori joriy va kelajakdagi talabni shakllantiradi."},"en":{"q":"Which demographic factor is a key driver of growing retail space demand in Tashkent?","a":["A large young population share and rising city population","A sustained decline in the city's population","Mass emigration of young people from the country"],"c":0,"why":"Tashkent's young and growing demographic profile drives strong current and future retail demand."}},{"id":"MR064","cat":"market","logic":false,"ru":{"q":"Как урбанизация и рост доходов среднего класса влияют на структуру спроса в ТРЦ Ташкента?","a":["Растёт спрос на международные бренды и развлекательные форматы","Спрос смещается исключительно к продаже сельхозинвентаря","Интерес к ТРЦ полностью пропадает"],"c":0,"why":"Урбанизация и рост доходов повышают спрос на международный fashion-ритейл и развлекательный сегмент (F&B, кино, детские зоны)."},"uz":{"q":"Urbanizatsiya va o'rta sinf daromadlarining o'sishi Toshkent TRClaridagi talab tuzilmasiga qanday ta'sir qiladi?","a":["Xalqaro brendlar va ko'ngilochar formatlarga talab oshadi","Talab faqat qishloq xo'jaligi jihozlari sotuviga siljiydi","TRCga qiziqish butunlay yo'qoladi"],"c":0,"why":"Urbanizatsiya va daromad o'sishi xalqaro fashion-riteyl va ko'ngilochar segmentga (F&B, kino, bolalar zonalari) talabni oshiradi."},"en":{"q":"How do urbanization and rising middle-class incomes affect demand patterns in Tashkent malls?","a":["Demand grows for international brands and entertainment formats","Demand shifts exclusively toward agricultural equipment sales","Interest in malls disappears entirely"],"c":0,"why":"Urbanization and rising incomes increase demand for international fashion retail and the entertainment segment (F&B, cinema, kids' zones)."}},{"id":"MR065","cat":"market","logic":false,"ru":{"q":"Что из перечисленного является типичным следствием быстрой урбанизации для новых районов Ташкента (например, TATU City, Yangi Uzbekistan)?","a":["Возникает спрос на новые локальные convenience- и neighborhood-центры","Полностью исчезает потребность в розничной торговле","Все ритейлеры переезжают в старый город"],"c":0,"why":"Новые жилые районы формируют локальный спрос, который закрывают convenience- и neighborhood-форматы."},"uz":{"q":"Tez urbanizatsiyaning Toshkentning yangi hududlari (masalan, TATU City, Yangi O'zbekiston) uchun odatiy oqibati qaysi?","a":["Yangi mahalliy convenience va neighborhood markazlarga talab paydo bo'ladi","Chakana savdoga ehtiyoj butunlay yo'qoladi","Barcha riteylerlar eski shaharga ko'chib o'tadi"],"c":0,"why":"Yangi turar-joy hududlari mahalliy talabni shakllantiradi, buni convenience va neighborhood formatlari qondiradi."},"en":{"q":"What is a typical consequence of rapid urbanization for new Tashkent districts (e.g., TATU City, Yangi Uzbekistan)?","a":["Demand emerges for new local convenience and neighborhood centers","The need for retail disappears entirely","All retailers relocate to the old city center"],"c":0,"why":"New residential districts generate local demand that is served by convenience and neighborhood formats."}},{"id":"MR066","cat":"market","logic":false,"ru":{"q":"Какой тренд характерен для развлекательной составляющей современных ТРЦ на фоне роста конкуренции с онлайн-торговлей?","a":["Увеличение доли F&B, кино и детских развлечений в общем GLA","Полный отказ от развлекательных зон в пользу магазинов одежды","Замена всех магазинов на офисные помещения"],"c":0,"why":"ТРЦ увеличивают долю развлечений и общепита, чтобы предложить опыт, недоступный онлайн-торговле."},"uz":{"q":"Onlayn savdo bilan raqobat kuchayishi fonida zamonaviy TRClarning ko'ngilochar qismi uchun qaysi tendensiya xos?","a":["Umumiy GLAda F&B, kino va bolalar ko'ngilochar zonalari ulushining oshishi","Ko'ngilochar zonalardan butunlay voz kechib, faqat kiyim do'konlarini qoldirish","Barcha do'konlarni ofis xonalariga almashtirish"],"c":0,"why":"TRClar onlayn savdoda mavjud bo'lmagan tajribani taklif qilish uchun ko'ngilochar va umumiy ovqatlanish ulushini oshirmoqda."},"en":{"q":"What trend is typical for the entertainment component of modern malls amid growing online competition?","a":["A rising share of F&B, cinema, and kids' entertainment in total GLA","Complete elimination of entertainment zones in favor of apparel stores","Replacing all stores with office space"],"c":0,"why":"Malls are increasing entertainment and F&B space to offer experiences that online retail cannot replicate."}},{"id":"MR067","cat":"market","logic":false,"ru":{"q":"Какой формат торговой недвижимости чаще всего выбирают международные fashion-ритейлеры для первого выхода на рынок Центральной Азии?","a":["Флагманский магазин в качественном региональном или суперрегиональном ТРЦ","Небольшой ларёк на вещевом рынке","Аутлет-центр за городом"],"c":0,"why":"Международные бренды предпочитают выходить через флагманский магазин в известном качественном ТРЦ для укрепления имиджа."},"uz":{"q":"Xalqaro fashion-riteylerlar Markaziy Osiyo bozoriga birinchi marta chiqishda ko'pincha qaysi formatni tanlaydi?","a":["Sifatli mintaqaviy yoki super-mintaqaviy TRCdagi flagman do'kon","Kiyim-kechak bozoridagi kichik do'kon","Shahar tashqarisidagi outlet-markaz"],"c":0,"why":"Xalqaro brendlar o'z imijini mustahkamlash uchun taniqli sifatli TRCdagi flagman do'kon orqali kirishni afzal ko'radi."},"en":{"q":"Which retail format do international fashion retailers most often choose for their first entry into Central Asia?","a":["A flagship store in a quality regional or super-regional mall","A small stall at a clothing bazaar","An out-of-town outlet center"],"c":0,"why":"International brands prefer entering via a flagship store in a well-known quality mall to build brand image."}},{"id":"MR068","cat":"market","logic":false,"ru":{"q":"Что подразумевает термин «якорный микс» (anchor mix) при планировании ТРЦ?","a":["Подбор сочетания крупных арендаторов разных категорий для генерации трафика","Список арендаторов, которые платят самую высокую ставку","Перечень магазинов на первом этаже здания"],"c":0,"why":"Anchor mix — это стратегический подбор якорей (гипермаркет, DIY, электроника, развлечения), формирующих разноплановый трафик."},"uz":{"q":"TRC rejalashtirishda «langar miksi» atamasi nimani anglatadi?","a":["Trafik yaratish uchun turli kategoriyadagi yirik arendatorlarni tanlash","Eng yuqori stavka to'laydigan arendatorlar ro'yxati","Binoning birinchi qavatidagi do'konlar ro'yxati"],"c":0,"why":"Langar miksi — turli xil trafik shakllantiruvchi langarlarni (gipermarket, DIY, elektronika, ko'ngilochar) strategik tanlashdir."},"en":{"q":"What does the term \"anchor mix\" mean in mall planning?","a":["Selecting a combination of large tenants from different categories to drive traffic","The list of tenants paying the highest rent","The list of stores located on the ground floor"],"c":0,"why":"Anchor mix refers to the strategic selection of anchors (hypermarket, DIY, electronics, entertainment) that generate diverse traffic."}},{"id":"MR069","cat":"market","logic":false,"ru":{"q":"Почему девелоперы ТРЦ в Центральной Азии всё чаще включают продуктовый гипермаркет как якорь, а не только fashion?","a":["Продуктовый ритейл обеспечивает стабильный ежедневный трафик независимо от сезона","Продукты питания приносят наибольшую арендную ставку за м²","Fashion-ритейл запрещён как якорь по закону"],"c":0,"why":"Продуктовый гипермаркет обеспечивает регулярные визиты и стабильный поток посетителей круглый год."},"uz":{"q":"Nega Markaziy Osiyodagi TRC devoloperlari nafaqat fashion, balki oziq-ovqat gipermarketini ham langar sifatida tobora ko'proq kiritmoqda?","a":["Oziq-ovqat riteyli mavsumga bog'liq bo'lmagan barqaror kundalik trafikni ta'minlaydi","Oziq-ovqat m² uchun eng yuqori ijara stavkasini beradi","Fashion-riteyl langar sifatida qonun bilan taqiqlangan"],"c":0,"why":"Oziq-ovqat gipermarketi yil davomida muntazam tashriflar va barqaror tashrifchilar oqimini ta'minlaydi."},"en":{"q":"Why do mall developers in Central Asia increasingly include a grocery hypermarket as an anchor alongside fashion?","a":["Grocery retail generates steady daily traffic regardless of season","Grocery tenants pay the highest rent per sq m","Fashion retail is legally barred from being an anchor"],"c":0,"why":"A grocery hypermarket ensures regular visits and a stable flow of visitors year-round."}},{"id":"MR070","cat":"market","logic":false,"ru":{"q":"Какой фактор инвесторы оценивают как признак растущей зрелости рынка торговой недвижимости Узбекистана?","a":["Появление профессиональных девелоперов и прозрачной рыночной статистики","Полное отсутствие новых проектов ТРЦ","Отказ международных брендов от присутствия в стране"],"c":0,"why":"Профессионализация девелопмента и доступность рыночных данных — признаки взросления рынка недвижимости."},"uz":{"q":"Investorlar O'zbekiston savdo ko'chmas mulki bozorining o'sib borayotgan yetukligi belgisi sifatida qaysi omilni baholaydi?","a":["Professional devoloperlarning va shaffof bozor statistikasining paydo bo'lishi","Yangi TRC loyihalarining butunlay yo'qligi","Xalqaro brendlarning mamlakatdan chiqib ketishi"],"c":0,"why":"Development sohasining professionallashuvi va bozor ma'lumotlarining ochiqligi bozor yetukligining belgisidir."},"en":{"q":"Which factor do investors view as a sign of growing maturity in Uzbekistan's retail real estate market?","a":["The emergence of professional developers and transparent market data","A complete absence of new mall projects","International brands withdrawing from the country"],"c":0,"why":"Professionalization of development and availability of market data are signs of a maturing real estate market."}},{"id":"OP001","cat":"ops","logic":false,"ru":{"q":"Что отличает якорного арендатора (anchor tenant) от остальных арендаторов ТРЦ?","a":["Крупная площадь и способность генерировать основной трафик","Расположение только на первом этаже","Минимальная арендная ставка среди всех"],"c":0,"why":"Якорный арендатор занимает большую площадь и привлекает основной поток посетителей в ТРЦ."},"uz":{"q":"Langar-ijarachi (yetakchi ijarachi) TRC dagi boshqa ijarachilardan nimasi bilan farq qiladi?","a":["Katta maydon egallaydi va asosiy tashrif oqimini yaratadi","Faqat birinchi qavatda joylashadi","Barcha ijarachilar orasida eng past ijara stavkasiga ega"],"c":0,"why":"Yetakchi ijarachi katta maydon egallab, savdo markaziga asosiy tashrif buyuruvchilar oqimini jalb qiladi."},"en":{"q":"What distinguishes an anchor tenant from other tenants in a shopping mall?","a":["Large floor area and ability to drive the main customer traffic","Location exclusively on the ground floor","The lowest rental rate among all tenants"],"c":0,"why":"An anchor tenant occupies a large area and pulls the majority of foot traffic into the mall."}},{"id":"OP002","cat":"ops","logic":false,"ru":{"q":"Какова основная роль sub-anchor (суб-якорного) арендатора в торговом центре?","a":["Поддерживать трафик между основными якорями на своем участке галереи","Заменять службу безопасности на своем этаже","Управлять инженерными системами здания"],"c":0,"why":"Суб-якоря — это средние по размеру сильные бренды, которые распределяют трафик между зонами и якорями."},"uz":{"q":"Savdo markazidagi sub-langar (kichik yetakchi) ijarachining asosiy vazifasi nima?","a":["Galereyaning o'z qismida asosiy yetakchilar orasida tashrifni qo'llab-quvvatlash","O'z qavatida xavfsizlik xizmatini almashtirish","Bino muhandislik tizimlarini boshqarish"],"c":0,"why":"Sub-langar o'rta hajmdagi kuchli brendlar bo'lib, tashrif oqimini zonalar va yetakchilar o'rtasida taqsimlaydi."},"en":{"q":"What is the primary role of a sub-anchor tenant in a shopping mall?","a":["Sustain foot traffic between main anchors in its section of the gallery","Replace the security team on its floor","Manage the building's engineering systems"],"c":0,"why":"Sub-anchors are mid-sized strong brands that help distribute traffic between zones and main anchors."}},{"id":"OP003","cat":"ops","logic":false,"ru":{"q":"Что такое магнит-арендатор (magnet tenant) в контексте зонирования ТРЦ?","a":["Небольшой яркий бренд, притягивающий поток в конкретную локальную зону","Инженерная служба, отвечающая за лифты","Арендатор с самой большой торговой площадью в центре"],"c":0,"why":"Магнит-арендатор — это популярный небольшой оператор, который стимулирует трафик в определенной части галереи."},"uz":{"q":"TRC zonalashtirish kontekstida magnit-ijarachi (magnet tenant) nima?","a":["Galereyaning muayyan qismiga oqim jalb qiluvchi mashhur, unchalik katta bo'lmagan brend","Liftlarga javobgar muhandislik xizmati","Markazdagi eng katta savdo maydoniga ega ijarachi"],"c":0,"why":"Magnit-ijarachi galereyaning muayyan qismida tashrif oqimini rag'batlantiruvchi mashhur, kichikroq operatordir."},"en":{"q":"What is a magnet tenant in the context of mall zoning?","a":["A popular smaller-format brand that draws traffic to a specific local zone","The engineering service responsible for elevators","The tenant occupying the largest retail space in the center"],"c":0,"why":"A magnet tenant is a popular smaller operator that stimulates traffic in a particular part of the gallery."}},{"id":"OP004","cat":"ops","logic":false,"ru":{"q":"Какова главная цель разработки тенант-микса (tenant mix) для ТРЦ?","a":["Сбалансировать категории арендаторов для максимального трафика и синергии","Заполнить площади любыми арендаторами как можно быстрее","Разместить только международные бренды на всех этажах"],"c":0,"why":"Тенант-микс должен создавать сбалансированное сочетание категорий, усиливающее взаимный трафик и продажи."},"uz":{"q":"TRC uchun tenant-miks (ijarachilar tarkibi) rejalashtirishning asosiy maqsadi nima?","a":["Maksimal tashrif va sinergiya uchun ijarachi toifalarini muvozanatlash","Maydonlarni imkon qadar tezroq har qanday ijarachi bilan to'ldirish","Barcha qavatlarga faqat xalqaro brendlarni joylashtirish"],"c":0,"why":"Tenant-miks ijarachi toifalarining muvozanatli birikmasini yaratib, o'zaro tashrif va savdoni kuchaytirishi kerak."},"en":{"q":"What is the primary goal of tenant mix planning in a mall?","a":["Balance tenant categories to maximize traffic and cross-shopping synergy","Fill vacant space with any available tenant as quickly as possible","Place only international brands on every floor"],"c":0,"why":"Tenant mix planning aims to create a balanced category blend that boosts mutual traffic and sales."}},{"id":"OP005","cat":"ops","logic":false,"ru":{"q":"Почему фуд-корт обычно располагают на верхнем этаже или в удаленной зоне ТРЦ?","a":["Чтобы вести посетителей через торговые галереи по пути к еде","Потому что там дешевле аренда для арендаторов","Потому что там легче организовать разгрузку товара"],"c":0,"why":"Размещение фуд-корта в конце маршрута заставляет посетителей проходить мимо магазинов, увеличивая их трафик."},"uz":{"q":"Fud-kort odatda TRC ning yuqori qavatida yoki chekka zonasida nima uchun joylashtiriladi?","a":["Tashrif buyuruvchilarni ovqatlanish tomon savdo galereyalari orqali yo'naltirish uchun","U yerda ijarachilar uchun ijara arzonroq bo'lgani uchun","U yerda tovar tushirishni tashkil qilish osonroq bo'lgani uchun"],"c":0,"why":"Fud-kortni marshrut oxirida joylashtirish tashrif buyuruvchilarni do'konlar yonidan o'tishga majbur qilib, ularning trafigini oshiradi."},"en":{"q":"Why is a food court typically placed on an upper floor or a remote zone of a mall?","a":["To route visitors through retail galleries on their way to dining","Because rent is cheaper for tenants in that location","Because it is easier to organize goods unloading there"],"c":0,"why":"Placing the food court at the end of a path forces visitors to pass by stores, increasing their exposure to retail."}},{"id":"OP006","cat":"ops","logic":false,"ru":{"q":"Какой показатель чаще всего используют для оценки эффективности фуд-корта?","a":["Продажи с квадратного метра и оборачиваемость посадочных мест","Только количество арендаторов в зоне","Средняя высота потолков в зоне питания"],"c":0,"why":"Продажи на кв.м и скорость оборачиваемости столов — ключевые операционные метрики фуд-корта."},"uz":{"q":"Fud-kort samaradorligini baholash uchun eng ko'p qanday ko'rsatkich ishlatiladi?","a":["Kvadrat metrga savdo va o'tirish joylarining aylanish tezligi","Faqat zonadagi ijarachilar soni","Ovqatlanish zonasidagi shift balandligining o'rtacha ko'rsatkichi"],"c":0,"why":"Kvadrat metrga savdo va stollarning aylanish tezligi fud-kortning asosiy operatsion ko'rsatkichlaridir."},"en":{"q":"Which metric is most commonly used to evaluate food court performance?","a":["Sales per square meter and seating turnover rate","Only the number of tenants operating in the zone","The average ceiling height in the dining area"],"c":0,"why":"Sales per square meter and table turnover rate are key operational metrics for a food court."}},{"id":"OP007","cat":"ops","logic":false,"ru":{"q":"Какую функцию выполняет развлекательная зона (детская площадка, кинотеатр, каток) в стратегии ТРЦ?","a":["Увеличивает время пребывания посетителей (dwell time) и повторные визиты","Заменяет функцию службы безопасности","Снижает необходимость в парковочных местах"],"c":0,"why":"Развлечения удерживают посетителей дольше в центре, что повышает вероятность покупок и лояльность."},"uz":{"q":"Ko'ngilochar zona (bolalar maydonchasi, kinoteatr, katok) TRC strategiyasida qanday vazifani bajaradi?","a":["Tashrif buyuruvchilarning markazda bo'lish vaqtini va qayta tashrifini oshiradi","Xavfsizlik xizmati vazifasini almashtiradi","Avtoturargoh joylariga bo'lgan ehtiyojni kamaytiradi"],"c":0,"why":"Ko'ngilochar zonalar tashrif buyuruvchilarni markazda uzoqroq ushlab turadi, bu xarid qilish ehtimolini va sodiqlikni oshiradi."},"en":{"q":"What function does an entertainment zone (kids' play area, cinema, ice rink) serve in mall strategy?","a":["It increases visitor dwell time and encourages repeat visits","It replaces the function of the security department","It reduces the need for parking spaces"],"c":0,"why":"Entertainment options keep visitors on-site longer, which raises purchase likelihood and loyalty."}},{"id":"OP008","cat":"ops","logic":false,"ru":{"q":"Какой принцип наиболее важен при управлении парковкой крупного ТРЦ в часы пик?","a":["Направление потока автомобилей и мониторинг заполняемости в реальном времени","Полное закрытие парковки после 80% заполнения","Взимание единой фиксированной платы независимо от времени"],"c":0,"why":"Управление потоком и контроль заполняемости в реальном времени позволяют избежать заторов и потери клиентов."},"uz":{"q":"Yirik TRC avtoturargohini eng band soatlarda boshqarishda qaysi tamoyil eng muhim?","a":["Avtomobillar oqimini yo'naltirish va to'lish darajasini real vaqtda kuzatish","80% to'lganda avtoturargohni butunlay yopish","Vaqtidan qat'i nazar bir xil belgilangan to'lov olish"],"c":0,"why":"Oqimni boshqarish va real vaqtda to'lishni kuzatish tirbandlik va mijozlarni yo'qotishning oldini oladi."},"en":{"q":"What is the most critical principle for managing a large mall's parking during peak hours?","a":["Directing vehicle flow and monitoring real-time occupancy","Fully closing the parking lot once it reaches 80% capacity","Charging one fixed fee regardless of time spent"],"c":0,"why":"Flow direction and real-time occupancy monitoring prevent congestion and customer loss."}},{"id":"OP009","cat":"ops","logic":false,"ru":{"q":"Зачем в крупных ТРЦ внедряют систему подсчета свободных мест на парковке с указателями?","a":["Чтобы сократить время поиска места и снизить внутреннее движение","Чтобы автоматически штрафовать нарушителей","Чтобы заменить необходимость в охране парковки"],"c":0,"why":"Указатели свободных мест сокращают время кружения по парковке и разгружают внутренний трафик."},"uz":{"q":"Yirik TRC larda avtoturargohdagi bo'sh joylarni ko'rsatuvchi tizim nima uchun joriy etiladi?","a":["Joy qidirish vaqtini qisqartirish va ichki harakatni kamaytirish uchun","Qoidabuzarlarni avtomatik jarimalash uchun","Avtoturargoh xavfsizligiga bo'lgan ehtiyojni bekor qilish uchun"],"c":0,"why":"Bo'sh joy ko'rsatkichlari avtoturargohda aylanib yurish vaqtini qisqartirib, ichki harakatni yengillashtiradi."},"en":{"q":"Why do large malls implement a parking guidance system showing available spaces?","a":["To reduce space-searching time and ease internal traffic congestion","To automatically fine parking violators","To eliminate the need for parking security staff"],"c":0,"why":"Guidance indicators reduce time spent circling for a spot and ease internal traffic flow."}},{"id":"OP010","cat":"ops","logic":false,"ru":{"q":"Почему разгрузочные зоны (loading dock) обычно проектируют отдельно от посетительских входов?","a":["Чтобы разделить грузовые и клиентские потоки для безопасности и удобства","Потому что грузовики не могут парковаться рядом с магазинами по закону","Потому что это требование пожарной инспекции для всех входов"],"c":0,"why":"Разделение потоков снижает риски для посетителей и позволяет эффективно организовать логистику поставок."},"uz":{"q":"Yuk tushirish zonalari (loading dock) odatda tashrif buyuruvchilar kirish joylaridan alohida nega loyihalashtiriladi?","a":["Xavfsizlik va qulaylik uchun yuk va mijozlar oqimini ajratish maqsadida","Yuk mashinalari qonun bo'yicha do'konlar yonida to'xtay olmasligi sababli","Bu barcha kirish joylari uchun yong'in nazorati talabi bo'lgani uchun"],"c":0,"why":"Oqimlarni ajratish tashrif buyuruvchilar uchun xavfni kamaytiradi va yetkazib berish logistikasini samarali tashkil qiladi."},"en":{"q":"Why are loading docks typically designed separately from customer entrances?","a":["To separate freight and customer flows for safety and convenience","Because trucks are legally barred from parking near any retail entrance","Because fire inspectors require it for every mall entrance"],"c":0,"why":"Separating flows reduces risk to shoppers and allows delivery logistics to run efficiently."}},{"id":"OP011","cat":"ops","logic":false,"ru":{"q":"Какой инструмент используется для регулирования графика поставок арендаторов через единый погрузочный узел?","a":["Расписание слотов доставки (delivery time slots)","Свободный доступ грузовиков в любое время суток","Отдельный лифт для каждого арендатора"],"c":0,"why":"Слотирование времени доставки предотвращает скопление транспорта и очереди на разгрузку."},"uz":{"q":"Yagona yuk tushirish tuguni orqali ijarachilarning yetkazib berish jadvalini tartibga solish uchun qanday vosita ishlatiladi?","a":["Yetkazib berish vaqt oralig'i jadvali (delivery time slots)","Yuk mashinalarining kun bo'yi erkin kirishi","Har bir ijarachi uchun alohida lift"],"c":0,"why":"Yetkazib berish vaqtini bandlash transport to'planishi va tushirish navbatlarining oldini oladi."},"en":{"q":"What tool is used to coordinate tenant delivery schedules through a shared loading area?","a":["A delivery time-slot booking schedule","Unrestricted truck access at any hour","A dedicated freight elevator for every tenant"],"c":0,"why":"Time-slot scheduling prevents vehicle backups and queues at the unloading dock."}},{"id":"OP012","cat":"ops","logic":false,"ru":{"q":"Какая инженерная система отвечает за поддержание комфортной температуры и качества воздуха в ТРЦ?","a":["HVAC (отопление, вентиляция и кондиционирование)","BMS-система видеонаблюдения","Система пожарных гидрантов"],"c":0,"why":"HVAC — комплекс отопления, вентиляции и кондиционирования, обеспечивающий микроклимат здания."},"uz":{"q":"TRC da qulay harorat va havo sifatini ta'minlash uchun qaysi muhandislik tizimi javobgar?","a":["HVAC (isitish, ventilyatsiya va konditsionerlash)","Videokuzatuv BMS-tizimi","Yong'in gidrantlari tizimi"],"c":0,"why":"HVAC — bino mikroiqlimini ta'minlaydigan isitish, ventilyatsiya va konditsionerlash majmuasidir."},"en":{"q":"Which engineering system is responsible for maintaining comfortable temperature and air quality in a mall?","a":["HVAC (heating, ventilation, and air conditioning)","The CCTV surveillance BMS system","The fire hydrant network"],"c":0,"why":"HVAC is the combined heating, ventilation, and air conditioning system that controls the building's climate."}},{"id":"OP013","cat":"ops","logic":false,"ru":{"q":"Как часто согласно нормам эксплуатации рекомендуется проводить плановое техобслуживание эскалаторов в ТРЦ?","a":["Регулярно по графику, установленному производителем (обычно ежемесячно)","Только один раз при вводе в эксплуатацию","Раз в пять лет по требованию арендаторов"],"c":0,"why":"Эскалаторы требуют регулярного планового обслуживания по регламенту производителя для безопасной работы."},"uz":{"q":"Ekspluatatsiya normalariga ko'ra TRC dagi eskalatorlarga rejali texnik xizmat qancha tez-tez ko'rsatilishi tavsiya etiladi?","a":["Ishlab chiqaruvchi belgilagan jadval bo'yicha muntazam (odatda har oy)","Faqat ishga tushirilganda bir marta","Ijarachilar talabiga ko'ra besh yilda bir marta"],"c":0,"why":"Eskalatorlar xavfsiz ishlashi uchun ishlab chiqaruvchi reglamentiga ko'ra muntazam rejali xizmat talab qiladi."},"en":{"q":"How often should escalators in a mall receive scheduled preventive maintenance, per standard operating practice?","a":["Regularly, per the manufacturer's schedule (typically monthly)","Only once, at the time of commissioning","Every five years, upon tenant request"],"c":0,"why":"Escalators require regular scheduled maintenance following the manufacturer's regulations to operate safely."}},{"id":"OP014","cat":"ops","logic":false,"ru":{"q":"Что входит в базовые требования пожарной безопасности для ТРЦ?","a":["Системы оповещения, пожаротушения, эвакуационные выходы и планы эвакуации","Только наличие огнетушителей у арендаторов","Установка камер видеонаблюдения на входах"],"c":0,"why":"Комплексная пожарная безопасность включает оповещение, пожаротушение и обеспечение путей эвакуации."},"uz":{"q":"TRC uchun asosiy yong'in xavfsizligi talablariga nima kiradi?","a":["Ogohlantirish, yong'in o'chirish tizimlari, evakuatsiya chiqishlari va rejalari","Faqat ijarachilarda o't o'chirgich bo'lishi","Kirish joylariga videokuzatuv kameralarini o'rnatish"],"c":0,"why":"Kompleks yong'in xavfsizligi ogohlantirish, o't o'chirish va evakuatsiya yo'llarini ta'minlashni o'z ichiga oladi."},"en":{"q":"What do baseline fire safety requirements for a mall include?","a":["Alarm systems, fire suppression, emergency exits, and evacuation plans","Only requiring tenants to keep fire extinguishers on hand","Installing CCTV cameras at every entrance"],"c":0,"why":"Comprehensive fire safety covers alarm notification, suppression systems, and clear evacuation routes."}},{"id":"OP015","cat":"ops","logic":false,"ru":{"q":"Кто обычно отвечает за координацию учебной пожарной эвакуации в ТРЦ?","a":["Служба эксплуатации/управляющая компания совместно со службой безопасности","Каждый арендатор самостоятельно без участия управляющей компании","Городская администрация без участия персонала ТРЦ"],"c":0,"why":"Управляющая компания и служба безопасности совместно организуют и координируют учебные эвакуации."},"uz":{"q":"TRC da o'quv yong'in evakuatsiyasini muvofiqlashtirish odatda kimning zimmasida bo'ladi?","a":["Ekspluatatsiya xizmati/boshqaruv kompaniyasi xavfsizlik xizmati bilan birgalikda","Boshqaruv kompaniyasi ishtirokisiz har bir ijarachi mustaqil ravishda","TRC xodimlari ishtirokisiz shahar hokimiyati"],"c":0,"why":"Boshqaruv kompaniyasi va xavfsizlik xizmati o'quv evakuatsiyalarni birgalikda tashkil qiladi va muvofiqlashtiradi."},"en":{"q":"Who typically coordinates fire evacuation drills in a shopping mall?","a":["The facility/property management team together with security","Each tenant independently, without property management involvement","The city administration, without any mall staff involvement"],"c":0,"why":"Property management and security jointly organize and coordinate evacuation drills."}},{"id":"OP016","cat":"ops","logic":false,"ru":{"q":"Какова главная задача службы безопасности ТРЦ помимо предотвращения краж?","a":["Обеспечение общей безопасности посетителей и реагирование на инциденты","Продажа билетов в развлекательную зону","Контроль качества товаров в магазинах арендаторов"],"c":0,"why":"Служба безопасности отвечает за общую безопасность посетителей и оперативное реагирование на любые инциденты."},"uz":{"q":"TRC xavfsizlik xizmatining o'g'irlikning oldini olishdan tashqari asosiy vazifasi nima?","a":["Tashrif buyuruvchilarning umumiy xavfsizligini ta'minlash va hodisalarga javob berish","Ko'ngilochar zonaga chipta sotish","Ijarachi do'konlaridagi tovarlar sifatini nazorat qilish"],"c":0,"why":"Xavfsizlik xizmati tashrif buyuruvchilarning umumiy xavfsizligi va har qanday hodisaga tezkor javob berish uchun javobgardir."},"en":{"q":"Besides theft prevention, what is a key responsibility of mall security operations?","a":["Ensuring overall visitor safety and responding to incidents","Selling tickets for the entertainment zone","Monitoring product quality inside tenant stores"],"c":0,"why":"Security operations are responsible for overall visitor safety and prompt incident response."}},{"id":"OP017","cat":"ops","logic":false,"ru":{"q":"Что такое CCTV-мониторинг в контексте безопасности ТРЦ?","a":["Система видеонаблюдения для контроля общественных зон в реальном времени","Технология учета покупателей на кассах арендаторов","Программа лояльности для постоянных посетителей"],"c":0,"why":"CCTV — это система видеокамер, позволяющая службе безопасности контролировать зоны центра в реальном времени."},"uz":{"q":"TRC xavfsizligi kontekstida CCTV-monitoring nima?","a":["Ommaviy zonalarni real vaqtda nazorat qiluvchi videokuzatuv tizimi","Ijarachi kassalarida xaridorlarni hisobga olish texnologiyasi","Doimiy tashrif buyuruvchilar uchun sodiqlik dasturi"],"c":0,"why":"CCTV — bu xavfsizlik xizmatiga markaz zonalarini real vaqtda kuzatish imkonini beruvchi videokamera tizimi."},"en":{"q":"What is CCTV monitoring in the context of mall security?","a":["A video surveillance system for real-time monitoring of common areas","A technology for counting shoppers at tenant checkout points","A loyalty program for frequent visitors"],"c":0,"why":"CCTV is a camera-based system that lets security staff monitor common areas of the mall in real time."}},{"id":"OP018","cat":"ops","logic":false,"ru":{"q":"Какая задача клининговой службы ТРЦ считается приоритетной в местах общего пользования?","a":["Поддержание чистоты и безопасности полов (особенно во влажную погоду)","Мытье витрин внутри магазинов арендаторов","Замена перегоревших ламп в торговых залах арендаторов"],"c":0,"why":"Клининг мест общего пользования включает контроль состояния полов, что напрямую влияет на безопасность посетителей."},"uz":{"q":"TRC tozalash xizmatining umumiy foydalanish zonalaridagi ustuvor vazifasi nima hisoblanadi?","a":["Pollarning tozaligi va xavfsizligini ta'minlash (ayniqsa nam ob-havoda)","Ijarachi do'konlari ichidagi vitrinalarni yuvish","Ijarachi savdo zallaridagi kuygan lampalarni almashtirish"],"c":0,"why":"Umumiy zonalarni tozalash pollar holatini nazorat qilishni o'z ichiga oladi, bu esa tashrif buyuruvchilar xavfsizligiga bevosita ta'sir qiladi."},"en":{"q":"What is considered a priority task for mall cleaning staff in common areas?","a":["Keeping floors clean and safe, especially in wet weather","Washing display windows inside tenant stores","Replacing burnt-out light bulbs inside tenant sales areas"],"c":0,"why":"Common-area cleaning includes floor condition management, which directly affects visitor safety."}},{"id":"OP019","cat":"ops","logic":false,"ru":{"q":"Что входит в зону ответственности facility management (эксплуатации здания) ТРЦ?","a":["Техническое обслуживание здания, инженерных систем и общих зон","Ведение переговоров об арендных ставках с брендами","Разработка маркетинговых акций для арендаторов"],"c":0,"why":"Facility management отвечает за исправную работу здания, инженерных систем и содержание общих зон."},"uz":{"q":"TRC facility management (bino ekspluatatsiyasi) mas'uliyat doirasiga nima kiradi?","a":["Bino, muhandislik tizimlari va umumiy zonalarga texnik xizmat ko'rsatish","Brendlar bilan ijara stavkalari yuzasidan muzokara olib borish","Ijarachilar uchun marketing aksiyalarini ishlab chiqish"],"c":0,"why":"Facility management binoning, muhandislik tizimlarining ishlashi va umumiy zonalarni saqlash uchun javobgardir."},"en":{"q":"What falls under the responsibility of facility management in a mall?","a":["Technical upkeep of the building, engineering systems, and common areas","Negotiating rental rates with retail brands","Designing marketing promotions for tenants"],"c":0,"why":"Facility management is responsible for the building's technical condition, engineering systems, and common area upkeep."}},{"id":"OP020","cat":"ops","logic":false,"ru":{"q":"Какова главная цель системы навигации (wayfinding) в крупном ТРЦ?","a":["Помочь посетителям быстро ориентироваться и находить нужные магазины","Заменить необходимость в информационной стойке","Регулировать поток грузового транспорта на парковке"],"c":0,"why":"Wayfinding — это система указателей и навигации, облегчающая ориентацию посетителей внутри центра."},"uz":{"q":"Yirik TRC dagi navigatsiya tizimi (wayfinding) ning asosiy maqsadi nima?","a":["Tashrif buyuruvchilarga tez yo'nalish olish va kerakli do'konlarni topishga yordam berish","Ma'lumot stoykasiga bo'lgan ehtiyojni bekor qilish","Avtoturargohdagi yuk transporti oqimini tartibga solish"],"c":0,"why":"Wayfinding — bu tashrif buyuruvchilarning markaz ichida yo'nalishni osonlashtiruvchi ko'rsatkichlar va navigatsiya tizimidir."},"en":{"q":"What is the main purpose of a wayfinding system in a large mall?","a":["Help visitors orient themselves quickly and find the stores they need","Eliminate the need for an information desk","Regulate freight vehicle flow in the parking area"],"c":0,"why":"Wayfinding is a system of signage and navigation aids that helps visitors orient themselves within the mall."}},{"id":"OP021","cat":"ops","logic":false,"ru":{"q":"Какой элемент навигации считается наиболее эффективным для помощи посетителям на разных этажах ТРЦ?","a":["Поэтажные карты-навигаторы «Вы находитесь здесь» у эскалаторов и лифтов","Только устные объяснения сотрудников охраны","Голосовые объявления по громкой связи каждые 10 минут"],"c":0,"why":"Карты «Вы находитесь здесь», размещенные у ключевых узлов, — стандартный и эффективный элемент wayfinding."},"uz":{"q":"TRC ning turli qavatlarida tashrif buyuruvchilarga yordam berish uchun qaysi navigatsiya elementi eng samarali hisoblanadi?","a":["Eskalator va liftlar yonidagi \"Siz shu yerdasiz\" qavat xaritalari","Faqat xavfsizlik xodimlarining og'zaki tushuntirishlari","Har 10 daqiqada baland ovozli e'lonlar"],"c":0,"why":"Muhim tugunlar yonida joylashtirilgan \"Siz shu yerdasiz\" xaritalari wayfinding ning standart va samarali elementidir."},"en":{"q":"Which navigation element is considered most effective for helping visitors across multiple mall floors?","a":["\"You Are Here\" floor maps placed near escalators and elevators","Verbal directions given only by security staff","Loudspeaker announcements repeated every 10 minutes"],"c":0,"why":"\"You Are Here\" maps placed at key nodes are a standard and effective wayfinding element."}},{"id":"OP022","cat":"ops","logic":false,"ru":{"q":"За что в первую очередь отвечает управляющая компания (mall management) ТРЦ?","a":["За общую стратегию, эксплуатацию, тенант-микс и коммерческую эффективность объекта","Только за подбор персонала в магазины арендаторов","Только за оформление витрин арендаторов"],"c":0,"why":"Управляющая компания отвечает за комплексное управление объектом: стратегию, эксплуатацию и коммерческие показатели."},"uz":{"q":"TRC boshqaruv kompaniyasi (mall management) birinchi navbatda nimaga javobgar?","a":["Obyektning umumiy strategiyasi, ekspluatatsiyasi, tenant-miksi va tijorat samaradorligi uchun","Faqat ijarachi do'konlariga xodim tanlash uchun","Faqat ijarachi vitrinalarini bezash uchun"],"c":0,"why":"Boshqaruv kompaniyasi obyektni kompleks boshqarish — strategiya, ekspluatatsiya va tijorat ko'rsatkichlari uchun javobgardir."},"en":{"q":"What is the mall management company primarily responsible for?","a":["The overall strategy, operations, tenant mix, and commercial performance of the property","Only recruiting staff for tenant stores","Only designing tenant storefront displays"],"c":0,"why":"The management company is responsible for comprehensive property management: strategy, operations, and commercial performance."}},{"id":"OP023","cat":"ops","logic":false,"ru":{"q":"Какую функцию выполняет отдел по работе с арендаторами (tenant relations) в управляющей компании ТРЦ?","a":["Поддерживает коммуникацию с арендаторами и решает операционные вопросы","Разрабатывает архитектурный проект здания","Устанавливает тарифы на коммунальные услуги города"],"c":0,"why":"Tenant relations — это связующее звено между управляющей компанией и арендаторами по текущим операционным вопросам."},"uz":{"q":"TRC boshqaruv kompaniyasida ijarachilar bilan ishlash bo'limi (tenant relations) qanday vazifani bajaradi?","a":["Ijarachilar bilan aloqani qo'llab-quvvatlaydi va operatsion masalalarni hal qiladi","Binoning arxitektura loyihasini ishlab chiqadi","Shahar kommunal xizmatlari tariflarini belgilaydi"],"c":0,"why":"Tenant relations boshqaruv kompaniyasi va ijarachilar o'rtasidagi joriy operatsion masalalar bo'yicha bog'lovchi bo'g'indir."},"en":{"q":"What function does the tenant relations department serve within a mall management company?","a":["It maintains communication with tenants and resolves day-to-day operational issues","It designs the building's architectural blueprint","It sets municipal utility tariffs"],"c":0,"why":"Tenant relations is the liaison between the management company and tenants on ongoing operational matters."}},{"id":"OP024","cat":"ops","logic":false,"ru":{"q":"Почему в тенант-миксе важно избегать чрезмерного повторения одинаковых категорий магазинов рядом друг с другом?","a":["Это создает избыточную внутреннюю конкуренцию и снижает привлекательность зоны","Потому что это запрещено пожарными нормами","Потому что одинаковые категории требуют разных инженерных систем"],"c":0,"why":"Чрезмерная кластеризация одинаковых категорий без стратегии может привести к каннибализации трафика и продаж между арендаторами."},"uz":{"q":"Tenant-miksda bir xil toifadagi do'konlarni bir-biriga juda yaqin joylashtirishdan nega qochish kerak?","a":["Bu ortiqcha ichki raqobat yaratadi va zona jozibadorligini kamaytiradi","Chunki bu yong'in xavfsizligi normalari bilan taqiqlangan","Chunki bir xil toifalar turli muhandislik tizimlarini talab qiladi"],"c":0,"why":"Strategiyasiz bir xil toifalarni ortiqcha to'plash ijarachilar o'rtasida trafik va savdoning bir-birini yeb qo'yishiga olib kelishi mumkin."},"en":{"q":"Why is it important to avoid excessive clustering of identical store categories next to each other in tenant mix planning?","a":["It creates excessive internal competition and reduces the zone's appeal","It is prohibited under fire safety regulations","Identical categories require different engineering systems"],"c":0,"why":"Excessive clustering of the same category without strategy can cannibalize traffic and sales between tenants."}},{"id":"OP025","cat":"ops","logic":false,"ru":{"q":"Что подразумевает термин «зонирование» (zoning) в операционном управлении ТРЦ?","a":["Логическое деление торговых площадей на функциональные зоны по типу арендаторов и трафику","Юридическое деление здания на отдельные права собственности","Разделение здания на противопожарные отсеки только для склада"],"c":0,"why":"Зонирование ТРЦ — это распределение площадей по функциональным зонам (мода, фуд-корт, развлечения и т.д.) для оптимизации трафика."},"uz":{"q":"TRC operatsion boshqaruvida \"zonalashtirish\" (zoning) atamasi nimani anglatadi?","a":["Savdo maydonlarini ijarachi turi va trafikka ko'ra funktsional zonalarga mantiqiy bo'lish","Binoni alohida mulkchilik huquqlariga yuridik bo'lish","Binoni faqat ombor uchun yong'inga qarshi bo'limlarga ajratish"],"c":0,"why":"TRC zonalashtirish maydonlarni funktsional zonalarga (moda, fud-kort, ko'ngilochar va h.k.) trafikni optimallashtirish uchun taqsimlashdir."},"en":{"q":"What does the term \"zoning\" mean in mall operational management?","a":["Logically dividing retail space into functional zones by tenant type and traffic flow","Legally dividing the building into separate ownership titles","Dividing the building into fire compartments solely for storage"],"c":0,"why":"Mall zoning allocates space into functional zones (fashion, food court, entertainment, etc.) to optimize traffic flow."}},{"id":"OP026","cat":"ops","logic":false,"ru":{"q":"Какой из перечисленных факторов чаще всего учитывается при размещении якорного арендатора в плане ТРЦ?","a":["Способность генерировать трафик на удаленные участки галереи","Личные предпочтения бренда по цвету фасада","Наличие отдельного входа для персонала клининга"],"c":0,"why":"Якорей размещают так, чтобы они «вытягивали» трафик через всю галерею, включая удаленные зоны."},"uz":{"q":"TRC rejasida yetakchi ijarachini joylashtirishda quyidagi omillardan qaysi biri eng ko'p hisobga olinadi?","a":["Galereyaning chekka qismlariga trafik yarata olish qobiliyati","Brendning fasad rangi bo'yicha shaxsiy afzalliklari","Tozalash xodimlari uchun alohida kirish joyi mavjudligi"],"c":0,"why":"Yetakchilar galereyaning barcha qismlari, jumladan chekka zonalar orqali trafikni \"tortib\" o'tishi uchun joylashtiriladi."},"en":{"q":"Which factor is most commonly considered when positioning an anchor tenant within the mall layout?","a":["Its ability to pull traffic toward the more remote sections of the gallery","The brand's personal preference for facade color","Whether a separate entrance exists for cleaning staff"],"c":0,"why":"Anchors are positioned so they pull traffic through the entire gallery, including remote zones."}},{"id":"OP027","cat":"ops","logic":false,"ru":{"q":"Что из перечисленного является примером взаимодействия между инженерной службой и арендаторами в ТРЦ?","a":["Согласование графика отключения электричества для проведения плановых работ","Установление розничных цен на товары арендатора","Подбор ассортимента для магазина арендатора"],"c":0,"why":"Инженерная служба координирует с арендаторами технические работы, влияющие на электро- и водоснабжение помещений."},"uz":{"q":"Quyidagilardan qaysi biri TRC dagi muhandislik xizmati va ijarachilar o'rtasidagi hamkorlikka misol bo'la oladi?","a":["Rejali ishlar uchun elektr energiyasini o'chirish jadvalini kelishish","Ijarachi tovarlariga chakana narxlarni belgilash","Ijarachi do'koni uchun assortimentni tanlash"],"c":0,"why":"Muhandislik xizmati xonalarning elektr va suv ta'minotiga ta'sir qiluvchi texnik ishlarni ijarachilar bilan muvofiqlashtiradi."},"en":{"q":"Which of the following is an example of coordination between engineering services and tenants in a mall?","a":["Agreeing on a power shutdown schedule for planned maintenance work","Setting retail prices for a tenant's merchandise","Selecting the product assortment for a tenant's store"],"c":0,"why":"Engineering services coordinate with tenants on technical work affecting power and water supply to their units."}},{"id":"OP028","cat":"ops","logic":false,"ru":{"q":"Какая практика характерна для эффективного управления очередями и потоком в фуд-корте в часы пик?","a":["Динамическое распределение посадочных мест и координация операторов кухни","Полное закрытие половины операторов питания","Отказ от уборки столов до конца рабочего дня"],"c":0,"why":"Эффективное управление предполагает гибкое распределение мест и координацию между операторами для сокращения очередей."},"uz":{"q":"Fud-kortda eng band soatlarda navbat va oqimni samarali boshqarish uchun qanday amaliyot xosdir?","a":["O'tirish joylarini dinamik taqsimlash va oshxona operatorlarini muvofiqlashtirish","Ovqatlanish operatorlarining yarmini butunlay yopish","Ish kuni tugagunga qadar stollarni tozalashdan voz kechish"],"c":0,"why":"Samarali boshqaruv navbatlarni kamaytirish uchun joylarni moslashuvchan taqsimlash va operatorlar o'rtasidagi muvofiqlashtirishni nazarda tutadi."},"en":{"q":"What practice characterizes effective queue and flow management in a food court during peak hours?","a":["Dynamic seating allocation and coordination among kitchen operators","Closing half of the food operators completely","Skipping table clearing until the end of the business day"],"c":0,"why":"Effective management involves flexible seating allocation and coordination between operators to reduce queues."}},{"id":"OP029","cat":"ops","logic":false,"ru":{"q":"Какой аспект наиболее важен при проектировании маршрута грузовых лифтов в многоэтажном ТРЦ?","a":["Изоляция грузового маршрута от посетительских зон и лифтов","Использование того же лифта, что и для покупателей","Расположение грузового лифта у главного входа для посетителей"],"c":0,"why":"Грузовые лифты должны быть физически отделены от посетительских потоков для безопасности и эстетики."},"uz":{"q":"Ko'p qavatli TRC da yuk liftlari marshrutini loyihalashtirishda eng muhim jihat nima?","a":["Yuk marshrutini tashrif buyuruvchilar zonalari va liftlaridan izolyatsiya qilish","Xaridorlar uchun ishlatiladigan liftdan foydalanish","Yuk liftini tashrif buyuruvchilarning asosiy kirish joyida joylashtirish"],"c":0,"why":"Yuk liftlari xavfsizlik va estetika uchun tashrif buyuruvchilar oqimidan jismonan ajratilgan bo'lishi kerak."},"en":{"q":"What aspect is most important when designing the freight elevator route in a multi-story mall?","a":["Isolating the freight route from customer zones and passenger elevators","Sharing the same elevator used by shoppers","Placing the freight elevator at the main visitor entrance"],"c":0,"why":"Freight elevators must be physically separated from visitor flows for safety and aesthetic reasons."}},{"id":"OP030","cat":"ops","logic":false,"ru":{"q":"Какова роль отдела маркетинга в структуре управляющей компании ТРЦ в отличие от отдела аренды?","a":["Продвижение центра и повышение трафика, тогда как аренда занимается коммерческими условиями","Установление цен на аренду и подписание договоров с брендами","Контроль инженерных систем и клининга здания"],"c":0,"why":"Маркетинг отвечает за продвижение и привлечение посетителей, а отдел аренды — за коммерческие переговоры и договоры."},"uz":{"q":"TRC boshqaruv kompaniyasi tuzilmasida marketing bo'limining ijara bo'limidan farqli roli nimada?","a":["Markazni targ'ib qilish va trafikni oshirish, ijara esa tijorat shartlari bilan shug'ullanadi","Ijara narxlarini belgilash va brendlar bilan shartnoma imzolash","Bino muhandislik tizimlari va tozalashni nazorat qilish"],"c":0,"why":"Marketing targ'ibot va tashrif buyuruvchilarni jalb qilish uchun javobgar, ijara bo'limi esa tijorat muzokaralari va shartnomalar bilan shug'ullanadi."},"en":{"q":"What is the role of the marketing department within a mall management company, as distinct from the leasing department?","a":["Promoting the mall and driving traffic, while leasing handles commercial terms","Setting rental prices and signing contracts with brands","Overseeing the building's engineering systems and cleaning"],"c":0,"why":"Marketing is responsible for promotion and driving visitor traffic, while leasing handles commercial negotiations and contracts."}},{"id":"OP031","cat":"ops","logic":false,"ru":{"q":"Чем суб-якорь отличается от якорного арендатора в ТРЦ?","a":["Меньшая площадь и узкая специализация, но всё равно генерирует трафик","Всегда занимает более 5000 м² и подписывает договор первым","Не платит аренду, только процент с оборота"],"c":0,"why":"Суб-якорь — это средний по масштабу генератор трафика с меньшей площадью, чем у якоря."},"uz":{"q":"Sub-langar ijarachi asosiy langardan nimasi bilan farq qiladi?","a":["Maydoni kichikroq va tor ixtisoslashgan, lekin trafik yaratadi","Har doim 5000 m² dan katta va shartnomani birinchi imzolaydi","Ijara to'lamaydi, faqat aylanmadan foiz beradi"],"c":0,"why":"Sub-langar kichikroq maydonli, lekin sezilarli trafik keltiruvchi ijarachidir."},"en":{"q":"How does a sub-anchor tenant differ from a true anchor tenant in a shopping mall?","a":["Smaller footprint and narrower focus, but still drives meaningful footfall","Always over 5,000 sqm and signs the lease before all others","Pays no fixed rent, only a percentage of turnover"],"c":0,"why":"A sub-anchor occupies a smaller area than an anchor but still generates significant traffic."}},{"id":"OP032","cat":"ops","logic":false,"ru":{"q":"Какова главная функция магнит-арендатора (magnet tenant) в позиционировании этажа ТРЦ?","a":["Притягивать посетителей вглубь этажа, стимулируя проходимость соседних бутиков","Обеспечивать максимальную ставку аренды за квадратный метр на этаже","Заменять функцию навигации и информационных стоек"],"c":0,"why":"Магнит-арендаторы размещаются так, чтобы вести поток покупателей мимо мелких магазинов."},"uz":{"q":"Magnit-ijarachining qavat pozitsiyalashdagi asosiy vazifasi nima?","a":["Tashrif buyuruvchilarni qavat ichkarisiga tortib, qo'shni do'konlar oqimini oshirish","Qavatdagi eng yuqori ijara stavkasini ta'minlash","Navigatsiya va ma'lumot stendlari vazifasini bajarish"],"c":0,"why":"Magnit-ijarachilar xaridorlar oqimini kichik do'konlar yonidan o'tkazish uchun joylashtiriladi."},"en":{"q":"What is the primary role of a magnet tenant in floor-level positioning within a mall?","a":["To pull visitors deeper into the floor, boosting traffic past smaller stores","To guarantee the highest rent per square meter on that floor","To replace the need for wayfinding signage"],"c":0,"why":"Magnet tenants are placed strategically to draw shopper flow past smaller units."}},{"id":"OP033","cat":"ops","logic":false,"ru":{"q":"При планировании tenant mix какой показатель обычно используют для оценки баланса категорий?","a":["Долю GLA (арендопригодной площади), занятую каждой категорией арендаторов","Только количество вывесок на фасаде здания","Среднюю высоту потолков в каждой зоне"],"c":0,"why":"Баланс категорий оценивается через процент GLA, отведённый под fashion, F&B, entertainment и services."},"uz":{"q":"Tenant mix rejalashtirishda kategoriyalar balansini baholash uchun odatda qaysi ko'rsatkich ishlatiladi?","a":["Har bir ijarachi toifasi egallagan GLA (ijaraga yaroqli maydon) ulushi","Bino fasadidagi lavhalar soni","Har bir zonadagi shift balandligining o'rtachasi"],"c":0,"why":"Kategoriya balansi fashion, F&B, ko'ngilochar va xizmatlar uchun ajratilgan GLA foizi orqali baholanadi."},"en":{"q":"When planning tenant mix, which metric is typically used to assess category balance?","a":["The share of GLA (gross leasable area) occupied by each tenant category","Only the number of storefront signs on the facade","The average ceiling height in each zone"],"c":0,"why":"Category balance is measured by the percentage of GLA allocated to fashion, F&B, entertainment, and services."}},{"id":"OP034","cat":"ops","logic":false,"ru":{"q":"Почему избыточная доля F&B в общем tenant mix считается риском для управляющей компании?","a":["Растёт нагрузка на инженерные системы (вентиляция, жироловки) и конкуренция за один и тот же трафик обеда","Потому что рестораны никогда не платят аренду вовремя","Потому что F&B операторы не подписывают долгосрочные договоры"],"c":0,"why":"Избыток F&B увеличивает инженерную нагрузку и каннибализирует посетительский поток в пиковые часы."},"uz":{"q":"Umumiy tenant mix'da F&B ulushi haddan tashqari ko'p bo'lishi nega boshqaruv kompaniyasi uchun xavf hisoblanadi?","a":["Muhandislik tizimlariga (ventilyatsiya, moy separatorlari) yuk oshadi va tushlik trafigi uchun raqobat kuchayadi","Restoranlar hech qachon ijarani o'z vaqtida to'lamaydi","F&B operatorlari uzoq muddatli shartnoma imzolamaydi"],"c":0,"why":"Ortiqcha F&B muhandislik yukini oshiradi va cho'qqi soatlarda mijozlar oqimini bo'lib yuboradi."},"en":{"q":"Why is an oversized F&B share in the overall tenant mix considered a risk for the management company?","a":["It strains engineering systems (ventilation, grease traps) and creates competition for the same lunch-hour traffic","Because restaurants never pay rent on time","Because F&B operators refuse to sign long-term leases"],"c":0,"why":"Excess F&B increases engineering load and cannibalizes visitor flow during peak meal hours."}},{"id":"OP035","cat":"ops","logic":false,"ru":{"q":"Что подразумевает принцип зонирования 'вертикального якоря' в многоэтажном ТРЦ?","a":["Размещение крупного арендатора (гипермаркет, кинотеатр) на верхнем или нижнем этаже, чтобы поднять трафик через все уровни","Установку вертикальных вывесок только у входа в здание","Разделение здания на зоны по этажам исключительно по цвету отделки"],"c":0,"why":"Вертикальный якорь на удалённом этаже заставляет посетителей проходить через промежуточные уровни."},"uz":{"q":"Ko'p qavatli TRTS'da 'vertikal langar' zonalashtirish tamoyili nimani anglatadi?","a":["Yirik ijarachini (gipermarket, kinoteatr) yuqori yoki pastki qavatga joylashtirib, barcha qavatlar orqali trafikni oshirish","Bino kirish qismida faqat vertikal lavhalar o'rnatish","Binoni qavatlarga faqat pardoz rangiga qarab bo'lish"],"c":0,"why":"Uzoq qavatdagi vertikal langar tashrif buyuruvchilarni oraliq qavatlardan o'tishga majbur qiladi."},"en":{"q":"What does the 'vertical anchor' zoning principle mean in a multi-level mall?","a":["Placing a major tenant (hypermarket, cinema) on a top or bottom floor to pull traffic through intermediate levels","Installing vertical signage only at the main entrance","Dividing the building into zones purely by interior finish color"],"c":0,"why":"A vertical anchor on a remote floor forces shoppers to pass through the levels in between."}},{"id":"OP036","cat":"ops","logic":false,"ru":{"q":"Какой принцип обычно применяют при размещении фуд-корта относительно кинотеатра и детской зоны?","a":["Располагать их смежно, формируя единый развлекательно-гастрономический кластер для увеличения времени пребывания","Максимально разносить их по разным этажам, чтобы избежать шума","Размещать фуд-корт только рядом с грузовым лифтом"],"c":0,"why":"Смежное расположение фуд-корта, кино и детской зоны увеличивает dwell time и перекрёстные визиты."},"uz":{"q":"Fud-kortni kinoteatr va bolalar zonasiga nisbatan joylashtirishda odatda qanday tamoyilga amal qilinadi?","a":["Ularni yonma-yon joylashtirib, ko'ngilocharlik-gastronomiya klasterini yaratish orqali tashrif vaqtini oshirish","Shovqindan qochish uchun ularni turli qavatlarga tarqatib joylashtirish","Fud-kortni faqat yuk lifti yonida joylashtirish"],"c":0,"why":"Fud-kort, kino va bolalar zonasining yonma-yon joylashuvi tashrif vaqtini va o'zaro tashriflarni oshiradi."},"en":{"q":"What principle is typically applied when locating the food court relative to the cinema and kids zone?","a":["Cluster them adjacently to create a combined entertainment-dining zone that extends visitor dwell time","Spread them across separate floors as far apart as possible to reduce noise","Place the food court only near the service elevator"],"c":0,"why":"Adjacent placement of food court, cinema, and kids zone increases dwell time and cross-visitation."}},{"id":"OP037","cat":"ops","logic":false,"ru":{"q":"Что такое 'grease trap' (жироуловитель) и почему он обязателен для операторов фуд-корта?","a":["Устройство для улавливания жиров из стоков кухни перед сбросом в канализацию, предотвращающее засоры","Специальный холодильник для хранения мясной продукции","Вытяжной вентилятор над зоной кассы фуд-корта"],"c":0,"why":"Жироуловитель защищает канализационную систему здания от засорения жирами из кухонных стоков."},"uz":{"q":"'Grease trap' (moy separatori) nima va nega u fud-kort operatorlari uchun majburiy?","a":["Oshxona oqava suvidagi moyni kanalizatsiyaga tushishidan oldin ushlab qoluvchi qurilma, tiqilib qolishning oldini oladi","Go'sht mahsulotlarini saqlash uchun maxsus muzlatgich","Fud-kort kassa zonasi ustidagi tortma ventilyator"],"c":0,"why":"Moy separatori bino kanalizatsiya tizimini oshxona moyidan tiqilib qolishdan himoya qiladi."},"en":{"q":"What is a grease trap and why is it mandatory for food court operators?","a":["A device that captures fats from kitchen wastewater before it enters the sewage system, preventing blockages","A special refrigerator for storing meat products","An exhaust fan installed above the food court cash registers"],"c":0,"why":"A grease trap protects the building's sewage system from being clogged by kitchen grease."}},{"id":"OP038","cat":"ops","logic":false,"ru":{"q":"Почему кинотеатр как развлекательный якорь обычно размещают на верхнем этаже ТРЦ?","a":["Верхние этажи менее востребованы под ритейл, а кино создаёт вечерний трафик, поднимая посетителей через все уровни","Потому что кинопроекторам нужен естественный дневной свет","Потому что пожарные нормы запрещают кинозалы ниже второго этажа"],"c":0,"why":"Кинотеатр компенсирует низкую ритейл-привлекательность верхних этажей и продлевает вечерний трафик."},"uz":{"q":"Nega kinoteatr ko'ngilochar langar sifatida odatda TRTSning yuqori qavatiga joylashtiriladi?","a":["Yuqori qavatlar chakana savdo uchun kam talab qilinadi, kino esa kechki trafikni yaratib, tashrif buyuruvchilarni barcha qavatlardan o'tkazadi","Kino proyektorlariga tabiiy kunduzgi yorug'lik kerak bo'lgani uchun","Yong'in xavfsizligi normalari kino zallarini ikkinchi qavatdan pastda taqiqlagani uchun"],"c":0,"why":"Kinoteatr yuqori qavatlarning past chakana jozibadorligini qoplaydi va kechki trafikni uzaytiradi."},"en":{"q":"Why is a cinema, as an entertainment anchor, usually placed on the top floor of a mall?","a":["Upper floors are less desirable for retail, while cinema generates evening traffic that pulls visitors through all levels","Because film projectors require natural daylight","Because fire codes prohibit cinema halls below the second floor"],"c":0,"why":"The cinema compensates for lower retail appeal on upper floors and extends evening foot traffic."}},{"id":"OP039","cat":"ops","logic":false,"ru":{"q":"Какое требование безопасности является ключевым при проектировании детской развлекательной зоны в ТРЦ?","a":["Визуальная изоляция от общих проходов и наличие контролируемого единственного входа-выхода","Расположение рядом с грузовыми лифтами для удобства поставки оборудования","Отсутствие какого-либо персонала внутри зоны в рабочие часы"],"c":0,"why":"Контролируемый вход-выход и отделение от общего потока снижают риск потери ребёнка или травм."},"uz":{"q":"TRTSdagi bolalar ko'ngilochar zonasini loyihalashda asosiy xavfsizlik talabi nima?","a":["Umumiy yo'laklardan vizual ajratilgan holda, nazorat qilinadigan yagona kirish-chiqish","Uskunalarni yetkazish qulay bo'lishi uchun yuk liftlari yonida joylashuv","Ish vaqtida zona ichida hech qanday xodim bo'lmasligi"],"c":0,"why":"Nazorat qilinadigan yagona kirish-chiqish va umumiy oqimdan ajratish bolaning yo'qolish yoki jarohat xavfini kamaytiradi."},"en":{"q":"What is a key safety requirement when designing a kids entertainment zone in a mall?","a":["Visual separation from general walkways with a single, supervised entry/exit point","Placement next to service elevators for easy equipment delivery","No staff present inside the zone during operating hours"],"c":0,"why":"A single supervised entry/exit and separation from general foot traffic reduce the risk of a lost child or injury."}},{"id":"OP040","cat":"ops","logic":false,"ru":{"q":"Какой стандартный ориентир парковочного коэффициента (parking ratio) часто используют для ТРЦ регионального формата?","a":["Примерно 4-6 машиномест на 100 м² GLA","Ровно 1 машиноместо на 100 м² GLA","20 машиномест на 100 м² GLA независимо от формата"],"c":0,"why":"Для региональных ТРЦ типичный ориентир — 4-6 машиномест на 100 м² арендуемой площади."},"uz":{"q":"Mintaqaviy formatdagi TRTS uchun ko'pincha qanday parking koeffitsiyenti me'yori qo'llaniladi?","a":["Har 100 m² GLA uchun taxminan 4-6 ta parking joyi","Har 100 m² GLA uchun aynan 1 ta parking joyi","Formatdan qat'i nazar har 100 m² GLA uchun 20 ta parking joyi"],"c":0,"why":"Mintaqaviy TRTSlar uchun odatiy me'yor — har 100 m² ijara maydoniga 4-6 ta parking joyi."},"en":{"q":"What is a common benchmark parking ratio used for a regional-format shopping mall?","a":["Approximately 4-6 parking spaces per 100 sqm of GLA","Exactly 1 parking space per 100 sqm of GLA","20 parking spaces per 100 sqm of GLA regardless of format"],"c":0,"why":"A typical benchmark for regional malls is 4-6 parking spaces per 100 sqm of leasable area."}},{"id":"OP041","cat":"ops","logic":false,"ru":{"q":"Почему высокая загрузка парковки в часы пик считается операционной проблемой, даже если торговая выручка растёт?","a":["Отсутствие свободных мест отпугивает новых посетителей и снижает потенциальный трафик","Это увеличивает арендную плату для всех арендаторов автоматически","Загрузка парковки не влияет на посещаемость торговых залов"],"c":0,"why":"Переполненная парковка создаёт барьер входа и теряет потенциальных клиентов, которые уезжают, не найдя места."},"uz":{"q":"Savdo aylanmasi o'sayotgan bo'lsa ham, cho'qqi soatlarda parkovkaning to'liq band bo'lishi nega operatsion muammo hisoblanadi?","a":["Bo'sh joy yo'qligi yangi tashrif buyuruvchilarni qaytaradi va potensial trafikni kamaytiradi","Bu barcha ijarachilar uchun ijara haqini avtomatik oshiradi","Parkovka bandligi savdo zallariga tashrif buyurishga ta'sir qilmaydi"],"c":0,"why":"To'lib ketgan parkovka kirish to'sig'ini yaratadi va joy topmagan mijozlarni yo'qotadi."},"en":{"q":"Why is high parking occupancy at peak hours considered an operational problem even if sales revenue is growing?","a":["Lack of available spaces deters new visitors and caps potential foot traffic","It automatically increases rent for all tenants","Parking occupancy has no effect on mall visitation"],"c":0,"why":"A saturated parking lot creates a barrier to entry, turning away potential customers who cannot find a space."}},{"id":"OP042","cat":"ops","logic":false,"ru":{"q":"Какова основная цель разделения зон парковки на 'краткосрочную' и 'долгосрочную' (например, для сотрудников)?","a":["Освободить ближние места для покупателей с быстрой ротацией и не занимать их персоналом на весь день","Увеличить общий тариф на парковку для всех категорий","Упростить работу службы уборки только в одной зоне"],"c":0,"why":"Разделение зон предотвращает занятие удобных мест сотрудниками на целый день, сохраняя ротацию для покупателей."},"uz":{"q":"Parkovkani 'qisqa muddatli' va 'uzoq muddatli' (masalan, xodimlar uchun) zonalarga bo'lishning asosiy maqsadi nima?","a":["Tez almashinuvchi xaridorlar uchun yaqin joylarni bo'shatib, ularni xodimlar butun kun band qilib qo'ymasligi","Barcha toifalar uchun umumiy parkovka tarifini oshirish","Tozalash xizmatining ishini faqat bitta zonada osonlashtirish"],"c":0,"why":"Zonalarni ajratish qulay joylarni xodimlar butun kun egallab turishining oldini olib, xaridorlar uchun aylanmani ta'minlaydi."},"en":{"q":"What is the main purpose of separating parking into 'short-term' and 'long-term' (e.g., staff) zones?","a":["To keep convenient spaces free for high-turnover shoppers instead of being occupied by staff all day","To raise the overall parking tariff for every category of user","To simplify cleaning operations in only one zone"],"c":0,"why":"Zone separation prevents staff from occupying prime spaces all day, preserving turnover for shoppers."}},{"id":"OP043","cat":"ops","logic":false,"ru":{"q":"Почему графики разгрузки товара на loading dock обычно составляют по временным слотам (time slots)?","a":["Чтобы избежать заторов грузового транспорта и обеспечить равномерную нагрузку на погрузочную зону","Потому что налоговое законодательство требует фиксировать время каждой поставки","Чтобы арендаторы могли получать товар только один раз в месяц"],"c":0,"why":"Слотирование разгрузки предотвращает скопление фур и очереди у ограниченного числа доковых ворот."},"uz":{"q":"Nega loading dock'da tovar tushirish jadvali odatda vaqt slotlari bo'yicha tuziladi?","a":["Yuk mashinalari to'planib qolishining oldini olish va ortish-tushirish zonasiga yukni teng taqsimlash uchun","Soliq qonunchiligi har bir yetkazib berish vaqtini qayd etishni talab qilgani uchun","Ijarachilar tovarni faqat oyiga bir marta olishi uchun"],"c":0,"why":"Vaqt slotlari cheklangan dock darvozalarida yuk mashinalari navbati va to'planib qolishining oldini oladi."},"en":{"q":"Why are loading dock delivery schedules typically organized into time slots?","a":["To prevent truck congestion and ensure an even workload across the limited dock bays","Because tax regulations require logging the exact time of every delivery","So that tenants can only receive goods once a month"],"c":0,"why":"Time slotting prevents trucks from queuing and congesting a limited number of dock bays."}},{"id":"OP044","cat":"ops","logic":false,"ru":{"q":"Какой параметр критичен при проектировании грузового лифта для доставки товара на верхние этажи ТРЦ?","a":["Грузоподъёмность и габариты кабины, достаточные для палет и крупногабаритного товара","Наличие зеркал в кабине для удобства персонала","Скорость движения, идентичная пассажирскому эскалатору"],"c":0,"why":"Грузовой лифт должен вмещать паллеты и тяжёлые грузы, поэтому его грузоподъёмность и размер кабины первичны."},"uz":{"q":"TRTSning yuqori qavatlariga tovar yetkazish uchun yuk liftini loyihalashda qaysi parametr hal qiluvchi ahamiyatga ega?","a":["Palletlar va gabaritli yuklar uchun yetarli yuk ko'tarish qobiliyati va kabina o'lchami","Xodimlar qulayligi uchun kabinada oyna bo'lishi","Yo'lovchi eskalatoriga teng harakat tezligi"],"c":0,"why":"Yuk lifti palletlar va og'ir yuklarni sig'dirishi kerak, shuning uchun yuk ko'tarish qobiliyati va kabina o'lchami muhim."},"en":{"q":"Which parameter is critical when designing a service elevator for goods delivery to upper floors of a mall?","a":["Load capacity and cabin dimensions sufficient for pallets and bulky goods","Having mirrors inside the cabin for staff convenience","A travel speed identical to passenger escalators"],"c":0,"why":"A service elevator must accommodate pallets and heavy loads, making capacity and cabin size the primary criteria."}},{"id":"OP045","cat":"ops","logic":false,"ru":{"q":"Что такое 'back-of-house' (BOH) маршрут в операционной логистике ТРЦ?","a":["Служебные коридоры и пути для персонала и доставки товара, скрытые от посетителей","Главный входной вестибюль для покупателей","Зона VIP-парковки перед центральным входом"],"c":0,"why":"BOH-маршруты — это скрытые от гостей служебные пути для логистики и персонала."},"uz":{"q":"TRTS operatsion logistikasida 'back-of-house' (BOH) yo'nalishi nima?","a":["Xodimlar va tovar yetkazib berish uchun mo'ljallangan, tashrif buyuruvchilardan yashirin xizmat yo'laklari","Xaridorlar uchun asosiy kirish vestibyuli","Markaziy kirish oldidagi VIP-parkovka zonasi"],"c":0,"why":"BOH yo'nalishlari mehmonlardan yashirin bo'lgan logistika va xodimlar uchun xizmat yo'llaridir."},"en":{"q":"What does 'back-of-house' (BOH) routing mean in mall operational logistics?","a":["Service corridors and pathways for staff and goods delivery, hidden from visitors","The main entrance lobby used by shoppers","The VIP parking zone in front of the main entrance"],"c":0,"why":"BOH routes are service pathways for logistics and staff kept out of visitors' sight."}},{"id":"OP046","cat":"ops","logic":false,"ru":{"q":"Зачем в системе HVAC торгового центра предусматривают отдельный контур вентиляции для фуд-корта?","a":["Чтобы изолировать запахи готовки и повышенную влажность от остальных торговых зон","Потому что фуд-корт всегда находится в подвале без окон","Чтобы снизить расходы на электроэнергию во всём здании"],"c":0,"why":"Отдельный контур вентиляции предотвращает распространение запахов и пара кухни на остальные зоны ТРЦ."},"uz":{"q":"Savdo markazining HVAC tizimida fud-kort uchun alohida ventilyatsiya konturi nega ko'zda tutiladi?","a":["Pishirish hidlari va yuqori namlikni boshqa savdo zonalaridan izolyatsiya qilish uchun","Fud-kort har doim derazasiz podvalda joylashgani uchun","Butun bino bo'yicha elektr energiyasi xarajatlarini kamaytirish uchun"],"c":0,"why":"Alohida ventilyatsiya konturi oshxona hidi va bug'ining boshqa zonalarga tarqalishining oldini oladi."},"en":{"q":"Why does a mall's HVAC system include a separate ventilation loop for the food court?","a":["To isolate cooking odors and elevated humidity from the rest of the retail zones","Because the food court is always located in a windowless basement","To reduce electricity costs across the entire building"],"c":0,"why":"A dedicated ventilation loop prevents kitchen odors and steam from spreading into other zones of the mall."}},{"id":"OP047","cat":"ops","logic":false,"ru":{"q":"Какова цель регулярного технического обслуживания эскалаторов согласно эксплуатационным нормам ТРЦ?","a":["Предотвращение аварийных остановок и обеспечение безопасности пассажиропотока","Повышение декоративной привлекательности эскалатора","Увеличение максимальной скорости движения ступеней"],"c":0,"why":"Плановое ТО эскалаторов снижает риск поломок и травм, обеспечивая бесперебойную работу."},"uz":{"q":"TRTS ekspluatatsiya me'yorlariga ko'ra eskalatorlarni muntazam texnik xizmat ko'rsatishning maqsadi nima?","a":["Favqulodda to'xtashlarning oldini olish va yo'lovchilar oqimi xavfsizligini ta'minlash","Eskalatorning bezak jozibadorligini oshirish","Pog'onalar harakatining maksimal tezligini oshirish"],"c":0,"why":"Rejali texnik xizmat eskalator buzilishi va jarohat xavfini kamaytirib, uzluksiz ishlashni ta'minlaydi."},"en":{"q":"What is the purpose of regular escalator maintenance under mall operational standards?","a":["Preventing unplanned breakdowns and ensuring passenger flow safety","Improving the decorative appearance of the escalator","Increasing the maximum step travel speed"],"c":0,"why":"Scheduled escalator maintenance reduces the risk of breakdowns and injuries, ensuring uninterrupted operation."}},{"id":"OP048","cat":"ops","logic":false,"ru":{"q":"Что входит в понятие 'зона дымоудаления' (smoke exhaust zone) в системе пожарной безопасности ТРЦ?","a":["Инженерная система для отвода дыма из атриума или коридоров при пожаре, обеспечивающая пути эвакуации","Отдельное помещение для курения посетителей","Зона хранения легковоспламеняющихся товаров на складе"],"c":0,"why":"Система дымоудаления освобождает пути эвакуации от дыма, повышая шансы безопасного выхода людей."},"uz":{"q":"TRTS yong'in xavfsizligi tizimida 'tutun chiqarish zonasi' (smoke exhaust zone) tushunchasi nimani anglatadi?","a":["Yong'in vaqtida atrium yoki koridorlardan tutunni chiqarib, evakuatsiya yo'llarini ta'minlovchi muhandislik tizimi","Tashrif buyuruvchilar uchun chekish xonasi","Omborda yonuvchan tovarlarni saqlash zonasi"],"c":0,"why":"Tutun chiqarish tizimi evakuatsiya yo'llarini tutundan tozalab, odamlarning xavfsiz chiqishini ta'minlaydi."},"en":{"q":"What does 'smoke exhaust zone' mean within a mall's fire safety system?","a":["An engineering system that vents smoke from the atrium or corridors during a fire to keep evacuation routes clear","A designated smoking room for visitors","A storage area for flammable goods in the warehouse"],"c":0,"why":"The smoke exhaust system clears escape routes of smoke, improving safe evacuation chances."}},{"id":"OP049","cat":"ops","logic":false,"ru":{"q":"С какой периодичностью, согласно типовой практике, должны проверяться системы пожаротушения и сигнализации в ТРЦ?","a":["Регулярно, по установленному графику планового технического обслуживания (например, ежемесячно/ежеквартально)","Только один раз при вводе здания в эксплуатацию","Раз в 10 лет при капитальном ремонте"],"c":0,"why":"Системы пожарной безопасности требуют регулярных плановых проверок для сохранения работоспособности."},"uz":{"q":"Odatiy amaliyotga ko'ra, TRTSda yong'in o'chirish va signalizatsiya tizimlari qanday davriylikda tekshirilishi kerak?","a":["Belgilangan rejali texnik xizmat ko'rsatish grafigi bo'yicha muntazam (masalan, oyiga/chorakda bir marta)","Faqat bino ishga tushirilganda bir marta","Kapital ta'mirlashda 10 yilda bir marta"],"c":0,"why":"Yong'in xavfsizligi tizimlari ishlash qobiliyatini saqlash uchun muntazam rejali tekshiruvlarni talab qiladi."},"en":{"q":"How frequently should fire suppression and alarm systems typically be inspected in a mall under standard practice?","a":["Regularly, on a scheduled maintenance calendar (e.g., monthly or quarterly)","Only once, when the building is first commissioned","Once every 10 years during major renovation"],"c":0,"why":"Fire safety systems require regular scheduled inspections to remain functional and compliant."}},{"id":"OP050","cat":"ops","logic":false,"ru":{"q":"Какова основная задача службы security на входных группах ТРЦ помимо контроля доступа?","a":["Мониторинг подозрительного поведения и оперативное реагирование на инциденты для безопасности посетителей","Проверка кассовых чеков у каждого покупателя на выходе","Сбор статистики по продажам арендаторов"],"c":0,"why":"Задача охраны — превентивный мониторинг и быстрое реагирование, а не финансовый контроль арендаторов."},"uz":{"q":"TRTS kirish guruhlaridagi xavfsizlik xizmatining kirishni nazorat qilishdan tashqari asosiy vazifasi nima?","a":["Shubhali xatti-harakatlarni kuzatish va tashrif buyuruvchilar xavfsizligi uchun voqealarga tezkor javob berish","Chiqishda har bir xaridorning kassa chekini tekshirish","Ijarachilarning savdo statistikasini yig'ish"],"c":0,"why":"Xavfsizlik xizmatining vazifasi ijarachilarni moliyaviy nazorat qilish emas, balki preventiv kuzatuv va tezkor javobdir."},"en":{"q":"Beyond access control, what is the main duty of security staff at mall entrance points?","a":["Monitoring for suspicious behavior and responding quickly to incidents to protect visitor safety","Checking every shopper's receipt at the exit","Collecting sales statistics from tenants"],"c":0,"why":"Security's role is proactive monitoring and rapid incident response, not tenant financial oversight."}},{"id":"OP051","cat":"ops","logic":false,"ru":{"q":"Почему CCTV-мониторинг в общих зонах ТРЦ важен не только для безопасности, но и для операционного менеджмента?","a":["Записи помогают анализировать потоки посетителей, разрешать споры и оптимизировать зонирование","Камеры автоматически начисляют штрафы нарушителям парковки","Видео используется исключительно для рекламных роликов арендаторов"],"c":0,"why":"Видеоаналитика CCTV даёт данные о трафике, которые используют для операционных решений, а не только для охраны."},"uz":{"q":"TRTSning umumiy zonalaridagi CCTV monitoring nega faqat xavfsizlik uchun emas, balki operatsion boshqaruv uchun ham muhim?","a":["Yozuvlar tashrif buyuruvchilar oqimini tahlil qilish, nizolarni hal qilish va zonalashtirishni optimallashtirishga yordam beradi","Kameralar parkovka qoidabuzarlariga avtomatik jarima yozadi","Video faqat ijarachilarning reklama roliklari uchun ishlatiladi"],"c":0,"why":"CCTV video-analitikasi trafik haqida ma'lumot beradi va bu operatsion qarorlar uchun ishlatiladi, nafaqat xavfsizlik uchun."},"en":{"q":"Why is CCTV monitoring in common areas important not just for security but for operational management?","a":["Footage helps analyze visitor flow, resolve disputes, and optimize zoning decisions","Cameras automatically issue fines to parking violators","Video is used solely for tenant advertising content"],"c":0,"why":"CCTV analytics provide traffic data used for operational decisions, not just security purposes."}},{"id":"OP052","cat":"ops","logic":false,"ru":{"q":"Какая практика уборки типична для общих зон ТРЦ в часы высокой посещаемости (пиковые часы)?","a":["Частая точечная уборка малыми командами без перекрытия проходов, а не масштабная влажная уборка","Полное закрытие зоны для генеральной уборки на 2 часа","Уборка полностью прекращается до закрытия ТРЦ"],"c":0,"why":"В часы пик применяется оперативная точечная уборка, чтобы не создавать помехи потоку покупателей."},"uz":{"q":"TRTSning umumiy zonalarida yuqori tashrif soatlarida (cho'qqi soatlar) qanday tozalash amaliyoti odatiy hisoblanadi?","a":["Yo'laklarni to'smasdan, kichik guruhlar tomonidan tez-tez nuqtali tozalash, keng ko'lamli ho'l tozalash emas","Zonani 2 soatga umumiy tozalash uchun to'liq yopish","TRTS yopilguncha tozalash butunlay to'xtatiladi"],"c":0,"why":"Cho'qqi soatlarda xaridorlar oqimiga xalaqit bermaslik uchun tezkor nuqtali tozalash qo'llaniladi."},"en":{"q":"What cleaning practice is typical for common areas during peak visitor hours in a mall?","a":["Frequent spot-cleaning by small teams without blocking walkways, rather than large-scale wet cleaning","Fully closing the area for a 2-hour deep clean","Suspending all cleaning entirely until the mall closes"],"c":0,"why":"During peak hours, quick spot-cleaning is used to avoid disrupting shopper flow."}},{"id":"OP053","cat":"ops","logic":false,"ru":{"q":"Зачем в facility management ТРЦ ведут журнал заявок (work order log) на инженерные и клининговые работы?","a":["Чтобы отслеживать сроки выполнения, ответственных и повторяемость проблем для планирования обслуживания","Чтобы начислять премии только клининговой службе","Это требуется исключительно для налоговой отчётности арендаторов"],"c":0,"why":"Журнал заявок помогает контролировать SLA, выявлять повторяющиеся проблемы и планировать превентивное обслуживание."},"uz":{"q":"TRTS facility management'ida muhandislik va tozalash ishlari bo'yicha ariza jurnali (work order log) nega yuritiladi?","a":["Bajarish muddatlari, mas'ullar va muammolarning takrorlanishini kuzatib, xizmat ko'rsatishni rejalashtirish uchun","Faqat tozalash xizmatiga mukofot hisoblash uchun","Bu faqat ijarachilarning soliq hisobotlari uchun talab qilinadi"],"c":0,"why":"Ariza jurnali SLA'ni nazorat qilish, takrorlanuvchi muammolarni aniqlash va preventiv xizmatni rejalashtirishga yordam beradi."},"en":{"q":"Why does mall facility management keep a work order log for engineering and cleaning tasks?","a":["To track completion times, accountability, and recurring issues for maintenance planning","To calculate bonuses only for the cleaning staff","It is required solely for tenant tax reporting"],"c":0,"why":"A work order log helps monitor SLAs, identify recurring problems, and plan preventive maintenance."}},{"id":"OP054","cat":"ops","logic":false,"ru":{"q":"Какова цель системы wayfinding (навигации) помимо указателей направления к магазинам?","a":["Снижение уровня стресса посетителей и увеличение времени пребывания за счёт лёгкой ориентации в пространстве","Полная замена персонала информационной стойки","Автоматическое начисление скидок постоянным посетителям"],"c":0,"why":"Хорошая навигация снижает когнитивную нагрузку посетителя, что напрямую увеличивает время и комфорт пребывания."},"uz":{"q":"Wayfinding (navigatsiya) tizimining do'konlarga yo'nalish ko'rsatkichlaridan tashqari maqsadi nima?","a":["Tashrif buyuruvchilarning stressini kamaytirish va fazoda oson yo'nalish topish orqali tashrif vaqtini oshirish","Ma'lumot stendi xodimini to'liq almashtirish","Doimiy mijozlarga avtomatik chegirma hisoblash"],"c":0,"why":"Yaxshi navigatsiya tashrif buyuruvchining kognitiv yukini kamaytiradi, bu esa tashrif vaqti va qulaylikni oshiradi."},"en":{"q":"Beyond directional signage to stores, what is the purpose of a wayfinding system?","a":["Reducing visitor stress and increasing dwell time by making spatial orientation easy","Fully replacing information desk staff","Automatically applying discounts to loyal visitors"],"c":0,"why":"Effective wayfinding reduces a visitor's cognitive load, which directly increases comfort and dwell time."}},{"id":"OP055","cat":"ops","logic":false,"ru":{"q":"Какую задачу решает digital wayfinding (интерактивные киоски/карты) лучше статичных указателей?","a":["Персонализированный поиск маршрута до конкретного магазина или акции с учётом текущего местоположения","Полное исключение необходимости в физических вывесках магазинов","Автоматический вызов лифта для посетителя"],"c":0,"why":"Интерактивные киоски позволяют построить персональный маршрут, чего не могут статичные карты."},"uz":{"q":"Digital wayfinding (interaktiv kiosklar/xaritalar) statik ko'rsatkichlarga nisbatan qaysi vazifani yaxshiroq bajaradi?","a":["Joriy joylashuvni hisobga olgan holda muayyan do'kon yoki aksiyagacha shaxsiylashtirilgan yo'nalish qidirish","Do'konlarning jismoniy lavhalariga ehtiyojni butunlay yo'q qilish","Tashrif buyuruvchi uchun liftni avtomatik chaqirish"],"c":0,"why":"Interaktiv kiosklar shaxsiylashtirilgan marshrut qurish imkonini beradi, statik xaritalar buni qila olmaydi."},"en":{"q":"What does digital wayfinding (interactive kiosks/maps) accomplish better than static signage?","a":["Personalized route guidance to a specific store or promotion based on current location","Completely eliminating the need for physical storefront signage","Automatically calling an elevator for the visitor"],"c":0,"why":"Interactive kiosks enable personalized route planning, which static maps cannot provide."}},{"id":"OP056","cat":"ops","logic":false,"ru":{"q":"За что в организационной структуре управляющей компании ТРЦ отвечает mall/center manager?","a":["За общую операционную деятельность объекта, координацию служб и достижение KPI по трафику и доходу","Только за подписание договоров аренды с новыми брендами","Только за расписание уборки общих зон"],"c":0,"why":"Управляющий ТРЦ несёт общую операционную ответственность и координирует все службы объекта."},"uz":{"q":"TRTS boshqaruv kompaniyasining tashkiliy tuzilmasida mall/center manager nima uchun javobgar?","a":["Obyektning umumiy operatsion faoliyati, xizmatlarni muvofiqlashtirish va trafik/daromad bo'yicha KPI'larga erishish uchun","Faqat yangi brendlar bilan ijara shartnomalarini imzolash uchun","Faqat umumiy zonalarni tozalash jadvali uchun"],"c":0,"why":"TRTS menejeri umumiy operatsion mas'uliyatni o'z zimmasiga oladi va barcha xizmatlarni muvofiqlashtiradi."},"en":{"q":"In a mall management company's org structure, what is the mall/center manager responsible for?","a":["Overall operational performance of the property, coordinating departments, and hitting traffic/revenue KPIs","Only signing lease agreements with new brands","Only the cleaning schedule for common areas"],"c":0,"why":"The mall manager holds overall operational responsibility and coordinates all departments at the property."}},{"id":"OP057","cat":"ops","logic":false,"ru":{"q":"Чем отличается роль leasing manager от роли operations manager в управляющей компании ТРЦ?","a":["Leasing manager отвечает за привлечение арендаторов и коммерческие условия, operations manager — за ежедневную эксплуатацию объекта","Leasing manager занимается только уборкой, operations manager — только охраной","Обе роли идентичны и дублируют друг друга во всех ТРЦ"],"c":0,"why":"Лизинг фокусируется на коммерческих сделках с арендаторами, а операционный менеджмент — на текущей эксплуатации объекта."},"uz":{"q":"TRTS boshqaruv kompaniyasida leasing manager va operations manager rollari bir-biridan nimasi bilan farq qiladi?","a":["Leasing manager ijarachilarni jalb qilish va tijorat shartlari uchun, operations manager esa obyektning kundalik ekspluatatsiyasi uchun javobgar","Leasing manager faqat tozalash bilan, operations manager faqat xavfsizlik bilan shug'ullanadi","Ikkala rol barcha TRTSlarda bir xil va bir-birini takrorlaydi"],"c":0,"why":"Lizing ijarachilar bilan tijorat bitimlariga, operatsion boshqaruv esa obyektning joriy ekspluatatsiyasiga qaratilgan."},"en":{"q":"How does a leasing manager's role differ from an operations manager's role in a mall management company?","a":["The leasing manager secures tenants and commercial terms, while the operations manager runs the day-to-day facility","The leasing manager only handles cleaning, the operations manager only handles security","Both roles are identical and duplicate each other in every mall"],"c":0,"why":"Leasing focuses on commercial tenant deals, while operations management focuses on running the facility day to day."}},{"id":"OP058","cat":"ops","logic":false,"ru":{"q":"Какова функция marketing/promotions manager в управляющей компании ТРЦ в контексте co-tenancy?","a":["Организация совместных акций, которые усиливают синергию между якорями и мелкими арендаторами для общего трафика","Начисление штрафов арендаторам за нарушение договора","Контроль инженерных систем здания"],"c":0,"why":"Маркетинг-менеджер создаёт совместные кампании, усиливающие взаимную выгоду якорных и обычных арендаторов."},"uz":{"q":"TRTS boshqaruv kompaniyasida marketing/promotions manager co-tenancy kontekstida qanday vazifani bajaradi?","a":["Langar va kichik ijarachilar o'rtasidagi sinergiyani kuchaytiruvchi qo'shma aksiyalarni tashkil etish","Shartnoma buzilishi uchun ijarachilarga jarima hisoblash","Bino muhandislik tizimlarini nazorat qilish"],"c":0,"why":"Marketing menejeri langar va oddiy ijarachilar o'rtasidagi o'zaro manfaatni kuchaytiruvchi qo'shma kampaniyalar yaratadi."},"en":{"q":"What is the function of the marketing/promotions manager in a mall management company regarding co-tenancy?","a":["Organizing joint promotions that reinforce synergy between anchors and smaller tenants to drive shared traffic","Issuing penalties to tenants for lease violations","Overseeing the building's engineering systems"],"c":0,"why":"The marketing manager builds joint campaigns that strengthen the mutual benefit between anchor and in-line tenants."}},{"id":"OP059","cat":"ops","logic":false,"ru":{"q":"Что означает co-tenancy clause (пункт о совместной аренде) в договоре с якорным арендатором?","a":["Условие, дающее якорю право на пересмотр аренды или выход, если определённая доля других арендаторов/другой якорь покинут ТРЦ","Требование, чтобы все арендаторы платили одинаковую ставку за м²","Запрет на открытие конкурирующего магазина в радиусе города"],"c":0,"why":"Co-tenancy clause защищает якоря от ситуации, когда снижение общего заполнения ТРЦ ухудшает его бизнес."},"uz":{"q":"Langar ijarachi bilan tuzilgan shartnomadagi co-tenancy clause (birgalikda ijara bandi) nimani anglatadi?","a":["Agar boshqa ijarachilarning ma'lum ulushi yoki boshqa langar TRTSni tark etsa, langarga ijarani qayta ko'rib chiqish yoki chiqib ketish huquqini beruvchi shart","Barcha ijarachilar m² uchun bir xil stavka to'lashi kerakligi haqidagi talab","Shahar radiusida raqobatchi do'kon ochishni taqiqlash"],"c":0,"why":"Co-tenancy bandi langarni TRTS to'lganligi pasayib, uning biznesiga zarar yetkazadigan vaziyatdan himoya qiladi."},"en":{"q":"What does a co-tenancy clause in an anchor tenant's lease mean?","a":["A provision letting the anchor renegotiate rent or exit if a certain share of tenants, or another anchor, leave the mall","A requirement that all tenants pay the same rate per sqm","A ban on any competing store opening anywhere in the city"],"c":0,"why":"A co-tenancy clause protects the anchor from a scenario where declining mall occupancy hurts its business."}},{"id":"OP060","cat":"ops","logic":false,"ru":{"q":"Почему уход крупного якорного арендатора считается наиболее серьёзным риском для мелких in-line магазинов?","a":["Якорь генерирует основную часть трафика, и его потеря резко снижает посещаемость соседних бутиков","Потому что мелкие магазины автоматически теряют лицензию на торговлю","Потому что арендная плата у мелких магазинов при этом обнуляется"],"c":0,"why":"Из-за со-зависимости трафика уход якоря напрямую бьёт по продажам всех окружающих его in-line арендаторов."},"uz":{"q":"Nega yirik langar ijarachining ketishi kichik in-line do'konlar uchun eng jiddiy xavf hisoblanadi?","a":["Langar asosiy trafikni yaratadi va uning yo'qolishi qo'shni butiklarga tashrifni keskin kamaytiradi","Chunki kichik do'konlar avtomatik ravishda savdo litsenziyasini yo'qotadi","Chunki kichik do'konlarning ijara haqi shu bilan nolga tushadi"],"c":0,"why":"Trafikning o'zaro bog'liqligi tufayli langarning ketishi atrofdagi barcha in-line ijarachilarning savdosiga to'g'ridan-to'g'ri ta'sir qiladi."},"en":{"q":"Why is the departure of a major anchor tenant considered the most serious risk for smaller in-line stores?","a":["The anchor generates the majority of foot traffic, and losing it sharply reduces visits to neighboring stores","Because small stores automatically lose their retail license","Because small stores' rent automatically drops to zero"],"c":0,"why":"Due to traffic co-dependency, an anchor's exit directly hits the sales of all surrounding in-line tenants."}}];
